    mode = body.get("mode") if isinstance(body, dict) else None
    if mode not in lowres.MODES:
        return jsonify({"error": "mode must be one of: %s." % ", ".join(lowres.MODES)}), 400
    config.set_setting("low_resource_mode", mode)
