@app.route("/api/agent/sessions/<session_id>", methods=["GET"])
def api_agent_get_session(session_id):
    gate = _agent_gate()
    if gate:
        return gate
    sess = agentic_chat.get_session(session_id)
    if sess is None:
        return jsonify({"error": "No such agentic session."}), 404
    # A "multi" turn runs as a swarm_windows run, not as this session's child
    # process, so the session itself looks idle. The page's reconnect logic
    # reads this flag to know whether to keep waiting.
    if not sess.get("currently_running") and _multi_run_for(session_id):
        sess["currently_running"] = True
    sess["auto_resume"] = agentic_history.auto_resume(session_id)
    return jsonify(sess)


@app.route("/api/agent/sessions/<session_id>/auto-resume", methods=["POST"])
def api_agent_auto_resume(session_id):
    """{enabled} -> whether this conversation continues by itself after a
    hub restart (default off: the owner presses Continue)."""
    gate = _agent_gate()
    if gate:
        return gate
    body = request.get_json(silent=True) or {}
    got = agentic_history.set_auto_resume(session_id, bool(body.get("enabled")))
    if got is None:
        return jsonify({"error": "No such conversation."}), 404
    return jsonify({"session_id": session_id, "auto_resume": got})


@app.route("/api/agent/sessions/<session_id>/message", methods=["POST"])
def api_agent_send_message(session_id):
    gate = _agent_gate()
    if gate:
        return gate
    body = request.get_json(force=True, silent=True)
    if not isinstance(body, dict) or not isinstance(body.get("text"), str):
        return jsonify({"error": "Pass {\"text\": string}."}), 400
    # Persist the user's side BEFORE the (possibly long-running, up to
    # _TURN_TIMEOUT) subprocess call -- so a hub restart mid-turn never loses
    # the outgoing message. Only persist the agent's reply if a turn actually
    # produced one (status 200); a 4xx/409/499/5xx has no reply text to save.
    sess_info = agentic_chat.get_session(session_id)
    # ...but only a turn that will RUN. A second tab sending while a turn is
    # going (409), or an empty/oversized message (400), used to be recorded
    # as a user turn first and refused after -- a phantom turn in history.
    refused = agentic_chat.precheck_turn(
        session_id, body["text"],
        cap=not (sess_info and sess_info.get("quality") == "multi"))
    if sess_info and refused and refused[0] in (400, 409):
        return jsonify({"status": refused[0], "text": None, "detail": refused[1]}), refused[0]
    if sess_info:
        # The files as they are RIGHT NOW, before this turn touches anything --
        # so restoring this turn's snapshot puts the project back to how it
        # looked when the message was sent. Fails open (returns None) rather
        # than ever holding up the turn; see snapshots.py.
        snap = None
        if config.get_flag("turn_snapshots", True):
            snap = snapshots.take(session_id, sess_info["project_dir"],
                                  "before: " + (body["text"] or "")[:60])
        agentic_history.record_turn(session_id, sess_info["cli"], sess_info["project_dir"],
                                    "user", body["text"], snapshot=snap)
        # Keep the saved conversation's mode in step with the live session. Done
        # here rather than at session start because the conversation record does
        # not exist until its first turn. set_quality returns without writing
        # when it already matches, so this is a dict lookup on every later turn.
        agentic_history.set_quality(session_id, sess_info.get("quality") or "normal")
        # AND THE MODE. The comment above says "mode" and the line above it
        # writes only the quality -- so a conversation given its own kind of
        # model kept it until the next hub restart and then came back with
        # none, which is the half of "per-conversation models, saved" that was
        # silently missing. Same shape: set_mode returns without writing when
        # it already matches.
        agentic_history.set_mode(session_id, sess_info.get("mode"))
    if sess_info and sess_info.get("quality") == "multi" and _multi_wants_a_swarm(body["text"]):
        # The reply is recorded by the run's own on_done (see
        # _multi_turn_events), never here: recording it twice would show the
        # same report as two turns. A question rather than a job falls
        # through to the ordinary turn below (see _multi_wants_a_swarm).
        status, text, detail = _multi_turn_blocking(session_id, sess_info, body["text"])
        return jsonify({"status": status, "text": text, "detail": detail}), status
    status, text, detail = agentic_chat.send_message(session_id, body["text"])
    if sess_info and status == 200 and text:
        # The CLI's OWN thread id, captured with the reply. Without it a
        # conversation cannot be continued after a hub restart -- sessions are
        # in memory, but `codex exec resume <id>` / `claude --resume <id>` pick
        # the real thread back up with the model's full context. Read AFTER the
        # turn: turn 1 is what creates it.
        _after = agentic_chat.get_session(session_id) or {}
        agentic_history.record_turn(session_id, sess_info["cli"], sess_info["project_dir"],
                                    "agent", text,
                                    native_session_id=_after.get("native_session_id"))
    return jsonify({"status": status, "text": text, "detail": detail}), status


@app.route("/api/agent/sessions/<session_id>/message/stream", methods=["POST"])
def api_agent_send_message_stream(session_id):
    """Live version of the message route: relays send_message_stream_durable's
    normalized progress events over SSE so the dashboard shows the agent working
    in real time. Records the user turn up front; the agent's reply is recorded
    by the durable wrapper's own background thread once the turn actually ends,
    whether or not this connection is still around to see it."""
    gate = _agent_gate()
    if gate:
        return gate
    body = request.get_json(force=True, silent=True)
    if not isinstance(body, dict) or not isinstance(body.get("text"), str):
        return jsonify({"error": "Pass {\"text\": string}."}), 400
    text = body["text"]
    sess_info = agentic_chat.get_session(session_id)
    # Refused turns are answered BEFORE anything is recorded: a second tab's
    # send while a turn runs used to land in the transcript as a user turn and
    # only then get its 409 (see the plain route above).
    refused = agentic_chat.precheck_turn(
        session_id, text, cap=not (sess_info and sess_info.get("quality") == "multi"))
    if sess_info and refused and refused[0] in (400, 409):
        def _refused(status=refused[0], detail=refused[1]):
            yield "data: " + json.dumps({"event": "error", "status": status,
                                         "detail": detail}) + "\n\n"
            yield "event: end\ndata: {}\n\n"
        return Response(_refused(), mimetype="text/event-stream", headers=_SSE_HEADERS)
    # BUDGET: a conversation's optional spend cap ends the turn cleanly with a
    # message (a Multi turn's cap is enforced by its run, not here).
    if sess_info and sess_info.get("quality") != "multi":
        capped = _conversation_budget_block(session_id)
        if capped:
            def _capped(status=capped[0], detail=capped[1]):
                yield "data: " + json.dumps({"event": "error", "status": status,
                                             "detail": detail}) + "\n\n"
                yield "event: end\ndata: {}\n\n"
            return Response(_capped(), mimetype="text/event-stream", headers=_SSE_HEADERS)
    if sess_info and orchestrator.is_command(text.strip()):
        # "/orchestrator ..." typed here: the hub answers it for THIS
        # conversation without starting the CLI (see orchestrator.py).
        reply = _orch_command_text(ctxwin.conversation_key(agent_sid=session_id), text.strip())
        agentic_history.record_turn(session_id, sess_info["cli"], sess_info["project_dir"],
                                    "user", text)
        agentic_history.record_turn(session_id, sess_info["cli"], sess_info["project_dir"],
                                    "agent", reply)

        def _orch_done(reply=reply):
            yield "data: " + json.dumps({"event": "done", "text": reply}) + "\n\n"
            yield "event: end\ndata: {}\n\n"
        return Response(_orch_done(), mimetype="text/event-stream", headers=_SSE_HEADERS)
    if sess_info:
        # Snapshot the files BEFORE the turn touches them, exactly as the
        # non-streaming route does. It was missing here, which made the whole
        # Restore & rerun feature inert on the path /build actually uses --
        # every turn from the dashboard streams.
        snap = None
        if config.get_flag("turn_snapshots", True):
            snap = snapshots.take(session_id, sess_info["project_dir"],
                                  "before: " + (text or "")[:60])
        agentic_history.record_turn(session_id, sess_info["cli"], sess_info["project_dir"],
                                    "user", text, snapshot=snap)
        agentic_history.set_quality(session_id, sess_info.get("quality") or "normal")
        # AND THE MODE. The comment above says "mode" and the line above it
        # writes only the quality -- so a conversation given its own kind of
        # model kept it until the next hub restart and then came back with
        # none, which is the half of "per-conversation models, saved" that was
        # silently missing. Same shape: set_mode returns without writing when
        # it already matches.
        agentic_history.set_mode(session_id, sess_info.get("mode"))

    def gen():
        # THE MODEL'S MEMORY. The CLI's own thread id is what `codex exec resume`
        # / `claude --resume` need to bring back the full context, and it used to
        # reach disk only when a turn COMPLETED -- so an interrupted turn lost it
        # and the next one started from nothing but the files. Persist it the
        # moment it exists instead. set_native_session_id does not write when it
        # is already stored, so this costs a dict lookup per event.
        saved_native = [False]

        def _keep_context():
            if saved_native[0]:
                return
            live = agentic_chat.get_session(session_id) or {}
            native = live.get("native_session_id")
            if native and agentic_history.set_native_session_id(session_id, native):
                saved_native[0] = True

        # The agent's reply is persisted from INSIDE send_message_stream_durable's
        # own background thread now, not here -- this loop merely relays events
        # to whoever is still connected. See its docstring: a plain generator
        # driven only by this route would silently lose the reply if the client
        # disconnected before the turn finished, even though the turn itself
        # completed for real.
        try:
            if sess_info and sess_info.get("quality") == "multi" and _multi_wants_a_swarm(text):
                # Several real sessions, in THIS conversation -- see
                # _multi_turn_events. The run keeps going and records its own
                # reply if this connection goes away; live_run mirrors the
                # events so a page that reloads can pick the turn back up.
                # A COPY OF THIS REQUEST'S CONTEXT goes with it: the planner
                # routes through the hub's own chain, which reads the request.
                events = agentic_chat.live_run(
                    session_id, _multi_turn_events(session_id, sess_info, text),
                    context=request_ctx._get_current_object().copy())
            elif sess_info and sess_info.get("quality") == "multi":
                # A question, not a job: the conversation answers it itself,
                # and says why no run started (see _multi_wants_a_swarm).
                def _direct():
                    yield {"event": "notice",
                           "text": "Answered directly -- a short question is not a job "
                                   "to split across sessions. Send the work itself to "
                                   "start a multi-session run."}
                    for ev in agentic_chat.send_message_stream_durable(session_id, text):
                        yield ev
                events = _direct()
            else:
                events = agentic_chat.send_message_stream_durable(session_id, text)
            for ev in events:
                _keep_context()
                yield "data: " + json.dumps(ev) + "\n\n"
        except Exception as exc:  # never leak a traceback into the stream
            yield "data: " + json.dumps({"event": "error", "status": 500,
                                         "detail": _sanitize(str(exc), 300)}) + "\n\n"
        finally:
            # Last chance, and the one that matters when the turn ERRORED: the
            # id may only have appeared on the way out.
            try:
                _keep_context()
            except Exception:                                    # noqa: BLE001
                pass
            yield "event: end\ndata: {}\n\n"

    return Response(stream_with_context(gen()), mimetype="text/event-stream", headers=_SSE_HEADERS)


def _multi_last_action(agent):
    """A helper's latest tool action or note, clipped for one line, or None."""
    try:
        for ev in reversed(list(getattr(agent, "events", None) or ())):
            line = _multi_activity_line({"index": agent.index}, ev)
            if line:
                return line.split(" \u00b7 ", 1)[-1]
    except Exception:                                            # noqa: BLE001
        pass
    return None


def _multi_pair_view(agent):
    """The co-pilot of a phase for the helpers panel: {model, state, url}, or
    None when the phase has none (swarm_windows PAIR mode)."""
    if not getattr(agent, "pair_state", None):
        return None
    sid = agent.pair_session
    with _worker_model_lock:
        model = _WORKER_MODEL.get(sid) if sid else None
    return {"model": model, "state": agent.pair_state, "session_id": sid,
            "url": ("/agent/" + sid) if sid else None}


def _multi_run_plan(session_id, project_dir=None):
    """The Build page's task list from this conversation's Multi run: one
    line per phase (done / working / waiting / failed, and the model the
    worker runs on), or None when no run should be shown.

    Shown while the run is going, and after it ended until PROGRESS.md is
    written again. MEASURED 2026-09-30: during a four-phase run the strip
    still read "9/9 done ... ALL GATES COMPLETE" from the previous turn's
    PROGRESS.md."""
    try:
        with _MULTI_LOCK:
            planning_since = _MULTI_PLANNING.get(session_id)
        if planning_since:
            return {"session_id": session_id,
                    "tasks": [{"text": "Planning the Multi run (%ds so far)"
                                       % int(time.time() - planning_since),
                               "done": False, "doing": True}],
                    "done": 0, "source": "multi-session run \u00b7 planning",
                    "interrupted": None}
        # A HELPER'S OWN PAGE (opened with Open ↗) shows ITS run, with itself
        # marked -- never the project's shared PROGRESS.md, which every helper
        # works in and which read as an old, unrelated plan (owner,
        # 2026-09-30: "when I open helpers in a new window I see nothing
        # accurate, the old plan from PROGRESS.md").
        helper = swarm_windows.worker_info(session_id)
        run = (swarm_windows.get(helper["run_id"]) if helper
               else swarm_windows.last_run_for(session_id))
        if run is None:
            return None
        live = run.state in (swarm_windows.PENDING, swarm_windows.RUNNING)
        if not live and not helper:
            try:
                path = os.path.join(project_dir or run.project_dir, "PROGRESS.md")
                if os.path.getmtime(path) > (run.ended_at or run.created_at):
                    return None
            except (OSError, TypeError):
                pass
        items = []
        for a in run.agents:
            text = "Phase %d: %s" % (a.index, a.title)
            with _worker_model_lock:
                model = _WORKER_MODEL.get(a.session_id) if a.session_id else None
            if model:
                text += " \u00b7 " + model
            if a.state == swarm_windows.FAILED:
                text += " (failed)"
            # Each helper is a real agent session with its own page: the
            # conversation lists them and opens any one in a new window
            # (owner, 2026-09-30: "see the helpers in the same conversation,
            # and open each one we want in a new window").
            items.append({"text": text, "done": a.state == swarm_windows.DONE,
                          "doing": a.state == swarm_windows.RUNNING,
                          "this": bool(helper and a.index == helper.get("index")),
                          "state": a.state, "index": a.index, "title": a.title,
                          "model": model, "session_id": a.session_id or None,
                          "url": ("/agent/" + a.session_id) if a.session_id else None,
                          "started_at": a.started_at, "ended_at": a.ended_at,
                          "last": _multi_last_action(a),
                          # What the phase's result rests on, honestly
                          # labelled: "12 passed (observed)" / "claimed,
                          # not checked" / "reviewed" (swarm_windows.check_of).
                          "check": swarm_windows.check_of(a),
                          "pair": _multi_pair_view(a)})
        running = [t["index"] for t in items if t["doing"]]
        # The stopping place stays visible next to the helpers: a run that was
        # cut short (or a turn cut by a restart) still offers Continue.
        try:
            cut = None if live else memory.interrupted(session_id)
        except Exception:                                        # noqa: BLE001
            cut = None
        return {"session_id": session_id, "tasks": items,
                "done": sum(1 for t in items if t["done"]),
                "source": "multi-session run %s" % run.id,
                "helper": helper,
                "run_id": run.id, "run_state": run.state,
                # The plan's design as ONE collapsed row ("Design: 3
                # components, 4 interfaces"), and its dry-run line.
                "design": swarm_windows.design_view(run),
                "plan_check": (getattr(run, "plan_check", None) or {}).get("line"),
                "parallel": swarm_windows.parallel_view(run),
                # Budget: X / Y in the run header (None when the run has no cap).
                "budget": swarm_windows.budget_view(run),
                "current": running[0] if running else None,
                # Picked back up by this process after a restart (it did not
                # need a click: swarm_windows.resume_interrupted at boot).
                "resumed": bool(live and getattr(run, "restored", False)),
                "now": time.time(), "interrupted": cut}
    except Exception:                                            # noqa: BLE001
        return None


@app.route("/api/agent/sessions/<session_id>/plan", methods=["GET"])
def api_agent_plan(session_id):
    """The conversation's task list and, if its last turn did not finish,
    where it stopped -- what the Build page shows above the transcript.
    Read from the hub's memory, which is refreshed at the end of every turn
    from the project's PROGRESS.md and the reply's checklist."""
    gate = _agent_gate()
    if gate:
        return gate
    sess = agentic_chat.get_session(session_id) or {}
    run_plan = _multi_run_plan(session_id, sess.get("project_dir"))
    if run_plan is not None:
        return jsonify(run_plan)
    if sess.get("project_dir"):
        # Fresh: the agent may have edited PROGRESS.md mid-turn, and a page
        # asking now wants what is on disk now. Mid-turn, the agent wrote it
        # (seen); between turns, a changed list is the user's edit, which the
        # next turn is handed (memory.should_restate_rules).
        try:
            memory.update_tasks_from_project(session_id, sess["project_dir"],
                                             seen=agentic_chat.turn_busy(session_id))
        except Exception:                                        # noqa: BLE001
            pass
    mem = memory.get(session_id)
    items = [t for t in (mem.get("tasks") or []) if isinstance(t, dict) and t.get("text")]
    return jsonify({
        "session_id": session_id,
        "tasks": items,
        "done": sum(1 for t in items if t.get("done")),
        "source": mem.get("tasks_source") or "",
        "interrupted": mem.get("interrupted") if isinstance(mem.get("interrupted"), dict) else None,
    })


@app.route("/api/agent/sessions/<session_id>/live", methods=["GET"])
def api_agent_follow_turn(session_id):
    """The turn that is running on this session, from its beginning, live.

    REPORTED: "when I refresh the page I don't see running what he was
    doing". This is what the page attaches to after a reload: the events the
    turn has emitted so far are replayed, then it stays attached until the
    turn ends. When nothing is running it says so at once ("idle"), so the
    page loads the transcript instead of waiting on nothing."""
    gate = _agent_gate()
    if gate:
        return gate

    def gen():
        try:
            got = False
            for ev in agentic_chat.follow_turn(session_id):
                got = True
                yield "data: " + json.dumps(ev) + "\n\n"
            if not got:
                yield "data: " + json.dumps({"event": "idle"}) + "\n\n"
        except Exception as exc:                                 # noqa: BLE001
            yield "data: " + json.dumps({"event": "error", "status": 500,
                                         "detail": _sanitize(str(exc), 300)}) + "\n\n"
        finally:
            yield "event: end\ndata: {}\n\n"

    return Response(stream_with_context(gen()), mimetype="text/event-stream", headers=_SSE_HEADERS)


@app.route("/api/agent/sessions/<session_id>/quality", methods=["POST"])
def api_agent_set_quality(session_id):
    """Switch a live session between normal and max quality.

    Works mid-conversation because the CLI subprocess is re-spawned per turn,
    so its ANTHROPIC_MODEL is rebuilt each time. A turn already running keeps
    the mode it started with -- its child is already launched."""
    gate = _agent_gate()
    if gate:
        return gate
    body = request.get_json(force=True, silent=True)
    q = body.get("quality") if isinstance(body, dict) else None
    if q not in agentic_chat.QUALITIES:
        return jsonify({"error": "Pass {\"quality\": one of %s}."
                        % "|".join(agentic_chat.QUALITIES)}), 400
    out = agentic_chat.set_quality(session_id, q)
    if out is None:
        return jsonify({"error": "No such agentic session."}), 404
    # Mirror it into the saved conversation. The live session holds the mode but
    # does not survive a hub restart (and the hub restarts every 5h to update),
    # so without this, Continue tomorrow silently resumes on Normal.
    agentic_history.set_quality(session_id, out)
    _log.info("[agent] session quality -> %s", out)
    return jsonify({"session_id": session_id, "quality": out})


@app.route("/api/agent/sessions/<session_id>/stop", methods=["POST"])
def api_agent_stop_session(session_id):
    stopped = agentic_chat.stop_session(session_id)
    # A "multi" turn is a swarm_windows run, not a child of this session:
    # Stop has to reach it too, or the button does nothing for that tier.
    with _MULTI_LOCK:
        rid = _MULTI_RUNS.get(session_id)
    if rid and swarm_windows.stop(rid):
        stopped = True
    return jsonify({"stopped": stopped})


@app.route("/api/agent/sessions/<session_id>", methods=["DELETE"])
def api_agent_end_session(session_id):
    ended, closed = _end_live_session(session_id)
    return jsonify({"ended": ended, "app_closed": bool(closed)})


def _end_live_session(session_id):
    """End one live /agent session and what it owns. (ended, app_closed)."""
    # Take the folder BEFORE ending: end_session drops the registry entry, and
    # after that there is nothing left to say which project this session owned.
    sess = agentic_chat.get_session(session_id)
    project_dir = (sess.get("project_dir") if isinstance(sess, dict)
                   else getattr(sess, "project_dir", None)) if sess else None
    ended = agentic_chat.end_session(session_id)
    # And its model rules. Nothing else ever removed them, so a hub that had
    # run a few hundred conversations carried a few hundred dead entries.
    if ended:
        _forget_session_models(session_id)
        _session_pin_drop(session_id)       # it holds no model any more
    # Ending a session ends the app it started. A dev server left holding :3000
    # after its session is gone is a leak the user has to clear by hand -- and
    # worse, the next project then finds that port busy or, until the ownership
    # guards landed, showed its site in the new project's preview.
    closed = False
    if ended and project_dir:
        try:
            closed = workspace.shutdown(project_dir)
        except Exception as exc:                                 # noqa: BLE001
            _log.warning("could not stop the preview for %s: %s", project_dir, exc)
    return ended, bool(closed)


# --------------------------------------------------------------------------- #
# Quick-chat history — the plain chat kept nothing across a reload
# --------------------------------------------------------------------------- #

@app.route("/api/chat/history", methods=["GET"])
def api_chat_history_list():
    try:
        limit = min(int(request.args.get("limit", 50)), 200)
    except (TypeError, ValueError):
        limit = 50
    return jsonify({"conversations": quick_history.list_conversations(limit)})


@app.route("/api/chat/history/<cid>", methods=["GET"])
def api_chat_history_get(cid):
    conv = quick_history.load_conversation(cid)
    if not conv:
        return jsonify({"error": "No such conversation."}), 404
    return jsonify(conv)


@app.route("/api/chat/history/<cid>", methods=["DELETE"])
def api_chat_history_delete(cid):
    deleted = quick_history.delete_conversation(cid)
    # Its rolling compaction recap goes with it (keyed by the chat id the
    # page sends as X-Conversation-Id): a deleted chat must not live on as a
    # recap a later chat could never see but the store still carries.
    try:
        _recap_store.delete(ctxwin.quick_chat_key(cid))
    except Exception:                                            # noqa: BLE001
        pass
    return jsonify({"deleted": deleted})


@app.route("/api/chat/history/<cid>/turn", methods=["POST"])
def api_chat_history_save_turn(cid):
    """Record one exchange.

    Written by the browser AFTER a reply completes, rather than by the chat
    endpoint itself: the quick chat calls /v1/chat/completions directly, the
    same endpoint every external CLI uses, and that endpoint has no idea which
    dashboard conversation a request belongs to. Teaching it would mean adding
    a hub-specific field to a public OpenAI-compatible API. The browser already
    knows, so it says."""
    body = request.get_json(silent=True) or {}
    user_text = body.get("user")
    assistant_text = body.get("assistant")
    if not isinstance(user_text, str) or not isinstance(assistant_text, str):
        return jsonify({"error": "Pass {user: str, assistant: str}."}), 400
    quick_history.save_turn(cid, user_text, assistant_text,
                            model=body.get("model"), provider=body.get("provider"))
    return jsonify({"ok": True})


@app.route("/api/agent/clis/<cli_id>/install", methods=["POST"])
def api_agent_cli_install(cli_id):
    """Install one agent CLI on demand, from the picker.

    Exists because the old path went through /api/subscriptions/<sub-*>/
    install-isolated, and that only covers CLIs that ARE subscription providers
    -- claude and codex. opencode is not one (it brings its own provider), so
    it had no install button at all. This works for every CLI the agent chat
    can drive, and does both halves: the machine's own copy, and the hub's
    isolated one."""
    gate = _agent_gate()
    if gate:
        return gate
    if cli_id not in _ISOLATED_NPM_PACKAGE:
        return jsonify({"error": "Unknown CLI '%s'." % _sanitize(str(cli_id), 40)}), 400
    bin_name = _CLI_BIN_NAME.get(cli_id, cli_id)
    out = {"cli": cli_id}
    if not shutil.which(bin_name):
        ok, res = _install_global_cli(cli_id)
        out["global"] = {"ok": ok, "error": res.get("error")}
    ok, res = _install_isolated_cli(cli_id, bin_name)
    res.pop("_status", None)
    out["isolated"] = {"ok": ok, "error": res.get("error")}
    if not ok and not out.get("global", {}).get("ok"):
        return jsonify({"error": res.get("error") or "install failed", **out}), 502
    return jsonify({"ok": True, **out})


@app.route("/api/agent/clis/<cli_id>/login", methods=["POST"])
def api_agent_cli_login(cli_id):
    """One-click sign-in for the hub's isolated copy of a CLI.

    Isolation on purpose means a SEPARATE, initially-empty credential store
    from the CLI the user already uses by hand -- asked for explicitly, and
    the reason the auth error names it. That separation still needs signing
    in once; this is what makes doing so one click in the dashboard rather
    than "copy this PowerShell line into a terminal yourself". Opens a real,
    visible window for the login flow itself and returns immediately -- the
    hub does not, and should not, see credentials as they are typed."""
    gate = _agent_gate()
    if gate:
        return gate
    ok, detail = agentic_chat.launch_isolated_login(cli_id)
    if not ok:
        return jsonify({"error": detail}), 400
    return jsonify({"ok": True})


@app.route("/api/agent/new-project", methods=["POST"])
def api_agent_new_project():
    """One-click 'Create new project': auto-create a fresh uniquely-named folder
    under ~/calvoun-projects and return its path, so the dashboard can fill it in
    and the user just clicks Start session."""
    gate = _agent_gate()
    if gate:
        return gate
    try:
        path = agentic_chat.new_project_dir()
    except OSError as exc:
        return jsonify({"error": "Could not create a new project folder: %s" % exc.__class__.__name__}), 500
    return jsonify({"path": path})


# ---------------------------------------------------------------------------
# Agentic chat -- persisted conversation history + rewind checkpoints.
# None of these five routes call _agent_gate(): they never touch a live CLI
# subprocess, only the locally-persisted transcript (agentic_history.py), so
# gating them behind agentic_chat_enabled would only block the user from
# browsing/managing their OWN past conversations after turning the live
# feature off -- that isn't what the master flag is for (same reasoning the
# pre-existing stop/end routes above already use, and the same precedent as
# /api/images/history's routes, which carry no image-generation-flag gate
# either). They still go through the normal global request guard in
# _local_control_guard() (loopback host/origin + dashboard header + control
# token for any POST/PUT/PATCH/DELETE under /api/).
#
# Checkpoint scope reminder (see agentic_history.py docstring): a checkpoint
# is a TRANSCRIPT BOOKMARK (turn index + timestamp + optional label), never a
# filesystem snapshot/undo -- this hub has no sandboxing/versioning of the
# project folder's actual files.
# ---------------------------------------------------------------------------

def _forget_conversation_state(session_id, project_dir=None):
    """Everything else a conversation owns, dropped with its transcript --
    on delete and when history retention prunes it.

    Memory (memory/<id>.json and any in-flight marker) and the per-session
    brief written INTO the project folder used to outlive the conversation
    forever. Project and global memory are not the conversation's and stay."""
    try:
        memory.forget(session_id)
    except Exception:                                            # noqa: BLE001
        pass
    try:
        agentic_chat.remove_task_brief(project_dir, session_id)
    except Exception:                                            # noqa: BLE001
        pass
    _forget_agent_recap(session_id)


def _forget_agent_recap(session_id):
    """Drop an /agent session's rolling compaction recap ('agent:<sid>').
    On delete it would sit on disk for 30 days; on rewind _multi_context and
    _rolling_recap handed the next turn a recap of work that was undone."""
    try:
        if session_id:
            _recap_store.delete(ctxwin.conversation_key(agent_sid=session_id))
    except Exception:                                            # noqa: BLE001
        pass


agentic_history.add_forget_hook(_forget_conversation_state)


def _recover_memory_state():
    """At boot, once this process owns the state dir: a turn the last process
    died in the middle of becomes a stopping place (memory.recover_inflight),
    and memory no conversation refers to any more is pruned on history's own
    retention clock. Never raises."""
    try:
        back = memory.recover_inflight()
        if back:
            _log.info("filed %d turn(s) cut short by the last shutdown as "
                      "resumable", len(back))
            # Only the conversations that asked to continue by themselves do;
            # the rest wait for the owner's Continue.
            threading.Thread(target=lambda: (time.sleep(20), _auto_continue_turns(back)),
                             daemon=True, name="auto-continue").start()
    except Exception as exc:                                     # noqa: BLE001
        _log.warning("could not recover in-flight turns: %s", exc)
    try:
        gone = memory.prune_orphans(agentic_history.known_session_ids(),
                                    max_age_days=agentic_history.RETENTION_DAYS)
        if gone:
            _log.info("pruned memory of %d conversation(s) that no longer exist",
                      len(gone))
    except Exception as exc:                                     # noqa: BLE001
        _log.warning("could not prune orphaned memory: %s", exc)


@app.route("/api/agent/history", methods=["GET"])
def api_agent_history_list():
    limit = request.args.get("limit", "50")
    try:
        limit = int(limit)
    except (TypeError, ValueError):
        limit = 50
    return jsonify({"conversations": agentic_history.list_conversations(limit=limit)})


@app.route("/api/agent/history/<session_id>", methods=["GET"])
def api_agent_history_get(session_id):
    conv = agentic_history.get_conversation(session_id)
    if conv is None:
        return jsonify({"error": "No such conversation."}), 404
    return jsonify(conv)


@app.route("/api/agent/history/<session_id>/title", methods=["POST"])
def api_agent_history_set_title(session_id):
    """Rename a conversation. The auto-title is a guess from the first message,
    so correcting it has to be possible."""
    body = request.get_json(force=True, silent=True)
    if not isinstance(body, dict) or not isinstance(body.get("title"), str):
        return jsonify({"error": "Pass {\"title\": str}."}), 400
    title = agentic_history.set_title(session_id, body["title"])
