def api_clis():
    return jsonify([_cli_row(e) for e in CLI_REGISTRY])


@app.route("/api/chains", methods=["GET", "POST", "DELETE"])
def api_chains():
    """Named fallback chains: an ORDER the user asserts.

    Distinct from the category buttons, which are a SET used to filter what
    routing may consider while leaving the benchmark to order it. A chain says
    "try this exact model, then that one", which is the only way to express "I
    know this pairing works for my project".

    It is a preference, not a cage: the ordinary chain still follows, so a chain
    whose models are all rate-limited degrades to normal routing instead of
    failing. One that could dead-end would be worse than none, because it would
    fail exactly when everything is busiest."""
    if request.method == "GET":
        chains = _named_chains()
        return jsonify({"chains": [
            {"name": n,
             "models": ids,
             # Which entries are actually usable right now: a chain saved months
             # ago can name models a provider has since withdrawn.
             "live": [p + "/" + m for p, m in _chain_entries(n)]}
            for n, ids in sorted(chains.items())]})

    body = request.get_json(force=True, silent=True) or {}
    name = str(body.get("name") or "").strip().lower()
    if not name:
        return jsonify({"error": "'name' is required."}), 400
    if "/" in name or name in ("auto", "best", "swarm", "crew", "team", "plan"):
        # Those already mean something as a model id; a chain shadowing one
        # would silently change what an existing client asks for.
        return jsonify({"error": "'%s' is already a model id." % name}), 400
    chains = _named_chains()
    if request.method == "DELETE":
        chains.pop(name, None)
        config.set_json(_CHAINS_KEY, chains)
        return jsonify({"ok": True, "removed": name})
    models = body.get("models")
    if not isinstance(models, list) or not models:
        return jsonify({"error": "'models' must be a non-empty list of '<provider>/<model>' ids."}), 400
    ids = [str(m).strip() for m in models if isinstance(m, str) and m.strip()]
    if not ids:
        return jsonify({"error": "'models' held no usable ids."}), 400
    chains[name] = ids
    config.set_json(_CHAINS_KEY, chains)
    return jsonify({"ok": True, "name": name, "models": ids,
                    "live": [p + "/" + m for p, m in _chain_entries(name)]})


@app.route("/api/model-speed", methods=["GET"])
def api_model_speed():
    """Measured speed per model: p50/p95 total, and p50/p95 time-to-first-token.

    Separate from /api/models because it answers a different question. The
    catalog says what exists and how it is ranked; this says how it has actually
    behaved on this machine, which is the only place that evidence lives.

    Models with no samples yet are omitted rather than reported as zero -- an
    unmeasured model is not a fast one."""
    rows = []
    with _outcome_lock:
        keys = set(_speed) | set(_ttft)
    for pid, model in sorted(keys):
        prof = _speed_profile(pid, model)
        if not prof["samples"] and not prof["ttft_samples"]:
            continue
        prof.update({"id": pid + "/" + model, "provider": pid, "model": model})
        rows.append(prof)
    # Slowest first: the reason to look at this page is to find what is hurting.
    rows.sort(key=lambda r: (r["p95_ms"] or r["ttft_p95_ms"] or 0), reverse=True)
    return jsonify({"models": rows, "sample_cap": _SPEED_SAMPLES,
                    "note": "measured since the hub last started"})


@app.route("/api/response-cache", methods=["GET", "POST"])
def api_response_cache():
    """The response cache's switch and its counters.

    Same reasoning as /api/ollama: off by default is a real decision, but
    reaching it should not mean editing a JSON file."""
    if request.method == "POST":
        body = request.get_json(force=True, silent=True) or {}
        if body.get("clear"):
            respcache.clear()
        want = body.get("enabled")
        if want is not None:
            if not isinstance(want, bool):
                return jsonify({"error": "'enabled' must be true or false."}), 400
            config.set_flag("response_cache", want)
        ttl = body.get("ttl")
        if ttl is not None:
            try:
                config.set_value("response_cache_ttl", str(max(30, int(ttl))))
            except (TypeError, ValueError):
                return jsonify({"error": "'ttl' must be a number of seconds."}), 400
    st = respcache.stats()
    st["enabled"] = config.get_flag("response_cache", False)
    st["ttl"] = _cache_ttl()
    return jsonify(st)


@app.route("/api/ollama", methods=["GET", "POST"])
def api_ollama():
    """The Ollama surface's on/off switch, as a control endpoint.

    It exists because "set the ollama_api flag" is not an answer anyone should
    have to act on. The surface is off by default for a real reason -- it is an
    extra, auth-less-by-default shape on the control port -- but "off by
    default" and "hidden behind a config file" are different things, and only
    the first one was intended."""
    if request.method == "POST":
        body = request.get_json(force=True, silent=True) or {}
        want = body.get("enabled")
        if not isinstance(want, bool):
            return jsonify({"error": "'enabled' must be true or false."}), 400
        config.set_flag("ollama_api", want)
    enabled = _ollama_enabled()
    key = config.get_local_api_key()
    return jsonify({
        "enabled": enabled,
        # Ollama clients ask for a HOST, not a /v1 base: they append /api/... on
        # their own. Handing them the /v1 URL is the single most common way to
        # get "connection refused" out of an otherwise correct setup.
        "base_url": "http://127.0.0.1:%d" % PORT,
        "openai_base_url": "http://127.0.0.1:%d/v1" % PORT,
        "api_key": key or "",
        "key_required": bool(key),
        "paths": sorted(_OLLAMA_ONLY_PATHS | _OLLAMA_SHARED_PATHS),
        "models": ["auto", "best", "swarm"],
    })


@app.route("/api/antigravity", methods=["GET"])
def api_antigravity():
    """Antigravity is NOT in CLI_REGISTRY on purpose.

    Every card there offers Connect / Disconnect / Test, which all assume the
    hub can write the tool's config and then prove the round trip. For
    Antigravity that would be a lie in both directions: its launcher has no
    headless exec mode to test through, and its built-in agent has no provider
    setting to write (see antigravity.py for what was actually measured). So it
    gets its own card that offers the two things that ARE real -- detection and
    a genuine one-click extension install -- and states the manual step instead
    of pretending it away."""
    info = antigravity.detect()
    key = config.get_local_api_key() or "free-llm-hub"
    info["connect"] = {
        "base_url": "http://127.0.0.1:%d/v1" % PORT,
        "api_key": key,
        "model": "auto",
        "models": ["auto", "best", "swarm"],
    }
    return jsonify(info)


@app.route("/api/antigravity/install", methods=["POST"])
def api_antigravity_install():
    body = request.get_json(force=True, silent=True) or {}
    ok, message = antigravity.install_extension(body.get("extension"))
    payload = {"ok": ok, "message": message}
    payload.update(antigravity.detect())
    return jsonify(payload), (200 if ok else 400)


@app.route("/api/hub-mode", methods=["GET", "POST"])
@app.route("/api/lifecycle/hub", methods=["GET", "POST"])
def api_hub_mode():
    if request.method == "GET":
        return jsonify(_hub_mode_payload())
    body = request.get_json(force=True, silent=True)
    if not isinstance(body, dict):
        return jsonify({"error": "invalid JSON body"}), 400
    desired = body.get("desired")
    if desired is None and isinstance(body.get("enabled"), bool):
        desired = "on" if body["enabled"] else "off"
    if desired not in ("on", "off"):
        return jsonify({"error": "desired must be 'on' or 'off'"}), 400
    if "revision" not in body:
        return jsonify({"error": "revision is required"}), 400
    if not _hub_switch_lock.acquire(blocking=False):
        return jsonify({"error": "a hub mode transition is already running",
                        "state": config.get_hub_mode_state()}), 409
    try:
        current = config.get_hub_mode_state()
        try:
            expected = int(body["revision"])
        except (TypeError, ValueError):
            return jsonify({"error": "revision must be an integer"}), 400
        if expected != current["revision"]:
            return jsonify({"error": "hub state changed; reload and retry",
                            "current_revision": current["revision"], "state": current}), 409
        if current.get("desired") == desired and current.get("phase") == desired:
            return jsonify(_hub_mode_payload())
        try:
            if desired == "on":
                _bulk_hub_on(expected)
            else:
                _bulk_hub_off(expected)
        except config.RevisionConflict as exc:
            return jsonify({"error": "hub state changed during transition",
                            "current_revision": exc.current_revision,
                            "state": config.get_hub_mode_state()}), 409
        except Exception as exc:
            _log.error("Hub mode transition failed: %s", _sanitize(str(exc)))
            return jsonify({"error": _sanitize(str(exc)) or "hub transition failed",
                            "state": config.get_hub_mode_state()}), 500
        return jsonify(_hub_mode_payload())
    finally:
        _hub_switch_lock.release()


@app.route("/api/clis/<cid>/autofix", methods=["POST"])
def api_cli_autofix(cid):
    entry = _get_cli_entry(cid)
    if not entry:
        return jsonify({"error": "unknown CLI '%s'" % cid}), 404
    key = config.get_local_api_key() or "free-llm-hub"
    base_root = "http://127.0.0.1:%d" % PORT
    base_v1 = base_root + "/v1"
    strategy = entry.get("autofix")
    if not strategy:
        # No autofix strategy. For CLIs that AREN'T wired via env vars (gemini is
        # protocol-incompatible; llm uses extra-openai-models.yaml + `llm keys`),
        # handing back OPENAI_* commands is misleading -> return the note only.
        if entry["id"] in _ENVLESS_CLIS:
            return jsonify({
                "ok": False, "manual": True,
                "note": entry.get("manual_note", "See this CLI's setup details."),
            })
        # env-based but uncertain (e.g. cursor-agent): never touch a global shell
        # profile — hand back copy-paste commands + a CLI-specific note instead.
        model = _first_free_model_id() or _suggested_model()
        env = _manual_env(entry, key, base_root, base_v1, model)
        return jsonify({
            "ok": False, "manual": True,
            "commands": _env_commands(env),
            "note": entry.get("manual_note", "Configure this CLI manually with the env vars above."),
        })
    model = _first_free_model_id()
    if not model:
        return jsonify({"ok": False, "reason": "no free model configured yet — add a provider key first"})
    fixer = _AUTOFIXERS.get(strategy)
    if not fixer:
        return jsonify({"ok": False, "reason": "no autofix strategy '%s'" % strategy})
    try:
        result = fixer(entry, key, base_root, base_v1, model)
    except OSError as exc:
        return jsonify({"ok": False, "reason": _sanitize("could not write config: %s" % exc)})
    if result.get("ok"):
        _mark_hub_mode_unmanaged()
        if entry.get("id") == "codex":
            _refresh_codex_catalog_soon()
    return jsonify(result)


@app.route("/api/clis/<cid>/disconnect", methods=["POST"])
def api_cli_disconnect(cid):
    """Revert a CLI to its NORMAL (non-hub) config. For an auto-fixable CLI this
    restores the .freehub-bak backup (the user's original file) or, if autofix
    created a fresh file, strips only the hub keys we added. Manual-only CLIs get
    copy-paste unset commands instead. Never 500s; never logs a secret."""
    entry = _get_cli_entry(cid)
    if not entry:
        return jsonify({"error": "unknown CLI '%s'" % cid}), 404
    strategy = entry.get("autofix")
    # Reverters are resolved by autofix strategy first, then by CLI id — so a CLI
    # with no autofix strategy but a real config surface (e.g. `llm`'s YAML) can
    # still register a disconnecter under its id.
    reverter = (_DISCONNECTERS.get(strategy) if strategy else None) \
        or _DISCONNECTERS.get(entry["id"])
    if not reverter:
        # Manual-only (protocol-incompatible / uncertain): we never wrote this
        # CLI's config, so we can't safely revert it — guide the user.
        if entry["id"] in _ENVLESS_CLIS:
            # Never wired via OPENAI_*/ANTHROPIC_* env vars -> no bogus unset block.
            return jsonify({
                "ok": False, "manual": True,
                "note": (entry.get("manual_note")
                         or "This CLI isn't wired through environment variables; nothing to unset."),
            })
        # An env-only CLI (cursor-agent, ...): the persistent var IS its wiring.
        # Release it like any other Disconnect -- removed only when no other
        # still-connected tool relies on it.
        env = _env_release_on_disconnect(entry)
        if env["removed"] or env["kept"]:
            env_notes = _env_disconnect_notes(entry, env)
            row = _cli_row(entry)
            out = {"ok": True, "connected": bool(row.get("connected")), "env": env,
                   "env_note": " ".join(env_notes), "note": " ".join(env_notes)}
            if row.get("connected"):
                out.update({"still_connected": True,
                            "still_connected_via": row.get("connect_method"),
                            "still_connected_detail": row.get("detail")})
            return jsonify(out)
        return jsonify({
            "ok": False, "manual": True,
            "note": ("This CLI was configured manually; remove the hub env vars/config "
                     "yourself"),
            "commands": _env_unset_commands(entry),
        })
    try:
        result = reverter(entry)
    except OSError as exc:
        return jsonify({"ok": False, "reason": _sanitize("could not restore config: %s" % exc)})
    _mark_hub_mode_unmanaged()
    # Shared env vars this CLI reads: removed from the persistent user
    # environment only when no OTHER still-connected tool relies on them,
    # otherwise left in place and named (see _env_release_on_disconnect).
    env = _env_release_on_disconnect(entry)
    # VERIFY THE REVERT. Recompute freshly from disk/env so 'connected' reflects
    # reality, and if the CLI is STILL wired to the hub, say so instead of
    # reporting a clean success. This is the honest answer to "I clicked
    # Disconnect, it said done, but the CLI is still connected". A shared var
    # alone no longer makes a config-wired CLI "connected" (its own config is
    # the connection); it is reported under `env` with the tools sharing it.
    row = _cli_row(entry)
    connected = bool(row.get("connected"))
    out = {
        "ok": True,
        "restored_from_backup": bool(result.get("restored_from_backup")),
        "wrote_path": result.get("wrote_path"),
        "restart_hint": result.get("restart_hint"),
        "connected": connected,
    }
    if "changed" in result:
        out["changed"] = bool(result["changed"])
    notes = []
    if result.get("catalog") == "deleted":
        notes.append("The hub's models and effort tiers were removed from %s's "
                     "/model picker." % entry.get("name", entry["id"]))
    elif result.get("catalog") == "restored":
        notes.append("%s's own /model catalog was restored." % entry.get("name", entry["id"]))
    if result.get("catalog"):
        out["catalog"] = result["catalog"]
    # Deliberately KEPT (documented design): the hub's MCP server entry, i.e.
    # the crew tools. It adds no model, effort or mode -- it is reported so the
    # user knows it is there and where to remove it.
    mcp_path = _hub_mcp_kept(entry["id"])
    if mcp_path:
        out["mcp_kept"] = _short(mcp_path)
        notes.append("The hub's MCP tool server (crew tools) stays registered in %s; "
                     "remove it under Hub controls > MCP servers if you do not want it."
                     % _short(mcp_path))
    env_notes = _env_disconnect_notes(entry, env)
    if env_notes:
        effect = _ENV_EFFECT.get(entry["id"])
        if effect and (env["kept"] or env["session"]) and _cli_config_wired(entry):
            env["effect"] = effect[0].upper() + effect[1:] + "."
        out["env"] = env
        out["env_note"] = " ".join(env_notes)
        notes.extend(env_notes)
        if env["session"] or (env["kept"] and not userenv.available()):
            # Nothing the hub can remove itself -- hand back the commands.
            out["commands"] = _env_unset_commands(
                entry, env["session"] + [k["name"] for k in env["kept"]])
    if notes:
        out["note"] = " ".join(notes)
    if connected:
        method = row.get("connect_method")
        out["still_connected"] = True
        out["still_connected_via"] = method
        out["still_connected_detail"] = row.get("detail")
        if method == "env":
            # Only an env-only CLI (aider, llm, ...) can still be connected by a
            # var: it has no other wiring, and the var was kept because another
            # connected tool relies on it.
            out["note"] = " ".join(
                ["%s's config was reverted, but it still reaches the hub through an "
                 "environment variable (%s)." % (entry.get("name", entry["id"]),
                                                 row.get("detail") or "an env var")]
                + env_notes)
            if not out.get("commands") and not env["kept"]:
                out["commands"] = _env_unset_commands(entry)
        else:
            out["note"] = (
                "Config reverted, but %s still reports as connected (%s). Nothing else "
                "was changed — check that path manually."
                % (entry.get("name", entry["id"]), row.get("detail") or "unknown source"))
    return jsonify(out)


@app.route("/api/clis/<cid>/instructions", methods=["GET"])
def api_cli_instructions(cid):
    entry = _get_cli_entry(cid)
    if not entry:
        return jsonify({"error": "unknown CLI '%s'" % cid}), 404
    key = config.get_local_api_key() or "free-llm-hub"
    model = _first_free_model_id() or _suggested_model()
    base_root = "http://127.0.0.1:%d" % PORT
    base_v1 = base_root + "/v1"
    snippets = _connect_snippets()
    # Some CLIs are NOT wired via OPENAI_*/ANTHROPIC_* env vars (codex -> config.toml,
    # gemini -> incompatible, llm -> extra-openai-models.yaml). For those, an env
    # block / OpenAI snippet is misleading — show the note + config path only.
    env_based = entry["id"] not in _ENVLESS_CLIS
    steps = []
    if entry.get("autofix"):
        steps.append("Auto-fix (recommended): POST /api/clis/%s/autofix to write %s for you "
                     "(a .freehub-bak backup is made first)." % (entry["id"], _short(entry.get("write_path", "the CLI config"))))
    if env_based:
        steps.append("Manual: set the environment variables in `env` below, then restart the CLI.")
    else:
        steps.append("Manual: follow the note below — this CLI is not wired through "
                     "OPENAI_*/ANTHROPIC_* environment variables.")
    if entry.get("manual_note"):
        steps.append(entry["manual_note"])
    steps.append("Verify: run `%s` and confirm it answers via this hub using %s." % (entry["bins"][0], model))
    # Env block is resolved with the SAME model id the auto-fixers write, and the
    # cross-platform commands (setx AND export) are emitted here too so a Windows
    # user on the manual path isn't handed a unix-only `export`.
    env = _manual_env(entry, key, base_root, base_v1, model) if env_based else {}
    out = {
        "steps": steps,
        "env": env,
        "snippet_openai": snippets["openai"] if env_based else None,
        "snippet_anthropic": snippets["claude_code"] if env_based else None,
    }
    if env_based:
        out["commands"] = _env_commands(env)
        # These `setx` lines are the ONLY way a hub URL ever lands in the
        # persistent environment: record this CLI as relying on each base-URL
        # var, so a later Disconnect of ANOTHER tool does not remove it.
        for name, val in env.items():
            if _points_at_hub(val):
                _env_record_owner(name, entry["id"])
    return jsonify(out)


# ---------------------------------------------------------------------------
# OpenAI-compatible gateway
# ---------------------------------------------------------------------------

@app.route("/v1/models", methods=["GET"])
def v1_models():
    agg = aggregated_models()
    # 'auto' is a REAL, selectable id here (it is what _is_orchestrate accepts) and
    # is listed FIRST so a CLI that validates its configured model — or just takes
    # the first row as its default — lands on the orchestrator instead of being
    # pinned to one provider's model for every request.
    # Every mode the hub serves as a model, from the one shared list -- 'auto'
    # first so a CLI that takes row 1 as its default lands on the orchestrator
    # rather than being pinned to one provider for every request.
    virtual = [{"id": mid, "object": "model", "created": 0,
                "owned_by": "free-llm-hub",
                "display_name": _virtual_model_label(mid)}
               for mid in _virtual_model_ids()]
    rows = [_codex_model_entry(m) for m in agg]
    return jsonify({"object": "list",
                    "data": virtual + rows,
                    "models": [dict(v, slug=v["id"]) for v in virtual]
                              + [dict(_codex_model_entry(m), slug=m["id"]) for m in agg]})


# Model row for /v1/models. `display_name` is additive and harmless for every
# client. We deliberately do NOT try to mirror Codex's full, strict model-manager
# schema (reasoning-effort presets, capability structs, ...): it changes across
# Codex versions, so chasing it here would break on every Codex update. Codex is
# therefore best pointed at its NATIVE subscription for the agentic Chat CLI (the
# hub's free models remain great for the Chat/Test playground + general CLI use,
# which use /v1/chat/completions and don't hit this strict schema).
def _codex_model_entry(m):
    return {
        "id": m["id"],
        "object": "model",
        "created": 0,
        "owned_by": m["provider"],
        "display_name": m["id"],
    }


_MISSING = object()  # sentinel: "no pre-read first item" for the peeked streamers


def _chain_first(first, iterator):
    """Yield `first` (unless it's the _MISSING sentinel) then the rest of
    `iterator` — used to prepend a first item pulled during the first-byte peek
    back onto the stream so no chunk is lost."""
    if first is not _MISSING:
        yield first
    for item in iterator:
        yield item


def _peek_first_chunk(iterator, deadline_s):
    """First-byte peek for streaming fallback (#4). Pull the FIRST item from an
    already-created `iterator` (resp.iter_content(...) for raw SSE, or
    resp.iter_lines(...) for the translating parsers) in a daemon worker thread
    bounded to ~deadline_s. Returns (ok, first):
      ok=True  -> `first` is the first item; the upstream is responsive. The worker
                  has finished (join returned), so the caller keeps iterating the
                  SAME iterator sequentially — no concurrency, no lost/duplicated
                  item.
      ok=False -> no usable first byte: the read timed out (slow/hung provider), the
                  stream ended immediately (StopIteration), or the read errored. The
                  caller should resp.close() and fall through to the next provider.
    A worker still blocked past the deadline is abandoned (daemon); the caller's
    resp.close() unblocks/ends its read. requests' STREAM_IDLE_TIMEOUT read timeout
    is the hard backstop if the tighter join deadline is ever exceeded."""
    box = {}

    def _worker():
        try:
            box["v"] = next(iterator)
            box["ok"] = True
        except StopIteration:
            box["ok"] = False
        except Exception:  # requests read timeout / connection reset / etc.
            box["ok"] = False

    t = threading.Thread(target=_worker, daemon=True)
    t.start()
    t.join(deadline_s)
    if t.is_alive() or not box.get("ok"):
        return False, None
    return True, box.get("v")


# HOW LONG THE CHAIN MAY WALK BEFORE THE CLIENT GIVES UP ON HEADERS.
#
# A streaming request deliberately withholds its 200 until a hop produces real
# content, so a hop that turns out to be dead can still be replaced by the next
# one. That is right, and it makes time-to-first-HEADER unbounded: MAX_HOPS(6) x
# STREAM_SLOW_BIG_PEEK_TIMEOUT(90) is 540 seconds of silence on the socket.
#
# REPORTED 2026-09-05 from opencode: "Provider response headers timed out after
# 300000ms" -- and it does not retry, it ends the turn. Every OpenAI-shaped
# client has such a timeout; opencode's is 5 minutes, which the chain can
# legitimately exceed while doing exactly what it was designed to do.
#
# So the walk gets a budget UNDER that. Once it is spent the chain stops trying
# new hops and returns its error properly, as an HTTP status the client can see
# and retry -- instead of holding a socket open past the point where anyone is
# still listening. A 503 that arrives is worth more than a better answer that
# does not.
#
# Only for STREAMING requests: a buffered one has already sent nothing and its
# caller is waiting on a body, not on headers.
_STREAM_HEADER_BUDGET = 240      # seconds


# HOW LONG ONE HOP MAY WAIT FOR RESPONSE HEADERS.
#
# requests applies its read timeout to the wait for HEADERS as well as to the
# gaps between chunks, so STREAM_IDLE_TIMEOUT was doing both jobs -- and at 280s
# it was LONGER THAN THE WHOLE CHAIN'S BUDGET of 240s below. A provider that
# accepts the connection and then goes quiet therefore burned the entire budget
# in hop one, and the chain stopped having tried exactly one model.
#
# MEASURED 2026-09-05 against nvidia directly, bypassing the hub:
#     996 bytes      ReadTimeout at 300.6s
#     840,676 bytes  ReadTimeout at 301.4s
# Nothing came back at any size -- it was not the 200K-token payloads, the
# provider was simply not answering. The hub kept electing it primary (it
# benchmarks 134) and waiting, which is the "stopped after 240s" half of the
# reported 503s.
#
# The control says the cap is safe. Time-to-headers where the provider works:
#     groq @ 6K 1.11s   openrouter @ 60K 2.73s   tokenrouter @ 60K 10.83s
# Worst healthy case 10.8s, so 60s leaves five times the margin while cutting a
# dead hop from 280s to 60 -- four hops inside the budget instead of one.
#
# STREAM_IDLE_TIMEOUT is deliberately NOT lowered: it governs the gaps between
# chunks, and once content is flowing the client has its headers and this budget
# no longer applies. A slow reasoning model keeps its long leash mid-answer.
_STREAM_HEADER_WAIT = 60         # seconds


def _post_with_header_deadline(deadline, post, **kw):
    """`post(**kw)` bounded by a wall-clock deadline for the RESPONSE HEADERS.

    Same daemon-worker discipline as _dispatch_chat_with_deadline and
    _peek_until_content: the call keeps running against its own socket timeout
    and is simply not waited on any longer. It is abandoned, not cancelled --
    Python cannot cancel a blocking socket read -- so the connection is released
    when that timeout expires rather than immediately. That costs a socket for a
    while; waiting for it costs the whole turn.

    Raises ReadTimeout when the deadline passes, so the caller's existing
    `except requests.RequestException` rotates the key and walks on exactly as
    it does for any other dead hop."""
    box = {}

    def _call():
        try:
            box["resp"] = post(**kw)
        except BaseException as exc:                             # noqa: BLE001
            box["exc"] = exc

    # clientgone.bind: a plain thread starts with an empty context, and the
    # upstream call it makes must still be tracked for the request's cancel.
    hop = clientgone.child("header-wait")
    t = threading.Thread(target=clientgone.run_as, args=(hop, _call), daemon=True)
    t.start()
    if clientgone.join(t, deadline):
        hop.cancel("client disconnected")
        raise clientgone.ClientGone("the client disconnected")
    if t.is_alive():
        hop.cancel("no response headers in time")   # cut, not left open
        raise requests.exceptions.ReadTimeout(
            "no response headers in %ss" % deadline)
    if "exc" in box:
        raise box["exc"]
    return box.get("resp")


def _header_budget_spent(started):
    """True once a streaming chain walk has run long enough to risk the
    client's header timeout."""
    try:
        return (time.monotonic() - started) >= _STREAM_HEADER_BUDGET
    except Exception:                                            # noqa: BLE001
        return False


# SLOWNESS FROM MEASUREMENT. _SLOW_MODEL_RE only knows names: MEASURED
# 2026-09-27, pollinations "openai-fast" (really gpt-oss-20b behind an alias)
# has a TTFT p50 of 34 s -- right at the flat 35 s peek -- yet matched nothing,
# so about half its healthy answers were cut as "timeout". With enough TTFT
# samples the MEASUREMENT decides: p50 at/over _SLOW_TTFT_MS is slow; p95
# under it (even the slow tail is quick) is fast, whatever the name says. In
# between, or with too few samples, the name regex stays the fallback. (TTFT
# is recorded only for hops that reached content, so a lone fast sample set
# never overrules the regex on its own median -- hence the p95 rule.)
_SLOW_TTFT_MS = STREAM_CONTENT_PEEK_TIMEOUT * 1000.0 / 2      # 17.5 s
_SLOW_TTFT_MIN_SAMPLES = 5


def _is_slow_model(pid, model):
    """True when (pid, model) is slow to its first content token: by measured
    TTFT when there are >= _SLOW_TTFT_MIN_SAMPLES samples, else by name."""
    by_name = bool(_SLOW_MODEL_RE.search((model or "").lower()))
    if not pid or not model:
        return by_name
    try:
        with _outcome_lock:
            ttfts = list(_ttft.get((pid, model)) or [])
        if len(ttfts) >= _SLOW_TTFT_MIN_SAMPLES:
            if _percentile(ttfts, 50) >= _SLOW_TTFT_MS:
                return True
            if _percentile(ttfts, 95) < _SLOW_TTFT_MS:
                return False
    except Exception:                                            # noqa: BLE001
        pass
    return by_name


def _stream_peek_timeout(model, est, pid=None):
    """Adaptive deadline for _peek_until_content: how long to wait for a stream's
    first REAL content before falling through to the next hop. A fast model on a
    small request answers in seconds, so a >35s silence means a hung provider —
    but a slow/reasoning model (_is_slow_model: measured TTFT, else
    _SLOW_MODEL_RE) or a big agentic prompt (Codex's
    15-40K tokens + tool schemas) legitimately needs longer before the first
    byte, and killing that hop abandoned HEALTHY strong models mid-chain."""
    slow = _is_slow_model(pid, model)
    big = bool(est) and est >= STREAM_BIG_REQUEST_TOKENS
    if big and not slow and _SLOW_MODEL_RE.search((model or "").lower()):
        # TTFT samples are size-blind (mostly small chats), so a measured
        # "fast" may ADD nothing here: it never clears a reasoning model's
        # name-based slowness on a big prompt.
        slow = True
    if slow and big:
        return STREAM_SLOW_BIG_PEEK_TIMEOUT + _huge_prefill_allowance(est)
    if slow or big:
        return STREAM_SLOW_PEEK_TIMEOUT + _huge_prefill_allowance(est)
    return STREAM_CONTENT_PEEK_TIMEOUT


# PREFILL GROWS WITH THE PROMPT. MEASURED live 2026-09-27 on a 160K-token
# history (~220K real tokens): nvidia/z-ai/glm-5.3 answered a buffered request
# in 113-163s, but the same hop STREAMED was cut at the flat 90s peek ("timeout
# (200 but no content)") -- and the next hop had to upload and prefill the whole
# history again, so the request hit its 240s deadline with nothing. Past
# STREAM_HUGE_REQUEST_TOKENS the peek grows by one second per
# STREAM_PREFILL_TOKENS_PER_S tokens, capped; the chain clock still bounds it.
STREAM_HUGE_REQUEST_TOKENS = 48000
STREAM_PREFILL_TOKENS_PER_S = 2000
STREAM_PREFILL_EXTRA_CAP = 90       # seconds


def _huge_prefill_allowance(est):
    try:
        extra = (int(est or 0) - STREAM_HUGE_REQUEST_TOKENS) / float(STREAM_PREFILL_TOKENS_PER_S)
    except (TypeError, ValueError):
        return 0
    return int(max(0, min(STREAM_PREFILL_EXTRA_CAP, extra)))


# ---------------------------------------------------------------------------
# ONE WALL CLOCK PER REQUEST.
#
# Every timeout above is PER SOMETHING: per recv (CHAT_READ_TIMEOUT), per gap
# between chunks (STREAM_IDLE_TIMEOUT), per hop's first content (the peek), per
# hop's headers (_STREAM_HEADER_WAIT). None of them bounds the request, and they
# compound: MAX_HOPS x a 300s per-recv read that a trickling provider resets on
# every byte has no ceiling at all.
#
# MEASURED in a live sweep (before this existed):
#   "What is N plus 1? Answer with only the number."  -> 180s client timeout in
#       the reasoning / seo / specialist category modes
#   "Use the add tool to add 17 and 25"               -> 82-112s in auto/best/
#       coding/fast, and 962s with coding-max; the client's 180s read timeout
#       never fired because bytes kept trickling, so the hub held the turn ~16
#       minutes for an answer of "42".
#
# So one deadline, set when routing starts, that every hop, every peek and a
# committed stream's non-progress all answer to. Setting
# `request_deadline_seconds` (default 240, 0 = unbounded). 240 matches
# _STREAM_HEADER_BUDGET: a client that gives up on headers at ~5 minutes must
# see a clean status before then, not a socket that is still "working".
# Pipelines (swarm / crew / multi) have their own cap, swarm_max_seconds, and do
# not start this clock; the single-model fallback behind a failed pipeline does.
_REQUEST_DEADLINE_DEFAULT = 240
# Once the deadline has passed, a COMMITTED stream may continue only while it
# is actually delivering visible content or tool calls -- cutting off a model
# that is mid-way through writing a file would throw away real work the client
# has already half-received. A keepalive, a reasoning-only delta or this much
# silence ends it; so does _POST_DEADLINE_MAX however healthy it looks, so
# nothing can hold a turn open indefinitely.
_POST_DEADLINE_IDLE = 20         # seconds of no visible content past the deadline
_POST_DEADLINE_MAX = 600         # absolute ceiling past the deadline
# A TRIVIAL SMALL turn ("what is 5+1", "use the add tool on 17 and 25") has an
# answer a working model produces in seconds. The adaptive peek (35/60/90s) and
# _STREAM_HEADER_WAIT (60s) are sized for Codex-sized prompts; applied to a
# one-liner they let one hung hop eat a minute or more before the next model --
# which then answers in five seconds -- is even tried. That is the 82-112s
# tool turn: hop one's full peek budget plus hop two's actual answer.
# Headers AND first content for the hop must arrive inside this budget.
_TRIVIAL_HOP_BUDGET = 25         # fast model
_TRIVIAL_SLOW_HOP_BUDGET = 45    # slow / reasoning model (_SLOW_MODEL_RE)
# ...and those two are now CEILINGS, not the budget. MEASURED 2026-09-26: with
# a flat 25s, "What is N plus 1?" still took 32-65s on auto/best/max/coding --
# a hop that normally answers in 2s was given 25s to not answer, and then the
# next one was. A hop with a MEASURED history gets max(_ADAPTIVE_HOP_FLOOR,
# _ADAPTIVE_HOP_MULT x its p90) for its first content; an unmeasured one keeps
# the ceiling, because there is no evidence to be tighter on.
#
# SET FROM MEASURED DATA 2026-09-27 (/api/model-speed on the live hub: 18
# models with time-to-first-content samples, 11 of them with n >= 5; plus
# perf-stats.json, 33 pairs). The snapshot and the derivations live in
# tests/test_latency_constants.py, which re-derives every number below:
#   * within-model tail p95/p50 (n >= 5, hung outliers > 10x excluded):
#     1.24 1.26 1.31 1.44 1.49 1.60 2.21 2.93 3.31 3.33 -> median 1.55,
#     max 3.33.
#     _ADAPTIVE_HOP_MULT must cover the heaviest HEALTHY tail even for a
#     bimodal model whose p90 sits near its p50: 3.33 rounds up to 3.5 (was
#     3.0, which covers glm-4.5-flash / groq qwen3.8's p95 only while their
#     p90 stays >= 1.11x their p50). Cost: a hung hop is dropped at most
#     0.5x its p90 later (nothing below the 6 s floor moves).
#     _HEDGE_DELAY_MULT = the median ratio (1.55 -> 1.5, unchanged): hedging
#     at ~a model's own p95 starts an extra call on ~1 request in 20.
#   * fastest measured class: codestral p50 1.3 s / p95 2.2 s total, ttft
#     p50 1.5 s -> _ADAPTIVE_HOP_FLOOR 6 s (~2.7x that p95) and
#     _HEDGE_DELAY_MIN 3 s (above 1.5x its p50 of 2.3 s): unchanged.
#   * ttft p95s (n >= 4, codestral's hang excluded) 12.6 15.0 15.4 18.2
#     19.0 20.7 22.2 22.5 48.2 55.1 62.3 s: _TRIVIAL_HOP_BUDGET 25 s covers
#     8 of 11 on MIXED traffic (Codex-sized prompts included; a trivial turn
#     is faster). The three above it have p50s of 14-34 s, which
#     _SIMPLE_SLOW_MS already moves out of the speed-first pick. Unchanged.
#   * no measured model matches _SLOW_MODEL_RE, so _TRIVIAL_SLOW_HOP_BUDGET
#     (45 s) has no data behind a change. Unchanged.
#   * fleet ttft: median of per-model p50s 12.1 s -> _SIMPLE_SLOW_MS 10 s
#     stays the "not speed-first" line (9 of 18 models are faster). Unchanged.
_ADAPTIVE_HOP_FLOOR = 6.0        # seconds: never tighter than this
_ADAPTIVE_HOP_MULT = 3.5         # x the measured p90 time to first content
_ADAPTIVE_MIN_SAMPLES = 3        # never judge a hop on one or two requests
# HEDGING a trivial, tool-free, small turn: when the hop has produced nothing
# after _HEDGE_DELAY_MULT x its p50 (min _HEDGE_DELAY_MIN; _HEDGE_DELAY_UNKNOWN
# with no history), the next candidate starts IN PARALLEL and the first valid
# answer wins. At most ONE extra call per request, and only before a byte has
# reached the client. The tail latency of a free fleet is one slow hop in
# five; waiting it out serially is most of the 30-65s.
_HEDGE_DELAY_MIN = 3.0
_HEDGE_DELAY_MULT = 1.5
_HEDGE_DELAY_UNKNOWN = 4.0
_HEDGE_MAX_EST = 4000            # "small": a one-liner and its system prompt
# A simple-turn candidate MEASURED slower than this is not "speed first".
_SIMPLE_SLOW_MS = 10000.0
# How long a peek keeps waiting on a hop whose visible text has STARTED but
# not yet reached the judge threshold (see _peek_until_content).
_PEEK_CONTENT_GRACE = 30.0


def _hop_samples(pid, model, stream=None):
    """The measured timing samples (ms) that describe this hop's first useful
    output: time-to-first-content for a stream, total duration for a
    non-streamed call, each falling back to the other. None while too thin."""
    try:
        with _outcome_lock:
            ttft = list(_ttft.get((pid, model)) or [])
            dur = list(_speed.get((pid, model)) or [])
        for s in ((dur, ttft) if stream is False else (ttft, dur)):
            if len(s) >= _ADAPTIVE_MIN_SAMPLES:
                return s
    except Exception:                                            # noqa: BLE001
        pass
    return None


def _adaptive_hop_budget(pid, model, ceiling, stream=None):
    """First-content budget for a trivial turn's hop: max(_ADAPTIVE_HOP_FLOOR,
    _ADAPTIVE_HOP_MULT x measured p90), never above `ceiling` (the old fixed
    budget). Unmeasured -> `ceiling`. Never raises."""
    try:
        s = _hop_samples(pid, model, stream)
        if not s:
            return ceiling
        p90 = _percentile(s, 90) / 1000.0
        return min(float(ceiling), max(_ADAPTIVE_HOP_FLOOR, _ADAPTIVE_HOP_MULT * p90))
    except Exception:                                            # noqa: BLE001
        return ceiling


def _hedge_delay(pid, model, stream=None):
    """Seconds of silence from this hop before a hedge starts the next one."""
    try:
        s = _hop_samples(pid, model, stream)
        if not s:
            return _HEDGE_DELAY_UNKNOWN
        return max(_HEDGE_DELAY_MIN, _HEDGE_DELAY_MULT * _percentile(s, 50) / 1000.0)
    except Exception:                                            # noqa: BLE001
        return _HEDGE_DELAY_UNKNOWN


def _simple_speed_rank(pid, model):
    """Sort key for the SIMPLE-turn primary, lower first: (measured to fail,
    measured slow). Both False while unmeasured, so this only ever moves a
    candidate the hub has real evidence about. Never raises."""
    try:
        sick = _chain_reliability_band(pid, model) >= 2
        ms = _measured_latency_ms(pid, model)
        if ms is None:
            with _outcome_lock:
                t = list(_ttft.get((pid, model)) or [])
            if len(t) >= _ADAPTIVE_MIN_SAMPLES:
                ms = _percentile(t, 50)
        return (sick, ms is not None and ms > _SIMPLE_SLOW_MS)
    except Exception:                                            # noqa: BLE001
        return (False, False)


def _request_deadline_seconds():
    """The configured per-request wall clock, or None for unbounded. Fails open
    to the default -- a broken setting must not silently remove the bound."""
    try:
        v = float(config.get_setting("request_deadline_seconds",
                                     _REQUEST_DEADLINE_DEFAULT))
    except Exception:                                            # noqa: BLE001
        v = float(_REQUEST_DEADLINE_DEFAULT)
    return v if v > 0 else None


# THE DEADLINE GROWS WITH THE REQUEST. MEASURED live 2026-09-27: at ~220K real
# tokens (~650 KB) ONE free hop needed 110-270 s to answer, so a request that
# was doing nothing wrong ended in a clean 504 at the flat 240 s -- the second
# hop never got the time the first one used up uploading and prefilling. Past
# LONG_DEADLINE_FROM_TOKENS the deadline gains `request_deadline_per_10k_seconds`
# per started 10K tokens, capped at `request_deadline_max_seconds`. A request
# below the threshold keeps exactly the base deadline.
#
# A STREAM keeps its stall limits: the hub withholds a stream's 200 until a hop
# produces content, and every streaming client has a ~300 s header/idle timeout
# (opencode 300 s, codex stream_idle_timeout 300 s). A stream's scaled deadline
# therefore never passes LONG_DEADLINE_STREAM_MAX, _STREAM_HEADER_BUDGET still
# stops new hops, and the post-deadline idle/max rules are unchanged.
LONG_DEADLINE_FROM_TOKENS = 60000
_REQUEST_DEADLINE_PER_10K_DEFAULT = 15       # seconds per started 10K tokens
_REQUEST_DEADLINE_MAX_DEFAULT = 600          # seconds, buffered requests
LONG_DEADLINE_STREAM_MAX = 285               # seconds, under the clients' 300


def _long_deadline_setting(key, default):
    try:
        v = float(config.get_setting(key, default))
    except Exception:                                            # noqa: BLE001
        v = float(default)
    return v if v >= 0 else float(default)


def _scaled_request_deadline(tokens=None, stream=False):
    """The request deadline for a request of `tokens` estimated tokens: the
    base (`_request_deadline_seconds`), plus the long-request allowance above
    LONG_DEADLINE_FROM_TOKENS, capped. None when unbounded. Never below the
    base, never raises."""
    base = _request_deadline_seconds()
    if not base:
        return base
    try:
        over = int(tokens or 0) - LONG_DEADLINE_FROM_TOKENS
        if over <= 0:
            return base
        per = _long_deadline_setting("request_deadline_per_10k_seconds",
                                     _REQUEST_DEADLINE_PER_10K_DEFAULT)
        cap = _long_deadline_setting("request_deadline_max_seconds",
                                     _REQUEST_DEADLINE_MAX_DEFAULT)
        if stream:
            cap = min(cap, LONG_DEADLINE_STREAM_MAX)
        steps = -(-over // 10000)                    # started 10K blocks
        return max(base, min(cap, base + per * steps))
    except Exception:                                            # noqa: BLE001
        return base


def _begin_request_deadline(tokens=None, stream=False):
    """Start this request's clock (once) and return its absolute monotonic
    deadline, or None when unbounded / outside a request.

    Idempotent within a request: /v1/responses re-enters itself for its
    transient-storm retry, and that retry is the same request to the client --
    it must not get a fresh four minutes. The clock starts at the FIRST call
    (before routing); a later call that knows the request's size may only
    EXTEND the deadline, measured from that same start (see
    _scaled_request_deadline)."""
    try:
        at = getattr(g, "hub_deadline_at", _MISSING)
        if at is _MISSING:
            secs = _request_deadline_seconds()
            g.hub_deadline_started = time.monotonic()
            at = (g.hub_deadline_started + secs) if secs else None
            g.hub_deadline_at = at
        if at is not None and tokens:
            started = getattr(g, "hub_deadline_started", None)
            secs = _scaled_request_deadline(tokens, stream)
            if started is not None and secs:
                at = max(at, started + secs)
                g.hub_deadline_at = at
        return at
    except Exception:                                            # noqa: BLE001
        return None


def _request_deadline_limit():
    """Seconds this request's deadline allows in total (for messages), or None."""
    try:
        at = getattr(g, "hub_deadline_at", None)
        started = getattr(g, "hub_deadline_started", None)
        if at is not None and started is not None:
            return at - started
    except Exception:                                            # noqa: BLE001
        pass
    return _request_deadline_seconds()


def _is_trivial_turn(messages, max_tokens, difficulty, est, pinned=False):
    """True for a SMALL turn whose ask is trivial -- the case the tight per-hop
    budget exists for. Judged on the CLASSIFIER's verdict, not the routed tier:
    best/max lifts a simple ask to medium to reach a strong model, which is
    right, but "add 17 and 25" is no less trivial for it. A creation ask is
    never trivial (see _CREATION_INTENT_RE), a big request never is (a
    Codex-sized prompt legitimately needs the long peek), and neither is a
    PINNED model: the caller named it, and a budget that walks away from it
    silently substitutes a model they did not ask for. Never raises."""
    try:
        if pinned or not est or est >= STREAM_BIG_REQUEST_TOKENS:
            return False
        if difficulty == "simple":
            return True
        if difficulty not in (None, "medium"):
            return False
        if _CREATION_INTENT_RE.search(_latest_user_text(messages) or ""):
            return False
        return _classify_difficulty(messages, max_tokens) == "simple"
    except Exception:                                            # noqa: BLE001
        return False


def _mark_turn_shape(difficulty, est, pinned=False):
    """Tell _build_chain (via `g`, the same channel the routing mode uses) that
    this turn was ROUTED as a small simple one, so the fallback chain behind the
    primary orders fast models first. Only the routed tier counts here: best/
    max asked for the strongest models and keeps the strength ordering."""
    try:
        g.hub_simple_turn = bool(not pinned and difficulty == "simple"
                                 and est and est < STREAM_BIG_REQUEST_TOKENS)
    except Exception:                                            # noqa: BLE001
        pass


def _simple_turn():
    """True while serving a turn _mark_turn_shape flagged. False outside a
    request, so probes and pipelines keep the ordinary chain order."""
    try:
        return bool(getattr(g, "hub_simple_turn", False))
    except Exception:                                            # noqa: BLE001
        return False


def _latency_rank(pid, model):
    """Sort key, lower = quicker to a useful answer. The MEASURED duration when
    there is enough evidence, else a heuristic in the same units derived from
    _speed_score, so a measured-fast model and a guessed-fast one compare."""
    try:
        ms = _measured_latency_ms(pid, model)
        if ms is None:
            ms = (100.0 - _speed_score(pid, model)) * 1000.0
        return (float(ms), -_speed_score(pid, model))
    except Exception:                                            # noqa: BLE001
        return (float("inf"), 0)


class _HopBudgetExceeded(RuntimeError):
    """A hop the HUB stopped waiting for -- the request deadline or a trivial
    turn's hop budget ran out. Deliberately not a requests Timeout: those
    throttle the hop and count toward parking its provider, and our own
    impatience on a one-liner is not evidence the provider is broken."""


def _call_with_wall_clock(seconds, fn, *a, **kw):
    """fn(*a, **kw) bounded by a wall clock. Raises _HopBudgetExceeded when it
    passes; re-raises whatever fn raised.

    Same daemon-worker discipline as _dispatch_chat_with_deadline: the call is
    abandoned, not cancelled (Python cannot cancel a blocking socket read), and
    a response it produces after we stopped waiting is closed so its connection
    goes back to the pool. Runs in a COPY of the caller's context, so `g` (the
    routing mode, the activity row) and the usage label work on the worker."""
    box = {}
    lock = threading.Lock()
    ctx = contextvars.copy_context()
    # The worker's own hop token (clientgone.child): when the wait below
    # gives up, its call is CUT instead of left open until the provider's
    # read timeout.
    hop = ctx.run(clientgone.child, "hop")

    def _run():
        try:
            v = ctx.run(clientgone.run_as, hop, fn, *a, **kw)
        except BaseException as exc:                             # noqa: BLE001
            with lock:
                box["exc"] = exc
            return
        with lock:
            if box.get("abandoned"):
                try:
                    v.close()
                except Exception:                                # noqa: BLE001
                    pass
                return
            box["v"] = v

    t = threading.Thread(target=_carry_usage_source(_run), daemon=True)
    end = time.monotonic() + max(0.0, seconds)
    t.start()
    if clientgone.join(t, max(0.0, seconds)):
        # The client left (clientgone): stop waiting at once. The worker's
        # upstream socket was shut down by the cancel, so it ends too.
        with lock:
            box["abandoned"] = True
            late = box.pop("v", None)
        hop.cancel("client disconnected")
        if late is not None:
            try:
                late.close()             # it landed just as the client left
            except Exception:                                    # noqa: BLE001
                pass
        raise clientgone.ClientGone("the client disconnected")
    # join() can return a hair EARLY by time.monotonic()'s reckoning (15.6 ms
    # ticks on Windows): the chain then saw its deadline "not yet spent" and
    # started another hop with a few ms left. Wait out the true remainder.
    while t.is_alive():
        rest = end - time.monotonic()
        if rest <= 0:
            break
        t.join(rest)
    with lock:
        if "exc" in box:
            raise box["exc"]
        if "v" in box:
            return box["v"]
        box["abandoned"] = True
    hop.cancel("hop budget spent")     # cut the abandoned call now
    raise _HopBudgetExceeded("no answer within %.0fs" % seconds)


def _deadline_error_text(clock, errors):
    return ("Request deadline of %ds reached before any model answered (setting "
            "request_deadline_seconds). Tried: %s"
            % (int(clock.limit or 0), "; ".join(errors) or "none"))


# THE HUB'S OWN WORDS WHEN EVERY HOP FAILED. The exhausted-chain reply used to
# RELAY the last hard upstream error verbatim -- MEASURED 2026-09-27: a trivial
# tool turn got HTTP 503 with body {"detail": "Function '4df48b4f-...': Not
# found for account ..."}, an NVIDIA NIM function id and account message from
# ONE of nine hops, presented to the client as if it were the answer to its
# request. That body describes one provider's catalog, not the request, and it
# leaks upstream ids. The client now gets every hop's failure CLASS (the same
# "pid: HTTP 404 / empty / timeout" strings the log line records), the last
# hard status by number, and nothing an upstream wrote. The raw body stays in
# the CHAT-503 / RESPONSES-503 / MESSAGES-503 log line for diagnosis.
_HOP_CLASS_WORDS = (
    ("_HopBudgetExceeded", "no answer within the hop budget"),
    ("ReadTimeout", "timeout"), ("ConnectTimeout", "connect timeout"),
    ("ConnectionError", "connection error"),
)


def _client_hop_errors(errors):
    """The hop-failure list for a client: internal exception names spelled as
    classes, consecutive repeats folded ("nvidia: HTTP 404 x3"). Never raises."""
    out = []
    try:
        for e in errors or ():
            s = str(e or "").strip()
            for raw, words in _HOP_CLASS_WORDS:
                s = s.replace(raw, words)
            s = _sanitize(s, 160)
            if out and out[-1][0] == s:
                out[-1][1] += 1
            else:
                out.append([s, 1])
    except Exception:                                            # noqa: BLE001
        return ["(unavailable)"]
    return ["%s x%d" % (s, n) if n > 1 else s for s, n in out]


def _chain_exhausted_text(errors, last_hard=None, est=0, tools=False):
    """The exhausted-chain error message, in the hub's own words (see above)."""
    hops = _client_hop_errors(errors)
    text = "All providers failed: " + ("; ".join(hops) or "none available")
    if not last_hard and _net_only_now():
        # Every hop that ran failed to RESOLVE its host, on 2+ hosts: say whose
        # problem it is instead of listing providers as if they were down.
        text = "All providers failed: %s (%s)" % (
            _LOCAL_NET_TEXT, "; ".join(hops) or "none available")
    try:
        if last_hard:
            code = last_hard.get("http", last_hard.get("status"))
            text += " (last hard error: HTTP %s from %s)" % (int(code), last_hard.get("pid"))
    except Exception:                                            # noqa: BLE001
        pass
    return text + _no_candidates_hint(est, tools)


def _last_hard_log_body(last_hard):
    """The raw upstream body of the last hard error, clipped -- LOG ONLY."""
    try:
        if not last_hard:
            return "none"
        body = last_hard.get("json")
        if body is not None:
            return _sanitize(json.dumps(body), 500)
        return _sanitize(str(last_hard.get("text") or last_hard.get("detail") or ""), 500)
    except Exception:                                            # noqa: BLE001
        return "?"


class _PrePeekedResponse:
    """A streamed hop whose first content a hedge leg already read: the loop's
    iter_content()/iter_lines() replays what was read, then continues the SAME
    upstream iterator. Everything else is the real response."""

    def __init__(self, resp, buffered, iterator):
        self._resp = resp
        self._buffered = list(buffered or ())
        self._it = iterator
        self.status_code = getattr(resp, "status_code", 200)

    def iter_content(self, chunk_size=None):
        return _chain_buffered(self._buffered, self._it)

    def iter_lines(self, decode_unicode=False):
        return _chain_buffered(self._buffered, self._it)

    def close(self):
        try:
            self._resp.close()
        except Exception:                                        # noqa: BLE001
            pass

    def __getattr__(self, name):
        return getattr(self._resp, name)


def _nb_close(resp):
    """Make an upstream response's close() safe while a reader thread is
    still blocked on it (clientgone.nonblocking_close): the socket is shut
    down first, the close finishes on a daemon thread. Reaches the real
    response inside the hub's wrappers. Returns `resp`; never raises.

    MEASURED before this: a hop the hub gave up on (a peek with no content,
    a stall cut, a hedge loser) closed its silent stream from the request
    thread, which waited on the blocked reader until the provider's read
    timeout (~90 s) -- one hop per read timeout instead of per peek."""
    try:
        clientgone.nonblocking_close(resp)
        for attr in ("_resp", "_upstream"):
            inner = getattr(resp, "__dict__", {}).get(attr)
            if inner is not None:
                clientgone.nonblocking_close(inner)
    except Exception:                                            # noqa: BLE001
        pass
    return resp


def _close_hedge_item(item):
    try:
        if item[1] in ("resp", "json", "peek"):
            item[2].close()
    except Exception:                                            # noqa: BLE001
        pass


def _run_hedge_leg(idx, pid, payload, stream, lines, budget, q, lock, abandoned,
                   grace, streaming=None, live=None):
    """One leg of a hedged hop, on its own thread. Puts (idx, kind, obj, extra)
    on `q`: kind "exc" (obj = the exception), "resp" (a non-200), "json" (a
    non-streamed 200) or "peek" (a streamed 200 already peeked to its first
    content: extra = (status, buffered, iterator)). A leg the caller stopped
    waiting for closes its own response instead. `live` (idx -> response,
    under `lock`) lets the caller close a leg's response while the leg is
    still peeking it, so a loser stops reading upstream at once."""
    started = time.monotonic()
    try:
        resp = _nb_close(_dispatch_chat(pid, payload, stream))
    except BaseException as exc:                                 # noqa: BLE001
        item = (idx, "exc", exc, None)
    else:
        item = (idx, "resp", resp, None)
        if live is not None:
            with lock:
                gone = idx in abandoned
                if not gone:
                    live[idx] = resp
            if gone:
                _close_hedge_item(item)
                return
        if getattr(resp, "status_code", None) == 200:
            if not stream:
                item = (idx, "json", resp, None)
            else:
                try:
                    it = (resp.iter_lines(decode_unicode=False) if lines
                          else resp.iter_content(chunk_size=None))
                    status, buffered = _peek_until_content(
                        it, max(0.0, budget - (time.monotonic() - started)),
                        content_grace=grace,
                        on_content=(lambda: streaming.add(idx))
                        if streaming is not None else None)
                    # The verdict's KIND lives in THIS thread's slot; carry it
                    # on the leg's response so _record_losers files it right.
                    _tag_nonanswer_kind(resp, _take_nonanswer_kind()
                                        if status == "nonanswer" else None)
                    item = (idx, "peek", resp, (status, buffered, it))
                except Exception as exc:                         # noqa: BLE001
                    _close_hedge_item(item)
                    item = (idx, "exc", exc, None)
    with lock:
        if live is not None:
            live.pop(idx, None)
        drop = idx in abandoned
        if not drop:
            q.put(item)
    if drop:
        _close_hedge_item(item)


def _tag_nonanswer_kind(resp, kind):
    try:
        resp._hub_nonanswer_kind = kind
    except Exception:                                            # noqa: BLE001
        pass


def _hedge_leg_verdict(item, payload):
    """'ok' | 'salvaged' | a failure class, for one finished hedge leg. 'ok'
    is what may win the race: a real answer answer_check.inspect passes."""
    try:
        _idx, kind, obj, extra = item
        if kind == "exc":
            return "error"
        if kind == "resp":
            return "http"
        if kind == "json":
            try:
                data = obj.json()
            except (ValueError, requests.RequestException):
                return "non-json"
            if not isinstance(data, dict):
                return "non-json"
            if _chat_json_nonanswer(data, False, None):
                # Two legs are judged one after the other on this thread: the
                # kind rides on the leg, not in the single thread-local slot.
                _tag_nonanswer_kind(obj, _take_nonanswer_kind())
                return "nonanswer"
            if _chat_json_is_empty(data):
                return "empty"
            if _starve_kind(data, payload) == "stub":
                return "starved"   # a stub must not win the race
            return _answer_gate(data, payload, False)
        if kind == "peek":
            status, buffered, _it = extra
            if status != "content":
                return status
            raw = "".join(b.decode("utf-8", "ignore") if isinstance(b, (bytes, bytearray))
                          else str(b) for b in buffered if b)
            _full, _tools, _fin = _buffered_digest(buffered)
            if not _tools and _is_truncated_stub(_full, _fin, _caller_budget(payload)):
                return "starved"
            text = _peeked_text(raw)
            if text and not answer_check.inspect(
                    text, prompt_text=_prompt_text_for_check(payload),
                    last_prompt=_last_user_text_for_check(payload)).get("ok", True):
                return "salvaged"
            return "ok"
    except Exception:                                            # noqa: BLE001
        return "ok" if item and item[1] in ("json", "peek") else "error"
    return "error"


# best/max DEGRADE GRACEFULLY instead of hanging.
#
# MEASURED 2026-09-27 on 3c10c24: Claude Code `claude -p "What is N plus 1?
# Reply with only the number." --model max` (/v1/messages, tools, stream) had
# no answer after 421 s, while `--model multi` answered in 7 s and the protocol
# sweep ran at a 0.9 s median. Upstream was degraded (google quota exhausted,
# dahl/openrouter 429, nvidia stalling). best/max lift a simple ask to medium,
# so the turn skipped every quick-turn rule `auto` uses (fast primary, fast-
# first chain, the tight trivial hop budget) and walked the strength-ordered
# chain one stall at a time until the 240 s deadline -- then the client retried.
#
# Now: once _QUALITY_FALLBACK_SHARE of the request deadline (at least
# _QUALITY_FALLBACK_MIN_SECONDS; _QUALITY_FALLBACK_TRIVIAL_SECONDS for a
# trivial ask) passed with nothing served, the walk jumps to the best
# AVAILABLE fast capable candidates (_quality_fallback_pick) -- healthy, not
# stalled, strongest first among them -- and a hop still waiting at that
# moment is cut there. The answer is marked: X-Free-LLM-Hub-Fallback
# ("max->auto") and the activity row's `fallback`. A healthy strong pool
# answers long before the mark and is unaffected.
_QUALITY_FALLBACK_SHARE = 0.45
_QUALITY_FALLBACK_MIN_SECONDS = 45.0
_QUALITY_FALLBACK_TRIVIAL_SECONDS = 30.0
_QUALITY_FALLBACK_PAIRS = 3


def _quality_fallback_pick(entries, tools=False, stalled=(), est=0):
    """Up to _QUALITY_FALLBACK_PAIRS (pid, model) of `entries` (the chain not
    walked yet) to serve a best/max turn whose strong pool did not answer in
    time: fast, not in a provider that stalled this walk, not recently
    stalled/failed, not benched, clearing the simple floor, tool-safe on a
    tool turn -- each filter fail-open -- then healthiest, measured-quick,
    strongest first. Never raises ([] on error).

    The fit filter (its KNOWN window must hold ~`est` tokens) is the one HARD
    one: a fallback that cannot hold the request is no fallback at all -- it
    would only overflow (MEASURED 2026-10-07: `best->auto` picked
    groq/qwen3.8-27b, ~8K TPM, for a 79K turn, 25 times in 3 h, each a wasted
    _ContextOverflow). So when nothing left can fit, the pick is empty and the
    chain goes straight to the native overflow reply instead of a dead pick."""
    try:
        pool = []
        for e in entries or ():
            pid, model = e[0], e[1]
            pool.append((_benchmark_score(pid, model), pid, model))

        def keep(cands, pred):
            return [c for c in cands if pred(c)] or cands

        # A pick that cannot hold the request is dropped outright (not fail-open
        # like the preference filters below): handing it the turn only overflows.
        if est:
            pool = [c for c in pool if _window_fits(c[1], c[2], est)]
            if not pool:
                return []
        # The chain now ends with hops from OUTSIDE a category mode (see
        # _mode_fallback_tail): they are the mode's last resort, not its
        # fallback's first pick while an in-mode hop is left. Fail-open.
        pool = _apply_mode(pool)
        pool = keep(pool, lambda c: _is_fast(c[1], c[2]))
        pool = keep(pool, lambda c: c[1] not in stalled)
        pool = keep(pool, lambda c: not _recent_hop_stall(c[1], c[2]))
        pool = keep(pool, lambda c: not _is_pair_benched(c[1], c[2]))
        pool = keep(pool, lambda c: not _is_low_quality(c[2]))
        pool = keep(pool, lambda c: c[0] >= _DIFFICULTY_FLOOR["simple"])
        if tools:
            pool = keep(pool, lambda c: not _is_vision_specialised(c[2]))
            pool = keep(pool, lambda c: not _tool_turn_sick(c[1], c[2]))
            pool = keep(pool, lambda c: not _relay_tool_sick(c[1], c[2]))
        pool.sort(key=lambda c: (_chain_reliability_band(c[1], c[2]) >= 2,
                                 bool(_recent_hop_failure(c[1], c[2])),
                                 _simple_speed_rank(c[1], c[2])[1],
                                 -c[0]))
        return [(p, m) for _s, p, m in pool[:_QUALITY_FALLBACK_PAIRS]]
    except Exception:                                            # noqa: BLE001
        return []


def _plan_quality_fallback(clock, model, has_images, pinned, messages, max_tokens):
    """Arm `clock`'s best/max fallback when this request routes in quality
    mode (the same test _quality_route_kwargs makes; never for a pinned
    model). Never raises."""
    try:
        if pinned or not _quality_route_kwargs(model, has_images):
            return
        clock.plan_quality_fallback("%s->auto" % str(model).strip().lower(),
                                    messages, max_tokens)
    except Exception:                                            # noqa: BLE001
        pass


def _quality_fallback_header(pid, model):
    """The fallback label when (pid, model) is one this request's best/max
    fallback put forward, else None. Never raises."""
    try:
        fb = getattr(g, "hub_quality_fallback", None)
        if fb and (pid, model) in fb.get("pairs", ()):
            return fb.get("label")
    except Exception:                                            # noqa: BLE001
        pass
    return None


class _ChainClock:
    """The request deadline plus the current hop's budget, for one chain walk.

    The three chain loops (/v1/chat/completions, /v1/responses, /v1/messages)
    are near-copies of each other; this keeps the timing rules in one place so
    they cannot drift: `spent()` at the top of each hop, `dispatch()` instead of
    _dispatch_chat, `peek_timeout()` instead of _stream_peek_timeout, `guard()`
    around a committed stream."""

    # Class defaults so a clock built without __init__ (tests) walks like a
    # plain one; __init__ gives every instance its own ledgers.
    tools = False
    est = 0
    pinned = False
    _cur = None
    _rest = ()
    _relay_hops = 0
    _prov_hops = None
    _prov_secs = None
    _relay_bad = None
    _qf = None                       # best/max fallback plan (plan_quality_fallback)
    # This computer's network (see _local_net_failed): hops that failed to
    # resolve their host, in a row / in total, vs hops that failed otherwise.
    _net_streak = None               # hosts of consecutive local failures
    _net_hosts = None                # every host that failed locally this walk
    _net_local = 0
    _net_other = 0
    _net_pauses = 0                  # steps of _LOCAL_NET_PAUSES spent
    _net_rewalked = False

    def __init__(self, trivial=False, tools=False, est=0, stream=False, pinned=False):
        # `est` / `stream`: a long request's deadline grows with its size
        # (see _scaled_request_deadline); omitted, the base deadline as before.
        self.deadline_at = _begin_request_deadline(est, stream) if est else \
            _begin_request_deadline()
        self.limit = (_request_deadline_limit() if est else _request_deadline_seconds()) \
            if self.deadline_at else None
        self.trivial = bool(trivial)
        self.tools = bool(tools)
        self.est = int(est or 0)
        # An explicit `<pid>/<model>` request: _build_chain puts that model at
        # hop 1 whatever its record says, and the walk must not reorder it.
        self.pinned = bool(pinned)
        self._hop_started = None
        self._hop_budget = None
        self._last_peek = None
        self._hedge_plan = None      # set by plan_hedge() for an eligible turn
        self._hedge_fired = False    # at most ONE extra call per request
        self._consumed = set()       # chain entries a hedge already ran
        self._served = None          # (pid, model, payload) a hedge served
        self._stalled = set()        # providers that stalled a hop in THIS walk
        # TOOL turns (see _TOOL_PER_PROVIDER_HOPS): per-provider hops and
        # seconds spent in THIS walk, relay hops and failed relay servers.
        self._prov_hops = {}
        self._prov_secs = {}
        self._cur = None             # (pid, model, started) of the hop in flight
        self._rest = []              # what the walk has not yielded yet
        self._relay_hops = 0
        self._relay_bad = set()
        self._net_streak = []
        self._net_hosts = set()
        try:
            if getattr(g, "hub_net_only", False):
                # An earlier clock of this request (the roles walk before its
                # `best` fallback, /v1/responses before its storm retry) ended
                # on local failures; THIS walk tells its own story.
                g.hub_net_only = False
        except Exception:                                        # noqa: BLE001
            pass
        if self.tools:
            try:
                g.hub_tool_turn = True
            except Exception:                                    # noqa: BLE001
                pass

    # -- stalled gateways ---------------------------------------------------- #

    def walk(self, chain):
        """Iterate the chain; on a TRIVIAL or TOOL turn, once a provider has
        STALLED a hop (hop budget / timeout / a silent peek) its remaining hops
        go behind every other provider's. A sibling model behind the same slow
        gateway is the likeliest to stall for the same reason -- the rule the
        hedge partner pick already follows -- and on a one-liner each stall
        costs 25-45s. Demoted, never dropped.

        A TOOL turn also demotes a provider that has had
        _TOOL_PER_PROVIDER_HOPS failed hops or its share of the deadline
        (_provider_cap), and skips relay hops past _TOOL_RELAY_MAX_HOPS or on a
        relay server that already failed in this walk. Any other turn: the
        chain as built."""
        self._ensure_ledgers()
        original = list(chain or ())
        self._rest = rest = list(original)
        first = True
        while True:
            while rest:
                self._close_hop()
                if _client_gone():
                    break        # the client left: no further hop (clientgone)
                if self._net_pause_due():
                    # 2+ different hosts in a row failed to RESOLVE: this
                    # computer's network blinked, not the providers. Give it a
                    # moment instead of spending the next hop in milliseconds.
                    self._net_pause()
                    if _client_gone():
                        break
                if self._quality_due():
                    self._fire_quality_fallback(rest)
                if self.tools:
                    rest[:] = [e for e in rest if not self._relay_skip(e)]
                    if not rest:
                        break
                i = 0
                if first and self.pinned:
                    # THE USER NAMED THE HEAD (see _build_chain's pinned branch):
                    # it opens the turn even when benched -- the picker below
                    # would silently serve a different model.
                    pass
                elif (self.trivial or self.tools) and (self._stalled or self.tools):
                    # A junk-benched pair is never what the demotion promotes: it
                    # stays the last hop the built chain made it (see _bench_last).
                    # MEASURED 2026-09-27: nvidia stalled one hop and the benched
                    # dahl pair was walked before nvidia's healthy sibling.
                    i = next((k for k, e in enumerate(rest)
                              if not self._demoted(e[0])
                              and not _is_pair_benched(e[0], e[1])), None)
                    if i is None:
                        i = next((k for k, e in enumerate(rest)
                                  if not _is_pair_benched(e[0], e[1])), 0)
                first = False
                yield rest.pop(i)
            self._close_hop()
            # The whole chain ended on this computer's network alone (2+ hosts
            # failed to resolve, nothing else went wrong): wait once more and
            # walk it ONCE again. Nothing was filed against any provider.
            if not self._net_rewalk_due():
                break
            if not self._net_pause() or _client_gone() or self.spent():
                break
            self._net_rewalked = True
            self._net_streak = []
            rest.extend(original)

    # -- best/max graceful degrade (see _QUALITY_FALLBACK_SHARE) ------------ #

    def plan_quality_fallback(self, label, messages=None, max_tokens=None):
        """Arm the best/max fallback for this walk. `label` names it in the
        header and the activity row ("max->auto"). The mark is measured from
        the REQUEST's start, so a second walk of the same request does not
        restart it. Never raises."""
        try:
            trivial = _is_trivial_ask(messages, max_tokens) if messages else False
            if trivial:
                wait = _QUALITY_FALLBACK_TRIVIAL_SECONDS
            else:
                wait = max(_QUALITY_FALLBACK_MIN_SECONDS,
                           _QUALITY_FALLBACK_SHARE * float(self.limit or 0))
            start = (self.deadline_at - float(self.limit)
                     if self.deadline_at is not None and self.limit else time.monotonic())
            self._qf = {"label": str(label), "at": start + wait, "start": start,
                        "fired": False, "trivial": bool(trivial)}
        except Exception:                                        # noqa: BLE001
            self._qf = None

    def _quality_due(self):
        qf = self._qf
        return bool(qf and not qf["fired"] and time.monotonic() >= qf["at"])

    def _fire_quality_fallback(self, rest):
        """Move the fallback picks to the front of `rest` (in place) and mark
        the request. Fires once per walk."""
        qf = self._qf
        qf["fired"] = True
        try:
            stalled = set(self._stalled) | {e[0] for e in rest if self._demoted(e[0])}
            picks = _quality_fallback_pick(rest, tools=self.tools, stalled=stalled,
                                           est=self.est)
            if not picks:
                return
            rest[:] = picks + [e for e in rest if e not in picks]
            if qf.get("trivial"):
                # a one-liner: the picks get the tight trivial hop budget, so
                # one of them stalling cannot eat what is left either
                self.trivial = True
            fb = getattr(g, "hub_quality_fallback", None) or {"pairs": set()}
            fb["label"] = qf["label"]
            fb["pairs"] = set(fb.get("pairs") or ()) | set(picks)
            g.hub_quality_fallback = fb
            act = getattr(g, "act", None)
            if act is not None:
                with _activity_lock:
                    act["fallback"] = qf["label"]
            _log.warning("[quality-fallback] %s: nothing served after %.0fs -> %s",
                         qf["label"], time.monotonic() - qf["start"],
                         ", ".join("%s/%s" % p for p in picks))
        except Exception:                                        # noqa: BLE001
            pass

    def _ensure_ledgers(self):
        if self._prov_hops is None:
            self._prov_hops = {}
        if self._prov_secs is None:
            self._prov_secs = {}
        if self._relay_bad is None:
            self._relay_bad = set()
        if self._net_streak is None:
            self._net_streak = []
        if self._net_hosts is None:
            self._net_hosts = set()

    # -- this computer's network (see _local_net_failed) -------------------- #

    def _net_hop_failed_locally(self, pid, model, host):
        """The hop that just ended failed to resolve its host: it is nobody's
        failure, so it is NOT charged to the provider (hop count, seconds, relay
        strike), and the streak/tally that drives the pause and the final
        message is updated."""
        self._ensure_ledgers()
        self._net_local += 1
        self._net_streak.append(host)
        self._net_hosts.add(host)
        try:
            self._prov_hops[pid] = max(0, self._prov_hops.get(pid, 0) - 1)
            if self.tools and _is_relay_pid(pid):
                self._relay_hops = max(0, self._relay_hops - 1)
        except Exception:                                        # noqa: BLE001
            pass
        self._net_publish()

    def _net_hop_failed_otherwise(self):
        self._ensure_ledgers()
        self._net_other += 1
        self._net_streak = []
        if self._net_local:
            self._net_publish()

    def _net_only(self):
        """Every hop that ran failed locally, on 2+ hosts: the machine's
        network, not the providers."""
        return (self._net_local > 0 and self._net_other == 0
                and len(self._net_hosts or ()) >= 2)

    def _net_publish(self):
        """Tell the rest of the request (the 503 text) and the Activity row.
        Request thread only; silently nothing elsewhere."""
        try:
            g.hub_net_only = self._net_only()
            act = getattr(g, "act", None)
            if act is not None and self._net_local:
                with _activity_lock:
                    act["net"] = "network"
        except Exception:                                        # noqa: BLE001
            pass

    def _net_pause(self):
        """Wait out the next step of _LOCAL_NET_PAUSES (1 s, then 3 s), in
        0.5 s slices that stop when the client leaves, never past the request
        deadline. False when there was no time for it."""
        self._ensure_ledgers()
        step = _LOCAL_NET_PAUSES[min(self._net_pauses, len(_LOCAL_NET_PAUSES) - 1)]
        self._net_pauses += 1
        self._net_streak = []
        left = self.left()
        secs = step if left is None else min(step, left - 1.0)
        if secs <= 0 or _client_gone():
            return False
        _log.warning("[network] %d hosts failed to resolve in a row (%s); "
                     "pausing %.0fs before the next hop",
                     len(self._net_hosts), ", ".join(sorted(self._net_hosts))[:120], secs)
        remaining = secs
        while remaining > 0 and not _client_gone():
            d = min(0.5, remaining)
            _LOCAL_NET_SLEEP(d)
            remaining -= d
        return True

    def _net_pause_due(self):
        return (len(set(self._net_streak or ())) >= 2
                and self._net_pauses < len(_LOCAL_NET_PAUSES))

    def _net_rewalk_due(self):
        """The walk ended and ONLY local failures happened, on 2+ hosts, and a
        pause step is left: walk the chain once more after it."""
        return (not self._net_rewalked and self._net_only()
                and self._net_pauses < len(_LOCAL_NET_PAUSES)
                and not _client_gone() and not self.spent())

    def _demoted(self, pid):
        if pid in self._stalled:
            return True
        if not self.tools:
            return False
        if self._prov_hops.get(pid, 0) >= _TOOL_PER_PROVIDER_HOPS:
            return True
        cap = self._provider_cap()
        return cap is not None and self._prov_secs.get(pid, 0.0) >= cap

    def _relay_skip(self, entry):
        """A relay hop a tool walk must not take (see walk)."""
        try:
            pid, model = entry[0], entry[1]
            if not _is_relay_pid(pid):
                return False
            if self._relay_hops >= _TOOL_RELAY_MAX_HOPS:
                return True
            return _relay_server_id(pid, model) in self._relay_bad
        except Exception:                                        # noqa: BLE001
            return False

    def _close_hop(self):
        """The walk resumed, so the hop in flight FAILED (a served hop ends the
        loop): charge its time to its provider, and remember a failed relay
        server for the rest of this walk."""
        cur, self._cur = self._cur, None
        if not cur:
            return
        pid, model, started = cur
        host = _local_net_since(pid, model, since=started)
        if host is not None:
            # It failed to RESOLVE its host: this computer's problem. Not charged
            # to the provider -- no time, no relay strike, no hop count.
            self._net_hop_failed_locally(pid, model, host)
            return
        self._net_hop_failed_otherwise()
        try:
            self._prov_secs[pid] = (self._prov_secs.get(pid, 0.0)
                                    + max(0.0, time.monotonic() - started))
            if self.tools and _is_relay_pid(pid):
                self._relay_bad.add(_relay_server_id(pid, model))
        except Exception:                                        # noqa: BLE001
            pass

    def _provider_cap(self):
        """Seconds one provider may spend on this TOOL turn while another
        provider still waits, or None (no deadline / not a tool turn)."""
        if not self.tools or not self.limit:
            return None
        share = (_TOOL_PROVIDER_SHARE_HUGE if self.est >= STREAM_HUGE_REQUEST_TOKENS
                 else _TOOL_PROVIDER_SHARE)
        return max(_TOOL_PROVIDER_MIN_SECONDS, share * float(self.limit))

    def _others_waiting(self, pid):
        return any(e[0] != pid for e in (self._rest or ()))

    def _note_stall(self, pid):
        if (self.trivial or self.tools) and pid:
            self._stalled.add(pid)

    def left(self):
        if self.deadline_at is None:
            return None
        return self.deadline_at - time.monotonic()

    def spent(self):
        left = self.left()
        return left is not None and left <= 0

    def _budget_for(self, pid, model, stream=None):
        budget = None
        # A local subscription CLI is a subprocess that cold-starts in tens of
        # seconds whatever the question; a first-content budget sized for an
        # HTTP API would cut every one of them off. The deadline still applies.
        if self.trivial and not _is_sub(pid):
            ceiling = (_TRIVIAL_SLOW_HOP_BUDGET
                       if _is_slow_model(pid, model)
                       else _TRIVIAL_HOP_BUDGET)
            budget = _adaptive_hop_budget(pid, model, ceiling, stream)
        # A TOOL turn: while another provider still waits, one provider may
        # not spend more than its share of the deadline -- MEASURED, nvidia
        # took all 240 s of a 16K tool turn over three hops.
        cap = self._provider_cap()
        if cap is not None and not _is_sub(pid) and self._others_waiting(pid):
            room = max(_TOOL_PROVIDER_MIN_HOP, cap - self._prov_secs.get(pid, 0.0))
            budget = room if budget is None else min(budget, room)
        # best/max: a hop still waiting at the fallback mark is cut there, so
        # the fallback (see plan_quality_fallback) gets the time that is left
        # -- only while something is left to fall back to.
        qf = self._qf
        if qf and not qf["fired"] and self._rest and not _is_sub(pid):
            room = max(_ADAPTIVE_HOP_FLOOR, qf["at"] - time.monotonic())
            budget = room if budget is None else min(budget, room)
        left = self.left()
        if left is not None:
            budget = left if budget is None else min(budget, left)
        return None if budget is None else max(0.0, budget)

    def content_grace(self):
        """How long a peek may keep waiting once visible text has started."""
        left = self.left()
        if left is None:
            return _PEEK_CONTENT_GRACE
        return max(0.0, min(_PEEK_CONTENT_GRACE, left))

    # -- hedging ------------------------------------------------------------ #

    def plan_hedge(self, chain, base_payload, difficulty, est=0, tools=False,
                   images=False, lines=False, output_budget=False):
        """Arm hedging for this chain walk when the turn qualifies: trivial,
        tool-free, image-free and small (_HEDGE_MAX_EST). `base_payload` and
        `difficulty` rebuild the partner hop's payload exactly as the loop
        builds its own; `lines` says the loop reads streams with iter_lines
        (/v1/responses, /v1/messages) rather than iter_content. Never raises;
        flag `hedge_simple_turns` (default on)."""
        self._hedge_plan = None
        try:
            if (not self.trivial or tools or images or not est
                    or est > _HEDGE_MAX_EST
                    or not config.get_flag("hedge_simple_turns", True)):
                return
            self._hedge_plan = {"chain": [tuple(e) for e in (chain or ())],
                                "base": dict(base_payload or {}),
                                "diff": difficulty, "lines": bool(lines),
                                "output_budget": bool(output_budget)}
        except Exception:                                        # noqa: BLE001
            self._hedge_plan = None

    def consumed(self, pid, model):
        """True for a chain entry a hedge already ran -- the loop skips it."""
        return (pid, model) in self._consumed

    def served(self, pid, model, payload):
        """(pid, model, payload) that actually produced the response the last
        dispatch() returned: the loop's own hop, or the hedge partner that won.
        The loop rebinds its hop variables to this, so recording, headers and
        the answer check all name the model that answered."""
        s, self._served = self._served, None
        if not s or (s[0], s[1]) == (pid, model):
            return pid, model, payload
        try:
            _act_pick(s[0], s[1])
        except Exception:                                        # noqa: BLE001
            pass
        return s

    def _hedge_partner(self, pid, model):
        plan = self._hedge_plan
        if not plan or self._hedge_fired or _is_sub(pid):
            return None
        try:
            chain = plan["chain"]
            i = chain.index((pid, model)) if (pid, model) in chain else -1
            rest = [e for e in chain[i + 1:]
                    if e != (pid, model) and e not in self._consumed
                    and not _is_sub(e[0]) and prov.is_model_allowed(e[1])
                    and not _is_provider_dead(e[0])
                    and not _recent_hop_failure(e[0], e[1])]
            # A different PROVIDER first: a sibling model behind the same
            # rate limit or the same slow gateway is the likeliest to be slow
            # for the same reason.
            other = [e for e in rest if e[0] != pid]
            return (other or rest or [None])[0]
        except Exception:                                        # noqa: BLE001
            return None

    def _hedge_payload(self, pid, model, stream):
        plan = self._hedge_plan
        pl = dict(plan["base"])
        pl["model"] = model
        if plan["output_budget"]:
            _apply_output_budget(pl, pid)
        _apply_reasoning_effort(pl, model, plan["diff"], pid=pid)
        pl["stream"] = stream
        return pl

    def _dispatch_hedged(self, pid, payload, stream, delay, partner):
        """Hop `pid` with `partner` started in parallel after `delay` seconds
        of silence. Returns what the loop would have got from a plain dispatch
        (a response, or the exception raised): the first VALID answer when the
        hedge fired, else leg 0's own result untouched."""
        lines = self._hedge_plan["lines"]
        q = queue.Queue()
        lock = threading.Lock()
        abandoned = set()
        live = {}                    # idx -> response of a leg still peeking
        streaming = set()            # legs whose visible text has started
        grace = self.content_grace()
        graced = False
        legs = {0: (pid, (payload or {}).get("model"), payload, time.monotonic())}

        # One hop token per leg (clientgone.child): a leg the race leaves
        # behind has its in-flight call cut, not left open until its read
        # timeout.
        self._leg_tokens = leg_tokens = {}

        def _start(idx, p, pl, budget):
            ctx = contextvars.copy_context()
            hop = leg_tokens[idx] = ctx.run(clientgone.child, "hedge-leg")

            def _run():
                ctx.run(clientgone.run_as, hop, _run_hedge_leg, idx, p, pl, stream,
                        lines, budget, q, lock, abandoned, grace, streaming, live)
            threading.Thread(target=_carry_usage_source(_run), daemon=True).start()

        budget0 = self._hop_budget
        t0 = legs[0][3]
        end = t0 + budget0
        _start(0, pid, payload, budget0)
        fired = False
        pending = {0}
        # Legs whose result the race has NOT received: the only ones _settle
        # may cut (a received leg's response may be the one handed back).
        self._leg_pending = pending
        fallback = None
        failed = {}
        # Each leg's verdict as judged in the race: _answer_gate salvages a
        # junk JSON answer IN PLACE, so re-judging it later reads "ok".
        verdicts = {}
        while pending:
            if _client_gone():
                # The client left: stop every leg, start none (their
                # sockets were already shut down by the cancel).
                self._settle(lock, abandoned, q, legs, keep=None, live=live)
                raise clientgone.ClientGone("the client disconnected")
            wait_to = end if fired or 0 in streaming else min(t0 + delay, end)
            try:
                item = q.get(timeout=min(0.5, max(0.0, wait_to - time.monotonic())))
            except queue.Empty:
                now = time.monotonic()
                if now < wait_to:
                    continue     # a 0.5 s slice, so a cancel is seen above
                if not fired and now < end:
                    if 0 in streaming:
                        # Leg 0 is answering (slowly, under the judge
                        # threshold): it has not "produced nothing", so there
                        # is nothing to hedge -- wait out its budget instead.
                        continue
                    p1, m1 = partner
                    pl1 = self._hedge_payload(p1, m1, stream)
                    budget1 = self._budget_for(p1, m1, stream) or budget0
                    end = max(end, now + budget1)
                    left = self.left()
                    if left is not None:
                        end = min(end, now + max(0.0, left))
                    fired = self._hedge_fired = True
                    self._consumed.add((p1, m1))
                    legs[1] = (p1, m1, pl1, now)
                    pending.add(1)
                    _log.info("[hedge] %s/%s silent %.1fs -> also starting %s/%s",
                              pid, legs[0][1], now - t0, p1, m1)
                    _start(1, p1, pl1, budget1)
                    continue
                if not graced and pending & streaming:
                    # A leg is already writing visible text: never cut it
                    # (its own peek holds on for the same grace).
                    graced = True
                    end = now + grace
                    continue
                break
            idx = item[0]
            pending.discard(idx)
            if not fired:
                # Leg 0 came back before the hedge was needed: hand it to the
                # loop EXACTLY as a plain dispatch would have, so its whole
                # error handling (starved retry, soft 400, junk gate) applies.
                self._settle(lock, abandoned, q, legs, keep=None, live=live)
                return self._loop_result(item, legs)
            verdict = verdicts[idx] = _hedge_leg_verdict(item, legs[idx][2])
            if verdict == "ok":
                self._settle(lock, abandoned, q, legs, keep=idx, live=live)
                if fallback is not None:
                    # A junk answer that lost the race is still junk.
                    failed[fallback[0]] = fallback
                self._record_losers(failed, legs, verdicts)
                if idx:
                    _log.info("[hedge] %s/%s won the race", legs[1][0], legs[1][1])
                return self._loop_result(item, legs)
            if verdict == "salvaged" and fallback is None:
                fallback = item
                continue
            failed[idx] = item
        # Nobody produced a valid answer in time.
        self._settle(lock, abandoned, q, legs, keep=None, live=live)
        now = time.monotonic()
        for idx in pending:
            if now - legs[idx][3] >= _ADAPTIVE_HOP_FLOOR:
                _note_recent_hop_failure(legs[idx][0], legs[idx][1], "deadline")
        if fallback is not None:
            self._record_losers(failed, legs, verdicts)
            return self._loop_result(fallback, legs)
        if 0 in failed:
            # Leg 0's own failure goes to the loop as if unhedged; leg 1's is
            # recorded here, since the loop never sees it.
            self._record_losers({k: v for k, v in failed.items() if k}, legs,
                                verdicts)
            return self._loop_result(failed[0], legs)
        self._record_losers(failed, legs, verdicts)
        raise _HopBudgetExceeded("no answer within %.0fs (hedged)" % (now - t0))

    def _settle(self, lock, abandoned, q, legs, keep, live=None):
        """Stop waiting on every leg but `keep`: a leg still peeking has its
        response closed here (its blocked read then fails and the leg exits,
        instead of reading upstream until its own budget and grace run out);
        one already queued is closed here too."""
        with lock:
            abandoned.update(i for i in legs if i != keep)
            running = [r for i, r in (live or {}).items() if i != keep]
        tokens = getattr(self, "_leg_tokens", None) or {}
        for i in list(getattr(self, "_leg_pending", None) or ()):
            if i != keep and i in tokens:
                tokens[i].cancel("hedge leg abandoned")   # its call, still in flight
        for r in running:
            try:
                r.close()
            except Exception:                                    # noqa: BLE001
                pass
        while True:
            try:
                item = q.get_nowait()
            except queue.Empty:
                break
            if item[0] != keep:
                _close_hedge_item(item)

    def _record_losers(self, failed, legs, verdicts=None):
        """File the failures of legs whose result the loop will never see."""
        for idx, item in failed.items():
            p, m = legs[idx][0], legs[idx][1]
            try:
                kind, obj = item[1], item[2]
                if kind == "exc":
                    if isinstance(obj, requests.exceptions.Timeout):
                        _note_recent_hop_failure(p, m, "timeout")
                        _throttle_failed_hop(p, m, exc=obj)
                elif kind == "resp":
                    _record_outcome(p, m, False)
                    code = getattr(obj, "status_code", 0) or 0
                    if code == 429:
                        _note_recent_hop_failure(p, m, "429")
                    elif code >= 500:
                        _throttle_failed_hop(p, m)
                else:
                    verdict = (verdicts or {}).get(idx) \
                        or _hedge_leg_verdict(item, legs[idx][2])
                    if verdict in ("junk", "salvaged"):
                        # As the loop files a junk answer (_JUNK_FAIL_WEIGHT +
                        # the junk bench): losing the race is no excuse.
                        _record_outcome(p, m, False, junk=True)
                    elif verdict == "nonanswer":
                        _note_nonanswer(p, m, kind=getattr(
                            obj, "_hub_nonanswer_kind", None))
                    elif verdict == "timeout":
                        _note_recent_hop_failure(p, m, "deadline")
            except Exception:                                    # noqa: BLE001
                pass
            _close_hedge_item(item)

    def _loop_result(self, item, legs):
        idx, kind, obj, extra = item
        p, m, pl, _t = legs[idx]
        self._served = (p, m, pl)
        if idx:
            # The winner's replay is already in hand; the loop's own peek must
            # not be cut by leg 0's budget.
            self._hop_budget = None
        if kind == "exc":
            if isinstance(obj, requests.exceptions.Timeout):
                _note_recent_hop_failure(p, m, "timeout")     # as _plain() does
            raise obj
        if kind == "peek":
            status, buffered, it = extra
            if status == "timeout":
                _close_hedge_item(item)
                raise _HopBudgetExceeded("no first content within the hop budget")
            self._hop_budget = None
            return _PrePeekedResponse(obj, buffered, it)
        return obj

    def dispatch(self, pid, payload, stream, hedge=True):
        """_dispatch_chat under this hop's budget. A non-streaming hop gets the
        whole budget for its answer; a streaming one for its headers, and
        peek_timeout() hands the rest to the first-content peek.

        On a hedge-eligible turn (plan_hedge) the hop may race the next
        candidate; call served() afterwards for the one that answered.
        `hedge=False` for a same-hop retry, which must stay on its hop."""
        self._served = None
        model = (payload or {}).get("model")
        if _client_gone():
            raise clientgone.ClientGone("the client disconnected")
        self._open_hop(pid, model, stream)
        try:
            if self._hop_budget is None:
                return self._plain(pid, model, payload, stream)
            if self._hop_budget <= 0:
                raise _HopBudgetExceeded("request deadline reached")
            partner = self._hedge_partner(pid, model) if hedge else None
            if partner is not None:
                delay = _hedge_delay(pid, model, stream)
                if delay < self._hop_budget:
                    resp = self._dispatch_hedged(pid, payload, stream, delay, partner)
                    s = self._served or (pid, model, payload)
                    self._note_status(s[0], s[1], resp, stream)
                    return resp
            return self._plain(pid, model, payload, stream)
        except (_HopBudgetExceeded, requests.exceptions.Timeout) as exc:
            self._note_stall(pid)            # see walk()
            _ctx_note_hop_result(pid, model, exc=exc)
            raise
        except Exception as exc:                                 # noqa: BLE001
            _ctx_note_hop_result(pid, model, exc=exc)
            raise

    def _open_hop(self, pid, model, stream):
        """The hop ledger + this hop's budget (see dispatch). Returns the
        budget (None = unbounded)."""
        _ctx_note_tried(pid, model)
        self._hop_started = time.monotonic()
        self._ensure_ledgers()
        if self._cur is None or self._cur[0] != pid:
            # A same-hop retry (hedge=False) is the SAME hop: counted once.
            self._prov_hops[pid] = self._prov_hops.get(pid, 0) + 1
            if self.tools and _is_relay_pid(pid):
                self._relay_hops += 1
            self._cur = (pid, model, self._hop_started)
        self._hop_budget = self._budget_for(pid, model, stream)
        return self._hop_budget

    # -- tool-turn roles (see _tool_turn_roles) ------------------------------ #

    def open_role_hop(self, pid, model):
        """dispatch()'s ledger and budget for a NON-streamed tool-turn hop the
        caller runs itself (the role actor). None = unbounded."""
        return self._open_hop(pid, model, False)

    def plan_tool_hedge(self, chain):
        """Arm the STALL hedge for a tool-turn role walk: one extra actor, on
        another provider, after _tool_hedge_delay of silence (flag
        `hedge_tool_turns`, default on). The trivial-turn hedge (plan_hedge)
        is unchanged; this plan is only read by tool_hedge_partner."""
        self._hedge_plan = None
        try:
            if not config.get_flag("hedge_tool_turns", True):
                return
            self._hedge_plan = {"chain": [tuple(e) for e in (chain or ())],
                                "base": {}, "diff": None, "lines": False,
                                "output_budget": False, "tool_roles": True}
        except Exception:                                        # noqa: BLE001
            self._hedge_plan = None

    def tool_hedge_partner(self, pid, model):
        """The backup actor for (pid, model), or None: the trivial hedge's
        partner rule (later in the chain, another provider first, not failing
        recently) minus pairs a tool turn must not take (_swarm_member_sick).
        At most one per request."""
        plan = self._hedge_plan
        if not plan or not plan.get("tool_roles") or self._hedge_fired:
            return None
        try:
            saved = list(plan["chain"])
            plan["chain"] = [e for e in saved
                             if e == (pid, model) or not _swarm_member_sick(e[0], e[1])]
            try:
                return self._hedge_partner(pid, model)
            finally:
                plan["chain"] = saved
        except Exception:                                        # noqa: BLE001
            return None

    def fire_tool_hedge(self, pid, model):
        """Mark the backup actor started: consumed by the walk, no second one."""
        self._hedge_fired = True
        self._consumed.add((pid, model))

    def _plain(self, pid, model, payload, stream):
        try:
            if self._hop_budget is None:
                resp = _dispatch_chat(pid, payload, stream)
            else:
                resp = _call_with_wall_clock(self._hop_budget, _dispatch_chat,
                                             pid, payload, stream)
            _nb_close(resp)
        except _HopBudgetExceeded:
            # Only a budget big enough to be a fair wait is evidence: a hop
            # squeezed into the last second of the request deadline is not.
            if (self._hop_budget or 0) >= _ADAPTIVE_HOP_FLOOR:
                _note_recent_hop_failure(pid, model, "deadline")
            self._note_long_stall(pid, model)
            raise
        except requests.exceptions.Timeout:
            _note_recent_hop_failure(pid, model, "timeout")
            self._note_long_stall(pid, model)
            raise
        except requests.exceptions.ConnectionError:
            # A relay server that cannot even be reached on a tool turn: one
            # strike toward skipping it for tool requests (_relay_tool_sick).
            if self.tools:
                _note_relay_tool_fail(pid, model)
            raise
        self._note_status(pid, model, resp, stream)
        return resp

    def _note_long_stall(self, pid, model):
        """A LONG request's hop that waited at least LONG_CTX_FAST_MS and got
        nothing is measured not-fast at long context (see _long_ctx_band). A
        shorter wait -- a hop squeezed by the deadline -- is no evidence."""
        try:
            if self.est < LONG_CTX_SPEED_TOKENS or self._hop_started is None:
                return
            ms = (time.monotonic() - self._hop_started) * 1000.0
            if ms >= LONG_CTX_FAST_MS:
                _record_long_ctx_speed(pid, model, self.est, ms, stalled=True)
        except Exception:                                        # noqa: BLE001
            pass

    @staticmethod
    def _note_status(pid, model, resp, stream):
        try:
            code = getattr(resp, "status_code", None)
            # How the hop ended, for the overflow reply (_ctx_overflow_reply).
            _ctx_note_hop_result(pid, model, status=code)
            if code == 429:
                _note_recent_hop_failure(pid, model, "429")
            elif code == 200 and not stream:
                _clear_recent_hop_failure(pid, model)
        except Exception:                                        # noqa: BLE001
            pass

    def note_peek(self, pid, model, status):
        """Feed a streamed hop's first-content verdict to the recent-failure
        ledger: content clears it, a silent hop that used a fair budget is
        remembered (see _RECENT_FAIL_TTL)."""
        try:
            if status == "timeout":
                self._note_stall(pid)        # see walk()
                self._note_long_stall(pid, model)
            if status == "content":
                _clear_recent_hop_failure(pid, model)
            elif status == "timeout" and max(self._hop_budget or 0,
                                             self._last_peek or 0) >= _ADAPTIVE_HOP_FLOOR:
                _note_recent_hop_failure(pid, model, "deadline")
        except Exception:                                        # noqa: BLE001
            pass

    def peek_timeout(self, model, est, pid=None):
        t = _stream_peek_timeout(model, est, pid=pid)
        if self._hop_budget is not None and self._hop_started is not None:
            t = min(t, self._hop_budget - (time.monotonic() - self._hop_started))
        left = self.left()
        if left is not None:
            t = min(t, left)
        self._last_peek = max(0.0, t)
        return self._last_peek

    def guard(self, iterator, terminator=None, label=""):
        return _deadline_guard(iterator, self.deadline_at, terminator, label)


def _stream_item_bytes(item):
    if isinstance(item, (bytes, bytearray)):
        return bytes(item)
    return str(item or "").encode("utf-8", "ignore")


def _stream_item_delivers(b):
    """True when a stream item carries something the client can USE: visible
    text, a tool call, a finish reason or the terminator. A keepalive comment
    or a reasoning-only delta is not -- that is exactly what a stream held open
    past its deadline consists of."""
    return bool(_STREAM_CONTENT_RE.search(b) or _STREAM_TOOLCALL_RE.search(b)
                or _STREAM_TERMINAL_RE.search(b)
                or _STREAM_FINISH_RE.search(b)
                or _STREAM_USAGE_RE.search(b))


_STREAM_FINISH_RE = re.compile(rb'"finish_reason"\s*:\s*"')
# stream_options.include_usage sends usage as its own `choices: []` frame
# AFTER the finish_reason one; it is part of a completed answer, not a stall.
_STREAM_USAGE_RE = re.compile(rb'"usage"\s*:\s*\{')


def _deadline_guard(iterator, deadline_at, terminator=None, label=""):
    """Relay `iterator` until the request deadline, then only while it delivers.

    Before the deadline every item passes untouched (a blocked read is waited on
    only until the deadline, never past it). After it, a blank line passes, a
    delivering item passes (see _stream_item_delivers), and anything else -- a
    keepalive, a reasoning-only delta -- or _POST_DEADLINE_IDLE of silence, or
    _POST_DEADLINE_MAX in total, ends the stream with `terminator` (when given)
    so the client gets a clean end instead of a socket that never closes.

    The upstream is read on a daemon pump thread so a read blocked inside the
    socket cannot hold the wall clock hostage; the caller's own finally closes
    the upstream response, which releases the pump."""
    if not deadline_at:
        for item in iterator:
            yield item
        return
    q = queue.Queue(maxsize=256)
    stop = threading.Event()

    def _put(entry):
        while not stop.is_set():
            try:
                q.put(entry, timeout=1.0)
                return True
            except queue.Full:
                continue
        return False

    def _pump():
        try:
            for item in iterator:
                if not _put(("item", item)):
                    return
            _put(("end", None))
        except BaseException as exc:                             # noqa: BLE001
            _put(("exc", exc))

    threading.Thread(target=_pump, daemon=True).start()
    hard_stop = deadline_at + _POST_DEADLINE_MAX
    # The idle grace counts from the deadline -- or from the commit, for a
    # stream committed at the very edge of it, which is owed its first frames.
    _started = time.monotonic()
    last_delivery = None       # set when the deadline is first crossed
    cut = None
    finished = False           # a finish_reason frame has already passed
    try:
        while True:
            now = time.monotonic()
            if now < deadline_at:
                wait = deadline_at - now
            else:
                if last_delivery is None:
                    last_delivery = max(deadline_at, _started)
                wait = min(last_delivery + _POST_DEADLINE_IDLE, hard_stop) - now
                if wait <= 0:
                    cut = "no visible content for %ds past the deadline" % _POST_DEADLINE_IDLE \
                        if now < hard_stop else "hard ceiling past the deadline"
                    break
            try:
                kind, val = q.get(timeout=wait)
            except queue.Empty:
                continue       # re-evaluated at the top: deadline or idle grace
            if kind == "end":
                return
            if kind == "exc":
                raise val
            now = time.monotonic()
            b = _stream_item_bytes(val)
            if now >= deadline_at and not finished:
                if b.strip():
                    if not _stream_item_delivers(b):
                        cut = "keepalive/reasoning only past the deadline"
                        break
                    last_delivery = now
                if now >= hard_stop:
                    cut = "hard ceiling past the deadline"
                    break
            elif now >= deadline_at and b.strip():
                last_delivery = now
            if not finished and _STREAM_FINISH_RE.search(b):
                # The answer is complete: whatever trails it (a usage frame,
                # [DONE]) passes untouched, and a cut never appends a second,
                # fake finish_reason after the real one.
                finished = True
            yield val
        _log.warning("[deadline] %s: cutting the committed stream (%s)",
                     label or "stream", cut)
        if terminator and not finished:
            yield terminator
    finally:
        stop.set()


# The frames a chat-completions stream cut at the deadline ends with. "length",
# not "stop": the answer was cut short, and an agent must see a half-assembled
# tool call as truncated rather than as something to run.
_CHAT_DEADLINE_TERMINATOR = (
    b'data: {"id":"chatcmpl-deadline","object":"chat.completion.chunk",'
    b'"choices":[{"index":0,"delta":{},"finish_reason":"length"}]}\n\n'
    b"data: [DONE]\n\n")

# /v1/responses and /v1/messages translate the upstream chat stream LINE by
# line (resp.iter_lines), so their cut sentinel is one chat line. Its id tells
# _responses_stream to report the turn "incomplete"; _anthropic_stream maps its
# finish_reason "length" to stop_reason "max_tokens". Without it the iterator
# just ended and both reported a cut turn (even a half-built tool call) as done.
_DEADLINE_CUT_ID = "chatcmpl-deadline"
_DEADLINE_CUT_LINE = (
    b'data: {"id":"chatcmpl-deadline","object":"chat.completion.chunk",'
    b'"choices":[{"index":0,"delta":{},"finish_reason":"length"}]}')


# How much of a streaming answer to collect before judging it. Small on
# purpose: the failures being caught are short (an announcement is a sentence, a
# refusal opens with one), and a turn that is really working emits a tool call,
# which commits the stream immediately without waiting for any of this.
_PEEK_JUDGE_CHARS = 600
# A tool-call delta in an SSE frame, in any of the three protocols' shapes.
# An EMPTY key is not a tool call: LiteLLM-style relays serialize every content
# delta with "tool_calls":null,"function_call":null, which used to disarm the
# stream gate (and commit the peek) on the first frame of a plain answer.
# A tool-call frame that NAMES its tool (OpenAI function.name, Anthropic
# tool_use name). An empty "name" is no name.
_STREAM_TOOLNAME_RE = re.compile(rb'"name"\s*:\s*"\s*[^"\s]')


def _nameless_verdict(buffered, check):
    """Peek verdict for a stream that ENDED having sent tool-call deltas but
    never a tool name: "content" when every call's arguments name their tool
    unambiguously (_infer_tool_name -- the translator repairs them), else
    "empty": nothing a client could run, so the chain walks to the next hop
    before a byte is committed."""
    try:
        calls = {}
        for x in buffered or ():
            b = x if isinstance(x, (bytes, bytearray)) else str(x).encode("utf-8", "ignore")
            for line in b.split(b"\n"):
                line = line.strip()
                if not line.startswith(b"data:"):
                    continue
                try:
                    chunk = json.loads(line[5:].strip().decode("utf-8"))
                except (ValueError, UnicodeDecodeError):
                    continue
                for ch in (chunk.get("choices") or []) if isinstance(chunk, dict) else []:
                    for tcd in ((ch or {}).get("delta") or {}).get("tool_calls") or []:
                        if not isinstance(tcd, dict):
                            continue
                        st = calls.setdefault(tcd.get("index", 0), {"name": "", "args": []})
                        fn = tcd.get("function") or {}
                        if str(fn.get("name") or "").strip():
                            st["name"] = str(fn["name"]).strip()
                        if isinstance(fn.get("arguments"), str):
                            st["args"].append(fn["arguments"])
        tools = (check or {}).get("tools")
        if calls and all(st["name"] or _infer_tool_name("".join(st["args"]), tools)
                         for st in calls.values()):
            return "content"
    except Exception:                                            # noqa: BLE001
        pass
    return "empty"


_STREAM_TOOLCALL_RE = re.compile(
    rb'"(?:tool_calls|function_call|tool_use|function_call_arguments)"'
    rb'(?!\s*:\s*(?:null\b|\[\s*\]|\{\s*\}|""))', re.I)


def _judge_peeked(chunks, check=None, raw_items=None, prompt=None, complete=True):
    """"content", "nonanswer" or "junk" for the text collected during the peek.

    Runs the same three detectors the non-streaming path has always had. They
    were unreachable on a stream, which is the path Codex and Claude Code
    actually use -- so a turn that typed its tool call, announced work it never
    did, or declined outright was relayed to the CLI as a finished answer.

    Plus the upstream error-page check on the WHOLE collected text: the per-
    frame check in _peek_until_content misses one split across deltas, and
    provider error phrasing (_provider_error_kind) is only judged whole.
    `prompt` is the last user turn (the peek runs off the request thread).

    With `check` ({prompt_text, last_prompt, tools_offered}) it also runs
    answer_check.inspect -- the _answer_gate verdict -- on the peeked answer:
    junk with NOTHING salvageable is "junk", and the chain moves to the next
    hop while it still can (nothing is committed yet). Junk WITH a salvage is
    "content": the committed stream's _StreamAnswerGate serves the clean part."""
    _set_nonanswer_kind(None)
    try:
        text = _peeked_text("".join(chunks))
        if not text:
            return "content"
        # A claim to have no tools on a turn that offered them (see
        # _no_tools_claim). The peek commits at once on a real tool call, so
        # text reaching here carried none so far; kind "no_tools_claim" makes
        # it a quality failure, not a dead-mark.
        if check and check.get("tools_offered") and _no_tools_claim(
                text, tools_offered=True,
                prompt=prompt if prompt is not None else check.get("last_prompt"),
                used_tools=bool(check.get("used_tools")), complete=complete):
            _set_nonanswer_kind("no_tools_claim")
            return "nonanswer"
        # A bare announcement on a TOOL turn is judged only on the COMPLETE
        # reply: mid-stream "I'll update the" is usually the lead-in to the
        # tool call that follows (the peek reads on for it -- see
        # _announce_pending), and judging the partial text threw such turns
        # away. Kind "announced": a quality failure, one retry per request.
        tools_turn = bool(check and check.get("tools_offered"))
        if tools_turn and complete and _ends_with_announcement(text):
            _set_nonanswer_kind("announced")
            return "nonanswer"
        if (_looks_like_text_tool_call(text)
                or (not tools_turn and _looks_like_announced_not_acted(text))
                or _looks_like_refusal(text)
                or _is_upstream_nonanswer(text, prompt)
                # Bare-tool-name and dangling-colon only mean anything on a
                # COMPLETE reply: mid-stream, "Changes made to parser.py:" is
                # just the lead-in to the list that follows.
                or (complete and check and check.get("tools")
                    and (tool_rescue.is_bare_tool_name(text, check.get("tools"))
                         or _looks_like_dangling_lead_in(text)))):
            return "nonanswer"
        if check and raw_items:
            items = [x if isinstance(x, (bytes, bytearray))
                     else str(x).encode("utf-8", "ignore") for x in raw_items if x]
            # iter_lines items carry no newline; iter_content chunks do.
            sep = b"" if any(b"\n" in x for x in items) else b"\n"
            full, saw_tools, fin = _sse_answer_digest([sep.join(items)])
            if (check.get("starve_check") and not saw_tools
                    and _is_truncated_stub(full, fin, check.get("budget"))):
                # The stream ENDED at "length" on a stub ("94" of 2994): the
                # budget went to hidden reasoning. Caught here, before a byte
                # is committed, so the loop can retry with room.
                return "starved"
            if full.strip() and not saw_tools:
                v = answer_check.inspect(
                    full, prompt_text=check.get("prompt_text"),
                    tools_offered=bool(check.get("tools_offered")),
                    finish_reason=fin,
                    last_prompt=check.get("last_prompt"))
                if not v.get("ok", True) and not v.get("salvage"):
                    return "junk"
    except Exception:                                            # noqa: BLE001
        pass
    return "content"


# A JSON string value for one of the keys an SSE delta puts visible text
# under. Non-greedy up to the first unescaped quote.
_PEEK_TEXT_RE = re.compile(r'"(?:content|text)"\s*:\s*"(.*?)(?<!\\)"', re.S)


def _peeked_text(raw):
    """The assistant's visible text, pulled out of raw SSE frames.

    Deliberately regex rather than a JSON parse: these are partial frames from
    three different protocols, and a strict parse would throw away the very
    turns worth judging (the measured one was malformed JSON -- one '[' and no
    ']')."""
    out = []
    for m in _PEEK_TEXT_RE.finditer(raw or ""):
        try:
            out.append(json.loads('"%s"' % m.group(1)))
        except Exception:                                        # noqa: BLE001
            out.append(m.group(1))
    return "".join(out).strip()


def _empty_or_starved(buf, check):
    """Verdict for a stream that ENDED with no visible text: 'starved' when it
    ended on finish_reason "length" (all of the budget went to reasoning --
    retryable with room, see _stream_starve_retry), else 'empty'."""
    try:
        if check and check.get("starve_check"):
            _text, saw_tools, fin = _buffered_digest(buf)
            if fin == "length" and not saw_tools:
                return "starved"
    except Exception:                                            # noqa: BLE001
        pass
    return "empty"


def _buffered_digest(buffered):
    """_sse_answer_digest over peeked stream items, whichever way they were
    read (iter_lines items carry no newline; iter_content chunks do)."""
    items = [x if isinstance(x, (bytes, bytearray))
             else str(x).encode("utf-8", "ignore") for x in (buffered or ()) if x]
    sep = b"" if any(b"\n" in x for x in items) else b"\n"
    return _sse_answer_digest([sep.join(items)])


def _stream_starve_retry(clock, pid, model, payload, est, has_tools, tools, lines):
    """ONE same-pair retry for a streamed hop whose peek said 'starved', with
    the reasoning allowance on top of what was sent. Nothing has reached the
    client yet (the peek commits nothing), so the retry is invisible to it.
    Returns (resp, iterator, status, buffered, payload) of the retry -- status
    is the retry's own peek verdict -- or None when no retry was possible (the
    caller walks on). A retry that starves again files a quality failure."""
    _note_thinking(pid, model, "starved stream")
    retry = _starve_retry_payload(pid, payload, "stub")
    if retry is None:
        _record_outcome(pid, model, False)
        return None
    retry["stream"] = True
    try:
        resp2 = clock.dispatch(pid, retry, True, hedge=False)
    except Exception:                                            # noqa: BLE001
        return None
    if getattr(resp2, "status_code", None) != 200:
        try:
            resp2.close()
        except Exception:                                        # noqa: BLE001
            pass
        return None
    it = (resp2.iter_lines(decode_unicode=False) if lines
          else resp2.iter_content(chunk_size=None))
    if has_tools:
        it = tool_rescue.rescue_stream(it, tools, "lines" if lines else "frames")
    status, buffered = _peek_until_content(
        it, clock.peek_timeout(model, est, pid=pid), content_grace=clock.content_grace(),
        check=_peek_check(retry, has_tools))
    clock.note_peek(pid, model, status)
    if status == "starved":
        _record_outcome(pid, model, False)
    return resp2, it, status, buffered, retry


def _peek_until_content(iterator, deadline_s, max_lines=400, content_grace=0.0,
                        on_content=None, check=None):
    """Look ahead on a streaming 200 to tell a REAL answer from an EMPTY one before
    committing it to the client. Reads SSE items (bytes) until one carries actual
    content / a tool call (the provider is really answering), or the stream
    TERMINATES with none (an empty 200 — some free providers 200 then stream only a
    role delta + [DONE], which left codex with nothing and no retry), or the stream
    goes idle past `deadline_s` (hung). Buffers everything it reads so the caller can
    replay it losslessly. Returns (status, buffered):
      'content' -> commit; stream `buffered` then the rest of the SAME iterator.
      'empty'   -> carried no content; caller closes resp + falls through to next model.
      'error'   -> the 200 body carries an upstream error frame (a 403/quota refusal
                   delivered inside the stream); caller falls through to next model.
      'timeout' -> nothing usable arrived in time; caller falls through.
      'junk'    -> only with `check` (see _judge_peeked): the peeked answer is
                   degenerate with nothing salvageable; caller falls through.
    Same daemon-worker discipline as _peek_first_chunk: the buffer/iterator are only
    used when the worker FINISHED (status set) so there's never concurrent iteration."""
    box = {"buf": [], "status": None, "kind": None}
    prompt = _request_prompt_text()   # the worker has no request context
    started = time.monotonic()
    # A tools turn where "I don't have tools" would be a non-answer: the peek
    # reads on past its usual verdict point for that claim alone (below).
    watch = bool(check and check.get("tools_offered") and _no_tools_watch(
        tools_offered=True,
        prompt=prompt if prompt is not None else check.get("last_prompt"),
        used_tools=bool(check.get("used_tools"))))
    tools_turn = bool(check and check.get("tools_offered"))

    def _judge(seen, complete=True):
        verdict = _judge_peeked(seen, check, box["buf"], prompt=prompt,
                                complete=complete)
        box["kind"] = _take_nonanswer_kind()
        return verdict

    def _read_on_end(seen):
        """Verdict for a stream that ENDED while the peek read on for a
        no-tools claim or a possible bare announcement: everything else was
        judged "content" already."""
        text = _peeked_text("".join(seen))
        if watch and _looks_like_no_tools_claim(text):
            box["kind"] = "no_tools_claim"
            return "nonanswer"
        if tools_turn and _ends_with_announcement(text):
            box["kind"] = "announced"
            return "nonanswer"
        return "content"

    def _worker():
        buf = box["buf"]
        saw_reasoning = False
        seen_content = []
        read_on_at, read_on_budget = None, 0.0
        try:
            for _ in range(max_lines):
                item = next(iterator)
                buf.append(item)
                if not item:
                    continue
                b = item if isinstance(item, (bytes, bytearray)) \
                    else str(item).encode("utf-8", "ignore")
                # A real tool call means the model is DOING the work. Commit at
                # once: nothing below can improve on that, and every extra frame
                # here is latency on the turns that are going well.
                if _STREAM_TOOLCALL_RE.search(b):
                    # ...but only a call that NAMES its tool. A nameless start
                    # frame usually gets its name on the next delta; one that
                    # never does is not work (codex cannot run it), so keep
                    # reading until a name arrives or the stream ends (judged
                    # below by _peeked_tools_usable). Without tool context
                    # (`check`) the old commit-at-once rule stands.
                    if _STREAM_TOOLNAME_RE.search(b) or not (check and check.get("tools")):
                        box["status"] = "content"
                        return
                    box["nameless_tool"] = True
                    continue
                if _STREAM_CONTENT_RE.search(b):
                    # LIVE-VERIFIED 2026-08-07: the api.airforce backend behind
                    # g4f ships its ENTIRE error in ONE content delta, so a
                    # per-frame check catches it before the stream is committed.
                    # This is the path Codex and Claude Code actually use, and
                    # the frame really is content -- _STREAM_ERROR_VALUE_RE below
                    # never fires because there is no "error" key anywhere.
                    if len(b) <= 1024 and _NONANSWER_RE.search(
                            b.decode("utf-8", "ignore")):
                        box["status"] = "nonanswer"
                        return
                    # KEEP READING instead of committing on the first delta.
                    #
                    # MEASURED 2026-08-31: every dead-turn detector the hub has
                    # -- a tool call typed out as prose, a turn that only
                    # announces work, a refusal -- hangs off _chat_json_nonanswer,
                    # which runs ONLY on non-streaming bodies. Codex and Claude
                    # Code both stream, so on the path that matters none of them
                    # ever ran. Committing here on the first content delta is why:
                    # at that moment there is no text to judge.
                    #
                    # So accumulate a little of the answer first. The failures
                    # being caught are short by nature (an announcement is one
                    # sentence; a refusal opens with one), while a turn that is
                    # really working reaches for a tool -- and that exits above
                    # without waiting at all. Bounded by _PEEK_JUDGE_CHARS and by
                    # the deadline this whole peek already runs under.
                    seen_content.append(b.decode("utf-8", "ignore"))
                    if not box.get("saw_content") and on_content is not None:
                        try:
                            on_content()
                        except Exception:                        # noqa: BLE001
                            pass
                    box["saw_content"] = True
                    if sum(len(x) for x in seen_content) < _PEEK_JUDGE_CHARS:
                        continue
                    if read_on_at is None:
                        verdict = _judge(seen_content, complete=False)
                        # A tool turn whose reply so far may still END as a
                        # bare announcement ("I'll read the file."): read on
                        # until a tool call arrives (commit), the text grows
                        # past one (commit) or the stream ends (judged whole
                        # by _read_on_end). MEASURED LIVE 2026-09-27: codex's
                        # turn ended on "I'll read the last line of big1.txt
                        # for you." -- committed after ~4 per-token frames.
                        box["ann"] = (verdict == "content" and tools_turn
                                      and _announce_pending(_peeked_text("".join(seen_content))))
                        if verdict != "content" or not (watch or box["ann"]):
                            box["status"] = verdict
                            return
                        # MEASURED 2026-09-27: _PEEK_JUDGE_CHARS counts frame
                        # BYTES, so on per-token frames the verdict above saw
                        # ~4 tokens ("I'm here to help, but I") and "I
                        # currently don't have the tools" came after it. Read
                        # on for that claim alone, while it is still possible
                        # (_no_tools_peek_state), within _NO_TOOLS_PEEK_EXTRA_S
                        # and never past what the peek itself may wait.
                        read_on_at = time.monotonic()
                        read_on_budget = max(0.0, min(
                            _NO_TOOLS_PEEK_EXTRA_S,
                            deadline_s + (content_grace or 0.0)
                            - (read_on_at - started) - 0.5))
                        box["nt"] = watch
                    text_now = _peeked_text("".join(seen_content))
                    if box.get("nt"):
                        state = _no_tools_peek_state(text_now)
                        if state == "claim":
                            box["kind"] = "no_tools_claim"
                            box["status"] = "nonanswer"
                            return
                        if state == "clear" or time.monotonic() - read_on_at >= read_on_budget:
                            box["nt"] = False
                    if box.get("ann") and not _announce_pending(text_now):
                        box["ann"] = False
                    if not (box.get("nt") or box.get("ann")):
                        box["status"] = "content"
                        return
                    continue
                # An error INSIDE a 200 stream (403/429/quota reported as an SSE
                # error frame instead of an HTTP status) — the single most common
                # way a provider dead-ends a turn. Report it so the caller drops
                # this hop and tries the next model instead of committing a stream
                # that will never produce an answer.
                if _STREAM_ERROR_VALUE_RE.search(b):
                    box["status"] = "error"
                    return
                if _STREAM_TERMINAL_RE.search(b):
                    # The stream ENDED. With content already read that is a
                    # SHORT, COMPLETE answer -- judge it, exactly like the
                    # StopIteration branch below. Calling it "empty" threw away
                    # every answer under _PEEK_JUDGE_CHARS whose [DONE] arrived
                    # as its own read ("5768" then finish then [DONE], which is
                    # every iter_lines stream -- each line on the /v1/responses
                    # and /v1/messages paths -- and many iter_content ones):
                    # the trivial answers this chain most needs to keep.
                    box["status"] = (_read_on_end(seen_content) if read_on_at is not None
                                     else _judge(seen_content) if seen_content
                                     else _nameless_verdict(buf, check)
                                     if box.get("nameless_tool")
                                     else _empty_or_starved(buf, check))
                    return
                if _STREAM_REASONING_RE.search(b):
                    saw_reasoning = True
            # Budget exhausted with no content marker. Only treat that as a real
            # stream if we saw the model THINKING (reasoning deltas) — otherwise it
            # was 400 lines of keepalives/role deltas and committing it hands the
            # CLI a stream that never answers.
            if read_on_at is not None:
                box["status"] = "content"     # judged already; no claim seen
            elif seen_content:
                box["status"] = _judge(seen_content, complete=False)
            else:
                # A long nameless tool stream: commit only when its arguments
                # so far name the tool (_nameless_verdict; the translator then
                # repairs it). An uninferable one would reach codex as an
                # empty response.completed with the 200 already committed, so
                # it walks to the next hop like a short one does.
                if box.get("nameless_tool"):
                    box["status"] = _nameless_verdict(buf, check)
                else:
                    box["status"] = "content" if saw_reasoning else "empty"
        except StopIteration:
            # The stream ENDED inside the peek window, so everything the model
            # was ever going to say is in hand -- the best possible moment to
            # judge it, and the shape a dead turn usually has.
            box["status"] = (_read_on_end(seen_content) if read_on_at is not None
                             else _judge(seen_content) if seen_content
                             else _nameless_verdict(buf, check)
                             if box.get("nameless_tool")
                             else _empty_or_starved(buf, check))
        except Exception:
            box["status"] = "empty"     # read error/timeout -> unusable, fall through

    t = threading.Thread(target=_worker, daemon=True)
    t.start()
    if clientgone.join(t, deadline_s):
        return "cancelled", []      # the client left (clientgone)
    if t.is_alive() and content_grace and box.get("saw_content"):
        # VISIBLE TEXT IS ALREADY ARRIVING -- it just has not reached
        # _PEEK_JUDGE_CHARS (or the end of the stream) yet. With the tight
        # trivial-turn budgets (see _adaptive_hop_budget) the deadline could
        # land mid-sentence and throw away a model that was answering; a hop
        # that is streaming words is never cut here, only one that is silent.
        # `content_grace` bounds the wait (the request deadline's remainder).
        t.join(content_grace)
    if t.is_alive():
        return "timeout", []
    status = box.get("status") or "empty"
    # The verdict's KIND for the caller's _note_nonanswer (same thread as it).
    _set_nonanswer_kind(box.get("kind") if status == "nonanswer" else None)
    return status, list(box["buf"])


def _chain_buffered(buffered, iterator):
    """Yield each already-read item in `buffered`, then the rest of `iterator` — the
    multi-item version of _chain_first, used to replay a look-ahead losslessly."""
    for item in buffered or ():
        yield item
    for item in iterator:
        yield item


def _chat_json_is_empty(data):
    """True if an OpenAI chat-completions JSON carried NO assistant content AND no
    tool calls — a non-streamed 'empty 200' that should fall through to the next
    model. Conservative: returns False on anything unexpected so a real answer is
    never discarded."""
    try:
        msg = ((data.get("choices") or [{}])[0] or {}).get("message") or {}
        content = msg.get("content")
        if isinstance(content, list):  # content-parts -> join their text
            content = "".join((p.get("text") or "") for p in content
                              if isinstance(p, dict))
        has_text = bool(content and str(content).strip())
        # A tool_call counts as content ONLY if it has a usable function name — a
        # nameless/blank tool_call is unusable and should fall through to a real model.
        has_tools = any(
            isinstance(tc, dict) and ((tc.get("function") or {}).get("name") or "").strip()
            for tc in (msg.get("tool_calls") or []))
        return not (has_text or has_tools)
    except Exception:
        return False


# A 200 whose "answer" IS the relay backend's error page.
#
# MEASURED LIVE 2026-08-07, reproduced twice with the hub's own g4f key:
#   model=srv_mp3lmkuad07322459f47:claude-opus-4-7  ->  HTTP 200,
#   finish_reason "stop", usage {"total_tokens": 399}, content =
#   "The model does not exist in https://api.airforce\ndiscord.gg/airforce"
#   -- character for character what the user reported, four separate times.
#
# g4f fronts ~42 donated backends; api.airforce answers an unknown model id
# with 200 + error-as-content instead of a 4xx. That is why FOUR previous
# fixes changed nothing: _DEAD_STATUSES, _maybe_mark_missing_model, the
# non-2xx _record_outcome(False) and the last_hard relay ALL live in the
# non-2xx branch, and this request never enters it -- the chain does not
# exhaust, it SUCCEEDS on hop 1 and returns. Worse, _record_chat_usage files
# every delivery as _record_outcome(..., True), so the reliability signal was
# PROMOTING the id while it kept its 138 claude-family score floor.
#
# Content is the only signal that exists here. Requiring the WHOLE message to
# be short is what makes it safe: a real model quoting "model does not exist"
# inside a genuine reply is never a <300-char complete answer, and a false
# positive costs only a fall-through to the next hop -- exactly what an empty
# 200 already pays.
_NONANSWER_MAX_CHARS = 300
_NONANSWER_RE = re.compile(
    r"model (?:'[^']*' )?does\s?n[o']?t exist"
    r"|requires an active subscription"
    r"|rate limit exceeded"
    r"|insufficient (?:credits|balance|quota)"
    r"|no cake credits"
    r"|discord\.gg/"
    # google/gemini-3.6-flash via g4f, MEASURED 2026-08-09: a Codex session
    # ships this AS THE STREAMED CONTENT (HTTP 200, no error status at all --
    # see _SOFT_400_CONTEXT_RE for the 400-status twin of this same phrasing),
    # so only the content-level nonanswer check (_peek_until_content) can
    # catch it; the soft-400 regex never runs because there is no 400 here.
    # Without this the hub committed the stream and relayed the provider's
    # own error text to Codex as if it were the real answer.
    r"|maximum prompt length", re.I)


# PROVIDER ERROR PHRASING delivered as the answer.
#
# MEASURED 2026-09 (live sweep, /v1/responses model "best", non-stream): an
# upstream relay answered HTTP 200 with the content "The API key used for this
# request has reached ..." and the hub served it as the assistant's reply.
# _NONANSWER_RE knows a handful of exact relay strings; this is the general
# shape -- a key/quota/credit/rate limit, an unknown model, "try again later".
#
# Conservative on three axes, because a real answer can say these words:
#   * the whole reply is short (_PROVIDER_ERROR_MAX_CHARS);
#   * it is MOSTLY the error: the sentences carrying the phrasing make up at
#     least _PROVIDER_ERROR_SHARE of it ("Set your API key in OPENAI_API_KEY,
#     then ..." is advice, and matches nothing here anyway);
#   * the last user turn did not ask about keys/quotas/limits/billing -- then
#     a short reply ABOUT them is exactly right.
# A hit is not a 6h ban (unlike _NONANSWER_RE): the failure is filed, and a
# key/quota/credit/rate limit additionally cools the pair down (_note_nonanswer).
_PROVIDER_ERROR_MAX_CHARS = 400
_PROVIDER_ERROR_SHARE = 0.6
_PROVIDER_QUOTA_COOLDOWN = 1800
_PROVIDER_QUOTA_RE = re.compile(
    r"\bapi[\s_-]?key\b[^.\n]{0,80}?\b(?:has\s+|have\s+|is\s+|was\s+)?(?:reached|exceeded"
    r"|hit|run\s+out|exhausted|expired|revoked|disabled|suspended|over\s+(?:its|the)\s+limit)"
    r"|\b(?:invalid|incorrect|expired|revoked|missing|disabled)\s+api[\s_-]?key\b"
    r"|\bquota\b[^.\n]{0,40}?\b(?:exceeded|exhausted|reached|used\s+up)"
    r"|\b(?:exceeded|reached|hit|exhausted)\s+(?:your|the|its|this)\s+(?:\w+\s+){0,3}?"
    r"(?:quota|rate[\s-]?limit|usage\s+limit|limit|credits?|allowance)\b"
    r"|\binsufficient\s+(?:credits?|balance|quota|funds)\b"
    r"|\b(?:credits?|balance|tokens?)\s+(?:is\s+|are\s+|has\s+been\s+|have\s+been\s+)?"
    r"(?:exhausted|depleted|insufficient|used\s+up|too\s+low)\b"
    r"|\brate[\s-]?limit(?:ed|s)?\b[^.\n]{0,30}?\b(?:reached|exceeded|hit)\b"
    r"|\btoo\s+many\s+requests\b"
    r"|\bupgrade\s+(?:your|to\s+a)\s+(?:\w+\s+)?(?:plan|account|subscription|tier)\b"
    r"|\b(?:daily|monthly|free|usage|request)\s+(?:usage\s+)?limit\s+(?:has\s+been\s+)?"
    r"(?:reached|exceeded)\b", re.I)
_PROVIDER_ERROR_RE = re.compile(
    r"\baccount\s+(?:has\s+been|is|was)\s+(?:suspended|disabled|banned|deactivated|blocked"
    r"|restricted|locked|flagged)\b"
    r"|\bno\s+such\s+model\b", re.I)
# GENERIC error phrasing counts only in the upstream's own voice: the sentence
# OPENS with it. "No, the model is not available on Azure yet." and "The job
# failed because the service is temporarily unavailable." are answers.
_PROVIDER_GENERIC_RE = re.compile(
    r"^\W*(?:(?:error|sorry)\b[\s:,.!-]*)?(?:"
    r"(?:the\s+)?model\s+(?:[`'\"][^`'\"\n]{1,80}[`'\"]\s+|\S+\s+)?(?:is\s+|was\s+)?"
    r"(?:not\s+found|not\s+available|unavailable|not\s+supported|does\s?n[o']?t\s+exist)\b"
    r"|(?:please\s+)?try\s+again\s+later\b"
    r"|(?:the\s+)?service\s+(?:is\s+)?(?:temporarily\s+)?unavailable\b"
    # A relay's sign-up wall. MEASURED 2026-09-27: g4f's Perplexity route
    # answered reasoning-max with exactly "Sign up and repeat your request."
    r"|sign\s+(?:up|in)\s+(?:and|to)\s+(?:repeat|retry|resend|continue|use)\b)", re.I)
# The relay speaking about THIS request -- "The API key used for this request
# has reached its budget." A model explaining an expired key to a user says
# "your key", not "this request".
_PROVIDER_RELAY_VOICE_RE = re.compile(r"\b(?:this|the)\s+request\b|\bthis\s+app\b", re.I)
# The follow-up lines an error page carries after its opening sentence: what
# to do about it, never content.
_PROVIDER_SUPPORT_RE = re.compile(
    r"try\s+again|top(?:ping)?\s+up|raise\s+(?:the|your)|contact\s+(?:whoever|the|your|support)"
    r"|wallet|upgrade|sign\s+(?:up|in)|billing|edit-key|dashboard|your\s+account|this\s+limit",
    re.I)
# The request's last turn carries TOOL RESULTS (an agent loop): a short reply
# then faithfully reports a tool's error output ("the registry returned 429
# Too Many Requests"), which is the answer, not the provider's error page.
_TOOL_RESULT_TURN = "\x00tool-results\x00"
# The last user turn asking ABOUT keys/quotas/limits: then a short reply about
# them is an answer, not an error page.
_PROVIDER_ERROR_PROMPT_RE = re.compile(
    r"api[\s_-]?keys?|apikey|quota|rate[\s-]?limit|\bcredits?\b|billing|\bbalance\b"
    r"|subscription|usage\s+limit|\bupgrade|\b(?:401|402|403|429)\b|error\s+message", re.I)
# A sentence that opens as advice or a condition explains an error; it is not one.
_PROVIDER_ADVICE_RE = re.compile(
    r"\W*(?:if|when|whenever|unless|once|to|make\s+sure|ensure|check|verify|consider"
    r"|you\s+(?:can|should|may|might|could|need)|this\s+(?:means|happens)|it\s+means)\b",
    re.I)
_PROMPT_UNSET = object()
# Which KIND of non-answer the detector just saw, for _note_nonanswer: set by
# the detectors on the request thread (the peek hands its worker's verdict
# back to that thread too), consumed by the next _note_nonanswer.
_nonanswer_tls = threading.local()


def _set_nonanswer_kind(kind):
    _nonanswer_tls.kind = kind


def _take_nonanswer_kind():
    kind = getattr(_nonanswer_tls, "kind", None)
    _nonanswer_tls.kind = None
    return kind


def _peek_nonanswer_kind():
    """The kind _take_nonanswer_kind would return, left in place for it."""
    return getattr(_nonanswer_tls, "kind", None)


def _request_prompt_text():
    """The LAST user turn of the request being served, any of the three
    protocols' shapes; None outside a request. Never raises."""
    try:
        if not has_request_context():
            return None
        body = request.get_json(force=True, silent=True)
        if not isinstance(body, dict):
            return None
        turns = body.get("messages")
        if not isinstance(turns, list):
            inp = body.get("input")
            if isinstance(inp, str):
                return inp[:_PROMPT_CHECK_CAP]
            turns = inp if isinstance(inp, list) else []
        if turns and _carries_tool_results(turns[-1]):
            return _TOOL_RESULT_TURN
        for m in reversed(turns):
            if not isinstance(m, dict) or m.get("role") != "user":
                continue
            c = m.get("content")
            if isinstance(c, list):
                c = "\n".join(p.get("text") or "" for p in c
                              if isinstance(p, dict) and isinstance(p.get("text"), str))
            return (c if isinstance(c, str) else "")[:_PROMPT_CHECK_CAP]
        return ""
    except Exception:                                            # noqa: BLE001
        return None


def _carries_tool_results(m):
    """True for a turn that IS tool output: OpenAI role "tool", an Anthropic
    user turn of tool_result blocks, a Responses function_call_output item."""
    if not isinstance(m, dict):
        return False
    if m.get("role") == "tool" or m.get("type") == "function_call_output":
        return True
    c = m.get("content")
    return (m.get("role") == "user" and isinstance(c, list)
            and any(isinstance(p, dict) and p.get("type") == "tool_result" for p in c))


def _provider_error_kind(text, prompt=None):
    """"provider_quota" | "provider_error" | None -- see the note above.

    The error must be the upstream's OWN voice: the reply's opening sentence
    is a hit (not a report further in), generic phrasing ("try again later",
    "model ... not available") only counts where it opens a sentence, and a
    turn answering tool results is never judged (an agent's faithful report
    of a tool's error output looked exactly like a relay's error page)."""
    s = (text or "").strip()
    if not s or len(s) > _PROVIDER_ERROR_MAX_CHARS:
        return None
    # A tool-result turn is judged ONLY for the unmistakable error page: a
    # quota sentence in the relay's own voice ("... used for this request has
    # reached its budget") opening the reply, followed by nothing but what-to-
    # do lines. MEASURED 2026-09-27 (/agent, codex "continue" after a stop):
    # g4f answered exactly that page while the last input item was a tool
    # output, the blanket exemption waved it through, and the turn ENDED with
    # the relay's billing notice as the agent's reply.
    after_tools = prompt == _TOOL_RESULT_TURN
    if after_tools:
        prompt = None
    if prompt and _PROVIDER_ERROR_PROMPT_RE.search(prompt):
        return None
    hit, total, quota, first = 0, 0, False, None
    first_quota_voice, rest_support = False, True
    for sent in re.split(r"(?<=[.!?])\s+|\n+", s):
        sent = sent.strip()
        if not sent:
            continue
        total += len(sent)
        is_hit = False
        if not _PROVIDER_ADVICE_RE.match(sent):   # "If your API key has expired" is advice
            q = _PROVIDER_QUOTA_RE.search(sent)
            if q or _PROVIDER_ERROR_RE.search(sent) or _PROVIDER_GENERIC_RE.match(sent):
                hit += len(sent)
                quota = quota or bool(q)
                is_hit = True
                if first is None and q and _PROVIDER_RELAY_VOICE_RE.search(sent):
                    first_quota_voice = True
        if first is None:
            first = is_hit
        elif not is_hit and not _PROVIDER_SUPPORT_RE.search(sent):
            rest_support = False
    if not hit or not first:
        return None
    if after_tools:
        return ("provider_quota" if quota and first_quota_voice and rest_support
                else None)
    # A quota error that OPENS the reply, followed only by what-to-do lines,
    # is an error page however long those lines are. MEASURED 2026-09-27: a
    # Pollinations relay answered every tier with "The API key used for this
    # request has reached its budget. Please raise the key budget ..., then
    # try again. Topping up the wallet does not raise this limit. If this
    # isn't your Pollinations account, contact whoever runs the app ..." --
    # the opening sentence was 17% of the text, under the share rule below,
    # so it was served as the answer on all three protocols.
    if quota and (first_quota_voice or rest_support):
        return "provider_quota"
    if hit < _PROVIDER_ERROR_SHARE * total:
        return None
    return "provider_quota" if quota else "provider_error"


def _is_upstream_nonanswer(text, prompt=_PROMPT_UNSET):
    """True if `text` is a COMPLETE, SHORT message that is an upstream service's
    error/branding rather than an answer. `prompt` (the last user turn) defaults
    to the request being served."""
    _set_nonanswer_kind(None)
    s = (text or "").strip()
    if not s:
        return False
    if len(s) <= _NONANSWER_MAX_CHARS and _NONANSWER_RE.search(s):
        return True
    if prompt is _PROMPT_UNSET:
        prompt = _request_prompt_text()
    kind = _provider_error_kind(s, prompt)
    if kind:
        _set_nonanswer_kind(kind)
        return True
    return False


# A tool call TYPED OUT as prose instead of emitted as a tool_calls array.
# MEASURED 2026-08-30 from a reported build that "stopped and did not finish" --
# the last two agent turns of that conversation both ended like this:
#
#     I'll now check all the generated pages...
#     ```shell
#     shell_command
#     <arg_key>command</arg_key>
#     <arg_value>Get-Content robots.txt -Raw</arg_value>
#     </tool_call>
#
# No tool_calls array, so the CLI saw an ordinary prose message, had nothing to
# execute and ended the turn. Nothing ran, nothing was written, and the hub
# recorded a clean success -- so it learned nothing and picked the same model
# again next turn.
#
# Detected from the RESPONSE rather than from a per-model blacklist on purpose:
# _TOOL_DIALECT_MISMATCH's own comment already concedes a blacklist is
# whack-a-mole ("three runs found three DIFFERENT model-specific ways to
# fail"), and this catches models nobody has met yet.
# MEASURED 2026-08-31: the live failures had moved dialect. The last agent turn
# of the most recent session typed a fenced ```json block containing
# {"tool_calls": [{"name": "shell_command", "arguments": {...}}]} -- valid-
# looking JSON (actually malformed: one [ and no ]) with no XML anywhere, so all
# three XML patterns missed it. An earlier turn used an OPENING <tool_call> that
# was never closed, which the closing-tag pattern also missed.
_TEXT_TOOL_CALL_RES = (
    re.compile(r"</tool_call>", re.I),
    re.compile(r"<tool_call\b", re.I),
    re.compile(r"<arg_key>.*?</arg_key>", re.I | re.S),
    re.compile(r"<arg_value>.*?</arg_value>", re.I | re.S),
    # the JSON dialect, fenced or bare: a tool_calls / function_call structure
    # written into the CONTENT instead of emitted as a tool call
    re.compile(r'"tool_calls"\s*:\s*\[', re.I),
    re.compile(r'"function_call"\s*:\s*\{', re.I),
    re.compile(r'```(?:json|tool_code|python)?\s*\{\s*"(?:name|tool|command)"\s*:', re.I),
)


# A turn that ANNOUNCED work instead of doing it.
#
# REPORTED 2026-08-31 from a real /build conversation -- two turns in a row,
# both straight after an explicit "continue", both ending as "Finished":
#   "I'll now craft a premium editorial UI system..."      (177 chars)
#   "I am now hard-coding the pillar architecture..."      (118 chars)
# No tool calls at all. One burned 2m 27s to say it. Nothing was written, and
# the hub scored both as clean successes -- so it learned nothing and picked
# the same models again next turn.
#
# ACT's first bullet did not cover it: it opens "If you already called a tool
# this turn", and these called nothing. That hole is closed in craft.ACT_RUN
# too, but a prompt rule only works when the model reads it; this is the
# structural half.
#
# TENSE is the discriminator, and it has to be. "Done -- all 12 pages built" is
# a perfectly good short final answer with no tool calls, and "I'll now build
# the 12 pages" is the same length and a dead turn. So: a statement of INTENT
# to do work, with no question in it, on a turn that offered tools.
# MEASURED 2026-08-31 across the three most recent sessions: this caught 2 of 13
# agent turns. It was ^-anchored, so "Core helpers are ready. Now I'll write the
# content generator." -- a turn that ended right there -- did not match, because
# the intent phrase was not at position 0. It also only knew the ASCII
# apostrophe, so "I'm locking the architecture" with a curly U+2019 missed, and
# it had no gerund form, so "Now writing the complete landing page." (the whole
# 38-character turn) missed.
#
# Now: the intent phrase may open ANY sentence in a short message, both
# apostrophes count, and the bare gerund is included.
_INTENT_RE = re.compile(
    r"(?:^|(?<=[.!?])\s|(?<=\n))\W*"
    r"(?:i\s*['’]?\s*(?:ll|m)\b|i will|i am (?:now )?|i\s*['’]?m (?:now )?going to"
    r"|i\s*['’]?m (?:now )?about to|let me|now i\s*['’]?ll|next,? i\s*['’]?ll"
    r"|next,? i will|now (?:writing|creating|building|generating|adding|updating)"
    r"|proceeding to|moving (?:on )?to|starting (?:on|with))", re.I)
_WORK_VERB_RE = re.compile(
    r"\b(?:build\w*|rebuild\w*|creat\w*|writ\w*|add\w*|updat\w*|fix\w*|redesign\w*|design\w*"
    r"|implement\w*|generat\w*|craft\w*|hard-?cod\w*|refactor\w*|instal\w*|run|test\w*"
    r"|deploy\w*|styl\w*|check\w*|verif\w*|deliver\w*|produc\w*|set up|wire\w*"
    # measured misses: "I'm locking the architecture", "moving forward with"
    r"|lock\w*|scaffold\w*|assembl\w*|final(?:is|iz)\w*|batch\w*|wrap\w*"
    r"|mov\w+ forward|start\w*|continu\w*|proceed\w*)\b", re.I)
# An announcement is SHORT by nature -- it is a sentence about what comes next,
# not the work. A long answer that happens to open with "I'll walk through..."
# is a real deliverable and must not be touched.
_ANNOUNCE_MAX_CHARS = 400


# A model DECLINING the task. The fourth way a clean 200 turns out not to be an
# answer, after a relay's error page as content, a tool call typed out as prose,
# and a turn that only announced work.
#
# ASKED 2026-08-31: "if task can't be done with a model then he try with other
# model usually hy3 and deepseek v4 flash and qwen 3.8 flash they can do things
# that other models dont accept to do". A refusal was invisible to the hub: real
# text, HTTP 200, so the chain accepted it, the turn ended, and the ledger
# recorded a SUCCESS -- which meant the next turn picked the same model and got
# refused again.
#
# FALSE POSITIVES are the whole risk, so this is narrow by construction: a SHORT
# reply, no tool calls, that is essentially nothing but the refusal. "I can't
# find config.yml, so I created one" is a real answer and must survive.
_REFUSAL_RE = re.compile(
    r"\b(?:i\s*(?:'|’)?\s*(?:m\s+sorry[, ]*)?(?:can\s*(?:not|'?t)|cannot|will\s+not|won'?t|"
    r"am\s+(?:not\s+able|unable)|(?:'|’)?m\s+(?:not\s+able|unable))"
    r"\s+(?:be\s+able\s+)?(?:to\s+)?(?:help|assist|comply|creat\w*|provide|generat\w*"
    r"|do|write|make|continue|fulfil\w*|support|engage|produce|proceed)"
    r"|i\s+must\s+decline|i\s+have\s+to\s+decline"
    r"|as\s+an\s+ai(?:\s+language)?\s+model[, ].{0,40}\b(?:cannot|can'?t|unable))",
    re.I)
# MEASURED 2026-08-31 against three real refusals in a live session: they were
# 865, 4585 and 1404 characters. A refusal in practice is the refusal PLUS a
# paragraph explaining why and offering alternatives, so a short-message cap
# caught none of them. What is actually characteristic is WHERE it appears: a
# model that declines says so immediately, in its opening sentence. So the test
# is applied to the OPENING of the message, not the whole of it.
_REFUSAL_HEAD_CHARS = 400


# A DECLINE THAT NEVER SAYS "I".
#
# _REFUSAL_RE above requires a first-person verb -- "I cannot help", "I must
# decline". A sandboxed CLI does not talk like that. It reports the obstacle
# flatly:
#
#     "Blocked: write permission not granted for <an AppData path>"
#     "Blocked. Every tool call needs approval -- run /permissions and allow Write"
#
# Neither matches, so neither was treated as a non-answer. MEASURED: that first
# string came back from sub-claude on three fan-outs out of three, was accepted
# as a delivered answer, and -- because the winner is picked as
# `acted or results` -- can WIN a turn on which no member emitted a tool call.
# The user then reads the hub telling them it lacks permissions, about a
# temp-directory path they never chose. That is the shape of the very first bug
# reported against the swarm.
#
# Deliberately narrow: the words have to be about PERMISSION or a BLOCK, in the
# opening sentence, with no tool call alongside. "Blocked the main thread" and
# "the request was denied by the API" are prose about the work, not a refusal to
# do it, and must keep passing.
_PERMISSION_DENIED_RE = re.compile(
    r"^\W*(?:blocked\s*(?=[:.]|$)|permission\s+(?:denied|not\s+granted|required)"
    r"|not\s+permitted\b|no\s+(?:write\s+)?permission\b"
    r"|needs?\s+(?:approval|permission)\b)"
    r"|(?:write|read|file|tool)\s+permissions?\s+(?:is\s+|are\s+|was\s+|were\s+)?"
    r"(?:not\s+granted|denied|required|needed)",
    re.I)


def _looks_like_permission_block(text):
    """True when a turn reports being BLOCKED rather than doing the work.

    Separate from _looks_like_refusal because the grammar is different: a model
    declines in the first person, a sandboxed CLI states an obstacle. Both are
    non-answers to a request that asked for an action."""
    if not text or not isinstance(text, str):
        return False
    head = text.strip()[:_REFUSAL_HEAD_CHARS]
    if not head:
        return False
    first = re.split(r"(?<=[.!?])\s", head, 1)[0]
    if "?" in first:
        return False                  # asking is what it SHOULD do
    return bool(_PERMISSION_DENIED_RE.search(first))


def _looks_like_refusal(text):
    """True when `text` OPENS by declining the task rather than doing it."""
    if not text or not isinstance(text, str):
        return False
    head = text.strip()[:_REFUSAL_HEAD_CHARS]
    if not head:
        return False
    # The FIRST SENTENCE only. Scanning the whole head was tried and produced a
    # real false positive: "Built all 12 pages and wired the nav. I can't reach
    # the CDN, so the fonts are self-hosted." is a turn that did the work and
    # then named a limit, and the refusal phrase sat well inside 400 characters.
    # A model that is declining says so before it says anything else.
    first = re.split(r"(?<=[.!?])\s", head, 1)[0]
    if "?" in first:
        return False                  # asking is what it SHOULD do
    return bool(_REFUSAL_RE.search(first))


# A model CLAIMING IT HAS NO TOOLS on a turn that offered them.
#
# MEASURED 2026-09-27 (protocol_sweep): llm7/codestral answered three tool-turn
# checks in TEXT -- "I don't have access to tools/functions..." -- while the
# request carried a tools array, and the hub served that as the answer. None
# of the detectors above fires on it: it declines nothing ("I cannot help" is
# _REFUSAL_RE's shape), announces nothing and types no call.
#
# Conservative on every axis, because a model may legitimately explain a
# tool's limits:
#   * only on a turn that OFFERED tools, with no tool call in the reply;
#   * never once tools ran this turn (a tool result is in the history after
#     the last user message): "I can't access that file, the read failed" is
#     a report, not a claim;
#   * never when the user's OWN words ask about tools / capabilities, or say
#     not to use them: then a reply about having none is the answer;
#   * the claim must OPEN the reply (its first sentence, or the second after
#     a short "Sorry."; within _NO_TOOLS_CLAIM_AT chars, no code before it)
#     and name TOOLS, FUNCTIONS, FILES, a file
#     system, commands or the user's machine -- in plural/generic form: "I
#     can't call the function `foo` directly" is about code, and passes;
#   * ...or, in a SHORT COMPLETE reply (< _NO_TOOLS_SHORT_REPLY chars), sit in
#     its first _NO_TOOLS_SHORT_SENTENCES sentences with only PREAMBLE before
#     it (_NT_PREAMBLE_RE: greetings, "I'm here to help", "I'd be happy to
#     help", "I understand you want...", "To do that I would need..."). A
#     sentence that already answers ("Here is the answer: 4.") ends the
#     search: a short answer that did the work and then names a limitation
#     is served.
# MEASURED 2026-09-27 (live /v1/responses, coding tier, plain tools): "I'm here
# to help, but I currently don't have the tools..." was SERVED -- the adverb
# before "don't" defeated the regex, and the stream peek judged the reply on
# its first ~4 per-token frames (_PEEK_JUDGE_CHARS counts frame BYTES), long
# before the claim arrived. The peek now reads on for the claim alone
# (_no_tools_peek_state), bounded by _NO_TOOLS_PEEK_EXTRA_S.
# A hit is a non-answer (next hop) and a quality failure for the pair, never
# a dead-mark (_note_nonanswer, kind "no_tools_claim").
_NO_TOOLS_CLAIM_AT = 160
_NO_TOOLS_SHORT_REPLY = 600
_NO_TOOLS_SHORT_SENTENCES = 3
_NO_TOOLS_SHORT_AT = 320
# Seconds the stream peek may read past its usual verdict point, only to see
# whether a no-tools claim follows (see _no_tools_peek_state).
_NO_TOOLS_PEEK_EXTRA_S = 4.0
# "I currently don't have", "I, unfortunately, cannot", "I'm currently unable".
_NT_ADV0 = (r"(?:(?:currently|actually|unfortunately|really|still|simply|just|presently"
            r"|also|sadly|genuinely|honestly|at\s+the\s+moment|right\s+now)\s*,?\s+)?")
_NT_I = (r"i(?:\s*,?\s+(?:currently|actually|unfortunately|really|still|simply|just"
         r"|presently|also|sadly|genuinely|honestly)\s*,?)?\s*")
_NT_DET = (r"(?:(?:any|the|your|my|external|local|real|direct|such|these|those|a|an|"
           r"specific|additional|built[\s-]?in|real[\s-]?time)\s+)*")
_NT_OBJ = (r"(?:tools|tool[\s-]?(?:calls?|calling|use|access)|functions"
           r"|function[\s-]?(?:calls?|calling)|(?:shell|terminal|system|bash|cli)\s+commands"
           r"|commands|files|file[\s-]?systems?|filesystems?|machine|computer|terminal"
           r"|shell|workspace|codebase|repository)\b")
_NT_ADV = r"(?:(?:directly|actually|currently|physically|really|personally)\s+)?"
_NT_VERB = (r"(?:use|call|invoke|access|execute|run|read|open|browse|interact\s+with|make"
            r"|perform|modify|edit|write\s+to|see|view|list)\w*"
            # "access or modify", "execute code or access", "read, write"
            r"(?:(?:\s+\w+)?\s*(?:,|/|\bor\b|\band\b)\s*(?:\w+\s+)?\w+){0,3}")
_NT_HAVE = (_NT_I + r"(?:(?:do\s+not|don['’]?t)\s+(?:currently\s+|actually\s+|really\s+)?have"
            r"|have\s+no|(?:currently\s+)?lack)\s+")
_NO_TOOLS_CLAIM_RE = re.compile(
    r"\b(?:"
    # I can't / cannot / am unable to  <verb> ... <object>
    + _NT_I + r"(?:can\s*not|can['’]?t|cannot|am\s+" + _NT_ADV0
    + r"(?:not\s+able|unable|not\s+capable)"
    r"|['’]m\s+" + _NT_ADV0 + r"(?:not\s+able|unable|not\s+capable))\s+(?:to\s+|of\s+)?"
    + _NT_ADV + _NT_VERB + r"\s+" + _NT_DET + _NT_OBJ +
    # I don't have the ability / capability to <verb> ... <object>
    r"|" + _NT_HAVE + r"(?:the\s+|any\s+)?(?:ability|capability|capacity|means|way)\s+"
    r"(?:to\s+|of\s+)?" + _NT_ADV + _NT_VERB + r"\s+" + _NT_DET + _NT_OBJ +
    # I don't have (direct) access to <object>
    r"|" + _NT_HAVE + _NT_DET + r"(?:direct\s+)?access\s+to\s+" + _NT_DET + _NT_OBJ +
    # I don't have (any) tools / function calling
    r"|" + _NT_HAVE + _NT_DET + r"(?:tools?|tool[\s-]?(?:calling|use|access)|functions"
    r"|function[\s-]?calling)\b"
    # I'm a text-based AI and can't access your files
    r"|i\s*(?:['’]m|\s+am)\s+(?:just\s+|only\s+|merely\s+|simply\s+)?an?\s+(?:[\w-]+\s+){0,3}?"
    r"(?:ai|model|assistant|chatbot|llm)\b[^.!?\n]{0,40}?\b(?:and|so|which\s+means)\s+"
    r"(?:i\s+)?(?:therefore\s+|thus\s+)?(?:can\s*not|can['’]?t|cannot"
    r"|(?:do\s+not|don['’]?t)\s+have\s+(?:direct\s+)?access\s+to|have\s+no\s+access\s+to)\s+"
    + _NT_ADV + r"(?:" + _NT_VERB + r"\s+)?" + _NT_DET + _NT_OBJ +
    # no tools are available (to me)
    r"|(?:there\s+are\s+)?no\s+(?:tools|functions|tool\s+calls?)\s+(?:are\s+|is\s+)?"
    r"(?:available|provided|accessible|enabled|at\s+my\s+disposal)\b"
    r"|(?:tools|functions|function[\s-]?calling|tool[\s-]?calling)\s+(?:are|is)\s+"
    r"(?:not|n['’]t)\s+(?:available|enabled|supported|accessible)\s+(?:to\s+me|for\s+me"
    r"|here|in\s+this)"
    r")", re.I)
# The user asking ABOUT tools (then "I have none" answers it) or ruling them out.
_NO_TOOLS_ASKED_RE = re.compile(
    r"\b(?:tools?|functions|function[\s-]?calling|tool[\s-]?calling|capabilit\w*)\b"
    r"[^.?!\n]{0,40}?\b(?:you|your)\b[^.!\n]*\?"
    r"|\b(?:you|your)\b[^.?!\n]{0,40}?\b(?:tools?|functions|function[\s-]?calling"
    r"|tool[\s-]?calling|capabilit\w*)\b[^.!\n]*\?"
    r"|\b(?:can|could|do|are|will)\s+you\b[^.?!\n]{0,30}?\b(?:access|read|see|open|run"
    r"|execute)\b[^.!\n]*\?"
    r"|\b(?:without|no|don['’]?t|do\s+not|never)\s+(?:use\s+|using\s+|call\s+|calling\s+)?"
    r"(?:any\s+)?(?:tools?|functions|tool\s+calls?)\b"
    r"|\b(?:list|describe|what\s+are|tell\s+me)\b[^.?!\n]{0,20}?\byour\s+"
    r"(?:tools|capabilities|functions)\b", re.I)
_NT_FILLER_RE = re.compile(
    r"\W*(?:i\s*['’]?m\s+sorry|sorry|i\s+apologi[sz]e|apologies|unfortunately|hello|hi|hey"
    r"|thanks|thank\s+you|sure|of\s+course|certainly|understood|okay|ok|note|hmm|well"
    r"|i\s+understand|i\s+see)\b", re.I)
# A sentence that only leads up to the claim: a greeting, an offer to help,
# the ask restated, or what the work "would need". Anchored at the sentence
# start; a sentence that already carries an answer never matches.
_NT_INTERJ = (r"(?:i\s*['’]?m\s+sorry|sorry|i\s+apologi[sz]e|apologies|unfortunately"
              r"|hello(?:\s+there)?|hi(?:\s+there)?|hey|thanks|thank\s+you|sure|of\s+course"
              r"|certainly|absolutely|understood|okay|ok|alright|got\s+it|no\s+problem"
              r"|great\s+question|good\s+question|hmm|well|yes)")
_NT_PREAMBLE_RE = re.compile(
    r"\W*(?:" + _NT_INTERJ + r"\W*$|(?:" + _NT_INTERJ + r"\W+)?(?:"
    r"i\s*(?:['’]m|\s+am)\s+(?:here|happy|glad|ready|more\s+than\s+happy)\s+to\s+(?:help|assist)"
    r"|i\s*(?:['’]d|\s+would)\s+(?:be\s+)?(?:happy|glad|love)\s+to\s+(?:help|assist)"
    r"|(?:i\s+)?(?:can|could|will|['’]ll|want\s+to|would\s+like\s+to)\s+(?:help|assist)\b"
    r"|(?:happy|glad)\s+to\s+(?:help|assist)"
    r"|thanks\s+for|thank\s+you\s+for|i\s+appreciate"
    r"|i\s+(?:understand|see)\b|it\s+(?:sounds|seems|looks)\s+like\s+you"
    r"|you['’]?(?:re|\s+are)\s+(?:asking|trying|looking|wanting)|you\s+(?:want|need|would\s+like"
    r"|['’]d\s+like)"
    r"|(?:in\s+order\s+)?to\s+(?:do\s+)?(?:this|that|so)\b|to\s+\w+\s+(?:the|your|this|that|these"
    r"|those|a|an)\b[^.!?]{0,80}?,\s*i\s+(?:would|will|['’]d|['’]ll)\s+need"
    r"|i\s+(?:would|will|['’]d|['’]ll)\s+need\s+to|(?:this|that|it)\s+(?:would\s+)?requires?\b"
    r"))", re.I)
# One sentence: ends at . ! ? followed by whitespace / the end, or a newline
# ("config.py" and "e.g" stay inside their sentence).
_NT_SENTENCE_RE = re.compile(r"(?:[^.!?\n]|[.!?]+(?=[^\s.!?]))*(?:[.!?]+(?=\s|$)|\n+|$)")


def _nt_sentences(text, limit):
    """(start offset, sentence) for the first `limit` sentences of `text`."""
    out = []
    for m in _NT_SENTENCE_RE.finditer(text):
        s = m.group(0)
        if s.strip():
            out.append((m.start() + len(s) - len(s.lstrip()), s.strip()))
            if len(out) >= limit:
                break
        if m.end() >= len(text):
            break
    return out


def _looks_like_no_tools_claim(text, complete=True):
    """True when `text` OPENS by claiming the model has no tools / cannot call
    functions / cannot access files -- or, when `text` is a SHORT COMPLETE
    reply, makes that claim in its first few sentences with only preamble
    before it. Text only: _no_tools_claim applies the turn's context.
    `complete` False = a stream still arriving: its length is unknown, so
    only the opening rule applies."""
    if not text or not isinstance(text, str):
        return False
    body = text.strip()
    head = body[:_NO_TOOLS_CLAIM_AT + 200]
    # The OPENING sentence ("Here is the answer: 4. I can't run tools to
    # verify it." answered first), or the second after a short "Sorry."/"Sure!".
    parts = re.split(r"(?<=[.!?])\s+", head, 2)
    scope = parts[0]
    if len(parts) > 1 and len(parts[0]) <= 60 and _NT_FILLER_RE.match(parts[0]):
        scope = parts[0] + " " + parts[1]
    m = _NO_TOOLS_CLAIM_RE.search(scope)
    if m and m.start() <= _NO_TOOLS_CLAIM_AT and "```" not in scope[:m.start()]:
        return True
    if not complete or len(body) >= _NO_TOOLS_SHORT_REPLY:
        return False
    # A short reply: the claim in one of its first few sentences, every
    # sentence before it preamble, no code before it.
    for start, sent in _nt_sentences(body[:_NO_TOOLS_SHORT_AT + 200],
                                     _NO_TOOLS_SHORT_SENTENCES):
        m = _NO_TOOLS_CLAIM_RE.search(sent)
        if m:
            at = start + m.start()
            return at <= _NO_TOOLS_SHORT_AT and "`" not in body[:at]
        if len(sent) > 160 or "`" in sent or not _NT_PREAMBLE_RE.match(sent):
            return False
    return False


def _no_tools_peek_state(text):
    """For the stream peek, which reads on past its usual verdict point only
    to see whether a no-tools claim follows: "claim" (the opening rule already
    holds), "clear" (no claim is possible any more: the reply is past the
    short-reply size, carries code, or its first few sentences are in and
    none made one), or "open" (keep reading). Text only; the caller has
    already decided the turn is one to watch."""
    if not text:
        return "open"
    if _looks_like_no_tools_claim(text, complete=False):
        return "claim"
    body = text.strip()
    if len(body) >= _NO_TOOLS_SHORT_REPLY:
        return "clear"
    # The same walk as _looks_like_no_tools_claim's short-reply loop, on a
    # reply still arriving (the last sentence may be unfinished).
    sents = _nt_sentences(body[:_NO_TOOLS_SHORT_AT + 200], _NO_TOOLS_SHORT_SENTENCES)
    for st, s in sents:
        m = _NO_TOOLS_CLAIM_RE.search(s)
        if m:
            at = st + m.start()
            if at > _NO_TOOLS_SHORT_AT or "`" in body[:at]:
                return "clear"
            # The short-reply rule's claim: its verdict needs the reply's
            # length -- read on until it ends or outgrows the short size.
            return "open"
        done = st + len(s) < len(body)
        if "`" in s or len(s) > 160 or (done and not _NT_PREAMBLE_RE.match(s)):
            return "clear"
        if not done:
            return "open"                 # this sentence is still arriving
    return "clear" if len(sents) >= _NO_TOOLS_SHORT_SENTENCES else "open"


def _turn_used_tools(turns):
    """True when tools already ran in the CURRENT turn: a tool result or a
    tool call sits after the last real user message. Every protocol's shape
    (OpenAI tool/tool_calls, Anthropic tool_use/tool_result, Responses
    function_call/_output items). Never raises."""
    try:
        for m in reversed(turns or []):
            if not isinstance(m, dict):
                continue
            if _carries_tool_results(m) or m.get("type") in (
                    "function_call", "function_call_output", "custom_tool_call",
                    "custom_tool_call_output", "local_shell_call"):
                return True
            role = m.get("role")
            if role == "assistant":
                if m.get("tool_calls"):
                    return True
                c = m.get("content")
                if isinstance(c, list) and any(isinstance(p, dict) and p.get("type") == "tool_use"
                                               for p in c):
                    return True
            elif role == "user":
                return False
    except Exception:                                            # noqa: BLE001
        pass
    return False


def _request_used_tools():
    """_turn_used_tools of the request being served; False outside one."""
    try:
        if not has_request_context():
            return False
        body = request.get_json(force=True, silent=True)
        if not isinstance(body, dict):
            return False
        turns = body.get("messages")
        if not isinstance(turns, list):
            turns = body.get("input") if isinstance(body.get("input"), list) else []
        return _turn_used_tools(turns)
    except Exception:                                            # noqa: BLE001
        return False


def _no_tools_watch(*, tools_offered, prompt=None, used_tools=False):
    """True when this turn is one where a no-tools claim would be a non-answer:
    tools offered, none ran yet this turn, and the user's own words neither
    ask about tools nor rule them out."""
    try:
        if not tools_offered or used_tools or prompt == _TOOL_RESULT_TURN:
            return False
        if isinstance(prompt, str) and prompt:
            own = answer_check._instruction(prompt) or ""
            if _NO_TOOLS_ASKED_RE.search(own[:_PROMPT_CHECK_CAP]):
                return False
        return True
    except Exception:                                            # noqa: BLE001
        return False


def _no_tools_claim(text, *, tools_offered, prompt=None, used_tools=False, complete=True):
    """The policy around _looks_like_no_tools_claim (see the note above).
    `prompt` is the last user turn (wrappers are stripped here) or the
    tool-results sentinel; `used_tools` whether tools already ran this turn;
    `complete` False for a stream still arriving (opening rule only).
    The caller has already established that the reply made no tool call."""
    try:
        if not tools_offered or used_tools or prompt == _TOOL_RESULT_TURN:
            return False
        if not _looks_like_no_tools_claim(text, complete=complete):
            return False
        return _no_tools_watch(tools_offered=tools_offered, prompt=prompt,
                               used_tools=used_tools)
    except Exception:                                            # noqa: BLE001
        return False


# The models the user named as accepting work others decline. Matched on the
# normalised identity, so every provider's spelling of them counts.
_PERMISSIVE_MODELS = ("hy3", "deepseek-v4-flash", "qwen3.8")


def _is_permissive(model_id):
    """True for a model known to take on work other models refuse."""
    ident = _normalize_model_identity(model_id)
    low = (model_id or "").lower()
    return any(p in ident or p in low for p in _PERMISSIVE_MODELS)


def _permissive_candidates():
    """Live (pid, model) pairs for the permissive models, best first."""
    out = []
    for pid in _available_providers():
        try:
            for m in provider_free_models(pid) or []:
                if _is_permissive(m) and not _is_model_skipped(pid, m):
                    out.append((_benchmark_score(pid, m), pid, m))
        except Exception:                                        # noqa: BLE001
            continue
    out.sort(reverse=True)
    out = _bench_last(out)          # a junk-benched host of one is the last pick
    return [(pid, m) for _s, pid, m in out]


def _ensure_permissive_hop(chain):
    """Guarantee the fallback chain contains a model that accepts work others
    decline, so a refusal always has somewhere to go.

    Appended, never promoted: the ordinary ranking still decides who answers
    first, and this only matters once the models ahead of it have refused."""
    if not chain:
        return chain
    if any(_is_permissive(m) for _p, m in chain):
        return chain
    try:
        for pid, model in _permissive_candidates():
            if (pid, model) in chain:
                continue
            out = list(chain)
            # BEFORE the low-quality tail, not at the very end. _build_chain
            # deliberately parks demoted families (kimi-k2.x, nemotron, gpt-oss)
            # last as a last resort; appending past them would rank a normal
            # model behind a demoted one, which test_last_resort_routing exists
            # to prevent -- and it caught exactly that.
            at = len(out)
            for i, (_p, m) in enumerate(out):
                if _is_low_quality(m):
                    at = i
                    break
            out.insert(at, (pid, model))
            return out
    except Exception:                                            # noqa: BLE001
        pass
    return chain


def _looks_like_announced_not_acted(text):
    """True when `text` states an intention to do work rather than reporting
    work done or asking a question. See the note above."""
    if not text or not isinstance(text, str):
        return False
    body = text.strip()
    if not body or len(body) > _ANNOUNCE_MAX_CHARS:
        return False
    if "?" in body:
        return False                      # asking is what it SHOULD do
    return bool(_INTENT_RE.search(body) and _WORK_VERB_RE.search(body))


# A TOOL turn that ends on "I'll read the last line of big1.txt for you." did
# nothing. MEASURED LIVE 2026-09-27 (codex, /v1/responses): that exact reply
# ended a turn -- _WORK_VERB_RE is about BUILDING (write/fix/run...), so the
# read-only actions an agent announces most (read, open, look at, list...)
# never matched. This is the stricter shape for them: the intent phrase at a
# sentence start, then (a few adverbs at most) the action verb itself. Only
# ever judged on a COMPLETE reply to a turn that offered tools -- mid-stream,
# "I'll read the file." is usually the lead-in to the call that follows.
_ANNOUNCE_ACTION_RE = re.compile(
    r"(?:^|(?<=[.!?:])\s+|\n)\W*"
    r"(?:i\s*['’]?ll|i will|let me(?!\s+know)|i\s*['’]?m (?:now )?going to|i am (?:now )?going to"
    r"|i\s*['’]?m (?:now )?about to|i am about to|now,? i\s*['’]?ll|first,? i\s*['’]?ll"
    r"|next,? i\s*['’]?ll)\s+"
    r"(?:(?:now|first|quickly|just|then|also|go ahead and|start by|begin by)\s+)*"
    r"(?:read\w*|open\w*|look\w*|check\w*|inspect\w*|examin\w*|view\w*|list\w*|search\w*"
    r"|grep\w*|find\w*|locat\w*|fetch\w*|get|grab\w*|run\w*|execut\w*|print\w*|show\w*"
    r"|display\w*|tail\w*|cat|scan\w*|explor\w*|investigat\w*|count\w*|quer\w*|pull\w*"
    r"|verif\w*|test\w*|use|call\w*|invok\w*)\b", re.I)


def _looks_like_announced_action(text):
    """True when `text` (a COMPLETE reply on a tool turn) is only an
    announcement of an action -- see the note above. Short, no question."""
    if not text or not isinstance(text, str):
        return False
    body = text.strip()
    if not body or len(body) > _ANNOUNCE_MAX_CHARS or "?" in body or "```" in body:
        return False
    return bool(_ANNOUNCE_ACTION_RE.search(body))


def _announced_only(text):
    """Either announcement detector (see both notes): a reply that states what
    it is about to do and does nothing. For COMPLETE replies on tool turns."""
    return _looks_like_announced_not_acted(text) or _looks_like_announced_action(text)


_LAST_SENTENCE_SPLIT_RE = re.compile(r"(?<=[.!?])\s+|\n+")
# The intent phrase OPENING a last sentence. Stricter than _INTENT_RE (which
# also takes a bare "I'm" and "let me"): "I'm here to help." and "Let me know
# if you want me to add tests." end real answers.
_LAST_INTENT_RE = re.compile(
    r"\W*(?:i\s*['’]?ll\b|i will\b|let me\b(?!\s+know)"
    r"|(?:i\s*['’]?m|i am)\s+(?:now\s+)?(?:going to|about to|[a-z-]+ing\b)"
    r"|(?:now|first|next),?\s+i\s*['’]?ll\b|(?:now|first|next),?\s+i will\b"
    r"|now (?:writing|creating|building|generating|adding|updating)"
    r"|proceeding to|moving (?:on )?to|starting (?:on|with))", re.I)


def _ends_with_announcement(text):
    """True when a COMPLETE streamed reply on a tool turn ENDS on an
    announcement of an action (its last sentence opens with the intent and
    names the action) and is short. Judged on the last sentence, not the
    whole reply: "...you can run the command yourself, and I'll help you
    interpret it." (a no-tools claim after tools ran) names work, but it does
    not end by announcing any. Never raises."""
    try:
        if not text or not isinstance(text, str):
            return False
        body = text.strip()
        if not body or len(body) > _ANNOUNCE_MAX_CHARS or "?" in body or "```" in body:
            return False
        parts = [p for p in _LAST_SENTENCE_SPLIT_RE.split(body) if p.strip()]
        last = parts[-1].strip() if parts else body
        if _ANNOUNCE_ACTION_RE.search(last):
            return True
        return bool(_LAST_INTENT_RE.match(last) and _WORK_VERB_RE.search(last))
    except Exception:                                            # noqa: BLE001
        return False


def _announce_pending(text):
    """True while a PARTIAL reply on a tool turn may still end as a bare
    announcement: short, no question, an intent phrase in it. The peek reads
    on instead of judging it now (a tool call may follow) -- see
    _peek_until_content."""
    try:
        if not text or not isinstance(text, str):
            return False
        body = text.strip()
        if not body or len(body) > _ANNOUNCE_MAX_CHARS or "?" in body or "```" in body:
            return False
        if _ends_with_announcement(body):
            return True
        # ...or its last sentence is still OPEN and opens with the intent
        # ("I'll read the" -- the action may be the next word).
        parts = [p for p in _LAST_SENTENCE_SPLIT_RE.split(body) if p.strip()]
        last = parts[-1].strip() if parts else body
        return last[-1:] not in ".!?:" and bool(_LAST_INTENT_RE.match(last))
    except Exception:                                            # noqa: BLE001
        return False


def _announce_skip_spent(kind):
    """ONE retry per request for a reply that only announced its action: the
    first such reply walks the chain on (kind "announced"); a second one in
    the same request is served, so a pool that keeps announcing cannot burn
    the whole deadline. False for any other kind. Never raises."""
    if kind != "announced":
        return False
    try:
        if getattr(g, "hub_announce_skipped", False):
            return True
        g.hub_announce_skipped = True
    except Exception:                                            # noqa: BLE001
        pass
    return False


def _skip_nonanswer():
    """For a hop the detectors just called a non-answer: True to walk on to
    the next hop (the usual), False when it is a SECOND bare announcement in
    this request -- served instead (see _announce_skip_spent)."""
    if _announce_skip_spent(_peek_nonanswer_kind()):
        _take_nonanswer_kind()
        return False
    return True


def _looks_like_dangling_lead_in(text):
    """True for a SHORT reply that ends on a colon with nothing after it -- a
    lead-in to a step that never came. Only ever judged on a tools turn, where
    the step after the colon was meant to be a tool call.

    MEASURED 2026-09-27 (/agent, codex, max tier): a 20-minute turn ENDED on
    "The default working directory isn't valid, but I can pinpoint it by
    locating where the brief file is:" -- no tool call followed, the test file
    was never written, and the phrasing slipped past _INTENT_RE ("I can")."""
    if not text or not isinstance(text, str):
        return False
    body = text.strip()
    if not body or len(body) > _ANNOUNCE_MAX_CHARS or "```" in body:
        return False
    return body.endswith(":")


def _looks_like_text_tool_call(text):
    """True when `text` contains a tool call the model wrote out instead of
    emitting. Requires a real closing/paired marker, not a passing mention, so
    prose that merely talks about tools does not trip it."""
    if not text or not isinstance(text, str):
        return False
    return any(rx.search(text) for rx in _TEXT_TOOL_CALL_RES)


def _chat_json_nonanswer(data, has_tools=False, tools=None):
    """_chat_json_is_empty's sibling: a 200 that is not really an answer.

    Two shapes. The original one is a relay returning its own error page as
    content. The second is a tool call typed out as prose (see
    _looks_like_text_tool_call) -- only ever checked when the request actually
    offered tools, because in plain chat, explaining what a tool call looks
    like is a perfectly good answer.

    ...except that "typed it out" is not always a failed turn. When the text
    contains a COMPLETE call to a tool the client actually offered, the model
    did the work and only got the envelope wrong, so tool_rescue promotes it
    into real tool_calls and this stops being a non-answer at all. That saves
    the whole retry: before, such a turn marked a working model dead for the
    TTL and paid for a second inference to get an answer the hub was already
    holding. Only unparseable text, or a call to a tool that was never offered,
    still falls through to the old path -- an invented tool name would just make
    the agent loop fail further downstream.

    `tools` is the client's tools array, needed to check the name. Without it
    the rescue is skipped rather than guessed at.

    Model-native markup (DeepSeek's "<｜DSML｜function_calls>", see tool_rescue)
    the rescue could NOT turn into an offered call is a non-answer too -- only
    on a tools turn: raw markup served as text is never a usable reply there."""
    _set_nonanswer_kind(None)
    try:
        msg = ((data.get("choices") or [{}])[0] or {}).get("message") or {}
        if msg.get("tool_calls"):
            return False                      # a real tool call is a real answer
        if tools and tool_rescue.rescue(data, tools):
            return False                      # it WAS an answer, in the wrong envelope
        content = msg.get("content")
        if isinstance(content, list):
            content = "".join((p.get("text") or "") for p in content
                              if isinstance(p, dict))
        # "I don't have access to tools" on a turn that offered them: next hop,
        # a quality failure, never a dead-mark (see _no_tools_claim). Judged
        # BEFORE the announcement check: the live claim ended "...and I'll help
        # you interpret it", which read as announced work and dead-marked the
        # pair for 6 hours over one reply.
        if has_tools and _no_tools_claim(content, tools_offered=True,
                                         prompt=_request_prompt_text(),
                                         used_tools=_request_used_tools()):
            _set_nonanswer_kind("no_tools_claim")
            return True
        if has_tools and (_looks_like_text_tool_call(content)
                          or tool_rescue.has_model_markup(content)
                          or tool_rescue.is_bare_tool_name(content, tools)
                          or _looks_like_dangling_lead_in(content)):
            return True
        if has_tools and _announced_only(content):
            # kind "announced": a quality failure, one retry per request
            # (_announce_skip_spent) -- never a dead-mark over one reply.
            _set_nonanswer_kind("announced")
            return True
        # A refusal counts with or without tools: it is no more useful in plain
        # chat, and the hub has other models that will answer.
        if _looks_like_refusal(content):
            return True
        return _is_upstream_nonanswer(content)
    except Exception:
        return False


def _note_nonanswer(pid, model, kind=_PROMPT_UNSET):
    """Both consequences in one hook: file the delivery failure the 200 branch
    never filed, and sideline this (pid, model) for _DEAD_MODEL_TTL. Dead-marking
    is the ONLY mechanism here that actually REMOVES an id from the chain
    (_build_chain checks _is_model_dead) rather than merely re-ordering it --
    which is why a reliability penalty alone could never have stopped this.

    Provider error PHRASING (_provider_error_kind, a heuristic) files the
    failure without the dead-mark; a key/quota/credit/rate limit also cools
    the pair down for _PROVIDER_QUOTA_COOLDOWN.

    `kind`: the verdict's kind when the caller carries it (hedge legs are
    judged on other threads, and one after another); otherwise the thread-
    local slot the detector on THIS thread just set."""
    if kind is _PROMPT_UNSET:
        kind = _take_nonanswer_kind()
    if _client_gone():
        return          # the client left: not the provider's failure
    if _local_net_failed(pid, model):
        return          # a local network failure: not the provider's failure
    _record_outcome(pid, model, False)
    if _in_tool_turn():
        _note_relay_tool_fail(pid, model)   # no-op for a non-relay provider
    # "no_tools_claim" (_no_tools_claim) and "announced" (_announced_only /
    # _ends_with_announcement) are heuristics about ONE reply: the failure is
    # filed, the pair stays routable.
    if kind in ("provider_quota", "provider_error", "no_tools_claim", "announced"):
        if kind == "provider_quota":
            _throttle_failed_hop(pid, model, secs=_PROVIDER_QUOTA_COOLDOWN)
        return
    _mark_model_dead(pid, model, 404)         # 404 is in _DEAD_STATUSES


# --------------------------------------------------------------------------- #
# ANSWER-QUALITY GATE -- a correct answer with junk glued on is not a success.
#
# MEASURED LIVE: llm7/GLM-5.3-Flash answered, then generated until max_tokens:
#   "OK出具证明的，原试题解析 做题如有雷同，纯属巧合…"
#   "6510</arg_value></tool_call>6510</arg_value></tool_call>The user asked"
# and both went out as clean 200s AND were filed as _record_outcome(True) --
# every earlier check hunted a BAD answer, none a GOOD answer plus garbage.
# answer_check.inspect judges the text; this is the hub-side policy:
#   * junk only after a real answer -> serve the clean part ("salvaged"), and
#     record the hop as a FAILED delivery (it burned the budget looping);
#   * nothing salvageable -> the hop is a non-answer: next hop + failure.
# Deliberately NOT _note_nonanswer (6h dead-mark): like the fan-out refusal
# check, a heuristic is good enough to lose a turn over, not to ban a model
# fleet-wide over.
# --------------------------------------------------------------------------- #
_PROMPT_CHECK_CAP = 40000


def _prompt_text_for_check(payload):
    """Every USER turn's text in an OpenAI-shaped payload, joined -- the
    reference for "did the prompt use this script / mention this markup".
    All user turns, not just the last: a conversation that was in Chinese two
    turns ago may legitimately be answered in Chinese now. Never raises."""
    try:
        parts = []
        for m in (payload or {}).get("messages") or ():
            if not isinstance(m, dict) or m.get("role") != "user":
                continue
            c = m.get("content")
            if isinstance(c, str):
                parts.append(c)
            elif isinstance(c, list):
                parts.extend(p.get("text") or "" for p in c
                             if isinstance(p, dict) and isinstance(p.get("text"), str))
        text = "\n".join(parts)
        if len(text) > _PROMPT_CHECK_CAP:
            half = _PROMPT_CHECK_CAP // 2
            text = text[:half] + "\n" + text[-half:]
        return text
    except Exception:                                            # noqa: BLE001
        return None


def _last_user_text_for_check(payload):
    """The LAST user turn's text -- where a format constraint ("answer with
    only the number") lives. An earlier turn's constraint does not bind a
    later "now describe it". Empty string when there is none. Never raises."""
    try:
        for m in reversed((payload or {}).get("messages") or ()):
            if not isinstance(m, dict) or m.get("role") != "user":
                continue
            c = m.get("content")
            if isinstance(c, list):
                c = "\n".join(p.get("text") or "" for p in c
                              if isinstance(p, dict) and isinstance(p.get("text"), str))
            return (c if isinstance(c, str) else "")[:_PROMPT_CHECK_CAP]
        return ""
    except Exception:                                            # noqa: BLE001
        return None


def _answer_gate(data, payload, has_tools, hop=None):
    """'ok' | 'salvaged' | 'junk' for a non-streamed OpenAI chat JSON.

    'salvaged' REWRITES `data` in place: content becomes the clean answer and a
    "length" finish becomes "stop" (the served text is complete). A message
    with real tool_calls is always 'ok' -- its content is not the answer.
    `hop` = (pid, model): an 'ok' answer carrying an informational quality
    strike (answer_check "echoed_decimal") files it against that pair via
    _note_quality_strike -- the answer itself is served unchanged.
    Fail-open: any error is 'ok', so the gate can never lose an answer."""
    try:
        choice = ((data.get("choices") or [{}])[0]) or {}
        msg = choice.get("message") or {}
        if msg.get("tool_calls"):
            # The same call N times in one answer is one call (see
            # tool_rescue.dedupe_stream): every non-streamed hop passes here.
            _dedupe_tool_calls_json(data)
            return "ok"
        content = msg.get("content")
        if isinstance(content, list):
            content = "".join((p.get("text") or "") for p in content
                              if isinstance(p, dict))
        if not isinstance(content, str) or not content.strip():
            return "ok"
        verdict = answer_check.inspect(
            content, prompt_text=_prompt_text_for_check(payload),
            tools_offered=bool(has_tools), finish_reason=choice.get("finish_reason"),
            last_prompt=_last_user_text_for_check(payload),
            relay=bool(hop) and _is_relay_pid(hop[0]))
        if verdict.get("ok"):
            strikes = _answer_quality_strikes(verdict.get("reasons"))
            if strikes and hop and len(hop) == 2:
                _note_quality_strike(hop[0], hop[1], strikes[0])
            return "ok"
        _log.warning("[answer-gate] junk in answer (%s), salvage=%s",
                     ",".join(verdict.get("reasons") or ()),
                     "yes" if verdict.get("salvage") else "no")
        if verdict.get("salvage"):
            msg["content"] = verdict["salvage"]
            if choice.get("finish_reason") == "length":
                choice["finish_reason"] = "stop"
            return "salvaged"
        return "junk"
    except Exception:                                            # noqa: BLE001
        return "ok"


def _record_stream_outcome(pid, model, text, *, tool_calls=False,
                           finish_reason=None, prompt_text=None, tools_offered=False,
                           last_prompt=None):
    """The outcome a STREAMED answer never used to file: every stream commit
    point returned the Response without any _record_outcome, so a streaming
    model that delivered was never credited and one that degenerated was never
    penalised. Called once, when the stream has ENDED; the bytes are already
    with the client, so this only teaches routing. A turn that produced tool
    calls is judged a delivery. No text and no tool calls files NOTHING: the
    first-content peek already proved content arrived, so an empty digest means
    frames this parser could not read (reasoning-only, odd framing) -- unknown,
    and a guess either way would teach routing something false. Never raises."""
    if not (pid and model):
        return
    if _client_gone():
        return          # the client left mid-answer: nothing to judge
    if _local_net_failed(pid, model):
        return          # a local network failure: nothing to judge
    try:
        ok, strikes = True, []
        if not tool_calls:
            if not (text or "").strip():
                return
            v = answer_check.inspect(
                text, prompt_text=prompt_text, tools_offered=tools_offered,
                finish_reason=finish_reason, last_prompt=last_prompt,
                relay=_is_relay_pid(pid))
            ok = v.get("ok", True)
            strikes = _answer_quality_strikes(v.get("reasons")) if ok else []
        # A stream that failed the gate degenerated: a junk strike, not a miss.
        _record_outcome(pid, model, ok, junk=not ok)
        if strikes:
            # Delivered uncut (it may be a real value) -- see _note_quality_strike.
            _note_quality_strike(pid, model, strikes[0])
    except Exception:                                            # noqa: BLE001
        pass


def _sse_answer_digest(raw_frames):
    """(text, saw_tool_calls, finish_reason) from raw OpenAI chat SSE bytes --
    parsed ONCE after a passthrough stream ends, so the zero-copy relay itself
    does no per-chunk JSON work. Never raises."""
    text, tools, fin = [], False, None
    try:
        blob = b"".join(raw_frames)
        for line in blob.split(b"\n"):
            line = line.strip()
            if not line.startswith(b"data:"):
                continue
            body = line[5:].strip()
            if not body.startswith(b"{"):
                continue
            try:
                chunk = json.loads(body.decode("utf-8", "ignore"))
            except ValueError:
                continue
            if not isinstance(chunk, dict):
                continue
            choice = ((chunk.get("choices") or [{}])[0]) or {}
            delta = choice.get("delta") or {}
            c = delta.get("content")
            if isinstance(c, str):
                text.append(c)
            if delta.get("tool_calls"):
                tools = True
            if choice.get("finish_reason"):
                fin = choice["finish_reason"]
    except Exception:                                            # noqa: BLE001
        pass
    return "".join(text), tools, fin


# --------------------------------------------------------------------------- #
# STREAM HOLD-BACK GATE -- _answer_gate for the path the CLIs actually use.
#
# MEASURED LIVE after _answer_gate shipped (streaming /v1/chat/completions,
# "What is N plus 1? Answer with only the number.", max_tokens 40,
# llm7/GLM-5.3-Flash):
#   best   -> "3324TouchableOpacity_FP$.\n\nActually, the answer is"
#   coding -> "319231923192"
# opencode, Codex and Claude Code all stream, and on a stream the gate only
# ran once the bytes were already with the client (to file an outcome).
#
# So visible text is HELD -- until the model finishes, the held text reaches
# _HOLD_CHARS, or _HOLD_SECONDS pass since its first delta -- and judged by
# answer_check.inspect before any of it is released:
#   * clean -> released unchanged, then every later delta passes a rolling
#     answer_check.inspect_tail first (a loop / separator run / script switch /
#     leaked markup starting mid-stream stops the stream there);
#   * junk with a salvage -> only the salvage goes out, the stream ends with a
#     proper finish "stop" + [DONE], and the hop is filed as a failure.
# Junk with NOTHING salvageable is caught one step earlier, by the pre-commit
# peek (_judge_peeked), where the chain can still move to the next hop.
#
# Deliberately never held or altered: tool-call deltas (one disarms the gate
# for the rest of the turn, flushing held text first so order is kept),
# reasoning deltas, keepalives, usage and error frames -- they pass at once.
# The cost is bounded by the hold window: a clean answer's first ~80 chars
# arrive together (early release, below); only text that does not yet read
# as an answer waits for 400 chars, at most 2.5 s.
#
# Works on OpenAI chat SSE in both shapes the hub relays: raw iter_content
# chunks ("bytes", re-framed on blank lines) for /v1/chat/completions, and
# iter_lines items ("lines") that /v1/responses and /v1/messages translate --
# so all three protocols get their own terminator from the translator.
# --------------------------------------------------------------------------- #
_HOLD_CHARS = 400
_HOLD_SECONDS = 2.5
# ...but the hold ends EARLY once the held text reads as a normal answer
# (answer_check.reads_as_answer: >= 80 chars of varied prose/code, no glued
# run, no leak marker, no number/word/yes-no brevity ask). Every junk sample
# the hold exists for is short or glued; a clean answer no longer waits for
# 400 chars / 2.5 s, so first-token latency is ~the time to its first 80
# chars. The released text is still judged by inspect() before it goes out.
_HOLD_EARLY_CHARS = answer_check.EARLY_MIN_CHARS
_EARLY_EVERY = 16
# Leak markers a released stream may receive split across deltas (see
# _StreamAnswerGate._marker_open); "<|...|>" template tokens separately.
_LEAK_MARKER_HEADS = ("<think>", "<thinking>", "</think>", "</thinking>",
                      "<tool_call", "</tool_call", "<arg_", "</arg_")
_TEMPLATE_OPEN_RE = re.compile(r"<\|[\w.-]*\|?")
# The rolling tail check costs O(window) per call, so after release it runs
# once per _TAIL_EVERY new chars rather than on every delta -- MEASURED before:
# a 60 KB answer in 4-char deltas spent 13.9 s of CPU in tail checks. A delta
# carrying a leak-marker char (<think>, <tool_call>, <|im_end|>, "Thought:")
# is still judged at once, so leaked markup never reaches the client; a loop
# or script switch is cut at most _TAIL_EVERY chars late (the cut point
# itself is unchanged).
_TAIL_EVERY = 64
# Chars of the text's end the gate keeps for its per-delta restart checks
# (answer_check.RESTART_KEY_MAX plus room for the boundary before it).
_GATE_TAIL = 2 * answer_check.RESTART_KEY_MAX + 8
_TAIL_TRIGGER_CHARS = frozenset("<>:|")
# A BARE-VALUE ask ("Reply with only the number.", answer_check.brevity_ask):
# the whole answer is a few chars, so the hold does not end on the 2.5 s
# clock -- only at the finish, _HOLD_CHARS, or this much longer bound for a
# slow model. MEASURED LIVE (Claude Code /v1/messages stream, model max):
# "4349âmara=METADATA:8;Note: TOKEN count=298121; REF:5" reached the client
# whole. Until the text passes _HOLD_CHARS every later delta is judged at
# once (not throttled), head rules included (inspect_tail's last_prompt), so
# a clock-released "4349" cannot grow junk unseen.
_BRIEF_HOLD_SECONDS = 8.0
_SSE_FRAME_END_RE = re.compile(rb"\r?\n\r?\n")


class _StreamAnswerGate:
    """Iterable wrapper over an upstream OpenAI chat SSE iterator. `cut` is True
    once the gate ended the stream on junk -- it has then already filed the
    hop's failed outcome, so the relay's end-of-stream judgement must not file
    a second (see _proxy_sse / _responses_stream / _anthropic_stream)."""

    def __init__(self, iterator, *, mode="bytes", hop_pid=None, hop_model=None,
                 prompt_text=None, last_prompt=None, tools_offered=False,
                 hold_chars=None, hold_seconds=None, visible_cap=None,
                 early_chars="default"):
        self._it = iterator
        # Chars of visible text past which the stream is ended at "length":
        # set only when the hub raised max_tokens for reasoning room, so the
        # caller still gets ~the visible length it asked for.
        self._cap_chars = visible_cap if isinstance(visible_cap, int) and visible_cap > 0 else None
        self._lines = mode == "lines"
        self._pid, self._model_id = hop_pid, hop_model
        self._prompt = prompt_text
        self._last_prompt = last_prompt
        self._tools = bool(tools_offered)
        self._hold_chars = _HOLD_CHARS if hold_chars is None else hold_chars
        self._brief = answer_check.brevity_ask(last_prompt)
        if hold_seconds is None:
            hold_seconds = _BRIEF_HOLD_SECONDS if self._brief else _HOLD_SECONDS
        self._hold_seconds = hold_seconds
        # Early release (reads_as_answer): off when a caller pins its own hold
        # window (tests measuring the window itself), or via early_chars=None.
        if early_chars == "default":
            early_chars = None if hold_chars is not None else _HOLD_EARLY_CHARS
        self._early_min = early_chars
        self._early_at = -_EARLY_EVERY
        self._frag = ""              # a possibly-split leak marker (_marker_open)
        self._rest = b""
        self._parts = []             # visible text so far (joined lazily)
        self._len = 0
        self._judged = 0             # self._len at the last tail check
        self._tail_state = {}        # answer_check.inspect_tail's scan cache
        self._emitted = 0            # chars of self._text already sent
        self._meta = {}              # id / created / model of the upstream chunks
        # A glued second answer (answer_check.glued_restart): the reply's
        # opening line once known (False = none), and where it ends.
        self._rkey = None
        self._rfirst_end = None
        self._tail = ""              # the last _GATE_TAIL chars of the text
        self._tail_before = ""       # ...as they were before the latest delta
        self.cut = False
        self.reasons = []

    def __iter__(self):
        run = self._run()
        return self._capped(run) if self._cap_chars else run

    def _capped(self, frames):
        """Relay `frames` (the gate's own output) until the visible text passes
        self._cap_chars, then end the stream at finish_reason "length" -- what
        a non-thinking model would have sent for the caller's budget. A tool
        call disarms the cap: an agent's arguments are never cut."""
        sent, rest, passthrough = 0, b"", False
        try:
            for item in frames:
                if passthrough:
                    yield item
                    continue
                if self._lines:
                    pieces = [item]
                else:
                    buf = rest + _stream_item_bytes(item)
                    pieces, pos = [], 0
                    for m in _SSE_FRAME_END_RE.finditer(buf):
                        pieces.append(buf[pos:m.end()])
                        pos = m.end()
                    rest = buf[pos:]
                    if len(rest) > _SSE_FRAME_CAP:
                        pieces.append(rest)
                        rest = b""
                for fr in pieces:
                    if passthrough:
                        yield fr
                        continue
                    k, t, _fin = self._classify(fr)
                    if k == "disarm":
                        passthrough = True
                    elif k == "text":
                        if sent + len(t) > self._cap_chars:
                            piece = t[:max(0, self._cap_chars - sent)]
                            sp = max(piece.rfind(" "), piece.rfind("\n"))
                            if sp > 0:
                                piece = piece[:sp]
                            elif _cut_splits_token(t, len(piece)):
                                # Never a prefix of a token ("5064" of
                                # "50648"): see _fit_visible_to_caller.
                                piece = ""
                            if piece.strip():
                                yield self._synth({"content": piece}, None)
                            yield self._synth({}, "length")
                            yield self._done()
                            return
                        sent += len(t)
                    yield fr
            if rest:
                yield rest
        finally:
            try:
                frames.close()
            except Exception:                                    # noqa: BLE001
                pass

    @property
    def _text(self):
        # str += on an attribute copies the whole answer on every delta; the
        # parts are joined only when something reads the text.
        if len(self._parts) > 1:
            self._parts = ["".join(self._parts)]
        return self._parts[0] if self._parts else ""

    def _add(self, t):
        self._parts.append(t)
        self._len += len(t)
        # Per-delta checks read only this rolling tail: self._text joins the
        # whole answer, which on every delta would be O(n^2) on a long one.
        self._tail_before = self._tail
        self._tail = (self._tail + t)[-_GATE_TAIL:]

    # -- framing ----------------------------------------------------------- #
    def _frames(self, item):
        if self._lines:
            return [item]
        raw = item if isinstance(item, (bytes, bytearray)) \
            else str(item).encode("utf-8", "ignore")
        buf = self._rest + bytes(raw)
        out, pos = [], 0
        for m in _SSE_FRAME_END_RE.finditer(buf):
            out.append(buf[pos:m.end()])
            pos = m.end()
        self._rest = buf[pos:]
        return out

    def _classify(self, frame):
        """(kind, text, finish_reason): kind is 'text' (visible content, maybe
        with a finish), 'finish', 'done', 'disarm' (tool call / anything the
        gate must not reorder) or 'other' (passes untouched)."""
        b = frame if isinstance(frame, (bytes, bytearray)) \
            else str(frame).encode("utf-8", "ignore")
        if b"data:" not in b:
            return "other", "", None
        if _STREAM_TOOLCALL_RE.search(b):
            return "disarm", "", None
        if re.search(rb"data:\s*\[DONE\]", b):
            return "done", "", None
        if b'"content"' not in b and b'"finish_reason"' not in b:
            return "other", "", None
        payload = b"".join(ln.strip()[5:].strip() for ln in b.split(b"\n")
                           if ln.strip().startswith(b"data:"))
        try:
            chunk = json.loads(payload.decode("utf-8", "ignore"))
        except ValueError:
            return "other", "", None
        if not isinstance(chunk, dict) or chunk.get("error"):
            return "other", "", None
        choices = chunk.get("choices") or []
        if not choices:
            return "other", "", None
        choice = choices[0] if isinstance(choices[0], dict) else {}
        if len(choices) > 1 or (choice.get("index") or 0) != 0:
            return "disarm", "", None      # n>1: not one answer to judge
        for k in ("id", "created", "model"):
            if chunk.get(k) is not None and k not in self._meta:
                self._meta[k] = chunk[k]
        delta = choice.get("delta") or {}
        c = delta.get("content")
        if isinstance(c, list):
            c = "".join((p.get("text") or "") for p in c if isinstance(p, dict))
        elif c is not None and not isinstance(c, str):
            c = str(c)
        fin = choice.get("finish_reason")
        if c:
            return "text", c, fin
        if fin:
            return "finish", "", fin
        return "other", "", None

    def _synth(self, delta, fin):
        chunk = {"id": self._meta.get("id") or "chatcmpl-gate",
                 "object": "chat.completion.chunk",
                 "created": self._meta.get("created") or int(time.time()),
                 "model": self._meta.get("model") or "",
                 "choices": [{"index": 0, "delta": delta, "finish_reason": fin}]}
        line = b"data: " + json.dumps(chunk).encode("utf-8")
        return line if self._lines else line + b"\n\n"

    def _done(self):
        return b"data: [DONE]" if self._lines else b"data: [DONE]\n\n"

    # -- verdicts ---------------------------------------------------------- #
    def _cut_at(self, clean_end, reasons):
        """Frames that end the stream after self._text[:clean_end], and file the
        hop as a failed delivery (it burned the budget on junk)."""
        self.cut = True
        self.reasons = list(reasons or ())
        out = []
        piece = self._text[self._emitted:max(self._emitted, clean_end)].rstrip()
        if piece.strip():
            out.append(self._synth({"content": piece}, None))
        out.append(self._synth({}, "stop"))
        out.append(self._done())
        _log.warning("[stream-gate] %s/%s: junk in stream (%s), %s",
                     self._pid, self._model_id, ",".join(self.reasons) or "?",
                     "served the clean part" if piece.strip() or self._emitted
                     else "nothing salvageable")
        if self._pid and self._model_id:
            try:
                _record_outcome(self._pid, self._model_id, False, junk=True)
            except Exception:                                    # noqa: BLE001
                pass
        return out

    def _judge_held(self, fin, partial=False):
        """None when the held text is clean, else the frames ending the stream.
        `partial`: the model is still going (the hold window ran out), so the
        held text's end is not the answer's end."""
        try:
            v = answer_check.inspect(
                self._text, prompt_text=self._prompt, tools_offered=self._tools,
                finish_reason=fin, last_prompt=self._last_prompt,
                partial=partial and not fin, relay=_is_relay_pid(self._pid))
        except Exception:                                        # noqa: BLE001
            return None
        if v.get("ok", True):
            return None
        salvage = v.get("salvage") or ""
        end = len(salvage) if salvage and self._text.startswith(salvage) else 0
        return self._cut_at(end, v.get("reasons"))

    def _reads_early(self):
        """True once the held text already reads as a normal answer
        (answer_check.reads_as_answer): the gate then releases at once
        instead of waiting out _HOLD_CHARS / _HOLD_SECONDS. The check runs at
        most once per _EARLY_EVERY new chars (it is O(held text))."""
        if self._early_min is None or self._len < self._early_min \
                or self._len - self._early_at < _EARLY_EVERY:
            return False
        self._early_at = self._len
        try:
            return answer_check.reads_as_answer(self._text,
                                                last_prompt=self._last_prompt,
                                                relay=_is_relay_pid(self._pid))
        except Exception:                                        # noqa: BLE001
            return False

    def _judge_tail(self, t=""):
        short_brief = self._brief and self._len <= self._hold_chars
        if not short_brief and self._len - self._judged < _TAIL_EVERY \
                and not _TAIL_TRIGGER_CHARS.intersection(t):
            return None
        self._judged = self._len
        try:
            c = answer_check.inspect_tail(self._text, prompt_text=self._prompt,
                                          tools_offered=self._tools,
                                          state=self._tail_state,
                                          last_prompt=self._last_prompt
                                          if self._brief else None)
        except Exception:                                        # noqa: BLE001
            return None
        if c is None:
            return None
        return self._cut_at(c, ["tail"])

    # -- a second answer glued onto the first (answer_check.glued_restart) -- #
    def _restart_key(self):
        k = self._rkey
        if k is None:
            head = self._text[:2048]
            s = head.lstrip()
            if "\n" in s or len(s) >= answer_check.RESTART_KEY_MAX:
                k = answer_check.restart_key(head) or False
                if k:
                    at = head.find(k)
                    self._rfirst_end = at + len(k) if at >= 0 else None
                    if self._rfirst_end is None:
                        k = False
                self._rkey = k
        return k or None

    def _judge_restart(self, t):
        """Frames ending the stream where a glued second answer starts, or
        None. Checks only the new text (plus a key's length before it)."""
        key = self._restart_key()
        if not key:
            return None
        try:
            region = self._tail_before[-(len(key) + 2):] + t
            base = self._len - len(region)          # offset of region[0]
            i = region.find(key, 1)
            while i >= 0:
                if self._restart_at(base + i, region[max(0, i - 2):i], region[i]):
                    return self._cut_at(base + i, ["restarted"])
                i = region.find(key, i + 1)
        except Exception:                                        # noqa: BLE001
            pass
        return None

    def _restart_at(self, q, before, cur):
        """A restatement at absolute offset `q` (`before`: the chars right
        before it) is a glued second answer: past the opening itself, glued
        (answer_check.restart_boundary), and not inside a code fence -- the
        one O(n) test, reached only by a real candidate."""
        return (q >= (self._rfirst_end or 0)
                and answer_check.restart_boundary(before, cur)
                and self._text.count("```", 0, q) % 2 == 0)

    def _restart_pending(self):
        """True while the text ENDS in a glued proper prefix of the reply's
        opening line -- maybe the start of a second answer. That text is kept
        back until the restatement completes (and is cut) or diverges, so not
        one character of a second answer reaches the client."""
        key = self._restart_key()
        if not key:
            return False
        try:
            tail = self._tail
            base = self._len - len(tail)
            for j in range(max(1, len(tail) - len(key) + 1), len(tail)):
                if key.startswith(tail[j:]) and self._restart_at(
                        base + j, tail[max(0, j - 2):j], tail[j]):
                    return True
        except Exception:                                        # noqa: BLE001
            return False
        return False

    def _marker_open(self, t):
        """True while the released text ends in what may be the START of a
        leak marker split across deltas ("<thi" + "nk>"): that delta is then
        kept back until the marker completes (judged and cut by _judge_tail)
        or turns out to be ordinary text. Without it, the first half of a
        split "<think>" reached the client before the second half was
        judged -- more often now that clean answers are released early."""
        if "<" in t:
            self._frag = t[t.rfind("<"):]
        elif self._frag:
            self._frag += t
        else:
            return False
        f = self._frag.lower()
        if f.startswith("<|"):
            if len(f) <= 24 and _TEMPLATE_OPEN_RE.fullmatch(f):
                return True
        elif len(f) <= 16 and ">" not in f and any(
                m.startswith(f) or f.startswith(m) for m in _LEAK_MARKER_HEADS):
            return True
        self._frag = ""
        return False

    # -- the relay --------------------------------------------------------- #
    def _run(self):
        q = queue.Queue(maxsize=256)
        stop = threading.Event()

        def _put(entry):
            while not stop.is_set():
                try:
                    q.put(entry, timeout=1.0)
                    return True
                except queue.Full:
                    continue
            return False

        def _pump():
            try:
                for item in self._it:
                    if not _put(("item", item)):
                        return
                _put(("end", None))
            except BaseException as exc:                         # noqa: BLE001
                _put(("exc", exc))

        threading.Thread(target=_pump, daemon=True).start()
        armed, holding = True, True
        held = []                    # the held visible-text frames, in order
        first_at = None
        try:
            while True:
                wait = None
                if armed and holding and first_at is not None:
                    wait = max(0.0, first_at + self._hold_seconds - time.monotonic())
                try:
                    kind, val = q.get(timeout=wait)
                except queue.Empty:
                    # The hold window ran out with the model still going.
                    stop_frames = self._judge_held(None, partial=True)
                    if stop_frames:
                        yield from stop_frames
                        return
                    if self._restart_pending():
                        # maybe a second answer starting: the relay branch
                        # below keeps it back until it completes or diverges
                        holding = False
                        continue
                    yield from held
                    held, holding = [], False
                    self._emitted = self._judged = self._len
                    continue
                if kind == "end":
                    break
                if kind == "exc":
                    # Upstream died mid-hold: the relay's own error handling
                    # ends the stream, but the text already received is still
                    # owed to the client (judged, as always) -- as it was
                    # before anything was held.
                    if held:
                        stop_frames = self._judge_held(None) if holding else None
                        if stop_frames:
                            yield from stop_frames
                            return
                        yield from held
                        held = []
                    raise val
                if not armed:
                    yield val
                    continue
                for fr in self._frames(val):
                    if not armed:
                        yield fr
                        continue
                    k, t, fin = self._classify(fr)
                    if k == "other":
                        yield fr
                        continue
                    if k == "disarm":
                        # A tool call: the turn is doing work, and its deltas
                        # are never held. Held text goes first, order kept.
                        yield from held
                        held, armed = [], False
                        yield fr
                        continue
                    if k == "text":
                        self._add(t)
                        if holding:
                            held.append(fr)
                            if first_at is None:
                                first_at = time.monotonic()
                            if not fin and self._len < self._hold_chars \
                                    and time.monotonic() - first_at < self._hold_seconds \
                                    and not self._reads_early():
                                continue
                            stop_frames = self._judge_held(fin, partial=True)
                            if stop_frames:
                                yield from stop_frames
                                return
                            if not fin and self._restart_pending():
                                holding = False  # kept back: see the relay branch
                                continue
                            yield from held
                            held, holding = [], False
                            self._emitted = self._judged = self._len
                            continue
                        stop_frames = self._judge_restart(t) or self._judge_tail(t)
                        if stop_frames:
                            yield from stop_frames
                            return
                        marker = self._marker_open(t)
                        if not fin and (marker or self._restart_pending()):
                            held.append(fr)      # a split leak marker, or a glued
                            continue             # second answer, may follow
                        if held:
                            yield from held
                            held = []
                        self._emitted = self._len
                        yield fr
                        continue
                    # 'finish' / 'done': the model is done talking.
                    if holding and held:
                        stop_frames = self._judge_held(fin)
                        if stop_frames:
                            yield from stop_frames
                            return
                        yield from held
                        held = []
                        self._emitted = self._len
                    elif held:
                        # a kept-back marker start that never completed
                        yield from held
                        held = []
                        self._emitted = self._len
                    holding = False
                    yield fr
                if armed and len(self._rest) > _SSE_FRAME_CAP:
                    # No frame boundary in sight (an upstream ignoring
                    # stream:true): nothing here is judgeable, so forward
                    # rather than turn a slow answer into a silent one.
                    yield from held
                    held, armed = [], False
                if not armed and self._rest:
                    yield self._rest
                    self._rest = b""
            # Upstream ended without a finish frame / [DONE].
            if held:
                stop_frames = self._judge_held(None) if holding else None
                if stop_frames:
                    yield from stop_frames
                    return
                yield from held
            if self._rest:
                yield self._rest
        finally:
            stop.set()


def _gate_stream(iterator, mode, hop_pid, hop_model, payload, has_tools):
    """_StreamAnswerGate for one committed hop. Fail-open: on any setup error
    the upstream iterator is relayed untouched (the gate is never the thing
    that loses an answer)."""
    try:
        cap = None
        caller = payload.get(_CALLER_MAX_KEY) if isinstance(payload, dict) else None
        if isinstance(caller, int) and caller > 0:
            cap = int(caller * 4 * 1.25) + 32     # ~caller tokens of text, 25% slack
        return _StreamAnswerGate(
            iterator, mode=mode, hop_pid=hop_pid, hop_model=hop_model,
            prompt_text=_prompt_text_for_check(payload),
            last_prompt=_last_user_text_for_check(payload),
            tools_offered=bool(has_tools), visible_cap=cap)
    except Exception:                                            # noqa: BLE001
        return iterator


def _peek_check(payload, has_tools):
    """The answer_check context _peek_until_content judges a peeked answer
    with. None on error: the peek then runs only its older detectors."""
    try:
        return {"prompt_text": _prompt_text_for_check(payload),
                "last_prompt": _last_user_text_for_check(payload),
                "tools_offered": bool(has_tools),
                # The offered tools themselves: a reply that is ONLY one of
                # their names ("shell_command") is a failed hop.
                "tools": (payload.get("tools") if has_tools and isinstance(payload, dict)
                          else None),
                # Tools already ran this turn: a later "I can't access that
                # file" is a report, not a claim to have no tools.
                "used_tools": bool(has_tools) and _turn_used_tools(
                    payload.get("messages") if isinstance(payload, dict) else None),
                # The caller's own budget: a reply cut at "length" far below
                # it is a starved stub, not an answer (_is_truncated_stub).
                "budget": _caller_budget(payload),
                "starve_check": True}
    except Exception:                                            # noqa: BLE001
        return None


# --------------------------------------------------------------------------- #
# BUDGET STARVATION — a reasoning model that spent the whole max_tokens thinking
# and had nothing left to answer with.
#
# MEASURED 2026-07-31 across cerebras / openrouter / opencode-zen / kilocode /
# g4f-gemini, ~85 live calls at budgets 1..512:
#   * empty content + finish_reason == "length" occurred 49/49 times when the
#     model was starved. Never "stop", never null. That pair IS the signal.
#   * the CONVERSE is false: finish_reason == "length" WITH real content is
#     common (a plain truncation). So both halves must be checked -- gating on
#     finish_reason alone would retry ordinary truncated answers forever.
#   * the reasoning text is NOT a usable discriminator. It arrives under three
#     different names (reasoning / reasoning_content / reasoning_details) and
#     g4f-gemini starves with NO reasoning field at all -- its message is
#     literally {"role":"assistant"} -- so keying on "has reasoning" would
#     misclassify exactly the provider that most needs the retry.
# Raising the budget fixed every case on a normal prompt; it is not a universal
# cure (cerebras stayed empty at 512 on a hard word problem), so this retries
# ONCE and then falls through to the next hop as before.
# --------------------------------------------------------------------------- #
_STARVED_RETRY_CAP = 2048        # never ask for more than this on the retry
_STARVED_RETRY_FLOOR = 512       # ...and never less than this, or it starves again


def _chat_json_starved(data):
    """True when a 200 carried no content ONLY because the token budget ran out
    mid-reasoning. Caller must already know the body is empty."""
    try:
        return (((data.get("choices") or [{}])[0] or {}).get("finish_reason") or "") == "length"
    except Exception:                                                # noqa: BLE001
        return False


def _starved_retry_budget(requested):
    """A budget likely to leave room for an answer after the thinking, or None
    when the caller already asked for plenty (then starvation is the model's
    problem, not the budget's, and a retry would just burn a second call)."""
    try:
        cur = int(requested) if requested else 0
    except (TypeError, ValueError):
        cur = 0
    if cur >= _STARVED_RETRY_CAP:
        return None
    return max(_STARVED_RETRY_FLOOR, min(_STARVED_RETRY_CAP, cur * 4 or _STARVED_RETRY_FLOOR))


# A provider can dodge STREAM_IDLE_TIMEOUT forever by sending blank/keepalive
# SSE lines without ever delivering real content -- observed LIVE, same
# provider+model, twice: 2026-08-06 held a swarm hop hostage 24+ minutes (see
# _SWARM_HOP_DEADLINE, the fix for that non-streaming case); 2026-08-08 held a
# live Codex /v1/responses stream 600+s, ending only when the ACTIVITY-FEED
# janitor relabelled the row 'stalled' for the dashboard (_ACTIVITY_STALL_SECS)
# -- which never touches the real connection, so Codex just kept waiting the
# whole time. Bounds time since the LAST real chunk, not total stream
# duration, so a genuinely slow-but-progressing generation (a long tool-call
# argument assembling, a reasoning model thinking) is never cut off -- only a
# stream that has gone quiet except for keepalives is.
# Same value and meaning as _SWARM_HOP_DEADLINE below ("this hop stopped
# delivering") -- not a direct reference, since that constant is defined
# later in the file and this one is used by _proxy_sse right below.
_STREAM_PROGRESS_DEADLINE = 150
_SSE_BLANK_DATA_RE = re.compile(rb"^data:\s*(?:\[DONE\])?\s*$")


def _sse_chunk_is_progress(raw):
    """True if `raw` -- one line from iter_lines(), or one arbitrary chunk from
    iter_content() that may itself contain several newline-joined lines --
    carries real upstream data, not just a blank/keepalive SSE line or a bare
    [DONE]. See _STREAM_PROGRESS_DEADLINE."""
    if not raw:
        return False
    if isinstance(raw, str):
        raw = raw.encode("utf-8", "ignore")
    for line in raw.split(b"\n"):
        line = line.strip()
        if line.startswith(b"data:") and not _SSE_BLANK_DATA_RE.match(line):
            return True
    return False


_STREAM_DIGEST_CAP = 2 << 20     # bytes of a relayed stream kept for the end check
_SSE_USAGE_TAIL = 16 << 10       # bytes of a stream's END kept to find its usage frame


def _sse_usage(blob):
    """The LAST OpenAI `usage` object in raw SSE bytes, or None. The tail a
    caller passes can start mid-frame; unparseable lines are skipped."""
    try:
        for line in reversed(bytes(blob or b"").split(b"\n")):
            line = line.strip()
            if not line.startswith(b"data:") or b'"usage"' not in line:
                continue
            try:
                chunk = json.loads(line[5:].strip().decode("utf-8", "ignore"))
            except ValueError:
                continue
            u = chunk.get("usage") if isinstance(chunk, dict) else None
            if isinstance(u, dict) and (u.get("prompt_tokens") or u.get("completion_tokens")):
                return u
    except Exception:                                            # noqa: BLE001
        pass
    return None


def _record_sse_usage(hop_pid, hop_model, kept, tail, prompt_est):
    """Usage for a relayed /v1/chat/completions stream, filed under the REAL hop.

    The passthrough never recorded usage at all -- only the Codex and Anthropic
    stream paths did (and Codex's under the client's "auto" label) -- so every
    streamed chat turn was missing from the usage history. Real usage when the
    stream carried a usage frame, else the char/4 estimate the other paths use.
    Never raises."""
    try:
        u = _sse_usage(tail) or _sse_usage(b"".join(kept))
        if u is not None:
            _note_thinking_evidence(hop_pid, hop_model, usage=u)
        if any(_STREAM_REASONING_RE.search(bytes(k)) for k in (kept or ())[:64]
                 if isinstance(k, (bytes, bytearray))):
            _note_thinking(hop_pid, hop_model, "reasoning deltas")
        if u is not None:
            usage_history.record(hop_pid, hop_model, int(u.get("prompt_tokens") or 0),
                                 int(u.get("completion_tokens") or 0), estimated=False)
            _note_session_spend(_build_sid(), u.get("prompt_tokens") or 0,
                                u.get("completion_tokens") or 0)
            return
        text, _tools, _fin = _sse_answer_digest(kept)
        usage_history.record(hop_pid, hop_model, int(prompt_est or 0),
                             len(text) // 4, estimated=True)
        _note_session_spend(_build_sid(), int(prompt_est or 0), len(text) // 4)
    except Exception:                                            # noqa: BLE001
        pass


# --------------------------------------------------------------------------- #
# BROKEN UPSTREAM STREAMS: an answer the upstream never finished is never handed
# to a CLI as a finished one. Covered by tests/test_broken_stream_retry.py.
#
# MEASURED 2026-10-03 (hub.log, Multi worker, opencode session fe4bbd96): after
# 7 minutes of real work the provider's stream died mid-answer ("SSE
# passthrough error: Response ended prematurely"). The passthrough then sent
# `data: [DONE]`, which tells the CLI the answer is COMPLETE: opencode ended the
# turn (exit 0, no message), the phase was written off as "opencode produced no
# reply", and nothing was filed against the pair, so the next request could
# pick it again. /v1/responses and /v1/messages did the same in their own
# shape (response.completed / message_stop on a partial answer).
#
# Now, when the upstream ITERATOR raises (reset, ChunkedEncodingError, read
# timeout, a Puter error event) -- or streams an error object -- BEFORE any
# finish_reason / terminal event, each protocol gets the signal its clients
# retry on (the evidence per CLI is at each site) and the pair is filed failed
# (_note_broken_stream). An upstream that had already sent its finish_reason
# delivered a complete answer: that keeps today's clean end. An exception from
# the hub's OWN frame handling is not upstream death and keeps the old path.
# --------------------------------------------------------------------------- #
class _UpstreamStreamError(Exception):
    """An upstream stream that reported an error instead of finishing (a Puter
    error event, an OpenAI `{"error": ...}` frame after the commit)."""


def _upstream_reads(iterator, box):
    """Relay `iterator`. An exception IT raises ends the relay quietly and is
    kept in box["exc"], so the caller can tell upstream death (the iterator
    raised) from a fault in its own frame handling (its loop raised).
    GeneratorExit (a client disconnect) is not caught."""
    try:
        for item in iterator:
            yield item
    except Exception as exc:                                     # noqa: BLE001
        box["exc"] = exc


def _stream_error_text(exc):
    """A short, key-free reason for a broken stream."""
    try:
        if isinstance(exc, _UpstreamStreamError):
            return _sanitize(str(exc) or "upstream stream error", 200)
        return _sanitize("%s: %s" % (type(exc).__name__, exc), 200)
    except Exception:                                            # noqa: BLE001
        return "upstream stream error"


def _stream_error_frame_text(chunk):
    """The message of an OpenAI `{"error": ...}` stream frame."""
    err = chunk.get("error") if isinstance(chunk, dict) else None
    if isinstance(err, dict):
        return str(err.get("message") or err.get("code") or err.get("type")
                   or "upstream error")
    return str(err or "upstream error")


_BROKEN_STREAM_TEXT = ("upstream connection lost mid-stream before the answer was "
                       "finished (%s); service unavailable, retry the request")


def _chat_broken_frame(exc, open_frame=False):
    """The end of a /v1/chat/completions stream whose upstream died before its
    finish_reason: ONE OpenAI error frame, then the body closes -- no [DONE].

    Evidence (sources read 2026-10-03):
    * opencode (anomalyco/opencode dev, ai 6.0.168 + @ai-sdk/openai-compatible
      2.0.41, patched): the chunk schema is z.union([chunkBase, errorSchema]);
      errorSchema = {error: {message: string, type?, param?, code?}} and
      chunkBase REQUIRES `choices`, so the frame carries no `choices`. The
      error part reaches session/llm/ai-sdk.ts (`case "error": Effect.fail`);
      message-v2.ts fromError maps `code === "ECONNRESET"` to APIError
      "Connection reset by server", isRetryable: true; session/retry.ts also
      retries any message containing "unavailable" / "connection lost" /
      "server_error" (RETRY_MAX_RETRIES 5, 2s x 2^n backoff). VERIFIED.
      By contrast `[DONE]` with no finish_reason is NOT an error there:
      parseJsonEventStream drops [DONE], flush reports finishReason 'other'
      -> opencode "unknown" -> prompt.ts loops on with the partial answer in
      history (and the measured run ended the turn with no reply).
    * qwen-code (QwenLM/qwen-code main): openai-node raises a `data:` frame
      with an `error` key as APIError(undefined, data.error), whose .code is
      the frame's code; utils/retryErrorClassification.ts getTransportCode
      finds "ECONNRESET" (in TRANSPORT_ERROR_CODES) -> 'transport', retried.
      VERIFIED. (A [DONE] with no finish_reason is retried there as well --
      InvalidStreamError NO_FINISH_REASON -- but not in opencode, and kimi-cli
      accepts it as complete; there an error frame is shown as an error,
      not retried. The frame is the one signal that reads "not finished"
      in all of them.)
    `open_frame`: the last relayed chunk ended mid-line; a blank line first
    closes it so the error frame is parsed on its own."""
    body = {"error": {"message": _BROKEN_STREAM_TEXT % _stream_error_text(exc),
                      "type": "server_error", "code": "ECONNRESET"}}
    frame = b"data: " + json.dumps(body).encode("utf-8") + b"\n\n"
    return (b"\n\n" + frame) if open_frame else frame


def _note_broken_stream(pid, model, exc, where):
    """File a committed stream that died before its finish_reason: one failed
    delivery (_record_outcome -> reliability) AND a recent failure
    (_note_recent_hop_failure), which is the ledger _build_chain and the
    router read to put the pair behind every other candidate for
    _RECENT_FAIL_TTL -- one failure in a long ok-history would not move its
    reliability band. A read timeout is filed as a stall ("timeout"), anything
    else as "conn". Never raises."""
    if _client_gone():
        # The hub cut this stream itself: its client left (clientgone).
        _log.info("[broken-stream] %s %s/%s: cut because the client left; "
                  "nothing filed", where, pid, model)
        return
    try:
        _log.warning("[broken-stream] %s %s/%s: upstream died before finishing (%s); "
                     "the client got a retryable error, hop filed as failed",
                     where, pid, model, _stream_error_text(exc))
        if not (pid and model):
            return
        _record_outcome(pid, model, False)
        kind = "timeout" if (isinstance(exc, (requests.Timeout, TimeoutError))
                             or "timed out" in str(exc).lower()) else "conn"
        _note_recent_hop_failure(pid, model, kind)
    except Exception:                                            # noqa: BLE001
        pass


def _proxy_sse(resp, iterator=None, first=_MISSING, hop_pid=None, hop_model=None,
               prompt_text=None, tools_offered=False, last_prompt=None, prompt_est=0,
               answer_gate=None):
    """Pass upstream SSE bytes through unchanged. When `iterator`/`first` are
    supplied (the first-byte peek already pulled the first chunk from this exact
    iterator), yield that chunk first, then continue the SAME iterator — so the
    fast-path byte stream is byte-for-byte identical to before. Empty chunks are
    still filtered exactly as before.

    Also enforces _STREAM_PROGRESS_DEADLINE: a provider that goes quiet except
    for keepalives is cut off, recorded as a delivery failure (so it stops
    winning top slot), and the client gets a clean [DONE] instead of an SSE
    body that never ends.

    With `hop_pid`, a stream that ENDS normally is judged once (answer_check,
    via _record_stream_outcome) and its outcome recorded -- the bytes are
    kept (capped) and parsed only then, so the relay stays a passthrough.
    `answer_gate` (the _StreamAnswerGate feeding `iterator`) skips that when
    the gate already cut the stream and filed the failure itself.

    An upstream that dies BEFORE its finish_reason / [DONE] ends the relay
    with _chat_broken_frame (a retryable error frame, no [DONE]) and is filed
    failed -- see BROKEN UPSTREAM STREAMS above."""
    saw_done = False
    finished = False         # a finish_reason frame passed: the answer is complete
    stalled = False
    kept, kept_len = [], 0
    tail = b""
    prev = b""               # end of the previous chunk (a finish split across two)
    open_frame = False       # the last relayed byte was not a frame/line end
    reads = {}               # what the upstream iterator raised (_upstream_reads)
    last_progress = time.time()
    try:
        if iterator is None:
            iterator = resp.iter_content(chunk_size=None)
        for chunk in _upstream_reads(_chain_first(first, iterator), reads):
            now = time.time()
            if _sse_chunk_is_progress(chunk):
                last_progress = now
            elif now - last_progress > _STREAM_PROGRESS_DEADLINE:
                _log.warning("[stream-stall] %s/%s: no real content for %ds, cutting off",
                            hop_pid, hop_model, _STREAM_PROGRESS_DEADLINE)
                _record_outcome(hop_pid, hop_model, False)
                stalled = True
                if not saw_done:
                    yield b"data: [DONE]\n\n"
                    saw_done = True
                break
            if chunk:
                raw = (chunk if isinstance(chunk, (bytes, bytearray))
                       else str(chunk).encode("utf-8", "ignore"))
                if not saw_done and _STREAM_TERMINAL_RE.search(raw):
                    saw_done = True
                if not finished and _STREAM_FINISH_RE.search(prev + bytes(raw)):
                    finished = True
                prev = bytes(raw[-64:])
                open_frame = not raw.endswith(b"\n")
                if hop_pid and kept_len < _STREAM_DIGEST_CAP:
                    kept.append(bytes(raw))
                    kept_len += len(raw)
                elif hop_pid:
                    # Past the digest cap: keep only the END, where the usage
                    # frame lives.
                    tail = (tail + bytes(raw))[-_SSE_USAGE_TAIL:]
                yield chunk
        broken = reads.get("exc")
        if broken is not None and not (saw_done or finished):
            # The upstream died before finishing: never [DONE] (= "complete"
            # to every client). See BROKEN UPSTREAM STREAMS / _chat_broken_frame.
            if not getattr(answer_gate, "cut", False):
                _note_broken_stream(hop_pid, hop_model, broken, "chat")
            yield _chat_broken_frame(broken, open_frame)
            return
        if broken is not None:
            # Died AFTER its finish_reason: the answer is complete. Close it as
            # before and judge it like any finished stream.
            _log.error("SSE passthrough error after the answer finished: %s",
                       _stream_error_text(broken))
            if not saw_done:
                saw_done = True
                yield b"data: [DONE]\n\n"
        if hop_pid and not stalled and not getattr(answer_gate, "cut", False):
            text, saw_tools, fin = _sse_answer_digest(kept)
            _record_stream_outcome(hop_pid, hop_model, text, tool_calls=saw_tools,
                                   finish_reason=fin, prompt_text=prompt_text,
                                   tools_offered=tools_offered, last_prompt=last_prompt)
    except Exception as exc:
        # A fault in THIS relay's own handling (upstream death is caught by
        # _upstream_reads above and never reaches here). Without a terminator
        # the client sits on a half-open SSE body waiting for a [DONE] that
        # will never come; this only appends it.
        _log.error("SSE passthrough error: %s", _sanitize(str(exc)))
        if not saw_done:
            try:
                yield b"data: [DONE]\n\n"
            except Exception:
                pass
    finally:
        if hop_pid and hop_model:
            _record_sse_usage(hop_pid, hop_model, kept, tail, prompt_est)
        resp.close()


_SSE_HEADERS ={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"}

# Beyond this many bytes with no frame boundary, stop trying to frame and just
# forward. An upstream that ignores `stream: true` and returns one JSON body has
# no "\n\n" in it at all; buffering that to the end would turn a slow answer into
# a silent one.
_SSE_FRAME_CAP = 1 << 20


def _repair_tool_call_deltas(delta, state):
    """Make one streaming delta's tool_calls act-on-able. Returns True if it
    changed anything -- an unchanged frame is forwarded as its original bytes.

    Three repairs, each for a shape measured in the wild:

    * index -- google/models/gemini-flash-latest omits it entirely. The AI SDK
      build opencode currently binds tolerates that (`F.index ?? X.length`); the
      sibling build in the same binary does `let s=T.index` with no fallback,
      and the Python openai SDK accumulates by index too.
    * id -- absent on a delta that STARTS a call is a hard throw client-side:
      "Expected 'id' to be a string." Only synthesised where a call begins (a
      `function.name`); continuation fragments legitimately carry neither.
    * arguments -- must be a string. Some relays send the object.

    Grouping rule, which is how a conforming stream already behaves: an `id`
    starts a new call, a delta without one continues the current call. Getting
    this wrong would either concatenate two commands into one or split one
    command into two."""
    calls = delta.get("tool_calls")
    if not isinstance(calls, list):
        return False
    changed = False
    for tc in calls:
        if not isinstance(tc, dict):
            continue
        state["seen"] = True
        tid = tc.get("id")
        if tid:
            if tid not in state["ids"]:
                state["ids"][tid] = state["next"]
                state["next"] += 1
            state["cur"] = state["ids"][tid]
        idx = tc.get("index")
        if isinstance(idx, int) and not isinstance(idx, bool):
            state["cur"] = idx
            state["next"] = max(state["next"], idx + 1)
        else:
            if state["cur"] is None:
                state["cur"] = state["next"]
                state["next"] += 1
            tc["index"] = state["cur"]
            changed = True
        fn = tc.get("function")
        if isinstance(fn, dict):
            args = fn.get("arguments")
            if args is not None and not isinstance(args, str):
                fn["arguments"] = json.dumps(args)
                changed = True
            if not tid and fn.get("name"):
                tc["id"] = "call_" + uuid.uuid4().hex[:16]
                changed = True
    return changed


def _repair_sse_frame(frame, state):
    """One SSE frame in, one out. Anything unparseable comes back verbatim."""
    stripped = frame.strip()
    if not stripped.startswith(b"data: "):
        return frame
    body = stripped[6:].strip()
    if not body.startswith(b"{"):          # [DONE], comments, event: lines
        return frame
    try:
        ev = json.loads(body.decode("utf-8"))
    except (ValueError, UnicodeDecodeError):
        return frame
    if not isinstance(ev, dict):
        return frame
    changed = False
    for ch in (ev.get("choices") or []):
        if not isinstance(ch, dict):
            continue
        delta = ch.get("delta")
        if isinstance(delta, dict) and _repair_tool_call_deltas(delta, state):
            changed = True
        # THE MEASURED BUG. gemini-flash-latest ends a turn that called a tool
        # with finish_reason "stop", and the AI SDK's mapping is a plain switch:
        # "stop" -> "stop" ends the turn, and the already-parsed tool call is
        # dropped. No error, no log -- the agent just stops with a command it
        # never ran. Only "stop" is rewritten: "length" means a TRUNCATED call
        # and the CLI has to see that as truncation, not as something to run.
        if state["seen"] and ch.get("finish_reason") == "stop":
            ch["finish_reason"] = "tool_calls"
            changed = True
    if not changed:
        return frame
    return b"data: " + json.dumps(ev).encode("utf-8") + b"\n\n"


def _sub_stream_message(data):
    """The delta + finish_reason a `sub-*` hop's non-streaming answer becomes.

    Both streaming sub branches (chat and responses) used to build this inline
    from `msg.get("content") or ""` with a hardcoded finish_reason "stop", which
    threw away two different things:

      * a genuine tool_calls list -- a subscription CLI can absolutely emit one;
      * and the repair made two lines earlier. _chat_json_nonanswer calls
        tool_rescue.rescue(data, tools), which MUTATES `data` in place to
        promote a prose-typed call into real tool_calls and sets content to
        None, then reports "that was an answer, carry on". So on exactly the
        turns where the rescue worked, the branch sent an EMPTY assistant
        message and told the CLI the turn was over.

    One helper for both, because they had already drifted -- the chat one
    carried `role`, the responses one did not."""
    _dedupe_tool_calls_json(data)
    choice = (data.get("choices") or [{}])[0] if isinstance(data, dict) else {}
    msg = choice.get("message") or {}
    delta = {"role": "assistant", "content": msg.get("content") or ""}
    fin = choice.get("finish_reason") or "stop"
    calls = msg.get("tool_calls")
    if calls:
        delta["tool_calls"] = [dict(tc, index=tc.get("index", i))
                               if isinstance(tc, dict) else tc
                               for i, tc in enumerate(calls)]
        if fin == "stop":
            fin = "tool_calls"
    return delta, fin


def _repair_tool_sse(chunks):
    """Wrap a relayed SSE byte stream and fix the tool-call frames in it.

    Deliberately a WRAPPER around _proxy_sse rather than an edit to it:
    _proxy_sse is a byte passthrough that also enforces the progress deadline
    and the terminator guarantee, and a JSON parser has no business in the path
    of every stream the hub serves. This runs only when the request carries
    tools -- so a plain chat stream keeps the zero-copy path exactly as it was,
    and a frame that needs no repair is re-emitted as its ORIGINAL bytes."""
    buf = b""
    state = {"seen": False, "next": 0, "cur": None, "ids": {}}
    for chunk in chunks:
        if not chunk:
            continue
        if not isinstance(chunk, (bytes, bytearray)):
            chunk = str(chunk).encode("utf-8", "ignore")
        buf += chunk
        while True:
            cut = buf.find(b"\n\n")
            if cut < 0:
                break
            frame, buf = buf[:cut + 2], buf[cut + 2:]
            yield _repair_sse_frame(frame, state)
        if len(buf) > _SSE_FRAME_CAP:      # not framed SSE -- stop pretending
            yield buf
            buf = b""
    if buf:
        yield _repair_sse_frame(buf, state)


def _dedupe_tool_calls_json(data):
    """Collapse exact duplicate tool calls (same name, byte-identical
    arguments) in a non-streamed chat JSON, in place; the first copy keeps its
    id. MEASURED: opencode's doom_loop guard rejected a reply carrying three
    identical bash calls. Never raises."""
    try:
        n = tool_rescue.dedupe_message(data)
        if n:
            _log.warning("[tool-dedupe] dropped %d exact duplicate tool call(s) (%s)",
                         n, (data.get("model") if isinstance(data, dict) else None) or "?")
    except Exception:                                            # noqa: BLE001
        pass


def _dedupe_tool_stream(iterator, framing, hop_pid=None, hop_model=None):
    """tool_rescue.dedupe_stream over a committed tools-turn stream (all three
    protocols feed it upstream OpenAI chat SSE), logging each dropped copy."""
    def _dropped(name, args):
        _log.warning("[tool-dedupe] %s/%s: dropped an exact duplicate %s call (%s)",
                     hop_pid, hop_model, name, _sanitize(args, 80))
    return tool_rescue.dedupe_stream(iterator, framing, on_drop=_dropped)


def _classify_hop_error(exc=None, status=None, peek=None):
    """One-token class of why a chain hop failed, for the X-Free-LLM-Hub-Last-Error
    transparency header (timeout / conn / 413 / 429 / http-<n> / empty / error /
    non-json) — so 'why did the chain degrade' is one curl -i away instead of a
    log dig."""
    if exc is not None:
        if isinstance(exc, _HopBudgetExceeded):
            return "deadline"      # the hub stopped waiting -- not a provider timeout
        if isinstance(exc, _ContextOverflow):
            return "context"       # skipped: this window would drop too much history
        if isinstance(exc, requests.Timeout):
            return "timeout"
        if isinstance(exc, requests.RequestException):
            # "dns": THIS computer could not resolve the host / reach the
            # network -- not the provider's failure (see _is_local_network_error).
            return "dns" if _is_local_network_error(exc) else "conn"
        return "error"      # RuntimeError (no key/base_url, sub relay, ...)
    if status is not None:
        if status in (413, 429):
            return str(status)
        return "http-%d" % status
    return peek or "error"


def _note_hop_detail(pid, exc):
    """LOG ONLY: remember a hop's exception class AND its sanitized message for
    the 503/deadline diagnosis line. The client never sees this (it gets the
    folded class words of _client_hop_errors); the log does, so a burst of
    "ConnectionError" can be read as what it really was -- a reset, a connect
    refusal, which host -- instead of a bare class name. Keys are redacted by
    _sanitize. Per-request (g); never raises."""
    try:
        msg = _sanitize(str(exc) if exc is not None else "", 200).strip()
        detail = "%s: %s%s" % (pid, type(exc).__name__ if exc is not None else "none",
                               (" " + msg) if msg else "")
        lst = getattr(g, "hub_hop_details", None)
        if lst is None:
            lst = []
            try:
                g.hub_hop_details = lst
            except Exception:                                    # noqa: BLE001
                return
        if len(lst) < 24:
            lst.append(detail)
    except Exception:                                            # noqa: BLE001
        pass


def _hop_details_log():
    """The log-only hop exception details for this request ("none" when none)."""
    try:
        return "; ".join(getattr(g, "hub_hop_details", None) or ()) or "none"
    except Exception:                                            # noqa: BLE001
        return "none"


def _mode_status(pid, model):
    """(the mode in force, True when `model` is NOT in it). Reporting only.

    _apply_mode is fail-open BY DESIGN: a mode whose models are all busy,
    withdrawn or rate-limited must degrade to answering rather than to refusing.
    What was missing is any record that it happened. MEASURED: a request sent
    with model "reasoning" was answered by groq/qwen/qwen3.8-27b, which is in
    `uncensored` and not in `reasoning`, with nothing anywhere saying so -- and
    from outside, a mode that quietly did not apply is indistinguishable from a
    routing bug.

    Asks the question the caller actually cares about -- "did I get the kind of
    model I asked for" -- by comparing the ANSWERING model against the mode,
    rather than tracking which _apply_mode call fell open. _build_chain filters
    its two tiers separately and the vision router does not filter at all, so
    that is the only version of the question with one honest answer.

    Never consulted while routing, and fails silent on anything it cannot
    evaluate: it must not be able to claim a mismatch it cannot prove."""
    try:
        m = _active_mode()
        if not m or m == MODE_ALL or not pid or not model:
            return None, False
        return m, not _mode_allows(m, pid, model)
    except Exception:                                            # noqa: BLE001
        return None, False


def _served_metadata(pid, model):
    """{"free_llm_hub_provider", "free_llm_hub_model"}: the pair that REALLY
    answered a /v1/responses request, for the Responses `metadata` map (a
    string->string map every Responses client already accepts). `model` on
    the response stays the id the client asked for -- codex keys its model
    metadata on it -- so this is where the served pair travels in the body."""
    out = {}
    if pid:
        out["free_llm_hub_provider"] = str(pid)
    if model:
        out["free_llm_hub_model"] = str(model)
    return out


def _routing_headers(pid, model, attempts, last_error=None):
    """Routing-transparency headers: which provider/model actually served the
    response (or was last tried, on a chain-exhausted error), how many
    upstream hops the chain burned, and the class of the LAST hop failure seen
    before this response ('none' when the first hop just worked — see
    _classify_hop_error). Debugging aid only — bodies stay untouched."""
    h = {"X-Free-LLM-Hub-Attempts": str(attempts),
         "X-Free-LLM-Hub-Last-Error": last_error or "none"}
    if pid:
        h["X-Free-LLM-Hub-Provider"] = str(pid)
    if model:
        h["X-Free-LLM-Hub-Model"] = str(model)
    # The MODE, and whether it was actually honoured. A mode that fell open is
    # still a correct answer -- it just is not the KIND of answer that was
    # asked for, and the caller has no other way to find that out.
    _mode, _missed = _mode_status(pid, model)
    if _mode:
        h["X-Free-LLM-Hub-Mode"] = str(_mode)
        if _missed:
            h["X-Free-LLM-Hub-Mode-Applied"] = "no"
    # best/max served by its graceful-degrade fallback (_QUALITY_FALLBACK_SHARE)
    _fb = _quality_fallback_header(pid, model)
    if _fb:
        h["X-Free-LLM-Hub-Fallback"] = _fb
    return h


def _with_headers(resp_tuple, headers):
    """Attach extra headers to an (response, status) tuple. Best-effort; returns
    the input untouched on error."""
    try:
        resp, status = resp_tuple
        for k, v in headers.items():
            resp.headers[k] = v
        return resp, status
    except Exception:
        return resp_tuple


# --------------------------------------------------------------------------- #
# SWARM — the "several strong models build it together" virtual model.
# Selected explicitly (model: "swarm"); see swarm.py for why it is not automatic.
# CREWS — the same pipeline with specialised stage prompts (model: "crew-code",
# "crew-research", ...; bare "crew" auto-detects); see crews.py.
# --------------------------------------------------------------------------- #
_SWARM_IDS = ("swarm", "team", "plan")

# Every VIRTUAL model id the hub serves, in the order a picker should show them:
# the two routing modes first, then the pipelines.
#
# This exists because "best" -- the dashboard's MAX mode -- was missing from all
# three model listings while working perfectly when typed. Each listing had
# built its own `[auto] + _SWARM_IDS + CREW_IDS`, and none of them included it,
# so every CLI's /model picker offered Normal and Swarm and silently dropped
# Max. One list, used by all three, so the next mode cannot be forgotten in two
# places out of three.
# The words a CLI's /model picker shows for the hub's own ids. Grouped with a
# leading kind ("Category ·", "Pipeline ·", the tier words) so a flat list
# still reads as three groups. "all" and "max" are the plain-language aliases
# the user asked for: "all" is auto with no category limit, "max" is "best".
_VIRTUAL_MODEL_LABELS = {
    "auto": "Auto · orchestrated (best free model per task)",
    "all": "All models · every category, orchestrated",
    "best": "Max · strongest free models only",
    "max": "Max · strongest free models only",
    # HONEST about what a CLI gets. "Multi sessions" (real agent windows) only
    # exists on the /agent page; a stateless /v1 turn maps "multi" to the crew
    # pipeline (tool-free) or the best-of-N fan-out (tool turns) -- see
    # _crew_name_for. The old label promised the windows.
    "multi": "Multi · phased crew (plan → work → review)",
}


# A friendlier word for the swarm/crew pipeline ids than the bare slug.
_PIPELINE_LABELS = {
    "swarm": "Swarm agents (several models answer, best wins)",
    "team": "Team (a swarm variant)",
    "plan": "Plan (a swarm variant)",
    "crew": "Crew (a multi-role pipeline)",
    "crew-code": "Crew · code", "crew-research": "Crew · research",
    "crew-write": "Crew · write", "crew-design": "Crew · design",
}


def _virtual_model_label(mid):
    """What a picker shows next to the id. Three groups: the tiers
    (Auto/All/Max), the CATEGORIES (from model_categories -- dynamic, so a new
    category shows up here on its own), and the PIPELINES (swarm/crew)."""
    if mid in _VIRTUAL_MODEL_LABELS:
        return _VIRTUAL_MODEL_LABELS[mid]
    if mid in _mode_keys():
        for key, label, _help in model_categories.labels():
            if key == mid:
                return "Category · %s" % label
        return "Category · %s" % mid
    return "Pipeline · " + _PIPELINE_LABELS.get(mid, mid)


def _virtual_model_ids():
    # The MODES are listed too. Selecting one inside a CLI has no other handle:
    # a coding agent has no settings screen and no notion of this hub's
    # projects, but every one of them can set a model id. `model: "coding"`
    # routes exactly like `auto` while restricting the pool to that category, so
    # "use the coding models here" is expressible from opencode, codex, Claude
    # Code and the rest without any per-CLI plumbing.
    # auto / all / best / max are the tiers, then every category (dynamic
    # from _mode_keys, no hardcoding), then the pipelines. "all" and "max"
    # are aliases -- "all" == auto with no category limit, "max" == best --
    # added because they are the words people reach for.
    return ("auto", "all", "best", "max", "multi") + _mode_keys() + _SWARM_IDS + tuple(crews.CREW_IDS)

# Total deadline for ONE swarm/crew stage hop. Swarm stages dispatch
# non-streaming, so they get neither the streaming first-byte peek (~25-90s)
# nor the inter-chunk idle timeout — only requests' per-recv read timeout
# (CHAT_READ_TIMEOUT). A provider that trickles keepalive bytes resets that on
# every byte and can hold a hop forever: OBSERVED LIVE 2026-08-06,
# tokenrouter/moonshotai/kimi-k3-free kept a stage hostage 24+ minutes (never
# answering stream:false), so a whole crew run produced nothing. CHAT_READ_TIMEOUT
# stays as the per-recv guard; this is the overall one. The abandoned thread
# is a daemon and its socket dies with the provider's connection — bounded by
# chain length, so the leak is small and self-cleaning.
# Per HOP, not per stage: _swarm_dispatch walks a fallback chain and gives each
# model this long. 150s was cutting off models that were working, just slowly --
# the same fault as the tool fan-out below. Raised, and the chain walk is capped
# (see _SWARM_STAGE_MAX_HOPS) so a stage's total does not grow with the fleet.
_SWARM_HOP_DEADLINE = 300
# How many models one prose stage may try. Without this, raising the per-hop
# deadline multiplies the whole crew run: 300s x a twelve-model chain is an hour
# for one stage.
_SWARM_STAGE_MAX_HOPS = 3

# The TOOL fan-out gets its own, longer deadline. The 150s above was measured
# against prose pipeline STAGES -- short, self-contained, and many per run, so a
# tight per-stage bound is what keeps a whole crew from stalling. A CLI agent
# turn is a different workload wearing the same clothes: the full system prompt,
# every tool schema the CLI declares, and the whole conversation so far, all
# dispatched NON-STREAMING so the model must finish generating before a single
# byte comes back. On free-tier models that routinely passes 150s.
#
# MEASURED 2026-09-04: five consecutive opencode build turns, 152/156/157/162/
# 168 seconds, every one of them 0-of-5 members answering -- durations clustered
# just above the deadline, which is what a deadline looks like when it is the
# thing doing the killing.
#
# Raised, not removed: an unbounded fan-out can hold a turn open for as long as
# the slowest provider feels like trickling keepalives (the 24-minute hostage in
# the note above). And it is now safe to be generous, because missing it no
# longer fails the turn -- it falls through to single-model routing.
# REPORTED 2026-09-10: "je vois toujours beaucoup de models dans les swarm
# 'no answer' ... meme dans les requests normaux ca marche avec tous les models,
# alors il faut juste attendre leur reponse."
#
# He is right, and the code already had the evidence: the note above records
# five opencode turns at 152/156/157/162/168 seconds, all 0-of-5, against a
# 150s deadline -- durations clustered just above the bound, which is what a
# deadline looks like when it is the thing doing the killing. Raised again, to
# the ~6 minutes asked for.
#
# This is a WALL CLOCK, and it has to stay one: CHAT_READ_TIMEOUT is per-recv
# and bounds nothing, because a provider trickling keepalives resets it on
# every byte (measured at 24+ minutes, see _SWARM_HOP_DEADLINE above).
_SWARM_TOOL_HOP_DEADLINE = 360

# ...and how long to keep waiting for stragglers AFTER a member has produced a
# usable tool call.
#
# The fan-out used to wait for every member, so one that never answers cost the
# full deadline even when the turn was already answerable. MEASURED 2026-09-04
# on a real tool turn: three of five answered, at 5s, 78s and 111s -- and the
# request took 297 SECONDS, because the two that never answered burned the whole
# budget. The user waited three extra minutes for an answer that had been
# sitting there since 111s.
#
# The grace only starts once something has actually CALLED A TOOL, which is what
# an agent turn needs. A prose-only answer does not start it: waiting longer is
# exactly right while the only thing on the table is an answer the CLI cannot
# execute.
#
# 25s first, then 90s -- asked for directly ("fewest no-answer, slowest turns")
# once the trade was visible. 25 bought the 297s -> 97s win and then showed its
# cost: the run that produced it answered 1-of-5, because the members measured
# at 78s and 111s were cut off by a first answer at 5s. 90 covers that spread
# while still ending a turn in roughly the time the 25s version took, since the
# clock starts at the FIRST answer and not at the request.
# RAISED from 90 after "je vois toujours beaucoup de models dans les swarm no
# answer". The measurement in the note above is the argument: members answered
# at 5s, 78s and 111s, so a 90s grace starting at the 5s answer cut off the
# 111s member -- which was working. 150s covers that spread.
#
# NOT turned into a floor measured from the fan-out's start, which was the
# first attempt here. That would have made every turn with one slow member
# wait the floor out, and test_a_dead_member_no_longer_costs_the_whole_budget
# exists because a 297s turn was reported as broken. Raising the grace buys the
# slow members room without reversing that trade.
_SWARM_STRAGGLER_GRACE = 150

# A VALID TEXT FINAL ANSWER ENDS THE RACE TOO. The grace above used to start
# only on a tool call, "because the CLI cannot execute prose" -- but a tool turn
# is every turn a CLI sends (Claude Code / opencode / codex attach their tool
# schema to a plain question), and for a question the text IS the answer.
# MEASURED 2026-09-27, Claude Code `-p "What is N plus 1?" --model multi`: the
# members answered the number in seconds, none called a tool (correctly), and
# every fan-out waited out the whole 360 s deadline -- past the client's ~300 s
# stream header timeout, so Claude Code retried and the SAME fan-out ran seven
# times back to back (1753 s, killed by hand).
#
# So a member whose text passed every check in _run (not a refusal, not an
# announcement, not a typed tool call, answer_gate "ok") starts the same
# _SWARM_STRAGGLER_GRACE a tool call does, and once MOST of the members still
# in the race have answered in text -- the turn is a question, not an action --
# the fan-out settles within the trivial-turn budget measured from its start
# (_SWARM_TEXT_SETTLE), or at once if that is already past. A tool call that
# lands inside the window still wins (acted beats answered, below).
_SWARM_TEXT_SETTLE = 25          # = _TRIVIAL_HOP_BUDGET, the normal trivial budget

# A CHECKED TOOL CALL SETTLES THE RACE SHORT. MEASURED 2026-09-27 on the
# owner's OpenCode /agent session (quality swarm, e021e26): every tool turn
# ended 200 on an nvidia member's tool call and still took ~137-145 s, because
# the 150 s grace above kept the race open for members that were going to fail
# anyway (g4f 524/504, dahl 429, a 400). In one logged turn the winner's reply
# was in hand ~85 s in and the turn ended ~55 s later.
#
# So once a member has made a VALID tool call (_swarm_tool_calls_valid: named,
# offered, JSON-object arguments) the race ends after a SHORT grace that follows
# the winner's own latency -- _SWARM_TOOL_SETTLE_FACTOR of it, clamped to
# [MIN, MAX] -- and never longer than _SWARM_STRAGGLER_GRACE. A fast answer gets
# 15 s for a second opinion, a slow one 25 s. An invalid tool call keeps the
# long grace: it may still lose to a valid one.
_SWARM_TOOL_SETTLE_MIN = 15
_SWARM_TOOL_SETTLE_MAX = 25
_SWARM_TOOL_SETTLE_FACTOR = 0.5

# A STREAMED fan-out holds the client's response headers until it finishes,
# and every streaming CLI gives up on headers at ~300 s (see
# LONG_DEADLINE_STREAM_MAX). A fan-out that outlives that is not merely slow:
# the client never sees its answer and RETRIES, re-running the whole fan-out
# (the seven back-to-back runs above). A stream's fan-out therefore stops at
# this bound, and the single-model fallback after an empty fan-out shares the
# same request clock (started at the fan-out, see _swarm_tool_result), so the
# whole turn stays under the client's limit.
_SWARM_TOOL_STREAM_DEADLINE = 180


def _dispatch_chat_with_deadline(pid, payload, deadline=None):
    """_dispatch_chat(..., stream=False) bounded by an OVERALL deadline.
    Returns (resp, exc): resp is None on deadline or failure, exc is the
    raised exception (None on deadline). Never raises."""
    if deadline is None:
        deadline = _SWARM_HOP_DEADLINE
    box = {}
    # A fresh thread starts with an EMPTY context: carry the pipeline's mode
    # across, so nothing below this hop can fall back to the global mode.
    mode = _PIPELINE_MODE.get()

    def _call():
        if mode is not None:
            _PIPELINE_MODE.set(mode)
        try:
            box["resp"] = _dispatch_chat(pid, payload, False)
        except (requests.RequestException, RuntimeError) as exc:
            box["exc"] = exc

    # _carry_usage_source: the worker thread has neither the caller's
    # thread-local label nor its request, so its quota hit would otherwise be
    # filed as "background" instead of "swarm" / the calling CLI.
    hop = clientgone.child("stage-hop")
    t = threading.Thread(target=clientgone.run_as,
                         args=(hop, _carry_usage_source(_call)), daemon=True)
    t.start()
    clientgone.join(t, deadline)    # returns early once the client left
    if t.is_alive():
        hop.cancel("stage hop deadline")   # cut the hung call, do not leak it
        return None, None            # hung hop — abandon and walk the chain on
    return box.get("resp"), box.get("exc")


def _crew_name_for(model):
    """None for a plain swarm id; otherwise the crew the id selects —
    bare "crew" -> "auto" (crews.detect_crew picks from the request text),
    "crew-code" / "crew/code" -> "code"."""
    m = (model or "").strip().lower()
    if m in ("crew", "multi"):
        # "multi" is the fourth quality tier. In the /agent page it spawns real
        # agent sessions that work the message in phases; a stateless CLI turn
        # cannot do that (the CLI IS the agent, and a /v1 call carries no
        # project folder to run in), so from a CLI it maps to the crew phase
        # pipeline -- plan, execute, review across several models -- which is
        # the same "work it in phases" shape and is safe to run per turn.
        return "auto"
    if m.startswith("crew-"):
        return m[len("crew-"):]
    if m.startswith("crew/"):
        return m[len("crew/"):]
    return None


def _is_swarm_model(model):
    m = (model or "").strip().lower()
    if m in _SWARM_IDS or m.startswith("swarm/"):
        return True
    # "multi" (the fourth tier) runs through the same pipeline path; _crew_name_for
    # maps it to the crew phase pipeline. Kept out of _SWARM_IDS on purpose so it
    # is listed once as a TIER, not twice (and not labelled a Pipeline).
    if m == "multi":
        return True
    if m in crews.CREW_IDS:
        return True
    return m.startswith("crew/") and ("crew-" + m[len("crew/"):]) in crews.CREW_IDS


_DISTINCT_WIDEN_BAND = 4.0     # at most this far below the best, only when needed


def _distinct_models_on():
    """Flag `swarm_distinct_models` (default ON): concurrent swarm/crew workers
    of one run open on different model identities."""
    try:
        return bool(config.get_flag("swarm_distinct_models", True))
    except Exception:                                            # noqa: BLE001
        return True


def _distinct_first(chain, ledger, exclude_pids=()):
    """(chain, reserved): `chain` with the best candidate whose model identity
    no other worker of this run holds moved to the FRONT, and that pair
    reserved in `ledger`. A candidate must sit within _AUTO_TOP_BAND of the
    best benchmark score (widened to _DISTINCT_WIDEN_BAND only when the
    narrow band holds no unused identity), is never a last-resort family and
    never a provider in `exclude_pids`. Preference: an unused identity, then
    an unused family, then an unused provider; ties keep chain order, so the
    best model still wins whenever it is free. Nothing unused = the chain
    untouched (the pair at its head is reserved). Provider and model are
    never excluded, only re-ordered. Never raises."""
    chain = list(chain or ())
    if not chain:
        return chain, None
    try:
        with ledger.lock:
            used = list(ledger._used)           # the reservation is made under this lock
            used_pairs = [u.split("/", 1) for u in used if "/" in u]
            used_ids = {_normalize_model_identity(m) for _p, m in used_pairs}
            used_pids = {p for p, _m in used_pairs}
            fam = _verify_family() or (lambda m: _normalize_model_identity(m))
            used_fams = set()
            for _p, m in used_pairs:
                try:
                    used_fams.add(fam(m))
                except Exception:                                # noqa: BLE001
                    pass
            scored = [(_benchmark_score(e[0], e[1]), e) for e in chain]
            cand = [(sc, e) for sc, e in scored
                    if not _is_low_quality(e[1])
                    and not (exclude_pids and e[0] in exclude_pids)]
            pick = None
            if cand:
                best = max(sc for sc, _e in cand)
                for band in (_AUTO_TOP_BAND, _DISTINCT_WIDEN_BAND):
                    best_key, best_i = None, None
                    for i, (sc, e) in enumerate(cand):
                        if sc < best - band:
                            continue
                        if _normalize_model_identity(e[1]) in used_ids:
                            continue
                        try:
                            f = fam(e[1])
                        except Exception:                        # noqa: BLE001
                            f = _normalize_model_identity(e[1])
                        key = (f not in used_fams, e[0] not in used_pids, -i)
                        if best_key is None or key > best_key:
                            best_key, best_i = key, i
                    if best_i is not None:
                        pick = cand[best_i][1]
                        break
            if pick is None:
                head = next((e for e in chain if not (exclude_pids and e[0] in exclude_pids)),
                            chain[0])
                ledger._used.append("%s/%s" % (head[0], head[1]))
                return chain, (head[0], head[1])
            ledger._used.append("%s/%s" % (pick[0], pick[1]))
            rest = [e for e in chain if e is not pick]
            return [pick] + rest, (pick[0], pick[1])
    except Exception:                                            # noqa: BLE001
        return chain, None


@_usage_source_as("swarm")
def _swarm_dispatch(messages, max_tokens, exclude_pids=(), fast=False, avoid_families=(),
                    ledger=None):
    """One stage of the pipeline, routed and executed through the SAME chain
    every other request uses (so fallback, key rotation, quota accounting and
    the activity trail all behave identically). Returns (text, 'pid/model');
    never raises — an empty text tells swarm.py that stage failed.

    `fast`: the FASTEST capable models instead of the strongest -- the
    stage is racing the post-cap grace window (see _swarm_fast_dispatch).

    `avoid_families`: model families (verify.family) this stage should not
    be written by -- e.g. a reviewer of the family that wrote the draft. Their
    candidates go to the BACK of the stage chain (_avoid_families_last):
    never excluded, never a failure, a no-op without the verify module.

    `ledger` (swarm.RunLedger, a WORKER call of a run with distinct models
    on): the stage chain is re-ordered so this worker opens on a model
    identity no other worker of the run has (_distinct_first), and the pair
    it uses is reserved in the ledger. None = the chain exactly as built."""
    try:
        est = _est_tokens(messages)
        # force_difficulty="hard": every swarm stage is creation work and must
        # take the strongest model, whatever the text alone would classify as.
        pid, model, _d = _route_by_difficulty(messages, max_tokens, est,
                                              require_tools=False,
                                              force_difficulty="hard")
        if not pid:
            return "", None
        best_partial, best_partial_who = "", None
        # CAPPED. Each hop now gets _SWARM_HOP_DEADLINE (300s), so an uncapped
        # walk down a twelve-model chain is an hour for one stage -- and a crew
        # is five stages. Three hops is two fallbacks, which is what the chain
        # is for; past that the stage is not going to be rescued by a fourth.
        _stage_chain = _build_chain(pid, model, est)
        if fast:
            # Capable (the strong end of the chain), then quickest first.
            _stage_chain = sorted(_stage_chain[:_SWARM_FAST_POOL],
                                  key=lambda e: _latency_rank(e[0], e[1]))
        if avoid_families:
            _stage_chain = _avoid_families_last(_stage_chain, avoid_families)
        _reserved = None
        _use_ledger = ledger is not None and not fast and _distinct_models_on()
        if _use_ledger:
            _stage_chain, _reserved = _distinct_first(_stage_chain, ledger, exclude_pids)
        for hop_pid, hop_model in _stage_chain[:_SWARM_STAGE_MAX_HOPS]:
            if _client_gone():
                break        # the client left: the stage ends empty, at once
            if exclude_pids and hop_pid in exclude_pids:
                continue     # reviewer must not be the provider that wrote it
            if _use_ledger and _reserved != (hop_pid, hop_model):
                # A hop that failed gives its reservation back to the run.
                try:
                    if _reserved is not None:
                        ledger.release(*_reserved)
                    ledger.reserve(hop_pid, hop_model)
                except Exception:                                # noqa: BLE001
                    pass
                _reserved = (hop_pid, hop_model)
            # THE PIPELINE'S OUTER BOUND (see _pipeline_outer_bound): a stage
            # still in flight when the run's own cap passes may finish, but it
            # may not start a hop the run can no longer afford.
            _hop_deadline = _SWARM_FAST_HOP_DEADLINE if fast else _SWARM_HOP_DEADLINE
            _outer_left = _pipeline_time_left()
            if _outer_left is not None:
                if _outer_left <= 1:
                    break
                _hop_deadline = min(_hop_deadline, _outer_left)
            # Bounded by the hop's own output cap when one was learned: a
            # synthesis now asks for up to swarm.SYNTH_MAX_CAP, which a model
            # capped lower would refuse outright.
            _hop_max = max_tokens
            _ocap = _model_output_cap(hop_pid, hop_model)
            if _ocap and isinstance(_hop_max, int) and _hop_max > _ocap:
                _hop_max = _ocap
            payload = {"model": hop_model, "stream": False,
                       "max_tokens": _hop_max, "messages": messages,
                       "_no_craft": True}   # stripped in _upstream_chat
            resp, hop_exc = _dispatch_chat_with_deadline(hop_pid, payload,
                                                         _hop_deadline)
            if resp is None:         # hung hop (deadline) or a failed one
                _record_outcome(hop_pid, hop_model, False)
                continue
            try:
                if resp.status_code != 200:
                    _record_outcome(hop_pid, hop_model, False)
                    continue
                data = resp.json() or {}
            except ValueError:
                continue
            finally:
                try:
                    resp.close()
                except Exception:                                # noqa: BLE001
                    pass
            # Degeneration check FIRST: a junk loop usually runs to the cap, so
            # left alone it would be filed as a mere truncation below. Salvage
            # rewrites the message (and its "length" finish) in place.
            gate = _answer_gate(data, payload, False, hop=(hop_pid, hop_model))
            if gate == "junk":
                _record_outcome(hop_pid, hop_model, False, junk=True)
                continue
            choice = (data.get("choices") or [{}])[0]
            text = ((choice.get("message") or {}).get("content") or "").strip()
            if text and choice.get("finish_reason") == "length":
                # Truncated by the PROVIDER's completion cap (observed live:
                # kilocode/hy3 cut a synthesis mid-attribute, shipping broken
                # HTML). Walking the chain costs one hop; a cut-off artefact is
                # what the user receives otherwise. Keep the longest truncation
                # as the stage result if EVERY hop truncates.
                if len(text) > len(best_partial):
                    best_partial = text
                    best_partial_who = "%s/%s" % (hop_pid, hop_model)
                continue
            if text and _is_upstream_nonanswer(text):
                # A relay's error page delivered as a 200 (see
                # _chat_json_nonanswer). Without this a swarm stage happily
                # synthesises on top of "The model does not exist in
                # https://api.airforce" as if it were real stage output.
                _note_nonanswer(hop_pid, hop_model)
                continue
            if text:
                # Same success hook as every other endpoint: usage accounting
                # AND the reliability record, so a stage's healthy hop is what
                # the next stage's chain prefers (and a hung hop sinks).
                _record_chat_usage(hop_pid, hop_model, data, est, ok=gate == "ok")
                _act_pick(hop_pid, hop_model)
                return text, "%s/%s" % (hop_pid, hop_model)
        if best_partial:
            return best_partial, best_partial_who
    except Exception:                                            # noqa: BLE001
        _log.debug("[swarm] stage failed", exc_info=True)
    return "", None


# The fast finish picks the quickest of the chain's strongest few.
_SWARM_FAST_POOL = 8


def _swarm_fast_dispatch(messages, max_tokens, exclude_pids=(), avoid_families=()):
    """swarm.run's `fast_dispatch`: finishes what the wall clock cut off,
    inside the grace window, on the quickest capable models (short hops)."""
    if avoid_families:
        return _swarm_dispatch(messages, max_tokens, exclude_pids, fast=True,
                               avoid_families=avoid_families)
    return _swarm_dispatch(messages, max_tokens, exclude_pids, fast=True)


# How many distinct models attempt a tool-carrying swarm turn in parallel.
# Each one is a full model call, so this multiplies the cost of every turn --
# 3 is enough for a real best-of, and small enough that a free tier survives a
# long agent run.
# ASKED 2026-08-31: "he can use more then 3 agents in the swarm". Five by
# default, settable per install. What makes a bigger swarm safe rather than
# reckless is the budget check in _swarm_rank -- more slots on a drained
# provider would just finish it off faster.
_SWARM_TOOL_FANOUT = 5
_SWARM_FANOUT_MAX = 8           # past this the quota cost outruns the benefit


# THE ORCHESTRATOR DECIDES HOW MANY, between these.
#
# REQUESTED: "in swarm agents I want 4 different best models, or 5 maximum at
# the same time, or 3, or just 2 -- depending on the orchestrator."
#
# A fixed five was wrong in both directions. On a one-line question it spends
# five models' quota to agree with itself; on a hard build with only three
# genuinely different models alive it asks for five and fills the last two with
# whatever is left, which is how a fan-out ends up running the same weights
# twice (see _swarm_rank's identity spread).
_SWARM_FANOUT_MIN = 2           # below this it is not a swarm, it is a model
_SWARM_FANOUT_SOFT_MAX = 5      # what the orchestrator may choose on its own


def _swarm_fanout(candidates=None, difficulty=None):
    """How many models answer one swarm turn: 2 to 5, chosen per turn.

    An explicit `swarm_fanout` setting still wins outright -- someone who typed
    a number meant it. Left unset, two things decide:

      * HOW MANY DISTINCT MODELS ARE ACTUALLY THERE. `candidates` has already
        been de-duplicated by identity, so four entries means four different
        models and asking for five would pad the swarm with a repeat.
      * HOW HARD THE TURN IS. "hard" earns the full width -- that is what the
        extra opinions are for. "simple" does not: a second opinion on a
        one-line answer is quota spent to agree with itself.
    Spending is NOT decided here -- _swarm_rank already demotes a drained
    provider out of its slot, and testing the budget twice bought nothing but
    bugs.

    Never below 2: one model is not a swarm, and a fan-out that quietly becomes
    a single call is worse than one that says it narrowed."""
    explicit = config.get_setting("swarm_fanout", None)
    if explicit is not None:
        try:
            return max(1, min(int(explicit), _SWARM_FANOUT_MAX))
        except (TypeError, ValueError):
            pass

    want = _SWARM_TOOL_FANOUT
    if difficulty == "simple":
        want = _SWARM_FANOUT_MIN
    elif difficulty == "medium":
        want = 3

    # NO AFFORDABILITY CHECK HERE, deliberately. _swarm_rank already splits its
    # candidates into afford/drained on _SWARM_MIN_HEADROOM and puts a drained
    # provider at the back, so a second budget test in the sizer protects
    # nothing the ranker was not already protecting -- and it cost two rounds
    # of real bugs to learn that: counting PROVIDERS punished a single strong
    # provider serving four models, and _quota_headroom answering 0 for an id
    # it has never heard of let any unrecognised provider halve the swarm.
    # Size is a question about the WORK; spending is the ranker's job.
    if candidates is not None:
        # Distinct MODELS, not rows: two providers serving one model is one
        # opinion, and the slot spent on the second is spent on nothing.
        try:
            distinct = len({_normalize_model_identity(m) for _p, m in candidates})
        except Exception:                                        # noqa: BLE001
            distinct = len(candidates)
        want = min(want, max(_SWARM_FANOUT_MIN, distinct))

    return max(1, min(want, _SWARM_FANOUT_SOFT_MAX))
# How deep into the chain to look before ranking. Bigger than the fan-out on
# purpose: with only three candidates there is nothing to choose BETWEEN, which
# is exactly how the swarm ended up filling half its slots with models that
# never answer (see _swarm_rank).
_SWARM_TOOL_CANDIDATES = 12
# Below this measured delivery rate a model is demoted out of a swarm slot.
# _reliability is Laplace smoothed and returns a flat 0.5 when unknown, so this
# only ever catches a REAL record: 0 of 3 answered is (0+1)/(3+2) = 0.2, while
# a single unlucky failure is (0+1)/(1+2) = 0.33 -- deliberately above a lone
# bad hop's reach once one success exists ((1+1)/(2+2) = 0.5).
_SWARM_MIN_RELIABILITY = 0.4
# Below this fraction of a provider's daily budget, it keeps its remaining calls
# for the single-model path rather than spending them on one slot of a fan-out.
_SWARM_MIN_HEADROOM = 0.10


# A provider needs a real record before it says anything about a model nobody
# has tried. Two failures is a bad afternoon; this many is a pattern.
_PROVIDER_PRIOR_MIN_SAMPLES = 6


def _provider_outcome_totals(pid):
    """Every recorded outcome for one provider, summed. None when it has no
    fresh record at all."""
    ok = fail = 0
    found = False
    now = time.time()
    with _outcome_lock:
        for (p, _m), rec in _outcomes.items():
            if p != pid or now - rec.get("last", 0) > _OUTCOME_TTL:
                continue
            found = True
            ok += rec.get("ok", 0)
            fail += rec.get("fail", 0)
    return {"ok": ok, "fail": fail} if found else None


def _swarm_reliability(pid, model):
    """Delivery rate for a swarm slot, with a PROVIDER-level prior behind it.

    MEASURED 2026-08-30, after ranking by _reliability alone shipped: a swarm
    turn came back 2-of-3 dead anyway, and one dead member was
    'g4f/RelayRouter:gemini-3.7-flash-free' -- an id the ledger had never seen,
    on a provider it had already measured at 0 successes in 16 tries under four
    OTHER ids. A relay fronts the same model once per backend
    ('srv_msjk...:gemini-3.6-flash', 'AnyProvider:gemini-3.6-flash',
    'RelayRouter:gemini-3.7-flash-free', ...), so every listing is a separate
    key and the hub relearns the same lesson forever, one id at a time.

    So: this exact model's own record when it has one, otherwise the provider's
    -- and a flat neutral 0.5 when neither has enough evidence to say anything.
    Deliberately SWARM-ONLY. Ordinary routing keeps judging a model purely on
    its own history, because there a bad hop costs one retry, while here it
    costs a whole slot in a fan-out that only has three."""
    own = _reliability(pid, model)
    if own != 0.5:
        return own                      # it has its own record; use it
    totals = _provider_outcome_totals(pid)
    if not totals:
        return 0.5
    ok, fail = totals["ok"], totals["fail"]
    if ok + fail < _PROVIDER_PRIOR_MIN_SAMPLES:
        return 0.5
    return (ok + 1.0) / (ok + fail + 2.0)


def _swarm_has_record(pid, model):
    """Whether there is real evidence about this (pid, model), either its own or
    its provider's.

    _swarm_reliability returns a flat 0.5 for "no idea", which is the right
    NUMBER -- an unmeasured model must not be judged -- but it makes an untried
    model indistinguishable from a measured, mediocre one at ranking time. For
    a fallback chain that hardly matters: an unknown that fails costs one retry.
    For a swarm it costs a whole slot out of five, and the slot is the scarce
    thing."""
    if _reliability(pid, model) != 0.5:
        return True
    totals = _provider_outcome_totals(pid)
    if not totals:
        return False
    return (totals["ok"] + totals["fail"]) >= _PROVIDER_PRIOR_MIN_SAMPLES


def _swarm_rank(cands, difficulty=None):
    """Order swarm candidates by what actually DELIVERS, and push the ones with
    a real record of not answering to the back.

    _build_chain hands its entries back in raw-benchmark order. That is right
    for a FALLBACK chain -- try the best, drop to the next when it fails -- and
    wrong for a swarm, where every member runs at once and one that will not
    answer is pure waste. Hops 2 and 3 of a fallback chain are, by construction,
    the entries the hub already ranks lower and trusts less.

    MEASURED 2026-08-30 over 24 real swarm slots: 12 came back "no answer", and
    not evenly -- g4f went 0-for-3 and nvidia 4-for-11 while google and glm
    answered 8 of 9. The hub was already recording that (_record_outcome on
    every hop, read back by _reliability); the swarm just never asked.

    Two orderings, in this order:
      1. models with a real record of failing go last (never dropped outright --
         a smaller swarm is worse than a member that might not answer, and the
         fan-out is the whole point);
      2. within that, _agentic_score decides -- the same key agentic routing
         already uses, so strength still wins between two healthy models.
    Then providers are spread across the slots, because one provider having a
    bad minute must not take the entire swarm down with it."""
    if not cands:
        return []
    # Sized from THIS turn's candidates and difficulty, not a constant.
    fanout = _swarm_fanout(cands, difficulty)
    def _rank_score(pm):
        return _agentic_score((_benchmark_score(pm[0], pm[1]), pm[0], pm[1]))
    ranked = sorted(cands, reverse=True, key=_rank_score)
    # The bandit breaks near-ties only: re-orders the models within
    # _AUTO_TOP_BAND of the best, never across a bigger gap (_nudge_in_band).
    ranked = _nudge_in_band(ranked, _TASK_KIND_CV.get()
                            or _task_kind(difficulty or "hard", True, 0),
                            _rank_score)
    # THREE tiers, not two. Splitting on the reliability number alone put
    # "measured, delivers" and "never tried" in the same bucket, because an
    # unknown scores a neutral 0.5 and 0.5 >= the health bar. So an untried
    # model could take a slot ahead of one with a measured record of answering,
    # and untried models are where "no answer" comes from.
    #
    # ASKED 2026-09-04: "why some models have no answer in swarm ... can this be
    # fixed". This is the half that can: the hub was already recording who
    # delivers (_record_outcome on every hop), and the swarm was reading the
    # score without asking whether there was any evidence behind it.
    #
    # Unknowns are demoted, never dropped -- a model has to get its first slot
    # somewhere, or nothing new is ever measured and the ranking freezes around
    # whatever happened to be tried first.
    proven, unknown, weak = [], [], []
    for pm in ranked:
        if _swarm_reliability(pm[0], pm[1]) < _SWARM_MIN_RELIABILITY:
            weak.append(pm)
        elif _swarm_has_record(pm[0], pm[1]):
            proven.append(pm)
        else:
            unknown.append(pm)
    ordered = proven + unknown + weak
    # BUDGET. Asked for directly -- "always in the range of best models to dont
    # exaust good ones quickly". A five-slot swarm aimed at one nearly-drained
    # provider finishes it off in a single turn, and it is precisely the
    # providers carrying the best models that are worth protecting. Same signal
    # the single-model router already uses (_quota_headroom); applied only when
    # there is somewhere else to go, because refusing to answer is worse than
    # spending the last of a budget.
    # DEMOTED, not dropped: a drained provider goes to the back of the queue and
    # is used only if there are not enough others to fill the slots. An
    # all-or-nothing filter was tried first and was worse -- with four healthy
    # candidates and a fan-out of five it gave up and let the drained provider
    # take TWO slots, which is the exact outcome this exists to prevent.
    afford = [pm for pm in ordered if _quota_headroom(pm[0]) > _SWARM_MIN_HEADROOM]
    drained = [pm for pm in ordered if pm not in afford]
    ordered = afford + drained
    # JUNK BENCH (see _junk_bench_note): a benched pair takes NO slot while any
    # other candidate exists. Not merely demoted like `weak` above: the spread
    # passes below pick by unseen provider/model, so a demoted-but-present
    # benched pair would still win a slot in pass 1 whenever its provider was
    # unique -- and a member known to answer junk is worse than a repeat.
    ordered = _unbenched(ordered, 0, 1)

    # SPREAD BY MODEL, NOT ONLY BY PROVIDER.
    #
    # This de-duplicated on pm[0], the provider id -- so groq/gpt-oss-120b and
    # cerebras/gpt-oss-120b, which are two providers serving ONE model, both
    # took a slot. A best-of-five that runs the same model twice is a
    # best-of-four with a wasted slot and two answers that agree because they
    # came from the same weights.
    #
    # REPORTED: "why in swarm he use same model 2 times". Exactly that.
    #
    # Three passes, each looser than the last, so the fan-out still fills:
    #   1. a provider AND a model neither seen yet -- the real spread;
    #   2. a model not seen yet, whatever provider serves it;
    #   3. anything left, repeats allowed -- a short swarm is worse than a
    #      duplicate, which is why this pass exists at all.
    picks, used_providers, used_models = [], set(), set()

    def _take(pm):
        picks.append(pm)
        used_providers.add(pm[0])
        used_models.add(_normalize_model_identity(pm[1]))
        return len(picks) >= fanout

    for pm in ordered:
        if pm[0] in used_providers:
            continue
        if _normalize_model_identity(pm[1]) in used_models:
            continue
        if _take(pm):
            return picks
    for pm in ordered:
        if pm in picks or _normalize_model_identity(pm[1]) in used_models:
            continue
        if _take(pm):
            return picks
    for pm in ordered:
        if pm not in picks:
            picks.append(pm)
            if len(picks) >= fanout:
                break
    return picks


# FAN-OUT MEMBER HEALTH. MEASURED 2026-09-27 (owner's OpenCode /agent session,
# quality swarm, e021e26): of five members per tool turn, four came from
# providers the hub already knew were failing -- g4f glm-5.3 HTTP 524, g4f
# kimi-k3 524/504, dahl DeepSeek-V4-Flash 429, a gemini-3.8-flash listing
# HTTP 400 -- while /api/providers showed dahl, g4f and google throttled. Three
# gaps put them there:
#   1. _swarm_rank re-sorts by score, which undoes the chain's recent-failure
#      TAIL: a pair that 429'd a minute ago took a slot again on its score;
#   2. the identity de-duplication kept the FIRST listing of a model, so a
#      failing g4f listing of glm-5.3 / kimi-k3 took the slot and the healthy
#      nvidia listing of the same model was dropped as a duplicate;
#   3. the fan-out filed a member's 429/5xx/400 nowhere but _record_outcome,
#      so nothing kept it out of the NEXT turn's fan-out (the chain loops cool
#      a 5xx down with _throttle_failed_hop and remember a 429; this did not).
# So a sick pair takes NO slot while at least _SWARM_FANOUT_MIN healthy ones
# exist; below that the old selection runs unchanged (a thin swarm of doubtful
# members beats no swarm).
_SWARM_MEMBER_FAIL_TTL = 600           # = _RECENT_FAIL_TTL
_swarm_member_fail = {}                # (pid, model) -> (epoch, kind)
_swarm_member_lock = threading.Lock()


def _note_swarm_member_fail(pid, model, kind):
    """A fan-out member failed (HTTP error or exception). Never raises."""
    if not (pid and model):
        return
    if _client_gone():
        return          # the client left: not the provider's failure
    if _local_net_failed(pid, model):
        return          # this computer could not resolve the host: not the provider's failure
    try:
        with _swarm_member_lock:
            _swarm_member_fail[(pid, str(model))] = (time.time(), str(kind or "fail"))
    except Exception:                                            # noqa: BLE001
        pass


def _swarm_member_failed(pid, model):
    """The kind of this pair's fan-out failure inside _SWARM_MEMBER_FAIL_TTL,
    else None. Never raises."""
    try:
        key = (pid, str(model))
        with _swarm_member_lock:
            rec = _swarm_member_fail.get(key)
            if not rec:
                return None
            if time.time() - rec[0] > _SWARM_MEMBER_FAIL_TTL:
                _swarm_member_fail.pop(key, None)
                return None
            return rec[1]
    except Exception:                                            # noqa: BLE001
        return None


def _swarm_note_member_status(pid, model, code, race_failed=None):
    """File a fan-out member's non-200 the way the chain loops do: a 429 goes
    to _recent_hop_fail, a 5xx (502/503/504/524...) is cooled down by
    _throttle_failed_hop; every one lands in the fan-out ledger. A 429 or 5xx
    also names the PROVIDER in `race_failed`, so the running race stops
    waiting on its other members. Never raises."""
    try:
        code = int(code)
        if code == 429:
            _note_recent_hop_failure(pid, model, "429")
        elif code in (401, 403):
            # A credential / policy refusal (zenmux 403 "free tier only in
            # OpenCode", a dead key): the pair will refuse again for a while, so
            # rest it for the recent-failure TTL instead of re-dispatching to it
            # every actor hop. MEASURED 2026-10-07: zenmux/glm-4.7-flash-free
            # 403'd on repeated roles hops of one big turn.
            _note_recent_hop_failure(pid, model, "http-%d" % code)
        elif code >= 500:
            _throttle_failed_hop(pid, model)
        if (code == 429 or code in (401, 403) or code >= 500) and race_failed is not None:
            race_failed.add(pid)
        _note_swarm_member_fail(pid, model, "HTTP %d" % code)
    except Exception:                                            # noqa: BLE001
        pass


def _swarm_note_member_exc(pid, model, exc):
    """File a fan-out member that raised: a timeout goes to _recent_hop_fail, a
    relay that could not be reached is a tool-turn strike (as in _ChainClock);
    both land in the fan-out ledger. Never raises."""
    try:
        if isinstance(exc, requests.exceptions.Timeout):
            _note_recent_hop_failure(pid, model, "timeout")
        elif isinstance(exc, requests.exceptions.ConnectionError):
            _note_relay_tool_fail(pid, model)       # no-op for a non-relay pid
        _note_swarm_member_fail(pid, model, type(exc).__name__)
    except Exception:                                            # noqa: BLE001
        pass


def _swarm_member_sick(pid, model):
    """Why (pid, model) must not take a tool fan-out slot right now, or None.
    Provider parked / throttled / exhausted, the model throttled, dead, not
    offered or junk-benched, a recent 429 or stall (_recent_hop_fail), a relay
    server struck on tool turns, or a failure in a recent fan-out. Local state
    only; fail-open (an error is None)."""
    try:
        if _is_provider_dead(pid):
            return "provider parked"
        if quota.is_exhausted(pid):
            return "provider throttled/exhausted"
        if quota.is_model_exhausted(pid, model):
            return "model throttled/exhausted"
        if _is_model_skipped(pid, model):
            return "model dead or not offered"
        if _is_pair_benched(pid, model):
            return "junk-benched"
        kind = _recent_hop_failure(pid, model)
        if kind:
            return "recent %s" % kind
        if _relay_tool_sick(pid, model):
            return "relay server struck on tool turns"
        kind = _swarm_member_failed(pid, model)
        if kind:
            return "recent fan-out %s" % kind
    except Exception:                                            # noqa: BLE001
        return None
    return None


def _swarm_tool_candidates(chain):
    """(candidates, skipped) for a tool fan-out from a _build_chain result.

    Candidates are distinct MODELS (one listing each), subscriptions left out,
    at most _SWARM_TOOL_CANDIDATES. Sick pairs (_swarm_member_sick) are
    excluded BEFORE the identity de-duplication, so a healthy listing of the
    same model on another provider takes the place of a failing one. With
    fewer than _SWARM_FANOUT_MIN healthy candidates the old selection is
    returned unchanged (first listing per model) and `skipped` is empty.
    `skipped` is [(pid, model, reason)]."""
    healthy, legacy, skipped = [], [], []
    seen_h, seen_l = set(), set()
    for hop_pid, hop_model in chain:
        # A LOCAL SUBSCRIPTION CANNOT EMIT A TOOL CALL (see _swarm_tool_result).
        if _is_sub(hop_pid):
            continue
        ident = _normalize_model_identity(hop_model)
        if ident not in seen_l and len(legacy) < _SWARM_TOOL_CANDIDATES:
            seen_l.add(ident)
            legacy.append((hop_pid, hop_model))
        why = _swarm_member_sick(hop_pid, hop_model)
        if why:
            skipped.append((hop_pid, hop_model, why))
            continue
        if ident in seen_h or len(healthy) >= _SWARM_TOOL_CANDIDATES:
            continue
        seen_h.add(ident)
        healthy.append((hop_pid, hop_model))
    if len(healthy) >= _SWARM_FANOUT_MIN:
        return healthy, skipped
    return legacy, []


def _swarm_tool_calls_valid(msg, tools):
    """True when every tool call in `msg` is one the CLI can run: a non-empty
    name among the offered tools (when every offered tool has a name) and
    arguments that are empty or a JSON object. Never raises."""
    try:
        calls = (msg or {}).get("tool_calls") or []
        if not calls:
            return False
        tool_list = [t for t in (tools or []) if isinstance(t, dict)]
        names = set(tool_rescue.tool_names(tool_list))
        check_names = bool(names) and len(names) >= len(tool_list)
        for tc in calls:
            if not isinstance(tc, dict):
                return False
            fn = tc.get("function") if isinstance(tc.get("function"), dict) else {}
            name = str(fn.get("name") or "").strip()
            if not name or (check_names and name not in names):
                return False
            args = fn.get("arguments")
            if args is None or isinstance(args, dict):
                continue
            if not isinstance(args, str):
                return False
            if not args.strip():
                continue
            if not isinstance(json.loads(args), dict):
                return False
        return True
    except Exception:                                            # noqa: BLE001
        return False


def _swarm_tool_grace(latency):
    """Seconds to keep waiting after the first VALID tool call, which landed
    `latency` seconds into the fan-out (see _SWARM_TOOL_SETTLE_MIN)."""
    try:
        g_ = _SWARM_TOOL_SETTLE_FACTOR * max(0.0, float(latency))
    except (TypeError, ValueError):
        g_ = 0.0
    g_ = max(float(_SWARM_TOOL_SETTLE_MIN), min(float(_SWARM_TOOL_SETTLE_MAX), g_))
    return min(g_, float(_SWARM_STRAGGLER_GRACE))


def _tool_turn_race_on():
    """Flag `tool_turn_race` (default OFF): True restores the old best-of-N
    fan-out (_swarm_tool_result) for every swarm/crew*/multi tool turn; off,
    the turn runs as ROLES (_tool_turn_roles). Fails to the default."""
    try:
        return bool(config.get_flag("tool_turn_race", False))
    except Exception:                                            # noqa: BLE001
        return False


@_usage_source_as("swarm")
def _swarm_tool_result(body):
    """Swarm for a TOOL-CALLING turn: run the same request on several strong
    models AT ONCE and return the best single response.

    Since 2026-10-04 only with flag `tool_turn_race`; by default the turn runs
    as ROLES, same contract (see _tool_turn_roles).

    The multi-phase pipeline (planner -> workers -> reviewer) cannot serve a CLI
    agent: it emits finished prose, never tool calls, so a coding agent driven
    by it would write no files at all. This is the shape of "several models work
    on it together" that actually survives an agent loop -- every candidate
    answers the real request with the real tools, so whatever wins is a normal,
    complete response the CLI can execute.

    Returns (data, headers) -- `data` is an ordinary OpenAI chat completion --
    or None when nothing usable came back, so the caller can fall through to
    ordinary single-model routing. Never raises.

    PROTOCOL-INDEPENDENT on purpose. This used to return a finished Flask
    response, which welded the whole fan-out to /v1/chat/completions -- and
    that is not the endpoint the CLIs use (codex speaks /v1/responses, claude
    /v1/messages), so the mode 404'd on a model literally named "swarm" for two
    of the three. Every protocol now runs this same race and translates the
    winner into its own shape.
    """
    if not _tool_turn_race_on():
        return _tool_turn_roles(body)
    messages = body.get("messages") or []
    # OPENING turn of a swarm session: ask for the phased plan up front. The
    # prose pipeline plans this way on its own (swarm._waves runs independent
    # phases concurrently), but a CLI drives its own loop, so it has to be
    # asked. Opening turn only -- re-sending it mid-task invites replanning
    # work that is already done. Done HERE because this is the last place the
    # REQUESTED model is still "swarm"; by the time the brief injector runs,
    # payload["model"] is the hop model and the mode is no longer visible.
    users = [m for m in messages if isinstance(m, dict) and m.get("role") == "user"]
    mid_loop = (len(users) != 1
                or any(isinstance(m, dict)
                       and (m.get("role") == "tool" or m.get("tool_calls"))
                       for m in messages))
    # The phased plan used to be injected HERE, and only here -- which meant it
    # existed in swarm mode alone while Normal and Max got none. It now ships
    # from craft.system_message() for every tool-carrying opening turn, and a
    # swarm tool turn goes through that same injector (it carries `tools` and
    # never sets _no_craft), so adding it again here would just buy a second
    # copy in the one mode that pays for its context three times over.
    est = _est_tokens(messages, body.get("tools"))
    pid, resolved, _d = _route_by_difficulty(messages, body.get("max_tokens"), est,
                                             require_tools=True,
                                             force_difficulty="hard")
    if not pid:
        return None
    # Distinct MODELS, not distinct listings: three copies of one model relayed
    # by one provider is not a second opinion, it is the same opinion three
    # times at three times the cost.
    #
    # A LOCAL SUBSCRIPTION CANNOT EMIT A TOOL CALL, so it can never win a
    # fan-out whose whole purpose is to produce one. _subscription_chat
    # reads only payload["messages"] and never payload["tools"], and its
    # response shim is a two-key {"role","content"} literal with no
    # tool_calls key at all -- structural, not a model failing today.
    #
    # MEASURED over three live fan-outs: sub-claude took a member slot every
    # time and returned the same prose every time -- "Blocked: write
    # permission not granted for <an AppData path>" -- at ~21s against 3-7s
    # for the models that answered. One slot in five, spent on a certainty.
    #
    # Skipped HERE rather than in _build_chain: `require_tools` is
    # bool(body["tools"]), which is true for every Claude Code, opencode and
    # codex turn INCLUDING read-only questions the CLI attaches its schema
    # to. Gating the chain own sub append on it would turn those into 503s
    # exactly when the free fleet is empty and the paid subscription is the
    # only thing left. The chain keeps its last resort; the swarm, which
    # needs a tool call specifically, stops spending a slot on one.
    #
    # Sick members (throttled / parked / recently failed / struck relay /
    # benched / not offered) take no slot -- see _swarm_member_sick. Both the
    # de-duplication and that filter live in _swarm_tool_candidates.
    cands, _skipped = _swarm_tool_candidates(
        _build_chain(pid, resolved, est, require_tools=True, messages=messages))
    if _skipped:
        _log.info("[swarm-tools] %d unhealthy member(s) left out: %s", len(_skipped),
                  "; ".join("%s/%s (%s)" % s for s in _skipped[:8]))
    # Rank by delivery, don't just take the top of the chain -- see _swarm_rank.
    #
    # The ROUTER above forces "hard" on purpose: a tool turn needs a model that
    # can actually drive tools, whatever the text looks like. How many opinions
    # to buy is a different question, so the fan-out is sized from the turn's
    # REAL difficulty -- a one-line ask that happens to carry a tools array is
    # not worth five models agreeing with each other.
    try:
        _real = _classify_difficulty(messages, body.get("max_tokens"))
    except Exception:                                            # noqa: BLE001
        _real = None
    _kt = _TASK_KIND_CV.set(_task_kind(_real or "hard", True, est))
    try:
        picks = _swarm_rank(cands, _real)
    finally:
        _TASK_KIND_CV.reset(_kt)
    if not picks:
        return None

    # Set once the fan-out has an answer and has stopped waiting. Members still
    # in flight after that are ABANDONED, and an abandoned member must not be
    # filed as a failure.
    #
    # REPORTED 2026-09-05: "glm 5.3 and qwen 3.8 dont work anymore, why he dont
    # use best models available first". groq/qwen3.8-27b had fallen from 0.72 to
    # 0.41 across this session, which then demoted it in the chain. A good part
    # of that drop was self-inflicted: every member the grace cut off was
    # recorded as not delivering, so the more impatient the swarm got, the worse
    # its own best models looked -- a ledger measuring the hub's patience and
    # calling it the model's reliability.
    moved_on = [False]

    def _run(pair):
        hop_pid, hop_model = pair
        # WHY a member did not answer. Six different outcomes reached the same
        # `return None`, and the summary line only ever counted them -- "0/5
        # models answered" with nothing to say which five or what went wrong.
        # Asked to explain a run of empty fan-outs, the log could not, and the
        # answer took an instrumented re-run against live providers to recover.
        # Recording the reason costs one dict entry and makes the same question
        # answerable from the log next time.
        def _why(reason):
            _member_why[(hop_pid, hop_model)] = reason
            return None
        payload = dict(body)
        payload["model"] = hop_model
        payload["stream"] = False        # fan-out cannot stream; re-emitted below
        resp, hop_exc = _dispatch_chat_with_deadline(hop_pid, payload,
                                                     _SWARM_TOOL_HOP_DEADLINE)
        if resp is None:
            if not moved_on[0]:
                # resp is None for TWO different things: a hop that genuinely
                # failed (hop_exc set) and one the hub stopped waiting for
                # (hop_exc None -- _dispatch_chat_with_deadline returns
                # (None, None) when the worker is still alive at the deadline).
                # Only the first is the model's fault. Dropping the penalty for
                # both, as a first pass here did, also stopped recording real
                # failures -- caught by test_a_real_failure_is_still_recorded.
                if hop_exc is not None:
                    _record_outcome(hop_pid, hop_model, False)
                    _swarm_note_member_exc(hop_pid, hop_model, hop_exc)
                # A pure deadline files nothing: it is indistinguishable
                # from impatience, and counting it turned slow-but-working
                # models into "unreliable" ones, dropping them below
                # _SWARM_MIN_RELIABILITY until they stopped being picked at all
                # -- a ledger measuring the hub's patience and calling it the
                # model's record.
                return _why("no response before the %ds deadline"
                            % _SWARM_TOOL_HOP_DEADLINE)
            return _why("abandoned: another member had already answered")
        try:
            if resp.status_code != 200:
                _record_outcome(hop_pid, hop_model, False)
                _swarm_note_member_status(hop_pid, hop_model, resp.status_code,
                                          _race_failed_pids)
                return _why("HTTP %d" % resp.status_code)
            data = resp.json() or {}
        except (ValueError, AttributeError):
            return _why("200 but the body was not usable JSON")
        finally:
            try:
                resp.close()
            except Exception:                                    # noqa: BLE001
                pass
        msg = ((data.get("choices") or [{}])[0].get("message") or {})
        if not (msg.get("tool_calls") or (msg.get("content") or "").strip()):
            _record_outcome(hop_pid, hop_model, False)
            return _why("200 with an empty message")
        # A member that TYPED its tool call instead of emitting one looks like
        # ordinary prose, so without this it competes as a candidate answer --
        # and if it wins, the CLI executes nothing and the build stops. That is
        # exactly the reported failure; see _looks_like_text_tool_call.
        # Same rescue as the single-model path: a member that typed a complete,
        # offered call did the work, and discarding it here would throw away a
        # usable answer in a mode that already paid for N inferences.
        if not msg.get("tool_calls") and body.get("tools"):
            if tool_rescue.rescue(data, body.get("tools")):
                msg = ((data.get("choices") or [{}])[0].get("message") or {})
        # A REFUSAL is not an answer either, and this is how the reported build
        # actually died. MEASURED 2026-09-04, 02:51:34: "1/5 models answered, 0
        # used a tool" -- the one member that replied wrote "Blocked. Every tool
        # call needs approval ... run `/permissions` and allow Write, Edit,
        # Bash(python:*)". The session was OPENCODE, which has no /permissions
        # command, no Edit tool and no Bash(...) syntax: the model invented a
        # Claude Code refusal wholesale. Nothing rejected it, so it won the slot
        # and became the whole turn's answer, and the user read it as the hub
        # denying permissions.
        #
        # _chat_json_nonanswer has treated a refusal as a non-answer on the
        # single-model path for a while; the fan-out simply never asked.
        if not msg.get("tool_calls") and (_looks_like_refusal(msg.get("content"))
                                          or _looks_like_permission_block(msg.get("content"))):
            # NOT _note_nonanswer here. That marks the model DEAD for
            # _DEAD_MODEL_TTL (6 hours) and _build_chain removes a dead model
            # from every request -- so one heuristic misfire inside a swarm
            # bans a working model fleet-wide for the rest of the day. The
            # heuristics are good enough to lose a slot over and nowhere near
            # good enough to ban over: _looks_like_announced_not_acted trips on
            # any reply under 400 characters with no question mark, and "Let me
            # check the config first." qualifies.
            _record_outcome(hop_pid, hop_model, False)
            return _why("refused: %s"
                        % " ".join((msg.get("content") or "")[:60].split()))
        if not msg.get("tool_calls") and _no_tools_claim(
                msg.get("content"), tools_offered=bool(body.get("tools")),
                prompt=_last_user_text_for_check(body),
                used_tools=_turn_used_tools(body.get("messages"))):
            # Same policy as the single-model path: lose the slot, file the
            # failure, no dead-mark.
            _record_outcome(hop_pid, hop_model, False)
            return _why("claimed it has no tools")
        if not msg.get("tool_calls") and (
                _looks_like_text_tool_call(msg.get("content"))
                or tool_rescue.has_model_markup(msg.get("content"))
                or _looks_like_announced_not_acted(msg.get("content"))):
            # MEASURED: the reported dead turn was swarm mode -- three models
            # ran, none called a tool, and the best-ranked ANNOUNCEMENT won the
            # slot, so the CLI executed nothing and the build said Finished.
            _note_nonanswer(hop_pid, hop_model)
            return _why("answered in prose without calling a tool")
        # Degenerate text (see _answer_gate): salvage keeps the member in the
        # race with its clean answer; pure junk loses the slot, never a ban.
        gate = _answer_gate(data, payload, bool(body.get("tools")),
                            hop=(hop_pid, hop_model))
        if gate == "junk":
            _record_outcome(hop_pid, hop_model, False, junk=True)
            return _why("degenerate answer (nothing salvageable)")
        msg = ((data.get("choices") or [{}])[0].get("message") or {})
        _record_chat_usage(hop_pid, hop_model, data, est, ok=gate == "ok")
        if gate == "ok" and not msg.get("tool_calls"):
            # A clean TEXT final answer: it may end the race (see
            # _SWARM_TEXT_SETTLE). A salvaged one still competes, but a reply
            # the gate had to repair does not get to cut the others short.
            _text_final.add((hop_pid, hop_model))
        if msg.get("tool_calls") and _swarm_tool_calls_valid(msg, body.get("tools")):
            # A tool call the CLI can run: it may settle the race short (see
            # _SWARM_TOOL_SETTLE_MIN).
            _valid_acted.add((hop_pid, hop_model))
        return (hop_pid, hop_model, data, msg)

    # `ex.map` waited for EVERY member, which is why a turn cost the slowest one
    # even after the answer was in hand. Collect as they finish instead, and
    # once a tool call has arrived give the rest a short grace before moving on.
    #
    # NOT a `with` block: ThreadPoolExecutor.__exit__ calls shutdown(wait=True),
    # which would join the very threads this is trying to stop waiting for and
    # undo the whole change. Abandoned members are bounded by their own hop
    # deadline and their sockets die with the provider's connection -- the same
    # trade-off _dispatch_chat_with_deadline already documents.
    results = []
    _member_why = {}
    _text_final = set()          # members whose answer is a clean TEXT final answer
    _valid_acted = set()         # members whose tool calls passed _swarm_tool_calls_valid
    _race_failed_pids = set()    # providers that answered 429/5xx in THIS race
    _started = time.monotonic()
    # A stream's fan-out must finish under the client's header timeout (see
    # _SWARM_TOOL_STREAM_DEADLINE), and the fallback after an empty fan-out
    # must not get a fresh request clock on top of it: start the request clock
    # HERE, so _begin_request_deadline in the fallback measures from now.
    _fan_limit = float(_SWARM_TOOL_HOP_DEADLINE)
    if body.get("stream"):
        _fan_limit = min(_fan_limit, float(_SWARM_TOOL_STREAM_DEADLINE))
        _begin_request_deadline()
    ex = concurrent.futures.ThreadPoolExecutor(max_workers=len(picks))
    try:
        # _pipeline_bound: members run on pool threads, where `g` -- and so the
        # category a "coding-swarm" id set -- does not exist. Captured here, at
        # fan-out start, and carried into every member.
        _member = _pipeline_bound(_carry_usage_source(_run))
        _fut_pid = {}
        _fut_pair = {}
        for pm in picks:
            _f = ex.submit(_member, pm)
            _fut_pid[_f] = pm[0]
            _fut_pair[_f] = (pm[0], pm[1])
        pending = set(_fut_pid)
        _fanout_started = time.monotonic()
        deadline = _fanout_started + _fan_limit
        # Never past a request clock that is already running (a stream starts
        # it just above): the grace below can only shorten the race.
        try:
            _req_at = getattr(g, "hub_deadline_at", None)
        except RuntimeError:                     # outside a request context
            _req_at = None
        if isinstance(_req_at, (int, float)) and _req_at > _fanout_started:
            deadline = min(deadline, _req_at)
        cutoff = deadline
        settled_empty = 0            # members that finished without a usable answer
        short_grace = False          # the valid-tool-call grace has been set
        while pending:
            remaining = cutoff - time.monotonic()
            if remaining <= 0:
                break
            if _client_gone():
                results = []               # the client left: nobody to answer
                break
            done, pending = concurrent.futures.wait(
                pending, timeout=min(remaining, 0.5),
                return_when=concurrent.futures.FIRST_COMPLETED)
            if not done:
                if time.monotonic() < cutoff:
                    continue               # a 0.5 s slice, so a cancel is seen
                break                      # nothing landed before the cutoff
            for fut in done:
                try:
                    r = fut.result()
                except Exception:                                # noqa: BLE001
                    r = None
                if r:
                    results.append(r)
                else:
                    settled_empty += 1
            acted_now = any((r[3] or {}).get("tool_calls") for r in results)
            texts = [r for r in results
                     if not (r[3] or {}).get("tool_calls")
                     and (r[0], r[1]) in _text_final]
            # Members still running on a provider that already answered 429 or
            # 5xx in this race: same account / same gateway, same fate
            # (measured: two g4f members 524'd in one race). Not waited on.
            doomed = {f for f in pending if _fut_pid.get(f) in _race_failed_pids}
            if not short_grace and any((r[0], r[1]) in _valid_acted for r in results):
                # A CHECKED tool call is in hand: short grace, adaptive to how
                # long the winner took (see _SWARM_TOOL_SETTLE_MIN).
                short_grace = True
                _now = time.monotonic()
                cutoff = min(cutoff, deadline,
                             _now + _swarm_tool_grace(_now - _fanout_started))
            elif cutoff == deadline and (acted_now or texts):
                # THE GRACE IS A FLOOR, NOT A CEILING. Measured in the note on
                # _SWARM_STRAGGLER_GRACE: members answered at 5s, 78s and 111s.
                # Starting a 90s clock at the FIRST answer put the cutoff at
                # 95s, so the 111s member -- working perfectly -- was cut off
                # and displayed as "no answer". A fast first answer is not a
                # reason to stop waiting for the rest; it is only a reason not
                # to wait forever.
                # A clean TEXT final answer starts the same grace a tool call
                # does (see _SWARM_TEXT_SETTLE).
                cutoff = min(deadline, time.monotonic() + _SWARM_STRAGGLER_GRACE)
            if texts and not acted_now:
                # MOSTLY TEXT: more than half of the members still in the race
                # (picks minus those that already failed) answered in clean
                # text and none called a tool -- the turn is a question. Settle
                # within the trivial budget from the fan-out's start.
                viable = len(picks) - settled_empty - len(doomed)
                if 2 * len(texts) > viable:
                    cutoff = min(cutoff, max(time.monotonic(),
                                             _fanout_started + _SWARM_TEXT_SETTLE))
            if results and pending and pending <= doomed:
                # An answer is in hand and everything still running is on a
                # provider that already failed this race: stop now. With NO
                # answer yet they are still waited on -- falling back would
                # re-dispatch to the same providers while these still run.
                break
    finally:
        # Members still running when the race ended were stopped by the HUB
        # (a winner was in hand, or the clock ran out) -- name that, instead of
        # the activity row's "no answer", which read as a broken model
        # (owner, 2026-10-04: "why I see some models don't answer").
        try:
            for _f in pending:
                _pr = _fut_pair.get(_f)
                if _pr and _pr not in _member_why:
                    _member_why[_pr] = (
                        "abandoned: another model answered first" if results
                        else "no answer before the time limit")
        except Exception:                                        # noqa: BLE001
            pass
        # Anything still running from here on was abandoned by US, not failed by
        # the provider -- stop counting it against the model.
        moved_on[0] = True
        ex.shutdown(wait=False, cancel_futures=True)
    if _client_gone():
        return None          # the client left: the caller replies 499 (clientgone)
    if not results:
        # LOG IT. The success line below sits after this early return, so a run
        # where NOTHING answered used to leave no trace at all -- five failing
        # turns in a row produced an empty log and a 503 with no model recorded,
        # which is the hardest possible shape to diagnose. The failing case is
        # the one worth a line.
        # The REASONS, not just the count. Also the elapsed time rather than
        # the deadline constant: the old line printed _SWARM_TOOL_HOP_DEADLINE
        # whatever had happened, so a fan-out that collapsed in two seconds was
        # reported as "in 300s" and read as five models hanging.
        _log.warning("[swarm-tools] 0/%d models answered in %.0fs -> %s",
                     len(picks), time.monotonic() - _started,
                     "; ".join("%s/%s: %s" % (p, m, _member_why.get((p, m), "no answer"))
                               for p, m in picks))
        return None

    # WINNER. A turn that needs an action is served by a model that took one:
    # prefer a response carrying tool_calls, because a model answering in prose
    # where the others reached for a tool has done strictly less of the job.
    # Within either group, the better-ranked model wins.
    acted = [r for r in results if (r[3].get("tool_calls"))]
    # ...and a tool call the CLI can run beats one it cannot (unknown tool name,
    # arguments that are not a JSON object -- _swarm_tool_calls_valid).
    pool = [r for r in acted if (r[0], r[1]) in _valid_acted] or acted or results
    hop_pid, hop_model, data, _msg = max(
        pool, key=lambda r: _benchmark_score(r[0], r[1]))
    _log.info("[swarm-tools] %d/%d models answered, %d used a tool -> %s/%s",
              len(results), len(picks), len(acted), hop_pid, hop_model)
    # Show the whole race in the activity feed, not just the survivor. The
    # existing pipeline chips already render (role, model) pairs for the prose
    # swarm, so reuse them: every model that was asked appears, labelled with
    # what it did, and the one that was actually served is marked. Without this
    # a swarm turn looks identical to an ordinary single-model turn -- three
    # models' worth of quota spent, one model's worth of evidence.
    try:
        answered = {(r[0], r[1]) for r in results}
        acted_set = {(r[0], r[1]) for r in acted}
        rows = []
        for p_id, m_id in picks:
            # "no answer" was written for anything simply ABSENT from
            # `answered` -- including members the hub abandoned itself because
            # someone else had already replied. They answered; nobody waited.
            # _member_why already records what really happened, so the row
            # reports that instead of inferring the worst from absence.
            if (p_id, m_id) == (hop_pid, hop_model):
                role = "winner"
            elif (p_id, m_id) in acted_set:
                role = "used a tool"
            elif (p_id, m_id) in answered:
                role = "answered"
            else:
                # What actually happened, from _member_why -- "abandoned:
                # another member had already answered" is not "no answer", and
                # showing it as one is what made the fan-out look like half the
                # fleet was broken.
                why = _member_why.get((p_id, m_id)) or "no answer"
                role = ("stopped: another model answered first"
                        if why.startswith("abandoned") else why[:60])
            rows.append({"role": role, "model": p_id + "/" + m_id})
        act = getattr(g, "act", None)
        if act is not None:
            with _activity_lock:
                act["crew"] = "swarm (parallel)"
                act["pipeline"] = rows
    except Exception:                                            # noqa: BLE001
        pass
    data["model"] = hop_pid + "/" + hop_model
    hdrs = _routing_headers(hop_pid, hop_model, len(picks), None)
    return data, hdrs


# --------------------------------------------------------------------------- #
# Roles instead of racing: the models of a tool turn COLLABORATE
# --------------------------------------------------------------------------- #
# MEASURED hub.log 2026-09-26..10-04 (see _swarm_tool_result): the race sent one
# tool turn to 3.72 models on average -- 4.02 upstream calls per served answer,
# 75% of member calls (2897/3857) served nothing, each resending ~100K+ prompt
# tokens -- and caused the hub's own 429s. Owner: "each model must do
# something -- collaboration, not racing." Each model now has a ROLE:
#   1. ACTOR     ONE model: the chain's head (router pick; the bandit only
#                breaks ties inside _AUTO_TOP_BAND), walked fail-fast on
#                429/5xx/empty/junk/invalid/prose-instead-of-action with the
#                same _ChainClock.walk rules as every tool chain;
#   2. BACKUP    ONE extra actor on another provider, started only after the
#                actor's MEASURED silence (_tool_hedge_delay); first valid
#                answer wins, the other call is cut (its hop token);
#   3. VERIFIER  only when verify.is_risky: a model of ANOTHER family reviews
#                the proposed step (non-streamed, <= _VERIFY_DEADLINE,
#                fail-open on any error);
#   4. CORRECTOR only on a high-severity "revise": ONE call to the best other
#                actor; its step must pass _swarm_tool_calls_valid, else the
#                original ships.
# The turn stays BUFFERED, exactly as the race was (members never streamed,
# the winner is replayed): a streaming client's first byte goes out after the
# verdict. Expected calls per turn: 1 (+1 on a stall, +1-2 on a risky step).
_TOOL_HEDGE_FLOOR = 6.0          # seconds: never hedge sooner (= _ADAPTIVE_HOP_FLOOR)
_TOOL_HEDGE_MULT = 3.5           # x the pair's measured tool-turn p50 (= _ADAPTIVE_HOP_MULT)
_TOOL_HEDGE_UNKNOWN = 45.0       # no tool-turn timing for the pair yet
_ROLE_MAX_ACTOR_HOPS = 4         # actor hops before the turn falls back to `best`
_VERIFY_DEADLINE = 25.0          # one verifier call, all in
_VERIFY_MIN_SECONDS = 4.0        # less turn time left than this: no verifier
_CORRECT_MIN_SECONDS = 15.0      # less turn time left than this: no corrector
_ROLE_LOG_NAME = "turn-roles.jsonl"
_ROLE_LOG_MAX_BYTES = 5 * 1024 * 1024
_role_log_lock = threading.Lock()


# STALLS ARE REMEMBERED (2026-10-04). An unmeasured actor's backup delay is the
# FLEET's measured tool-turn p50 x _TOOL_FLEET_MULT, clamped; only a huge
# prompt (>= _TOOL_HEDGE_HUGE_EST) still waits _TOOL_HEDGE_UNKNOWN.
_TOOL_FLEET_MULT = 2.5
_TOOL_FLEET_MIN_SAMPLES = 5
_TOOL_FLEET_CLAMP = (12.0, 30.0)
_TOOL_HEDGE_HUGE_EST = 100000
_ROLE_MIN_HOP_SECONDS = 20.0         # an actor hop never gets less of the turn
# Empty / junk 200s on a tool turn: 3 in 10 min rest the pair (even a pin).
_EMPTY_STREAK_LIMIT = 3
_EMPTY_STREAK_TTL = 600.0
_empty_200 = {}                      # (pid, model) -> [epoch, ...]
_empty_200_lock = threading.Lock()


def _note_empty_200(pid, model):
    """File one empty/junk 200 on a tool turn. Not when the client left."""
    if not (pid and model) or _client_gone():
        return
    try:
        now = time.time()
        with _empty_200_lock:
            row = [t for t in _empty_200.get((pid, model), ()) if now - t <= _EMPTY_STREAK_TTL]
            row.append(now)
            _empty_200[(pid, model)] = row[-_EMPTY_STREAK_LIMIT:]
    except Exception:                                            # noqa: BLE001
        pass


def _clear_empty_200(pid, model):
    try:
        with _empty_200_lock:
            _empty_200.pop((pid, model), None)
    except Exception:                                            # noqa: BLE001
        pass


def _empty_streak(pid, model):
    """Empty/junk 200s of this pair inside the TTL (0 when none). Never raises."""
    try:
        now = time.time()
        with _empty_200_lock:
            return len([t for t in _empty_200.get((pid, model), ())
                        if now - t <= _EMPTY_STREAK_TTL])
    except Exception:                                            # noqa: BLE001
        return 0


def _empty_resting(pid, model):
    """True while the pair is resting after _EMPTY_STREAK_LIMIT empties."""
    return _empty_streak(pid, model) >= _EMPTY_STREAK_LIMIT


def _fleet_tool_p50_ms():
    """Median over pairs with >= _TOOL_FLEET_MIN_SAMPLES tool-turn samples of
    each pair's p50, or None while no pair has that many."""
    try:
        with _outcome_lock:
            rows = [list(s) for s in _tool_ttft.values()]
        meds = sorted(_percentile(s, 50) for s in rows if len(s) >= _TOOL_FLEET_MIN_SAMPLES)
        if not meds:
            return None
        n = len(meds)
        return meds[n // 2] if n % 2 else (meds[n // 2 - 1] + meds[n // 2]) / 2.0
    except Exception:                                            # noqa: BLE001
        return None


def _tool_hedge_delay(pid, model, est=0):
    """Seconds of silence from a tool-turn actor before the backup starts:
    max(_TOOL_HEDGE_FLOOR, _TOOL_HEDGE_MULT x its tool-turn p50) from
    _tool_ttft (streamed first content on tool turns, plus every role call's
    duration -- a buffered tool call is usable only once complete). While the
    pair has fewer than _TOOL_MIN_SAMPLES: the fleet median x 2.5 clamped to
    12-30 s (30 s with no fleet data), and _TOOL_HEDGE_UNKNOWN for a request
    of _TOOL_HEDGE_HUGE_EST tokens or more."""
    try:
        with _outcome_lock:
            s = list(_tool_ttft.get((pid, model)) or [])
        if len(s) >= _TOOL_MIN_SAMPLES:
            return max(_TOOL_HEDGE_FLOOR, _TOOL_HEDGE_MULT * _percentile(s, 50) / 1000.0)
        if (est or 0) >= _TOOL_HEDGE_HUGE_EST:
            return _TOOL_HEDGE_UNKNOWN
        fleet = _fleet_tool_p50_ms()
        if fleet is None:
            return _TOOL_FLEET_CLAMP[1]
        lo, hi = _TOOL_FLEET_CLAMP
        return min(hi, max(lo, _TOOL_FLEET_MULT * fleet / 1000.0))
    except Exception:                                            # noqa: BLE001
        return _TOOL_HEDGE_UNKNOWN


def _role_log(row):
    """Append one row to state_dir()/turn-roles.jsonl (rolled to .1 past
    _ROLE_LOG_MAX_BYTES). Read offline by scripts/role_eval.py. Never raises."""
    try:
        path = os.path.join(config.state_dir(), _ROLE_LOG_NAME)
        line = json.dumps(dict(row, ts=round(time.time(), 3)), ensure_ascii=False,
                          default=str) + "\n"
        with _role_log_lock:
            try:
                if os.path.getsize(path) > _ROLE_LOG_MAX_BYTES:
                    os.replace(path, path + ".1")
            except OSError:
                pass
            with open(path, "a", encoding="utf-8") as f:
                f.write(line)
    except Exception:                                            # noqa: BLE001
        pass


def _bandit_reward(kind, pid, model, value):
    """File a QUALITY reward (1 / 0.5 / 0) with the bandit. Never for a client
    that left or a call the hub cut (_client_gone on the leg's token); the
    callers never call it for 429 / 5xx / timeouts. Never raises."""
    b = _bandit()
    if b is None or not kind or not (pid and model) or _client_gone():
        return False
    try:
        b.default.reward(kind, pid, model, float(value))
        return True
    except Exception:                                            # noqa: BLE001
        return False


def _bandit_remember(calls, pid, model, kind):
    """Tell the bandit which tool calls (pid, model) served, so the NEXT
    request's tool results credit it (_bandit_credit). Never raises."""
    b = _bandit()
    ids = [tc.get("id") for tc in (calls or ())
           if isinstance(tc, dict) and tc.get("id")]
    if b is None or not kind or not ids:
        return
    try:
        b.default.remember_tool_calls(ids, pid, model, kind)
    except Exception:                                            # noqa: BLE001
        pass


def _ensure_tool_call_ids(msg):
    """Give every tool call an id (a remembered call must be findable when the
    CLI sends its result back). In place; never raises."""
    try:
        for tc in (msg or {}).get("tool_calls") or ():
            if isinstance(tc, dict) and not tc.get("id"):
                tc["id"] = "call_" + uuid.uuid4().hex[:24]
    except Exception:                                            # noqa: BLE001
        pass


_EXIT_CODE_RE = re.compile(
    r"(?i)\b(?:exit(?:ed)?(?:\s+with)?|process\s+exited\s+with|returned)\s+"
    r"(?:exit\s+)?(?:code|status)\s*[:=]?\s*(-?\d+)")
# A tool result that reads as an ERROR (no evidence verdict available).
_TOOL_ERROR_RE = re.compile(
    r"(?im)^\s*(?:error\b|traceback \(most recent call last\)|fatal:|"
    r"[\w.]*(?:error|exception):)|command not found|no such file or directory"
    r"|\bexit(?:ed)?(?:\s+with)?\s+(?:code|status)\s*[:=]?\s*[1-9]\d*")


def _exit_code_in(text):
    """The exit code a tool result states ("Exit code: 1"), or None."""
    try:
        m = _EXIT_CODE_RE.search(str(text or "")[-4000:])
        return int(m.group(1)) if m else None
    except Exception:                                            # noqa: BLE001
        return None


def _command_from_call(call):
    """The shell command a tool call runs (its arguments' command / cmd /
    script, an argv list joined), or None."""
    try:
        fn = call.get("function") if isinstance(call.get("function"), dict) else call
        args = fn.get("arguments")
        if isinstance(args, str):
            args = json.loads(args) if args.strip() else {}
        if not isinstance(args, dict):
            return None
        for key in ("command", "cmd", "script", "commands"):
            v = args.get(key)
            if isinstance(v, list) and v and all(isinstance(x, str) for x in v):
                import shlex
                return shlex.join(v)
            if isinstance(v, str) and v.strip():
                return v
    except Exception:                                            # noqa: BLE001
        pass
    return None


def _tool_call_commands(messages):
    """{tool_call_id: command} for every command-running tool call in the
    conversation (OpenAI shape -- all three protocols are translated to it)."""
    out = {}
    for m in messages or ():
        if not isinstance(m, dict) or m.get("role") != "assistant":
            continue
        for tc in m.get("tool_calls") or ():
            if isinstance(tc, dict) and tc.get("id"):
                cmd = _command_from_call(tc)
                if cmd:
                    out[tc["id"]] = cmd
    return out


def _observed_pass(messages):
    """True when the conversation's LAST observed test/build result is a PASS,
    False when a FAIL, None when none was observed (evidence.classify on the
    tool results of command calls; never from words). Never raises."""
    ev = _evidence()
    if ev is None:
        return None
    try:
        cmds = _tool_call_commands(messages)
        last = None
        for m in messages or ():
            if not isinstance(m, dict) or m.get("role") != "tool":
                continue
            cmd = cmds.get(m.get("tool_call_id"))
            if not cmd:
                continue
            out = _message_text(m)
            verdict = (ev.classify(cmd, _exit_code_in(out), out, None) or {}).get("verdict")
            if verdict == getattr(ev, "PASS", "PASS"):
                last = True
            elif verdict == getattr(ev, "FAIL", "FAIL"):
                last = False
        return last
    except Exception:                                            # noqa: BLE001
        return None


def _make_bandit_grade(messages):
    """The `grade` callable bandit.credit_from_messages uses on a served tool
    call's RESULT: 1.0 for an observed PASS or a clean result, 0.5 for an
    observed FAIL or a result reading as an error. Accepts the result message
    (dict), its text, its tool_call_id and/or the call itself in any order."""
    memo = {}
    ev = _evidence()

    def grade(*args, **kwargs):
        if "cmds" not in memo:       # built on first use: most requests credit nothing
            memo["cmds"] = _tool_call_commands(messages)
        cmds = memo["cmds"]
        result = call = text = None
        cmd = None
        for a in list(args) + list(kwargs.values()):
            if isinstance(a, dict):
                if isinstance(a.get("function"), dict):
                    call = a
                elif result is None and ("content" in a or a.get("role") == "tool"):
                    result = a
            elif isinstance(a, str):
                if a in cmds:
                    cmd = cmds[a]
                elif text is None:
                    text = a
        out = _message_text(result) if result is not None else (text or "")
        if not isinstance(out, str):
            out = str(out or "")
        if call is not None:
            cmd = _command_from_call(call) or cmd
        if cmd is None and isinstance(result, dict):
            cmd = cmds.get(result.get("tool_call_id"))
        is_err = result.get("is_error") if isinstance(result, dict) else None
        is_err = is_err if isinstance(is_err, bool) else None
        if ev is not None and cmd:
            try:
                vd = (ev.classify(cmd, _exit_code_in(out), out, is_err) or {}).get("verdict")
                if vd == getattr(ev, "PASS", "PASS"):
                    return 1.0
                if vd == getattr(ev, "FAIL", "FAIL"):
                    return 0.5
            except Exception:                                    # noqa: BLE001
                pass
        if is_err is True or _TOOL_ERROR_RE.search(out[:4000]):
            return 0.5
        return 1.0
    return grade


def _bandit_credit(messages):
    """At the start of every /v1 request: the tool results this conversation
    sends back credit the models whose calls produced them (bandit
    remembered the call ids). Returns how many were credited. Never raises."""
    b = _bandit()
    if b is None or not messages:
        return 0
    try:
        n = int(b.default.credit_from_messages(messages, _make_bandit_grade(messages)) or 0)
    except Exception:                                            # noqa: BLE001
        return 0
    if n:
        _role_log({"event": "credit", "credited": n})
    return n


def _bandit_boot():
    """bandit.configure(state_dir()/task-bandit.json) -- at hub BOOT only
    (never at import: a test importing app must not touch any state file)."""
    b = _bandit()
    if b is None or not hasattr(b, "configure"):
        return
    try:
        b.configure(os.path.join(config.state_dir(), "task-bandit.json"))
    except Exception as exc:                                     # noqa: BLE001
        _log.warning("[bandit] not configured: %s", exc)


# --------------------------------------------------------------------------- #
# CLI /v1 parity: observed evidence + receipts + harvested facts (2026-10-08)
#
# Build and Multi PARSE a CLI's output and so can write receipts and harvest
# facts; a terminal CLI on /v1/* hands the hub only the conversation. But the
# conversation CARRIES what the CLI already ran: an assistant tool_call that
# runs a command, answered by a tool message with the command's output (and,
# after translation, Anthropic's is_error). So on every /v1 request the hub
# reads those results -- it RUNS nothing -- classifies them with evidence.py,
# writes a receipt (flag v1_observed_evidence) and harvests durable facts into
# the project's memory scope when the CLI's cwd is known (flag v1_memory_facts).
# Both are cheap, deduped and fail open; neither changes the reply.
# --------------------------------------------------------------------------- #

_V1_SEEN_LOCK = threading.Lock()
_V1_SEEN_IDS = collections.OrderedDict()      # tool_call_id -> True (bounded LRU)
_V1_SEEN_MAX = 5000
_V1_CWD_TAG_RE = re.compile(r"<cwd>\s*([^<\n]+?)\s*</cwd>", re.I)
_V1_CWD_LINE_RE = re.compile(
    r"(?im)(?:current\s+working\s+directory|working\s+directory|workspace\s+root|"
    r"project\s+root|\bcwd\b)\s*(?:is\s+|[:=]\s*)[`\"']?\s*"
    r"([A-Za-z]:[\\/][^\n\r`\"'<>|]+|/[^\n\r`\"'<>|]+)")
_V1_WRITE_NAME_RE = re.compile(
    r"(?i)(write|edit|create|multiedit|multi_edit|str_replace\w*|apply_patch|"
    r"notebookedit|create_file|write_file|edit_file|replace)")
_PATH_ARG_KEYS = ("file_path", "filepath", "path", "filename", "file", "target_file",
                  "notebook_path", "abs_path", "fullpath")
_CONTENT_ARG_KEYS = ("content", "contents", "file_text", "new_string", "newstring",
                     "code", "new_str", "source", "text", "new_text", "new_content",
                     "replacement", "code_edit", "insert_text")


def _v1_flag(name):
    try:
        return bool(config.get_flag(name, True))
    except Exception:                                            # noqa: BLE001
        return True


def _v1_seen(tcid):
    """True when this tool_call_id was already receipted (and records it). LRU."""
    with _V1_SEEN_LOCK:
        if tcid in _V1_SEEN_IDS:
            _V1_SEEN_IDS.move_to_end(tcid)
            return True
        _V1_SEEN_IDS[tcid] = True
        while len(_V1_SEEN_IDS) > _V1_SEEN_MAX:
            _V1_SEEN_IDS.popitem(last=False)
        return False


def _call_file_path_content(tc):
    """(path, content) a write/edit tool call names, each None when absent.
    OpenAI chat shape (function.arguments JSON), or the input/args dict."""
    try:
        fn = tc.get("function") if isinstance(tc.get("function"), dict) else tc
        args = fn.get("arguments") if isinstance(fn, dict) else None
        if args is None and isinstance(tc, dict):
            for k in ("input", "args", "parameters"):
                if k in tc:
                    args = tc[k]
                    break
        if isinstance(args, str):
            args = json.loads(args) if args.strip() else {}
        if not isinstance(args, dict):
            return None, None
        path = next((args[k] for k in _PATH_ARG_KEYS
                     if isinstance(args.get(k), str) and args[k].strip()), None)
        content = next((args[k] for k in _CONTENT_ARG_KEYS
                        if isinstance(args.get(k), str) and args[k]), None)
        return path, content
    except Exception:                                            # noqa: BLE001
        return None, None


def _v1_project_cwd(messages):
    """The project folder the CLI states (its <cwd> / working-directory env
    line), an existing directory that is NOT the hub's own repo. None when
    nothing usable. Never raises."""
    try:
        hub = os.path.normcase(os.path.dirname(os.path.abspath(__file__)))
        for m in messages or ():
            if not isinstance(m, dict) or m.get("role") not in ("system", "user", "developer"):
                continue
            text = _message_text(m)
            if not text:
                continue
            for raw in _V1_CWD_TAG_RE.findall(text) + _V1_CWD_LINE_RE.findall(text):
                p = str(raw).strip().strip("`\"'").rstrip(".,; ")
                if not p:
                    continue
                try:
                    if not os.path.isdir(p):
                        continue
                    n = os.path.normcase(os.path.abspath(p))
                except Exception:                                # noqa: BLE001
                    continue
                if n == hub or n.startswith(hub + os.sep) or hub.startswith(n + os.sep):
                    continue                     # never the hub's own repo dir
                return os.path.abspath(p)
    except Exception:                                            # noqa: BLE001
        pass
    return None


def _v1_evidence_rows(messages):
    """Classify the not-yet-seen command tool results (a shell/command call
    answered by a tool message) into evidence rows for RECOGNISED test/build
    commands. Deduped per tool_call_id (bounded LRU). Never raises."""
    ev = _evidence()
    if ev is None:
        return []
    try:
        cmds = _tool_call_commands(messages)
        if not cmds:
            return []
        rows = []
        for m in messages or ():
            if not isinstance(m, dict) or m.get("role") != "tool":
                continue
            tcid = m.get("tool_call_id")
            cmd = cmds.get(tcid)
            if not tcid or not cmd or _v1_seen(tcid):
                continue
            out = _message_text(m)
            is_err = m.get("is_error") if isinstance(m.get("is_error"), bool) else None
            try:
                row = ev.from_event({"command": cmd, "exit_code": _exit_code_in(out),
                                     "output_tail": out, "is_error": is_err})
            except Exception:                                    # noqa: BLE001
                continue
            if row and row.get("tool"):          # a recognised test/build command
                rows.append(row)
        return rows
    except Exception:                                            # noqa: BLE001
        return []


def _v1_last_assistant_text(messages):
    for m in reversed(messages or ()):
        if isinstance(m, dict) and m.get("role") == "assistant":
            t = _message_text(m)
            if t and t.strip():
                return t
    return ""


def _v1_write_tool_strings(messages):
    """"write: <path>" for every file-writing tool call -- what
    memory.harvest_files reads. Bounded. Never raises."""
    out = []
    try:
        for m in messages or ():
            if not isinstance(m, dict) or m.get("role") != "assistant":
                continue
            for tc in m.get("tool_calls") or ():
                if not isinstance(tc, dict):
                    continue
                fn = tc.get("function") if isinstance(tc.get("function"), dict) else tc
                name = (fn.get("name") if isinstance(fn, dict) else "") or ""
                path, _c = _call_file_path_content(tc)
                if path and _V1_WRITE_NAME_RE.search(name):
                    out.append("write: " + str(path))
    except Exception:                                            # noqa: BLE001
        return out[-200:]
    return out[-200:]


def _v1_observe(messages, body=None):
    """Gaps 3 & 4: write OBSERVED-evidence receipts for the recognised
    test/build commands in the history, and harvest durable facts into the
    project's memory scope when the CLI's cwd is known. The hub RUNS nothing.
    Never raises; nothing here affects the reply."""
    try:
        if not messages:
            return
        key, cwd = None, None
        rows = _v1_evidence_rows(messages) if _v1_flag("v1_observed_evidence") else []
        if rows:
            try:
                key = _orch_key(body, messages)
            except Exception:                                    # noqa: BLE001
                key = None
            rcpts = _optional_module("receipts", ("write",))
            if rcpts is not None:
                cwd = _v1_project_cwd(messages)
                try:
                    rcpts.write("v1-" + (key or "conversation"), "v1-turn", rows, cwd=cwd)
                except Exception:                                # noqa: BLE001
                    pass
        if not _v1_flag("v1_memory_facts"):
            return
        if cwd is None:
            cwd = _v1_project_cwd(messages)
        if not cwd:
            return
        if key is None:
            try:
                key = _orch_key(body, messages)
            except Exception:                                    # noqa: BLE001
                key = None
        memory.harvest_facts(key or "v1", request=_team_instruction(messages),
                             reply=_v1_last_assistant_text(messages), project_dir=cwd,
                             tools=_v1_write_tool_strings(messages), results=rows)
    except Exception:                                            # noqa: BLE001
        pass


def _role_judge(pid, model, resp, exc, body, payload, est, kind):
    """One role call's result -> {"ok": True, "data", "msg", "gate"} or
    {"ok": False, "fail", "why"}. The fan-out's member checks, plus: a tool
    call the CLI cannot run is a FAILED hop here (one actor, nothing to
    prefer it over). Files outcomes like the fan-out did and the quality
    reward 0 for junk / invalid / prose-instead-of-action. Never raises."""
    tools = body.get("tools")

    def fail(kind_, why, reward=None):
        if reward is not None:
            _bandit_reward(kind, pid, model, reward)
        return {"ok": False, "fail": kind_, "why": why}
    try:
        if resp is None:
            if exc is not None:
                _record_outcome(pid, model, False)
                _swarm_note_member_exc(pid, model, exc)
                _m = _sanitize(str(exc), 120).strip()
                return fail("exc", "%s%s" % (type(exc).__name__, (": " + _m) if _m else ""))
            return fail("deadline", "no answer in time")
        try:
            if resp.status_code != 200:
                _record_outcome(pid, model, False)
                _swarm_note_member_status(pid, model, resp.status_code)
                return fail("http", "HTTP %d" % resp.status_code)
            data = resp.json() or {}
        except (ValueError, AttributeError):
            return fail("bad-json", "200 but the body was not usable JSON")
        finally:
            try:
                resp.close()
            except Exception:                                    # noqa: BLE001
                pass
        if not isinstance(data, dict):
            return fail("bad-json", "200 but the body was not a JSON object")
        msg = ((data.get("choices") or [{}])[0].get("message") or {})
        if not (msg.get("tool_calls") or (msg.get("content") or "").strip()):
            _record_outcome(pid, model, False)
            _note_empty_200(pid, model)
            return fail("empty", "200 with an empty message")
        if not msg.get("tool_calls") and tools:
            if tool_rescue.rescue(data, tools):
                msg = ((data.get("choices") or [{}])[0].get("message") or {})
        content = msg.get("content")
        if not msg.get("tool_calls"):
            if _looks_like_refusal(content) or _looks_like_permission_block(content):
                _record_outcome(pid, model, False)
                return fail("prose", "refused: %s" % " ".join(str(content or "")[:60].split()), 0)
            if tools and _no_tools_claim(
                    content, tools_offered=True, prompt=_last_user_text_for_check(body),
                    used_tools=_turn_used_tools(body.get("messages"))):
                _record_outcome(pid, model, False)
                return fail("prose", "claimed it has no tools", 0)
            if tools and (_looks_like_text_tool_call(content)
                          or tool_rescue.has_model_markup(content)
                          or _looks_like_announced_not_acted(content)):
                _note_nonanswer(pid, model)
                return fail("prose", "answered in prose without calling a tool", 0)
        gate = _answer_gate(data, payload, bool(tools), hop=(pid, model))
        if gate == "junk":
            _record_outcome(pid, model, False, junk=True)
            _note_empty_200(pid, model)
            return fail("junk", "degenerate answer (nothing salvageable)", 0)
        msg = ((data.get("choices") or [{}])[0].get("message") or {})
        if msg.get("tool_calls") and not _swarm_tool_calls_valid(msg, tools):
            _record_outcome(pid, model, False)
            return fail("invalid", "a tool call the CLI cannot run", 0)
        _clear_empty_200(pid, model)
        _record_chat_usage(pid, model, data, est, ok=gate == "ok")
        return {"ok": True, "data": data, "msg": msg, "gate": gate}
    except Exception as e:                                       # noqa: BLE001
        return {"ok": False, "fail": "error", "why": "error: %s" % type(e).__name__}


def _role_start_leg(idx, pid, model, body, deadline, q, est, kind):
    """Start one non-streamed role call on its own thread under its own hop
    token (clientgone.child): cancelling the token cuts the call, and inside
    it _client_gone() is then True, so a call the hub cut files nothing.
    Puts (idx, verdict) on `q`. Returns the token."""
    tok = clientgone.child("role-leg")
    payload = dict(body)
    payload["model"] = model
    payload["stream"] = False

    def _go():
        t0 = time.monotonic()
        try:
            resp, exc = _dispatch_chat_with_deadline(pid, payload, deadline)
            v = _role_judge(pid, model, resp, exc, body, payload, est, kind)
            if v.get("ok"):
                _record_speed_sample(_tool_ttft, pid, model,
                                     (time.monotonic() - t0) * 1000.0)
        except Exception as e:                                   # noqa: BLE001
            v = {"ok": False, "fail": "error", "why": "error: %s" % type(e).__name__}
        v["secs"] = round(time.monotonic() - t0, 2)
        q.put((idx, v))
    run = _pipeline_bound(_carry_usage_source(lambda: clientgone.run_as(tok, _go)))
    threading.Thread(target=run, daemon=True, name="role-leg-%d" % idx).start()
    return tok


# A BIG tool turn needs a bigger actor share than room/attempts_left: MEASURED
# 2026-10-07, OpenCode coding-swarm at ~79K tokens, nvidia/kimi-k3 and
# glm-4.7-flash ended "no answer in time" because the 3-way split (~60 s) cut a
# healthy model that needed ~70-120 s at that size. So past
# LONG_CTX_SPEED_TOKENS the split is capped to _LONG_CTX_ROLE_ATTEMPTS (so each
# attempt gets ~room/2 ≈ 90 s, which still fits two actors inside the ~180-270 s
# turn), and a model MEASURED healthy-but-slow at long context gets at least its
# own long-context p90 -- capped so one more attempt still fits
# (_LONG_CTX_ROLE_FLOOR_SHARE of the room). The fastest long-context model opens
# the walk anyway (_prefer_fast_long_context in _build_chain).
_LONG_CTX_ROLE_ATTEMPTS = 2
_LONG_CTX_ROLE_FLOOR_SHARE = 0.6
_LONG_CTX_ROLE_FLOOR_MARGIN = 1.2


def _role_share(room, attempts_left):
    """Seconds one attempt may take of `room` when `attempts_left` attempts
    must still fit: room / attempts_left, never under _ROLE_MIN_HOP_SECONDS,
    never over the room itself."""
    n = max(1, int(attempts_left or 1))
    return min(room, max(_ROLE_MIN_HOP_SECONDS, room / n))


def _role_longctx_floor(pid, model, est):
    """A measured floor (seconds) for an actor hop on a BIG request, from this
    pair's long-context first-content p90 (non-stalled samples), falling back to
    its tool-turn p90; 0 when the request is not big or the pair is unmeasured.
    Never raises."""
    try:
        if int(est or 0) < LONG_CTX_SPEED_TOKENS:
            return 0.0
        now = time.time()
        with _outcome_lock:
            rows = [r for r in (_long_ctx_speed.get((pid, model)) or ())
                    if not r[2] and now - r[0] <= LONG_CTX_SPEED_TTL]
            tool = list(_tool_ttft.get((pid, model)) or [])
        if len(rows) >= 2:
            return _percentile([r[1] for r in rows], 90) / 1000.0
        if len(tool) >= _TOOL_MIN_SAMPLES:
            return _percentile(tool, 90) / 1000.0
        return 0.0
    except Exception:                                            # noqa: BLE001
        return 0.0


def _role_hop_deadline(clock, pid, model, room_total, attempts_left, est, budget):
    """Seconds for one actor hop. A big request caps the split at
    _LONG_CTX_ROLE_ATTEMPTS and lifts the share to a measured-healthy-but-slow
    model's long-context p90 (capped at _LONG_CTX_ROLE_FLOOR_SHARE of the room so
    a second attempt still fits). Never raises (plain _role_share on error)."""
    try:
        n = attempts_left
        if int(est or 0) >= LONG_CTX_SPEED_TOKENS:
            n = min(n, _LONG_CTX_ROLE_ATTEMPTS)
        share = _role_share(room_total, n)
        floor = _role_longctx_floor(pid, model, est)
        if floor:
            share = min(room_total, max(share, min(floor * _LONG_CTX_ROLE_FLOOR_MARGIN,
                                                   room_total * _LONG_CTX_ROLE_FLOOR_SHARE)))
        return share if budget is None else min(budget, share)
    except Exception:                                            # noqa: BLE001
        share = _role_share(room_total, attempts_left)
        return share if budget is None else min(budget, share)


def _note_actor_stall(clock, pid, model, silent_s):
    """An actor the hub stopped waiting for after `silent_s` of silence (its
    backup fired, or the hop ran out): a CENSORED tool-turn timing sample
    (>= silent_s) plus the recent-stall mark _build_chain reads, so the next
    turn puts the pair behind the quick ones. Files nothing when the client
    left. Never raises."""
    if _client_gone():
        return
    try:
        _record_speed_sample(_tool_ttft, pid, model, float(silent_s) * 1000.0)
        _note_recent_hop_failure(pid, model, "timeout")
        clock._note_stall(pid)
    except Exception:                                            # noqa: BLE001
        pass


def _role_actor_hop(clock, body, pid, model, est, kind, rec, rows, turn_end, spent=None,
                    attempts_left=1):
    """One actor hop with its stall backup. Returns (pid, model, data, msg)
    of the first VALID answer, or None (the walk moves on).

    `spent` (a list the caller owns) collects every pair this hop dispatched
    to -- the actor, and the backup if it fired -- so the verifier that runs
    afterwards is never a model that just stalled or lost the race here."""
    budget = clock.open_role_hop(pid, model)
    now = time.monotonic()
    # attempts_left attempts (this actor, its backup, the next hop) must fit in
    # the turn: a silent first hop cannot eat half the clock. A big request caps
    # the split so a healthy slow model is not cut just before it answers (see
    # _role_hop_deadline).
    deadline = _role_hop_deadline(clock, pid, model, turn_end - now, attempts_left,
                                  est, budget)
    if deadline <= 1.0:
        return None
    q = queue.Queue()
    legs = {0: (pid, model)}
    if spent is not None:
        spent.append((pid, model))
    toks = {0: _role_start_leg(0, pid, model, body, deadline, q, est, kind)}
    rec["calls"] += 1
    rec["sent_tokens"] += est
    delay = _tool_hedge_delay(pid, model, est)
    partner = clock.tool_hedge_partner(pid, model) if delay < deadline - 1.0 else None
    t0, end = now, now + deadline
    pending, fired = {0}, False

    def _row(idx, role):
        p, m = legs[idx]
        rows.append({"role": role, "model": "%s/%s" % (p, m)})

    while pending:
        if _client_gone():
            for j in pending:
                toks[j].cancel("client disconnected")
            return None
        wait_to = end if (fired or partner is None) else min(t0 + delay, end)
        try:
            idx, v = q.get(timeout=max(0.0, min(0.5, wait_to - time.monotonic())))
        except queue.Empty:
            now = time.monotonic()
            if now < wait_to:
                continue                 # a 0.5 s slice, so a cancel is seen
            if not fired and partner is not None and now < end:
                fired = True
                p1, m1 = partner
                b1 = clock._budget_for(p1, m1, False)
                d1 = _role_share(turn_end - now, max(1, attempts_left - 1))
                if b1 is not None:
                    d1 = min(b1, d1)
                if d1 > 1.0:
                    clock.fire_tool_hedge(p1, m1)
                    legs[1] = (p1, m1)
                    if spent is not None:
                        spent.append((p1, m1))
                    toks[1] = _role_start_leg(1, p1, m1, body, d1, q, est, kind)
                    pending.add(1)
                    rec["calls"] += 1
                    rec["sent_tokens"] += est
                    rec["hedge"] = "%s/%s" % (p1, m1)
                    end = min(max(end, now + d1), turn_end)
                    _log.info("[roles] %s/%s silent %.1fs -> backup %s/%s",
                              pid, model, now - t0, p1, m1)
                continue
            break                        # out of time
        pending.discard(idx)
        if v.get("ok"):
            if idx == 1 and 0 in pending:
                # The actor was silent for the whole delay and lost to its
                # backup: remembered. (A backup that loses is not: it ran for
                # less than its own delay.)
                _note_actor_stall(clock, pid, model, time.monotonic() - t0)
            elif idx == 0:
                _clear_recent_hop_failure(pid, model)
            for j in pending:
                toks[j].cancel("another actor answered first")
            _row(idx, "actor" if idx == 0 else "backup (stall)")
            if pending:
                _row(min(pending), "%s: stopped, %s answered first" % (
                    "actor" if 0 in pending else "backup (stall)",
                    "the backup" if idx else "the actor"))
            return (legs[idx][0], legs[idx][1], v["data"], v["msg"])
        why = str(v.get("why") or "failed")[:60]
        _row(idx, "%s: %s" % ("actor" if idx == 0 else "backup (stall)", why))
        rec["failed"].append({"pair": "%s/%s" % legs[idx], "why": why})
        if v.get("fail") in ("invalid", "prose", "junk"):
            rec["invalid"] += 1
            # A tool call the CLI cannot run (or prose/junk where a tool call
            # was due) answered FAST but wrong: demote the pair for tool turns
            # like a stall, so _build_chain's recent-failure tail orders it
            # behind the healthy ones next turn. Not when the client left.
            if not _client_gone():
                _note_recent_hop_failure(legs[idx][0], legs[idx][1], v.get("fail"))
        if v.get("fail") == "deadline" and not _client_gone():
            clock._note_stall(legs[idx][0])
            if deadline >= _ADAPTIVE_HOP_FLOOR:
                _note_recent_hop_failure(legs[idx][0], legs[idx][1], "deadline")
    for j in pending:
        toks[j].cancel("role hop out of time")
        _row(j, "%s: no answer in time" % ("actor" if j == 0 else "backup (stall)"))
    if 0 in pending and not _client_gone():
        clock._note_stall(pid)
        if deadline >= _ADAPTIVE_HOP_FLOOR:
            _note_recent_hop_failure(pid, model, "deadline")
            _record_speed_sample(_tool_ttft, pid, model,
                                 (time.monotonic() - t0) * 1000.0)
    return None


def _role_candidates(chain, producer, failed=(), kind=None):
    """[(pid, model, score)] -- the shape verify.pick_verifier takes -- for
    the healthy chain entries other than `producer` and the pairs that failed
    this turn: chain (= benchmark) order and benchmark score, with the bandit
    nudge applied only inside the top band (_band_scores / _nudge_in_band)."""
    pairs = []
    bad = {tuple(p) for p in failed or ()}
    prod = tuple(producer)[:2]
    for e in chain or ():
        p, m = e[0], e[1]
        if (p, m) == prod or (p, m) in bad or _is_sub(p):
            continue
        if _swarm_member_sick(p, m):
            continue
        pairs.append((p, m))
    if not pairs:
        return []

    def _score(e):
        return _benchmark_score(e[0], e[1])
    scores, band = _band_scores(pairs, kind, _score)
    rows = [(p, m, round(s, 4)) for (p, m), s in zip(pairs, scores)]
    out = list(rows)
    for slot, i in zip(band, sorted(band, key=lambda i: -scores[i])):
        out[slot] = rows[i]          # only the band's own slots move
    return out


def _run_verifier(v, vp, vm, messages, msg, deadline, rec, strict=False, info=None):
    """One non-streamed verifier call -> parsed verdict dict, or None on ANY
    error / timeout / unreadable verdict (the caller fails open).

    `strict`: the one-line retry contract (verify.STRICT_VERIFIER_SYSTEM).
    `info` (a dict): gets "unparsed" = True when the reply was text that
    verify.parse_verdict could not read, "empty" = True for a blank reply.
    The call is filed in the verifier ledger (_verifier_rate) as usable or
    not, unless the client left."""
    usable = False
    try:
        return _run_verifier_inner(v, vp, vm, messages, msg, deadline, rec, strict, info)
    finally:
        if not _client_gone():
            _verifier_stats_note(vp, vm, bool(rec.pop("_v_usable", False)))


def _run_verifier_inner(v, vp, vm, messages, msg, deadline, rec, strict, info):
    if info is None:
        info = {}
    rec.pop("_v_usable", None)
    try:
        vmsgs = v.digest(messages, msg, strict=True) if strict else v.digest(messages, msg)
        max_tokens = int(getattr(v, "VERIFY_MAX_TOKENS", 400) or 400)
    except Exception:                                            # noqa: BLE001
        return None
    payload = {"model": vm, "stream": False, "max_tokens": max_tokens,
               "messages": vmsgs, "_no_craft": True}    # stripped in _upstream_chat
    rec["calls"] += 1
    v_est = _est_tokens(vmsgs)
    rec["sent_tokens"] += v_est
    resp, exc = _dispatch_chat_with_deadline(vp, payload, deadline)
    if resp is None:
        if exc is not None:
            _swarm_note_member_exc(vp, vm, exc)
        return None
    try:
        if resp.status_code != 200:
            _swarm_note_member_status(vp, vm, resp.status_code)
            return None
        data = resp.json() or {}
    except (ValueError, AttributeError):
        return None
    finally:
        try:
            resp.close()
        except Exception:                                        # noqa: BLE001
            pass
    try:
        text = _message_text(((data.get("choices") or [{}])[0].get("message") or {}))
        if not str(text or "").strip():
            info["empty"] = True
            return None
        _record_chat_usage(vp, vm, data, v_est)
        verdict = v.parse_verdict(text)
        # verify.parse_verdict turns an unreadable reply into ACCEPT with
        # "unparsed": True. Fail-open here too, but it is NOT a verification:
        # no reward, nothing shown as "verifier: ok".
        if not isinstance(verdict, dict) or "ok" not in verdict or verdict.get("unparsed"):
            info["unparsed"] = True
            return None
        rec["_v_usable"] = True
        return verdict
    except Exception:                                            # noqa: BLE001
        return None


# --------------------------------------------------------------------------- #
# Web SLOP in a proposed answer (Gap 1, 2026-10-08)
#
# The pipelines already slop-check built web files (swarm_windows._slop_scan,
# crews); the app's own verifier / corrector did not. Now a proposed step that
# WRITES a web file (a tool call whose args carry .html/.css/.jsx/.tsx/.vue
# content) or a Max text answer that returns HTML in a code fence is scanned
# with verify.slop_problems, and its HIGH findings become verifier problems
# that drive the existing corrector (ONE call, severity high). Web output only;
# flag turn_slop_check (default on), under the turn_verifier kill switch.
# --------------------------------------------------------------------------- #

def _slop_check_on():
    try:
        return bool(config.get_flag("turn_slop_check", True))
    except Exception:                                            # noqa: BLE001
        return True


def _web_writes_in_msg(msg):
    """[(name, text)] of the web files a proposed message writes: tool-call
    args writing a web file, plus HTML code fences in its text. Never raises."""
    out = []
    try:
        v = _verify()
        is_web = getattr(v, "is_web_file", None) if v is not None else None

        def webp(path):
            if callable(is_web):
                try:
                    return bool(is_web(path))
                except Exception:                                # noqa: BLE001
                    pass
            return str(path or "").lower().split("?")[0].endswith(
                (".html", ".htm", ".css", ".jsx", ".tsx", ".vue", ".svelte"))

        for tc in (msg or {}).get("tool_calls") or ():
            if not isinstance(tc, dict):
                continue
            path, content = _call_file_path_content(tc)
            if path and content and webp(path):
                out.append((str(path), content))
        text = _message_text(msg) or ""
        blocks = getattr(v, "html_blocks", None) if v is not None else None
        if callable(blocks) and text:
            try:
                out.extend(blocks(text))
            except Exception:                                    # noqa: BLE001
                pass
    except Exception:                                            # noqa: BLE001
        return []
    return out[:40]


def _slop_problems_for_proposal(msg):
    """HIGH web-slop findings in a proposed message as problem strings, or []
    (flag off, no web output, nothing found, or verify absent). Never raises."""
    if not _slop_check_on():
        return []
    v = _verify()
    if v is None or not hasattr(v, "slop_problems"):
        return []
    try:
        files = _web_writes_in_msg(msg)
        if not files:
            return []
        return list(v.slop_problems(files))[:8]
    except Exception:                                            # noqa: BLE001
        return []


def _role_verify_and_correct(body, messages, producer, msg, chain, kind, difficulty,
                             rec, rows, turn_end, est, tool_turn=True, failed=()):
    """VERIFIER (+ at most ONE CORRECTOR) for a proposed answer. Returns
    (pid, model, data, msg) of an accepted correction, else None (ship the
    original). Rewards the producer on the verdict (1 ok / 0.5 revise).
    Fail-open everywhere. Never raises."""
    v = _verify()
    if v is None:
        return None
    try:
        if not config.get_flag("turn_verifier", True):
            return None
        calls = msg.get("tool_calls") or []
        # Web slop in what the proposal WRITES (Gap 1): its HIGH findings force
        # a correction even when the verifier would ACCEPT; [] off / non-web.
        slop = _slop_problems_for_proposal(msg)
        weak = bool(_model_is_weak(*producer[:2]))
        if tool_turn:
            # The WHOLE assistant message: verify.is_risky reads its tool
            # calls (write/exec on a hard turn) and its text ("done" / "tests
            # pass" claimed with no observed PASS on any non-simple turn).
            try:
                risky = bool(v.is_risky(msg, difficulty,
                                        observed_pass=_observed_pass(messages)))
            except Exception:                                    # noqa: BLE001
                risky = False
            if not risky and not weak and not slop:
                return None
        else:
            risky = True                 # a Max text review always verifies
        if turn_end - time.monotonic() < _VERIFY_MIN_SECONDS:
            rec["verdict"] = "skipped: no time left"
            return None
        ppid, pmodel = producer
        pool = _rank_verifier_pool(_role_candidates(chain, producer, failed, kind))
        # Run the independent verifier unless the ONLY reason we are here is web
        # slop (then the HIGH findings alone drive the corrector -- no model
        # call spent on a verdict we would override anyway).
        run_verifier = risky or weak
        verdict = None
        if run_verifier:
            try:
                pick = v.pick_verifier((ppid, pmodel), pool)
            except Exception:                                    # noqa: BLE001
                pick = None
            if not pick and not slop:
                rec["verdict"] = "no verifier available"
                return None
            if pick:
                vp, vm = pick[0], pick[1]
                rec["verifier"] = "%s/%s" % (vp, vm)
                vinfo = {}
                verdict = _run_verifier(v, vp, vm, messages, msg,
                                        min(_VERIFY_DEADLINE, turn_end - time.monotonic()),
                                        rec, info=vinfo)
                if _client_gone():
                    return None
                if verdict is None and (vinfo.get("unparsed") or vinfo.get("empty")):
                    # A reply that could not be read: ONE retry on the next-best
                    # verifier with the strict one-line contract, if time remains.
                    rec["verifier_unparsed"] = int(rec.get("verifier_unparsed") or 0) + 1
                    left = min(_VERIFY_DEADLINE, turn_end - time.monotonic())
                    if left >= _VERIFY_MIN_SECONDS + 4.0:
                        try:
                            pick2 = v.pick_verifier(
                                (ppid, pmodel), [e for e in pool if (e[0], e[1]) != (vp, vm)])
                        except Exception:                        # noqa: BLE001
                            pick2 = None
                        if pick2:
                            rec["verifier_retry"] = int(rec.get("verifier_retry") or 0) + 1
                            vp, vm = pick2[0], pick2[1]
                            rec["verifier"] = "%s/%s" % (vp, vm)
                            verdict = _run_verifier(v, vp, vm, messages, msg, left, rec,
                                                    strict=True)
                            if _client_gone():
                                return None
        if verdict is None and run_verifier and not slop:
            rec["verdict"] = "no verdict (fail-open)"
            rows.append({"role": "verifier: no verdict", "model": rec.get("verifier")})
            return None
        if verdict is not None:
            ok = bool(verdict.get("ok"))
            sev = str(verdict.get("severity") or "").strip().lower()
            rec["verdict"] = "ok" if ok else "revise"
            rec["severity"] = sev or None
            rows.append({"role": "verifier: %s" % rec["verdict"], "model": rec["verifier"]})
            _bandit_reward(kind, ppid, pmodel, 1.0 if ok else 0.5)
        else:
            ok, sev, verdict = True, "low", {"ok": True, "problems": [], "severity": "low"}
        if slop:
            # HIGH slop beats an ACCEPT: the corrector gets the slop findings
            # (ahead of any verifier problems) at high severity.
            probs = list(slop) + [p for p in (verdict.get("problems") or []) if p]
            verdict = {"ok": False, "problems": probs[:8], "severity": "high"}
            ok, sev = False, "high"
            rec["slop"] = len(slop)
            rec["verdict"] = "revise"
            rec["severity"] = "high"
            rows.append({"role": "slop: %d high" % len(slop),
                         "model": "%s/%s" % (ppid, pmodel)})
        if ok or sev != "high":
            return None
        if turn_end - time.monotonic() < _CORRECT_MIN_SECONDS:
            rec["correction"] = "skipped: no time left"
            return None
        ident = _normalize_model_identity(pmodel)
        cpool = [e for e in pool if _normalize_model_identity(e[1]) != ident]
        if not cpool:
            rec["correction"] = "no other actor"
            return None
        cp, cm = cpool[0][0], cpool[0][1]
        try:
            cbody = dict(body)
            # verify.corrector_messages keeps a proposed tool_calls message
            # native and answers each call "not executed" before the
            # problems note (providers 400 without them): sent as-is.
            cbody["messages"] = v.corrector_messages(messages, msg, verdict)
        except Exception:                                        # noqa: BLE001
            return None
        q = queue.Queue()
        c_est = _est_tokens(cbody["messages"], cbody.get("tools"))
        dl = max(1.0, turn_end - time.monotonic())
        tok = _role_start_leg(2, cp, cm, cbody, dl, q, c_est, kind)
        rec["calls"] += 1
        rec["sent_tokens"] += c_est
        rec["corrector"] = "%s/%s" % (cp, cm)
        got = None
        stop_at = time.monotonic() + dl + 1.0
        while time.monotonic() < stop_at:
            if _client_gone():
                tok.cancel("client disconnected")
                return None
            try:
                got = q.get(timeout=0.5)[1]
                break
            except queue.Empty:
                continue
        if got is None:
            tok.cancel("corrector out of time")
            rows.append({"role": "corrector: no answer in time", "model": rec["corrector"]})
            return None
        cmsg = got.get("msg") or {}
        if cmsg.get("tool_calls"):
            # A corrected STEP must be one the CLI can run.
            accepted = (bool(got.get("ok")) and tool_turn
                        and _swarm_tool_calls_valid(cmsg, cbody.get("tools")))
        else:
            # Prose replaces prose only: a proposed tool step is never swapped
            # for text.
            accepted = bool(got.get("ok")) and not calls
        if not accepted:
            why = got.get("why") or "not a usable correction"
            rows.append({"role": "corrector: kept the original (%s)" % str(why)[:40],
                         "model": rec["corrector"]})
            return None
        rec["corrected"] = True
        rows.append({"role": "corrector", "model": rec["corrector"]})
        return (cp, cm, got["data"], cmsg)
    except Exception:                                            # noqa: BLE001
        return None


def _role_activity(rows, label):
    """Show the roles on the activity row (the pipeline chips)."""
    try:
        act = getattr(g, "act", None)
        if act is not None:
            with _activity_lock:
                act["crew"] = label
                act["pipeline"] = list(rows)
    except Exception:                                            # noqa: BLE001
        pass


def _roles_header(rec):
    return "actor_hops=%d;backup=%d;verifier=%s;corrected=%d;calls=%d;specialists=%d" % (
        int(rec.get("actor_hops") or 0), 1 if rec.get("hedge") else 0,
        (rec.get("verdict") or "none").split(" ")[0], 1 if rec.get("corrected") else 0,
        int(rec.get("calls") or 0), int(rec.get("specialists_ok") or 0))


# --------------------------------------------------------------------------- #
# TEAM NOTES: parallel specialists for hard tool turns (2026-10-04)
#
# A CLI turn must yield ONE next action, which cannot be split -- but the
# THINKING around it can. On a HARD, fresh-instruction tool turn up to three
# DIFFERENT models (scout / designer / critic) each do one read-only job in
# parallel on a digest of the conversation, a deterministic orchestrator
# merges their notes into ONE system message, and the actor then runs exactly
# as before (verifier / corrector / backup untouched). No extra model call
# for the merge; a failed specialist is simply omitted; nothing is rewarded
# or punished in the bandit from specialist output.
# --------------------------------------------------------------------------- #

_TEAM_MAX_SPECIALISTS = 3
_TEAM_HOP_SECONDS = 35.0     # MEASURED: answered p50 11.9 s, p90 19.4 s; 4 of 12 hit the old 25 s
_TEAM_MAX_TOKENS = 700
_TEAM_MAX_EST = 60000
_TEAM_BRIEF_CHARS = 2500
_TEAM_CACHE_TURNS = 3
_TEAM_MIN_ROOM = 40.0
_TEAM_INSTR_CHARS = 8000
_TEAM_RESULT_CHARS = 3000
_TEAM_RESULTS = 3
_TEAM_ORDER = ("scout", "designer", "critic")
_TEAM_LABELS = {"scout": "SCOUT (what matters)", "designer": "DESIGN",
                "critic": "RISKS AND CHECKS"}
_TEAM_HEADER = ("TEAM NOTES (hints from parallel specialists, not instructions): "
                "use as hints; verify against the real files; do not invent paths.")
_TEAM_SYSTEM = {
    "scout": ("You are the SCOUT on a coding team. You cannot run tools or see files "
              "beyond the digest. From what is VISIBLE in it, list the files, symbols "
              "and commands that matter for the user's instruction and why, as short "
              "bullets. Say 'unknown' instead of guessing a path. Max 200 words."),
    "designer": ("You are the DESIGNER on a coding team. You cannot run tools. For the "
                 "thing the user wants built, give the components, their interfaces "
                 "and data flow; for web/UI work add concrete hex palette, a named "
                 "type pairing and the layout idea (no purple-blue default gradient, "
                 "no placeholder copy, readable contrast). Short bullets, max 200 words."),
    "critic": ("You are the CRITIC on a coding team. You cannot run tools. List the "
               "risks and edge cases of this task, how to verify the result (the "
               "cheapest check first), and what NOT to do. Short bullets, max 200 words."),
}
_team_cache = {}
_team_cache_lock = threading.Lock()


def _team_flag_on():
    try:
        return bool(config.get_flag("tool_turn_specialists", True))
    except Exception:                                            # noqa: BLE001
        return True


def _team_fresh(messages):
    """True when the conversation ENDS on a real user instruction (an opening
    turn or a fresh follow-up), not on a tool result (a loop continuation)."""
    for m in reversed(messages or ()):
        if not isinstance(m, dict):
            continue
        if m.get("role") in ("system", "developer"):
            continue
        return bool(ctxwin.is_real_instruction(m))
    return False


def _team_instruction(messages):
    for m in reversed(messages or ()):
        if ctxwin.is_real_instruction(m):
            return ctxwin.instruction_text(ctxwin.message_text(m))
    return ""


def _specialists_wanted(body, kind, est=None, real=None):
    """True when this swarm/crew*/multi tool turn should get TEAM NOTES: flag
    on, low-resource mode off, a fresh instruction (never a mid-loop tool
    result), hard, not trivial, not a CLI compaction, est <= _TEAM_MAX_EST.
    Never raises."""
    try:
        if not _team_flag_on():
            return False
        try:
            if lowres.active():
                return False
        except Exception:                                        # noqa: BLE001
            pass
        messages = (body or {}).get("messages") or []
        if not messages or not _team_fresh(messages):
            return False
        if ctxwin.is_compaction_request(messages):
            return False
        if est is None:
            est = _est_tokens(messages, (body or {}).get("tools"))
        if est > _TEAM_MAX_EST:
            return False
        if real is None:
            real = _classify_difficulty(messages, (body or {}).get("max_tokens"))
        if real != "hard":
            if not (real == "medium" and _team_medium_ok(messages, est)):
                return False
        if _is_trivial_ask(messages, (body or {}).get("max_tokens")):
            return False
        return True
    except Exception:                                            # noqa: BLE001
        return False


_TEAM_MEDIUM_MAX_EST = 30000
_TEAM_IMPLEMENT_RE = re.compile(
    r"\b(?:implement\w*|refactor\w*|migrat\w+|restructur\w+|rewrit\w+|overhaul\w*|"
    r"integrat\w+|extract\w*|multi[- ]?file)\b"
    r"|\b(?:across|in\s+all|in\s+every|throughout)\s+(?:(?:the|all)\s+)*"
    r"(?:files?|modules?|codebase|repo|repository|project|tests?|components?)\b"
    r"|\badd\b[^.\n]{0,40}\b(?:feature|endpoint|command|page|component|module|support|"
    r"route|api|handler|service)\b", re.I)
_TEAM_SMALL_EDIT_RE = re.compile(
    r"\b(?:typo|one[- ]?lin(?:e|er)|single\s+line|small\s+tweak|bump\s+(?:the\s+)?version|"
    r"rename\s+\w+\s+to|change\s+the\s+(?:text|colou?r|title|label|name)\b)", re.I)
_TEAM_QUESTION_START_RE = re.compile(
    r"^\s*(?:what|why|how|which|where|when|who|is|are|does|do|did|explain|describe|"
    r"show|list|tell|summari[sz]e|compare)\b", re.I)
_TEAM_POLITE_RE = re.compile(
    r"^\s*(?:(?:hey|hi|ok|okay|so|please)[,\s]+)*(?:can|could|would|will)\s+you\s+"
    r"(?:please\s+)?", re.I)


def _team_medium_flag_on():
    try:
        return bool(config.get_flag("tool_turn_specialists_medium", True))
    except Exception:                                            # noqa: BLE001
        return True


def _medium_build_ask(text):
    """Is the instruction a build / create / implement / refactor / fix-across-
    files ask worth a team (a MEDIUM turn)? Not a question, not a one-line
    edit, not tiny. 'Can you implement X?' is a polite build ask, 'how does X
    work?' is a question. Never raises."""
    try:
        t = " ".join(str(text or "").split())
        if len(t.split()) < 8:
            return False
        polite = bool(_TEAM_POLITE_RE.match(t))
        body = _TEAM_POLITE_RE.sub("", t, count=1) if polite else t
        if _TEAM_QUESTION_START_RE.match(body):
            return False
        if t.rstrip().endswith("?") and not polite:
            return False
        if _TEAM_SMALL_EDIT_RE.search(t):
            return False
        return bool(_FAST_PATH_CREATE_RE.search(t) or _TEAM_IMPLEMENT_RE.search(t))
    except Exception:                                            # noqa: BLE001
        return False


def _team_medium_ok(messages, est):
    """The MEDIUM-turn team gate: flag on, est <= _TEAM_MEDIUM_MAX_EST and the
    latest instruction is a build ask (_medium_build_ask)."""
    try:
        if not _team_medium_flag_on():
            return False
        if est is not None and est > _TEAM_MEDIUM_MAX_EST:
            return False
        return _medium_build_ask(_team_instruction(messages))
    except Exception:                                            # noqa: BLE001
        return False


def _team_clip(text, limit):
    text = str(text or "")
    if len(text) <= limit:
        return text
    head = int(limit * 0.6)
    tail = max(0, limit - head - 40)
    return text[:head] + "\n...[middle omitted]...\n" + (text[-tail:] if tail else "")


def _team_digest(messages, tools):
    """The specialists' input (<= ~6K tokens): the last real instruction, the
    last few tool results, tool NAMES only."""
    names = []
    for t in tools or ():
        if isinstance(t, dict):
            n = (t.get("function") or {}).get("name") or t.get("name")
            if n:
                names.append(str(n))
    results = []
    for m in reversed(messages or ()):
        if len(results) >= _TEAM_RESULTS:
            break
        if isinstance(m, dict) and m.get("role") in ("tool", "function"):
            results.append(ctxwin.message_text(m))
    parts = ["USER INSTRUCTION (latest):\n" + _team_clip(_team_instruction(messages) or "(none)",
                                                       _TEAM_INSTR_CHARS)]
    if results:
        parts.append("RECENT TOOL RESULTS (oldest first):")
        for i, r in enumerate(reversed(results), 1):
            parts.append("[%d]\n%s" % (i, _team_clip(r or "(empty)", _TEAM_RESULT_CHARS)))
    parts.append("TOOLS THE ACTOR HAS (names only): %s" % (", ".join(names[:40]) or "none"))
    return "\n\n".join(parts)


def _orchestrate_brief(parts, limit=_TEAM_BRIEF_CHARS):
    """Deterministic merge of [(role, text)] into ONE brief: drop empty /
    'unknown' parts, dedupe lines across parts, order scout -> design -> risks,
    label each, clip to `limit` chars. No model call. "" when nothing is left."""
    by_role = {}
    for role, text in parts or ():
        if role in _TEAM_ORDER and role not in by_role:
            by_role[role] = str(text or "")
    seen, sections = set(), []
    for role in _TEAM_ORDER:
        text = re.sub(r"<think>.*?</think>", "", by_role.get(role, ""), flags=re.S | re.I)
        lines = []
        for raw in text.splitlines():
            line = raw.rstrip()
            norm = re.sub(r"[\W_]+", " ", line).strip().lower()
            if not norm or norm in ("unknown", "none", "n a") or norm in seen:
                continue
            seen.add(norm)
            lines.append(line)
        if lines:
            sections.append((role, lines))
    if not sections:
        return ""
    remaining = limit - len(_TEAM_HEADER) - 2
    out = [_TEAM_HEADER]
    for i, (role, lines) in enumerate(sections):
        share = max(0, remaining // (len(sections) - i))
        block = _TEAM_LABELS[role] + ":\n" + "\n".join(lines)
        if len(block) > share:
            block = block[:max(0, share - 1)].rstrip() + "…"
        if len(block) < 12:
            continue
        out.append(block)
        remaining -= len(block) + 2
    if len(out) == 1:
        return ""
    return "\n\n".join(out)[:limit]


def _with_team_notes(messages, brief):
    """`messages` plus ONE system message holding the brief, placed after the
    leading system messages. A new list; the originals are untouched."""
    msgs = list(messages or ())
    i = 0
    while i < len(msgs) and isinstance(msgs[i], dict) and msgs[i].get("role") in (
            "system", "developer"):
        i += 1
    msgs.insert(i, {"role": "system", "content": brief})
    return msgs


def _team_key(body, messages):
    k = None
    try:
        k = _orch_key(body, messages)
    except Exception:                                            # noqa: BLE001
        k = None
    if k:
        return str(k)
    first = ""
    for m in messages or ():
        if ctxwin.is_real_instruction(m):
            first = ctxwin.instruction_text(ctxwin.message_text(m))
            break
    return "h:" + hashlib.sha1(first.encode("utf-8", "ignore")).hexdigest()


def _team_hash(text):
    return hashlib.sha1(str(text or "").encode("utf-8", "ignore")).hexdigest()


def _team_assistants(messages):
    return sum(1 for m in messages or () if isinstance(m, dict) and m.get("role") == "assistant")


_TEAM_DROP_SECONDS = 1800.0     # a specialist that failed 2 of its last 3 rests this long
_TEAM_STATS_EVENTS = 20
_TEAM_STATS_SEED_ROWS = 500
_TEAM_UNKNOWN_P50 = 20.0
_team_stats = {}                # (pid, model) -> [(ts, role, ok, secs)]
_team_stats_lock = threading.Lock()
_team_stats_seeded = [False]


def _split_label(label):
    """(pid, model) from a 'pid/model' label (the model may hold slashes)."""
    if isinstance(label, str) and "/" in label:
        p, m = label.split("/", 1)
        return p, m
    return None


def _team_stats_note(pid, model, role, ok, secs, ts=None):
    """File one specialist call. Never raises."""
    if not ok and _local_net_failed(pid, model):
        return          # this computer's network, not the specialist's record
    try:
        with _team_stats_lock:
            lst = _team_stats.setdefault((pid, model), [])
            lst.append((float(ts if ts is not None else time.time()), str(role), bool(ok),
                        float(secs or 0.0)))
            del lst[:-_TEAM_STATS_EVENTS]
    except Exception:                                            # noqa: BLE001
        pass


def _team_stats_seed(path=None, force=False):
    """Seed the specialist (and verifier) ledgers from the last
    _TEAM_STATS_SEED_ROWS rows of turn-roles.jsonl, once per process. Never
    raises; a missing or unreadable file seeds nothing."""
    if _team_stats_seeded[0] and not force:
        return
    _team_stats_seeded[0] = True
    try:
        path = path or os.path.join(config.state_dir(), _ROLE_LOG_NAME)
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            lines = f.readlines()[-_TEAM_STATS_SEED_ROWS:]
    except Exception:                                            # noqa: BLE001
        return
    for line in lines:
        try:
            row = json.loads(line)
        except ValueError:
            continue
        if not isinstance(row, dict):
            continue
        ts = row.get("ts")
        for sp in row.get("specialists") or ():
            pair = _split_label(sp.get("model")) if isinstance(sp, dict) else None
            if pair:
                _team_stats_note(pair[0], pair[1], sp.get("role"), sp.get("ok"),
                                 float(sp.get("ms") or 0) / 1000.0, ts)
        pair = _split_label(row.get("verifier"))
        verdict = str(row.get("verdict") or "")
        if pair and verdict and not verdict.startswith(("skipped", "no verifier")):
            _verifier_stats_note(pair[0], pair[1], verdict.split(" ")[0] in ("ok", "revise"), ts)


def _team_events(pid, model):
    _team_stats_seed()
    with _team_stats_lock:
        return list(_team_stats.get((pid, model)) or ())


def _team_rate(pid, model):
    """Answered rate with a Beta(1,1) prior: (answered + 1) / (calls + 2)."""
    ev = _team_events(pid, model)
    return (sum(1 for e in ev if e[2]) + 1.0) / (len(ev) + 2.0)


def _team_p50(pid, model):
    """Median seconds of its ANSWERED calls, _TEAM_UNKNOWN_P50 when none."""
    secs = sorted(e[3] for e in _team_events(pid, model) if e[2])
    return secs[len(secs) // 2] if secs else _TEAM_UNKNOWN_P50


def _team_recently_failing(pid, model, now=None):
    """Failed >= 2 of its last 3 specialist calls, the latest failure within
    _TEAM_DROP_SECONDS of `now`: out of the team pool for those 30 minutes."""
    ev = _team_events(pid, model)[-3:]
    fails = [e for e in ev if not e[2]]
    if len(fails) < 2:
        return False
    now = time.time() if now is None else now
    return now - max(e[0] for e in fails) < _TEAM_DROP_SECONDS


def _team_rank(rows):
    """[(pid, model, score)] best-first -> the specialists' pool: recently
    failing pairs dropped, and INSIDE the top band (_AUTO_TOP_BAND of the
    best score) re-ordered by answered rate, then p50 latency. Slots outside
    the band keep their place. Never raises."""
    rows = list(rows or ())
    try:
        rows = [r for r in rows if not _team_recently_failing(r[0], r[1])]
        if len(rows) < 2:
            return rows
        best = max(float(r[2]) for r in rows)
        band = [i for i, r in enumerate(rows) if float(r[2]) >= best - _AUTO_TOP_BAND]
        ranked = sorted(band, key=lambda i: (-_team_rate(rows[i][0], rows[i][1]),
                                             _team_p50(rows[i][0], rows[i][1]), i))
        out = list(rows)
        for slot, i in zip(band, ranked):
            out[slot] = rows[i]
        return out
    except Exception:                                            # noqa: BLE001
        return rows


_verifier_stats = {}            # (pid, model) -> [(ts, usable)]


def _verifier_stats_note(pid, model, usable, ts=None):
    if not usable and _local_net_failed(pid, model):
        return          # this computer's network, not the verifier's record
    try:
        with _team_stats_lock:
            lst = _verifier_stats.setdefault((pid, model), [])
            lst.append((float(ts if ts is not None else time.time()), bool(usable)))
            del lst[:-_TEAM_STATS_EVENTS]
    except Exception:                                            # noqa: BLE001
        pass


def _verifier_rate(pid, model):
    """Usable-verdict rate with a Beta(1,1) prior."""
    _team_stats_seed()
    with _team_stats_lock:
        ev = list(_verifier_stats.get((pid, model)) or ())
    return (sum(1 for e in ev if e[1]) + 1.0) / (len(ev) + 2.0)


def _rank_verifier_pool(pool):
    """[(pid, model, score)] with the scores of the top-band members replaced
    by 1000 + 100 x usable-verdict rate + 0.01 x score, so verify.pick_verifier
    (family, identity, provider, THEN score) breaks its last tie by measured
    usable verdicts -- family diversity still comes first, and nothing outside
    the band can win a tie. Never raises."""
    pool = list(pool or ())
    try:
        if len(pool) < 2:
            return pool
        best = max(float(e[2]) for e in pool)
        out = []
        for e in pool:
            sc = float(e[2])
            if sc >= best - _AUTO_TOP_BAND:
                sc = 1000.0 + 100.0 * _verifier_rate(e[0], e[1]) + 0.01 * sc
            out.append((e[0], e[1], sc))
        return out
    except Exception:                                            # noqa: BLE001
        return pool


def _team_pick(chain, routed, kind, n):
    """Up to `n` (pid, model) of DIFFERENT identities, best first, preferring a
    new provider AND a new family, then a new provider, then any new identity.
    The routed (actor) pair, subscriptions, sick pairs and last-resort families
    are left out. The bandit nudge only reorders inside the top band."""
    rows = [r for r in _role_candidates(chain, routed, kind=kind)
            if not _is_low_quality(r[1])][:10]
    cands = [(p, m) for (p, m, _s) in _team_rank(rows)]
    fam = _verify_family() or (lambda m: _normalize_model_identity(m))
    chosen, fams, pids, ids = [], set(), set(), set()
    for need in ("both", "pid", "identity"):
        for p, m in cands:
            if len(chosen) >= n:
                break
            ident = _normalize_model_identity(m)
            if (p, m) in chosen or ident in ids:
                continue
            try:
                f = fam(m)
            except Exception:                                    # noqa: BLE001
                f = ident
            if need == "both" and (f in fams or p in pids):
                continue
            if need == "pid" and p in pids:
                continue
            chosen.append((p, m))
            fams.add(f)
            pids.add(p)
            ids.add(ident)
    return chosen


def _team_start(i, role, pid, model, digest, deadline, q, est):
    """One read-only, non-streamed specialist call on its own hop token.
    Puts (i, result dict) on `q`; returns the token."""
    tok = clientgone.child("team-%s" % role)
    payload = {"model": model, "stream": False, "max_tokens": _TEAM_MAX_TOKENS,
               "messages": [{"role": "system", "content": _TEAM_SYSTEM[role]},
                            {"role": "user", "content": digest}],
               "_no_craft": True}                    # stripped in _upstream_chat

    def _go():
        t0 = time.monotonic()
        res = {"ok": False, "why": "failed", "text": ""}
        try:
            resp, exc = _dispatch_chat_with_deadline(pid, payload, deadline)
            if resp is None:
                if exc is not None:
                    _swarm_note_member_exc(pid, model, exc)
                    res["why"] = "error: %s" % type(exc).__name__
                else:
                    res["why"] = "no answer"
            else:
                try:
                    if resp.status_code != 200:
                        _swarm_note_member_status(pid, model, resp.status_code)
                        res["why"] = "HTTP %s" % resp.status_code
                    else:
                        data = resp.json() or {}
                        text = str(_message_text(
                            ((data.get("choices") or [{}])[0].get("message") or {})) or "")
                        if len(text.strip()) < 20 or "<|" in text:
                            res["why"] = "empty"
                        else:
                            _record_chat_usage(pid, model, data, est)
                            res.update(ok=True, text=text, why="")
                except (ValueError, AttributeError):
                    res["why"] = "unreadable"
                finally:
                    try:
                        resp.close()
                    except Exception:                            # noqa: BLE001
                        pass
        except Exception as e:                                   # noqa: BLE001
            res["why"] = "error: %s" % type(e).__name__
        res["secs"] = round(time.monotonic() - t0, 2)
        q.put((i, res))
    run = _pipeline_bound(_carry_usage_source(lambda: clientgone.run_as(tok, _go)))
    threading.Thread(target=run, daemon=True, name="team-%s" % role).start()
    return tok


def _team_run(messages, tools, jobs, deadline, rec, rows):
    """Run the specialists in PARALLEL; return [(role, text)] of those that
    answered. Cancels every leg when the client leaves or time runs out."""
    digest = _team_digest(messages, tools)
    d_est = _est_tokens([{"role": "user", "content": digest}]) + 200
    q = queue.Queue()
    toks, pending = {}, set()
    for i, (role, pid, model) in enumerate(jobs):
        toks[i] = _team_start(i, role, pid, model, digest, deadline, q, d_est)
        pending.add(i)
        rec["calls"] += 1
        rec["sent_tokens"] += d_est
    results = {}
    end = time.monotonic() + deadline
    while pending:
        if _client_gone():
            for j in pending:
                toks[j].cancel("client disconnected")
            return []
        left = end - time.monotonic()
        if left <= 0:
            break
        try:
            i, res = q.get(timeout=min(0.05, left))
        except queue.Empty:
            continue
        pending.discard(i)
        results[i] = res
    for j in pending:
        toks[j].cancel("specialist out of time")
        results[j] = {"ok": False, "why": "no answer in time", "text": "", "secs": deadline}
        if not _client_gone():
            _note_recent_hop_failure(jobs[j][1], jobs[j][2], "deadline")
    parts = []
    for i, (role, pid, model) in enumerate(jobs):
        res = results.get(i) or {"ok": False, "why": "no answer", "secs": 0}
        label = "%s/%s" % (pid, model)
        if not _client_gone():
            _team_stats_note(pid, model, role, res.get("ok"), res.get("secs"))
        rec["specialists"].append({"role": role, "model": label, "ok": bool(res["ok"]),
                                   "ms": int(float(res.get("secs") or 0) * 1000),
                                   "why": res.get("why") or ""})
        rows.append({"role": "specialist: %s%s" % (
            role, "" if res["ok"] else ": %s" % (res.get("why") or "failed")), "model": label})
        if res["ok"]:
            parts.append((role, res["text"]))
    return parts


def _team_notes_for_turn(body, messages, chain, routed, est, real, kind, rec, rows, turn_end):
    """The body the ACTOR gets: the original, or with one TEAM NOTES system
    message. Fail-open; never raises."""
    try:
        if not _team_flag_on():
            return body
        key = _team_key(body, messages)
        instr_h = _team_hash(_team_instruction(messages))
        asst = _team_assistants(messages)
        with _team_cache_lock:
            ent = _team_cache.get(key)
        fresh = _team_fresh(messages)
        if ent and 0 <= asst - ent["assistants"] <= _TEAM_CACHE_TURNS:
            if ent["instr"] == instr_h and ent["brief"]:
                rec["team"] = "cached"
                rec["brief_chars"] = len(ent["brief"])
                return dict(body, messages=_with_team_notes(messages, ent["brief"]))
            if fresh:
                rec["team"] = "skipped (recent brief)"
            return body
        if not _specialists_wanted(body, kind, est=est, real=real):
            return body
        if turn_end - time.monotonic() < _TEAM_MIN_ROOM:
            return body
        goal = _team_instruction(messages)
        n = _TEAM_MAX_SPECIALISTS
        want_design = bool(craft.is_web_ui(goal) or _FAST_PATH_CREATE_RE.search(goal or ""))
        roles = ["scout", "designer", "critic"] if want_design else ["scout", "critic"]
        if real != "hard":
            roles = ["scout", "critic"]           # a MEDIUM turn: at most two
            rec["team_tier"] = "medium"
        picks = _team_pick(chain, routed, kind, min(n, len(roles)))
        if len(picks) < 2:
            rec["team"] = "no distinct models"
            return body
        jobs = [(r, p, m) for r, (p, m) in zip(roles, picks)]
        deadline = min(_TEAM_HOP_SECONDS, turn_end - time.monotonic() - 5.0)
        parts = _team_run(messages, body.get("tools"), jobs, deadline, rec, rows)
        rec["specialists_ok"] = len(parts)
        brief = _orchestrate_brief(parts)
        rec["brief_chars"] = len(brief)
        if _client_gone() or not brief:
            return body
        with _team_cache_lock:
            _team_cache[key] = {"brief": brief, "instr": instr_h, "assistants": asst,
                                "ts": time.time()}
            if len(_team_cache) > 200:
                for k in sorted(_team_cache, key=lambda x: _team_cache[x]["ts"])[:50]:
                    _team_cache.pop(k, None)
        rec["team"] = "ran"
        _log.info("[team] %d/%d specialist(s) answered, brief %d chars", len(parts),
                  len(jobs), len(brief))
        return dict(body, messages=_with_team_notes(messages, brief))
    except Exception as exc:                                     # noqa: BLE001
        _log.warning("[team] notes skipped: %s", exc)
        return body


def _single_turn_team_notes(messages, tools, chain, routed, est, diff, pinned, stream):
    """Gap 2 (CLI/Build parity): TEAM NOTES for a SINGLE-MODEL (auto/best/mode)
    HARD, fresh-instruction TOOL turn -- the parallel specialists run BEFORE
    the actor and their brief is injected into the request actually sent, so
    the stream path needs no buffering. Returns the messages to send (the
    originals unchanged when nothing applies). Flag tool_turn_specialists_single
    (default on) plus the existing _team_flag_on / _specialists_wanted gates.
    Never changes routing or the chain; never raises."""
    try:
        if not messages or not tools or pinned:
            return messages                  # tool turns on auto/best only
        if not config.get_flag("tool_turn_specialists_single", True):
            return messages
        if not _team_flag_on():
            return messages
        body = {"messages": messages, "tools": tools}
        real = diff if diff in ("simple", "medium", "hard") else None
        if real is None:
            try:
                real = _classify_difficulty(messages, None)
            except Exception:                                    # noqa: BLE001
                real = None
        kind = _task_kind(real or "hard", True, est)
        started = time.monotonic()
        rec = {"event": "turn", "turn": "tool", "kind": kind, "difficulty": real,
               "input_tokens": est, "sent_tokens": 0, "stream": bool(stream), "calls": 0,
               "actor": None, "actor_hops": 0, "served": None, "failed": [], "invalid": 0,
               "specialists": [], "specialists_ok": 0, "brief_chars": 0, "team": None,
               "single": True}
        turn_end = started + float(_SWARM_TOOL_STREAM_DEADLINE if stream
                                   else _SWARM_TOOL_HOP_DEADLINE)
        try:
            at = getattr(g, "hub_deadline_at", None)
        except Exception:                                        # noqa: BLE001
            at = None
        if isinstance(at, (int, float)):
            turn_end = min(turn_end, at)
        rows = []
        abody = _team_notes_for_turn(body, messages, chain, routed, est, real, kind,
                                     rec, rows, turn_end)
        if rec.get("specialists") or rec.get("team") in ("ran", "cached"):
            rec["latency_s"] = round(time.monotonic() - started, 2)
            _role_log(rec)
        new = abody.get("messages") if isinstance(abody, dict) else None
        return new if new else messages
    except Exception:                                            # noqa: BLE001
        return messages


@_usage_source_as("swarm")
def _tool_turn_roles(body):
    """A swarm/crew*/multi TOOL turn as ROLES (see the block comment above):
    (data, headers) -- `data` an ordinary OpenAI chat completion -- or None
    when no actor delivered, so the caller falls back to single-model `best`
    routing. Never raises."""
    messages = body.get("messages") or []
    tools = body.get("tools")
    stream = bool(body.get("stream"))
    started = time.monotonic()
    est = _est_tokens(messages, tools)
    try:
        real = _classify_difficulty(messages, body.get("max_tokens"))
    except Exception:                                            # noqa: BLE001
        real = None
    kind = _task_kind(real or "hard", True, est)
    rec = {"event": "turn", "turn": "tool", "kind": kind, "difficulty": real,
           "input_tokens": est, "sent_tokens": 0, "stream": stream, "calls": 0,
           "actor": None, "actor_hops": 0, "nudge": None, "hedge": None,
           "verifier": None, "verdict": None, "severity": None, "corrector": None,
           "corrected": False, "served": None, "failed": [], "invalid": 0,
           "specialists": [], "specialists_ok": 0, "brief_chars": 0, "team": None,
           "verifier_unparsed": 0, "verifier_retry": 0}
    token = _TASK_KIND_CV.set(kind)
    try:
        return _tool_turn_roles_run(body, messages, tools, stream, est, real, kind, rec,
                                    started)
    except Exception as exc:                                     # noqa: BLE001
        _log.warning("[roles] tool turn failed inside the hub: %s", exc)
        rec["outcome"] = "error: %s" % type(exc).__name__
        return None
    finally:
        _TASK_KIND_CV.reset(token)
        rec["latency_s"] = round(time.monotonic() - started, 2)
        if _client_gone():
            rec["outcome"] = "client gone"
        _role_log(rec)


def _tool_turn_roles_run(body, messages, tools, stream, est, real, kind, rec, started):
    pid, resolved, _d = _route_by_difficulty(messages, body.get("max_tokens"), est,
                                             require_tools=True,
                                             force_difficulty="hard")
    if not pid:
        rec["outcome"] = "no route"
        return None
    # A LOCAL SUBSCRIPTION CANNOT EMIT A TOOL CALL (see _swarm_tool_result).
    chain = [(e[0], e[1]) for e in _build_chain(pid, resolved, est, require_tools=True,
                                                 messages=messages)
             if not _is_sub(e[0])]
    if not chain:
        rec["outcome"] = "no candidate"
        return None
    rec["routed"] = "%s/%s" % (pid, resolved)
    # A stream's turn must finish under the client's header timeout (see
    # _SWARM_TOOL_STREAM_DEADLINE); the clock below also starts the REQUEST
    # clock, so a fallback after an empty turn shares it.
    clock = _ChainClock(tools=True, est=est, stream=stream)
    turn_end = started + float(_SWARM_TOOL_STREAM_DEADLINE if stream
                               else _SWARM_TOOL_HOP_DEADLINE)
    if clock.deadline_at is not None:
        turn_end = min(turn_end, clock.deadline_at)
    # Pairs resting after 3 empty/junk 200s go to the TAIL (kept, never dropped).
    chain = ([e for e in chain if not _empty_resting(e[0], e[1])]
             + [e for e in chain if _empty_resting(e[0], e[1])])
    clock.plan_tool_hedge(chain)
    rows, served, hops = [], None, 0
    spent = []          # every pair dispatched to: kept off the verifier pool
    abody = _team_notes_for_turn(body, messages, chain, (pid, resolved), est, real, kind,
                                 rec, rows, turn_end)
    for hop_pid, hop_model in clock.walk(chain):
        if _client_gone():
            break
        if clock.consumed(hop_pid, hop_model):
            continue                    # the backup already ran it
        if not _window_fits(hop_pid, hop_model, est):
            # Its KNOWN window cannot hold this request: dispatching to it only
            # burns an actor hop on a _ContextOverflow (MEASURED 2026-10-07:
            # groq/qwen3.8-27b, ~8K TPM, on a 79K turn). Skip it WITHOUT
            # spending a hop; when nothing left fits the walk ends fast and the
            # caller falls back to `best`, which emits the native overflow reply.
            rows.append({"role": "actor: skipped (window too small)",
                         "model": "%s/%s" % (hop_pid, hop_model)})
            rec["failed"].append({"pair": "%s/%s" % (hop_pid, hop_model),
                                  "why": "window too small for ~%d tokens" % est})
            continue
        if hops >= _ROLE_MAX_ACTOR_HOPS or time.monotonic() >= turn_end - 1.0:
            break
        hops += 1
        if rec["actor"] is None:
            rec["actor"] = "%s/%s" % (hop_pid, hop_model)
            rec["nudge"] = round(_bandit_delta(kind, hop_pid, hop_model,
                                               _benchmark_score(hop_pid, hop_model)), 3)
        served = _role_actor_hop(clock, abody, hop_pid, hop_model, est, kind, rec, rows,
                                 turn_end, spent,
                                 attempts_left=max(1, min(3, _ROLE_MAX_ACTOR_HOPS - hops + 1)))
        if served:
            break
    rec["actor_hops"] = hops
    if _client_gone():
        return None          # the client left: the caller replies 499 (clientgone)
    if not served:
        rec["outcome"] = "no answer"
        _log.warning("[roles] no actor delivered in %d hop(s), %.0fs -> %s", hops,
                     time.monotonic() - started,
                     "; ".join("%s: %s" % (f["pair"], f["why"]) for f in rec["failed"][:6]))
        _role_activity(rows, "swarm (roles)")
        return None
    spid, smodel, data, msg = served
    _ensure_tool_call_ids(msg)
    # A model that FAILED, STALLED or lost the stall race this turn is not a
    # second opinion -- keep every pair we already dispatched to off the
    # verifier pool (the producer is excluded by verify.pick_verifier anyway).
    excluded = list({tuple(f["pair"].split("/", 1)) for f in rec["failed"]} | set(spent))
    corrected = _role_verify_and_correct(body, messages, (spid, smodel), msg, chain, kind,
                                         real, rec, rows, turn_end, est, tool_turn=True,
                                         failed=excluded)
    if corrected:
        spid, smodel, data, msg = corrected
        _ensure_tool_call_ids(msg)
    if _client_gone():
        return None
    _bandit_remember(msg.get("tool_calls"), spid, smodel, kind)
    rec["served"] = "%s/%s" % (spid, smodel)
    rec["outcome"] = "tool call" if msg.get("tool_calls") else "text"
    _log.info("[roles] %s/%s served after %d actor hop(s), %d call(s)%s%s%s", spid, smodel,
              hops, rec["calls"], ", backup %s" % rec["hedge"] if rec["hedge"] else "",
              ", verifier %s: %s" % (rec["verifier"], rec["verdict"]) if rec["verifier"] else "",
              ", corrected" if rec["corrected"] else "")
    _role_activity(rows, "swarm (roles)")
    data["model"] = spid + "/" + smodel
    hdrs = _routing_headers(spid, smodel, rec["calls"], None)
    hdrs["X-Free-LLM-Hub-Roles"] = _roles_header(rec)
    return data, hdrs


def _max_text_review(tier, difficulty, has_tools, messages, pid, model, data, chain, est,
                     max_tokens=None, usage_est=None):
    """Max tier (best/max), HARD, NON-streamed TEXT answer: the same verifier
    (+ one corrector on a high-severity revise) as a risky tool step. Never on
    streamed or Normal turns. Returns (pid, model, data) when a correction
    replaced the answer, else None (serve it as is). Fail-open; never raises."""
    try:
        if has_tools or difficulty != "hard" or _client_gone():
            return None
        if str(tier or "").strip().lower() not in ("best", "max"):
            return None
        if _verify() is None or not config.get_flag("turn_verifier", True):
            return None
        msg = ((data.get("choices") or [{}])[0].get("message") or {})
        if msg.get("tool_calls") or not str(_message_text(msg) or "").strip():
            return None
        started = time.monotonic()
        kind = _task_kind(difficulty, False, est)
        rec = {"event": "turn", "turn": "text", "kind": kind, "difficulty": difficulty,
               "input_tokens": est, "sent_tokens": 0, "stream": False, "calls": 0,
               "actor": "%s/%s" % (pid, model), "actor_hops": 1, "hedge": None,
               "verifier": None, "verdict": None, "severity": None, "corrector": None,
               "corrected": False, "served": "%s/%s" % (pid, model), "failed": [],
               "invalid": 0}
        try:
            at = getattr(g, "hub_deadline_at", None)
        except Exception:                                        # noqa: BLE001
            at = None
        turn_end = started + float(_SWARM_HOP_DEADLINE)
        if isinstance(at, (int, float)):
            turn_end = min(turn_end, at)
        rows = [{"role": "actor", "model": "%s/%s" % (pid, model)}]
        body = {"messages": messages}
        if max_tokens:
            body["max_tokens"] = max_tokens
        out = _role_verify_and_correct(body, messages, (pid, model), msg,
                                       [tuple(e[:2]) for e in (chain or ())], kind,
                                       difficulty, rec, rows, turn_end, est, tool_turn=False)
        rec["latency_s"] = round(time.monotonic() - started, 2)
        if rec.get("verifier"):
            _role_activity(rows, "max (verified)")
        if out:
            cp, cm, cdata, _cmsg = out
            rec["served"] = "%s/%s" % (cp, cm)
            _ctx_fix_chat_usage(cdata, usage_est or est, cp, cm)
            cdata["model"] = cp + "/" + cm
            _role_log(rec)
            return cp, cm, cdata
        if rec.get("verifier"):
            _role_log(rec)
        return None
    except Exception:                                            # noqa: BLE001
        return None


def _verify_family():
    """verify.family (model id -> family name), for the pipelines' own
    verifier choice (swarm.run / crews.run / swarm_windows.start), or None."""
    v = _verify()
    fam = getattr(v, "family", None) if v is not None else None
    return fam if callable(fam) else None


def _pipeline_search_on():
    """Flag `pipeline_search` (default ON): wider-or-deeper retries."""
    try:
        return bool(config.get_flag("pipeline_search", True))
    except Exception:                                            # noqa: BLE001
        return True


def _pipeline_check_kwargs():
    """swarm.run / crews.run kwargs for the reviewer family and the search.
    {} when verify is absent and the flag is off (the pipeline exactly as
    before); never raises."""
    out = {}
    try:
        fam = _verify_family()
        if fam is not None:
            out["family"] = fam
        if _pipeline_search_on():
            out["search"] = True
        if _distinct_models_on():
            out["ledger"] = True
        if _verify() is not None and config.get_flag("swarm_phase_verdict", True):
            out["free_verdict"] = _free_verdict
    except Exception:                                            # noqa: BLE001
        return {}
    return out


# ========================================================================= #
# Heartbeats and budgets (2026-10-07; owner: Paperclip-style heartbeats +
# per-run budgets). A self-contained section: the per-session spend ledger
# (so a run's budget is MEASURED from its worker sessions), the budget kwargs
# injected into the Multi start path, the conversation spend cap, the heartbeat
# scheduler wiring and the three routes. Hook points elsewhere are named
# "BUDGET:" / "HEARTBEAT:".
# ========================================================================= #

# -- per-(build) session spend ledger --------------------------------------- #
# Every hub-launched agent session (a Multi worker included) reaches the hub as
# /build/<session_id>/... (_BuildPrefix), so _build_sid() names the session a
# request arrived under. The usage hooks (_record_chat_usage / _record_sse_usage)
# add each request's tokens here; _run_spent sums a run's worker sessions, and a
# conversation's own cap reads its session directly. This is the hub's OWN usage
# accounting -- measured, never a guess.
_SESSION_SPEND = {}
_session_spend_lock = threading.Lock()
_SESSION_SPEND_MAX = 2000


def _note_session_spend(sid, prompt_tokens=0, completion_tokens=0):
    """Add one request's tokens (and one call) to a build session's running
    total. No session (terminal CLI, off-request) files nothing. Never raises."""
    if not sid:
        return
    try:
        tok = max(0, int(prompt_tokens or 0)) + max(0, int(completion_tokens or 0))
    except (TypeError, ValueError):
        tok = 0
    try:
        with _session_spend_lock:
            rec = _SESSION_SPEND.get(sid)
            if rec is None:
                if len(_SESSION_SPEND) >= _SESSION_SPEND_MAX:
                    _SESSION_SPEND.pop(next(iter(_SESSION_SPEND)), None)
                rec = {"tokens": 0, "calls": 0}
                _SESSION_SPEND[sid] = rec
            rec["tokens"] += tok
            rec["calls"] += 1
    except Exception:                                            # noqa: BLE001
        pass


def _session_spend(sid):
    with _session_spend_lock:
        rec = _SESSION_SPEND.get(sid)
        return {"tokens": rec["tokens"], "calls": rec["calls"]} if rec \
            else {"tokens": 0, "calls": 0}


def _run_spent(run_id):
    """{tokens, calls} spent by a Multi run, summed over its worker sessions
    (swarm_windows.worker_session_ids -- retried workers' past sessions too).
    Injected into swarm_windows.start/resume so a budget is measured. Never
    raises (a budget that cannot be measured simply never trips)."""
    try:
        run = swarm_windows.get(run_id)
        if run is None:
            return {"tokens": 0, "calls": 0}
        tokens = calls = 0
        for sid in swarm_windows.worker_session_ids(run):
            s = _session_spend(sid)
            tokens += s["tokens"]
            calls += s["calls"]
        return {"tokens": tokens, "calls": calls}
    except Exception:                                            # noqa: BLE001
        return {"tokens": 0, "calls": 0}


# BUDGET: register the spend accountant now that _run_spent exists, so every
# run measures its token/call spend without any call site threading it through.
swarm_windows.set_spent_counter(_run_spent)


def _multi_budget_kwargs(session_id=None):
    """BUDGET: swarm_windows.start / resume kwargs. The run's cap: the
    conversation's own cap when it set one, else the multi_default_budget
    setting (None = unlimited, as today). Empty when nothing is capped -- so a
    run with no budget calls start()/resume() exactly as before. The spend
    accountant is a module hook (swarm_windows.set_spent_counter(_run_spent)),
    not a per-call kwarg."""
    cap = None
    if session_id:
        try:
            cap = agentic_history.budget(session_id)
        except Exception:                                        # noqa: BLE001
            cap = None
    if cap is None:
        try:
            cap = config.get_json("multi_default_budget", None)
        except Exception:                                        # noqa: BLE001
            cap = None
    b = swarm_windows.normalize_budget(cap) if isinstance(cap, dict) else None
    return {"budget": b} if b else {}


# -- the per-conversation spend cap (plain /agent Build turns) --------------- #
def _conversation_budget(session_id):
    """{cap, spent, reached, message} for a conversation's OPTIONAL spend cap
    (tokens/calls, measured from its session). No cap = never reached."""
    try:
        cap = agentic_history.budget(session_id)
    except Exception:                                            # noqa: BLE001
        cap = None
    spent = _session_spend(session_id)
    if not isinstance(cap, dict) or not cap:
        return {"cap": None, "spent": spent, "reached": False, "message": None}
    reached, reason, msg = swarm_windows.budget_check(
        swarm_windows.normalize_budget(cap), spent)
    return {"cap": cap, "spent": spent, "reached": reached,
            "reason": reason, "message": msg}


def _conversation_budget_block(session_id):
    """(status, detail) when a plain /agent turn must be refused for its cap,
    else None. Terminal CLIs have no build session, so they are never capped."""
    try:
        b = _conversation_budget(session_id)
    except Exception:                                            # noqa: BLE001
        return None
    if b.get("reached"):
        return (429, (b.get("message") or "Budget reached")
                + " — this conversation has reached its spend cap. "
                  "Raise or clear it in the conversation to continue.")
    return None


# -- heartbeat scheduler wiring --------------------------------------------- #
_HEARTBEAT = [None]
_HB_CONVO = {}                 # schedule id -> the conversation its runs belong to


def _hb_enabled():
    return config.get_flag("heartbeats_enabled", False)


def _hb_load():
    v = config.get_json("heartbeats", [])
    return v if isinstance(v, list) else []


def _hb_save(schedules):
    config.set_setting("heartbeats", list(schedules or []))


def _hb_state_get():
    v = config.get_json("heartbeat_state", {})
    return v if isinstance(v, dict) else {}


def _hb_state_set(state):
    config.set_setting("heartbeat_state", state if isinstance(state, dict) else {})


def _hb_busy(sched):
    """HEARTBEAT skip: the owner is working -- a live Multi run for this
    project, or any hub request in flight / finished in the last 60s."""
    try:
        project = (sched or {}).get("project_dir")
        for r in swarm_windows.list_runs():
            if r.get("state") in (swarm_windows.PENDING, swarm_windows.RUNNING) \
                    and (not project or r.get("project_dir") == project):
                return True
        now = time.time()
        with _activity_lock:
            for a in list(_activity):
                if a.get("finished") is None:
                    return True
                if (now - (a.get("finished") or 0)) <= 60:
                    return True
    except Exception:                                            # noqa: BLE001
        return True            # unsure = do not compete with the owner
    return False


def _hb_ram_ok():
    """HEARTBEAT skip: no room for a new run (the live RAM governor's rules)."""
    try:
        import lowres
        m = lowres.machine()
        free = m.get("free_gb")
        if free is None:
            return True
        return (free - lowres.reserve_gb(m)) >= 0.6
    except Exception:                                            # noqa: BLE001
        return True


def _hb_providers_ok():
    """HEARTBEAT skip: the providers are rate-limited (the Multi 429 back-off)."""
    try:
        info = swarm_windows.concurrency_info()
        return not (info.get("backoff") or info.get("limited_by") == "429s")
    except Exception:                                            # noqa: BLE001
        return True


def _hb_conversation(sched):
    """A conversation the schedule's runs belong to, so the Build page shows
    them and Continue/Stop work. Reused across beats; recreated if it was
    deleted. None when agentic chat is off or the project is gone."""
    sid = _HB_CONVO.get(sched.get("id"))
    if sid:
        try:
            if agentic_chat.get_session(sid) is not None \
                    or agentic_history.get_conversation(sid) is not None:
                return sid
        except Exception:                                        # noqa: BLE001
            pass
    project = sched.get("project_dir")
    if not project or not os.path.isdir(project):
        return None
    try:
        sid = agentic_chat.start_session(sched.get("cli") or "opencode", project,
                                         quality="multi", mode=sched.get("mode"))
    except Exception as exc:                                     # noqa: BLE001
        _log.warning("[heartbeat] could not open a conversation: %s", exc)
        return None
    try:
        agentic_history.set_title(sid, "Heartbeat %s" % sched.get("id"))
        agentic_history.set_quality(sid, "multi")
    except Exception:                                            # noqa: BLE001
        pass
    _HB_CONVO[sched.get("id")] = sid
    return sid


def _hb_start_run(sched, goal_text, tasks, budget):
    """HEARTBEAT: start ONE Multi run for the schedule's project with the open
    tasks as its goal, through the same path the Build page uses. Returns the
    run id, or None. owner = the conversation (so it shows up and Continue/Stop
    work); the heartbeat origin rides in the beat log and the title."""
    if not goal_text:
        return None
    project = sched.get("project_dir")
    cli_id = sched.get("cli") or "opencode"
    sid = _hb_conversation(sched)
    owner = sid or ("heartbeat:" + str(sched.get("id")))
    try:
        run_id = swarm_windows.start(
            goal_text, project, cli_id,
            _swarm_windows_spawn, _swarm_windows_turn,
            planner=_pipeline_bound(_swarm_windows_planner, sched.get("mode")),
            configure=_swarm_windows_configure,
            stop=agentic_chat.stop_session,
            modes=((sched["mode"],) if sched.get("mode") else _worker_mode_keys()),
            default_mode=sched.get("mode"),
            on_done=_multi_owner_record,
            owner=owner,
            budget=swarm_windows.normalize_budget(budget), spent=_run_spent,
            **_swarm_windows_manager_kw(), **_multi_check_kwargs())
    except Exception as exc:                                     # noqa: BLE001
        _log.warning("[heartbeat] run could not start: %s", exc)
        return None
    if sid and run_id:
        with _MULTI_LOCK:
            _MULTI_RUNS[sid] = run_id
    return run_id


def _heartbeat_scheduler():
    if _HEARTBEAT[0] is None:
        _HEARTBEAT[0] = heartbeat.Scheduler(
            load=_hb_load, state_get=_hb_state_get, state_set=_hb_state_set,
            enabled=_hb_enabled, busy=_hb_busy, ram_ok=_hb_ram_ok,
            providers_ok=_hb_providers_ok, start_run=_hb_start_run)
    return _HEARTBEAT[0]


def _start_heartbeat_scheduler():
    """HEARTBEAT boot: start the one daemon thread (no immediate beat). The
    kill switch (heartbeats_enabled, default OFF) is checked every tick, so the
    thread is cheap while there is nothing to do. Stubbed out in tests."""
    try:
        _heartbeat_scheduler().start()
    except Exception as exc:                                     # noqa: BLE001
        _log.warning("could not start the heartbeat scheduler: %s", exc)


@app.route("/api/heartbeats", methods=["GET", "POST"])
def api_heartbeats():
    """GET: the kill switch, every schedule, its next-due time, last beat and
    last skip reason. POST {"enabled": bool} flips the kill switch; POST a
    schedule spec (needs a readable `when` and a goal_id or project_dir) adds
    one."""
    if request.method == "GET":
        return jsonify(_heartbeat_scheduler().status())
    body = request.get_json(force=True, silent=True) or {}
    if "enabled" in body and len(body) == 1:
        config.set_flag("heartbeats_enabled", bool(body["enabled"]))
        return jsonify(_heartbeat_scheduler().status())
    schedules, sched = heartbeat.add(_hb_load(), body.get("schedule") or body)
    if sched is None:
        return _openai_error("a schedule needs a readable 'when' "
                             "(e.g. 'every 30 min', 'daily 09:00') and a "
                             "goal_id or project_dir", 400)
    _hb_save(schedules)
    return jsonify({"added": sched, **_heartbeat_scheduler().status()})


@app.route("/api/heartbeats/<hb_id>", methods=["PUT", "DELETE"])
def api_heartbeat_edit(hb_id):
    if request.method == "DELETE":
        schedules, removed = heartbeat.remove(_hb_load(), hb_id)
        if not removed:
            return _openai_error("no such schedule", 404)
        _hb_save(schedules)
        _HB_CONVO.pop(hb_id, None)
        return jsonify(_heartbeat_scheduler().status())
    patch = request.get_json(force=True, silent=True) or {}
    schedules, sched = heartbeat.update(_hb_load(), hb_id, patch)
    if sched is None:
        return _openai_error("no such schedule, or the change left it invalid", 400)
    _hb_save(schedules)
    return jsonify({"updated": sched, **_heartbeat_scheduler().status()})


@app.route("/api/budgets", methods=["GET"])
def api_budgets():
    """Spent vs cap for every live budgeted Multi run, and every conversation
    that set a spend cap."""
    runs = []
    try:
        for r in swarm_windows.list_runs():
            run = swarm_windows.get(r.get("run_id"))
            bv = swarm_windows.budget_view(run) if run is not None else None
            if bv:
                runs.append({"run_id": r.get("run_id"), "state": r.get("state"),
                             "project_dir": r.get("project_dir"),
                             "owner": r.get("owner"), "budget": bv})
    except Exception:                                            # noqa: BLE001
        pass
    conversations = []
    try:
        with _session_spend_lock:
            sids = list(_SESSION_SPEND.keys())
        for sid in sids:
            cap = agentic_history.budget(sid)
            if not isinstance(cap, dict) or not cap:
                continue
            b = _conversation_budget(sid)
            conversations.append({"session_id": sid, "cap": b["cap"],
                                  "spent": b["spent"], "reached": b["reached"]})
    except Exception:                                            # noqa: BLE001
        pass
    return jsonify({"runs": runs, "conversations": conversations})


def _multi_check_kwargs():
    """swarm_windows.start / resume / resume_interrupted kwargs: the free
    verdict (no manager needed) and the search. Same fail-open contract."""
    out = {}
    try:
        if _verify() is not None:
            out["free_verdict"] = _free_verdict
        if _pipeline_search_on():
            out["search"] = True
    except Exception:                                            # noqa: BLE001
        return {}
    return out


def _brief_producer(value):
    """(pid, model) from a (pid, model) pair or a "pid/model" string, else None."""
    if isinstance(value, (list, tuple)) and len(value) >= 2:
        return (str(value[0]), str(value[1]))
    if isinstance(value, str) and "/" in value:
        p, m = value.split("/", 1)
        return (p, m)
    return None


def _free_verdict(brief, producer=None):
    """A FREE cross-family verdict on one pipeline phase, for the pipelines'
    own review (swarm.run / crews.run / swarm_windows.start).

    `brief` is a dict: brief["text"] = the phase brief the verifier reads (the
    task and the phase's output); optional brief["producer"] = (pid, model) or
    "pid/model" of the model that wrote it (the verifier is then of ANOTHER
    family, verify.pick_verifier) and brief["avoid_families"]. A plain string
    or a message list is accepted too. Returns {"ok", "problems", "severity"}
    or None on ANY failure, timeout or unreadable verdict -- the pipeline then
    proceeds exactly as without it. A reply that could not be READ gets ONE
    retry on the next-best verifier with the strict one-line contract
    (verify.STRICT_VERIFIER_SYSTEM). Never raises."""
    v = _verify()
    if v is None or not brief or _client_gone():
        return None
    try:
        avoid = ()
        if isinstance(brief, dict):
            text = brief.get("text")
            producer = _brief_producer(brief.get("producer")) or producer
            avoid = tuple(brief.get("avoid_families") or ())
            if not str(text or "").strip():
                return None
            brief = str(text)
        producer = _brief_producer(producer)
        if isinstance(brief, list):
            base = list(brief)
        else:
            base = [{"role": "user", "content": str(brief)}]
        first = base[0].get("role") if base and isinstance(base[0], dict) else None
        probe = list(base)
        system = getattr(v, "VERIFIER_SYSTEM", None)
        if first != "system" and isinstance(system, str) and system.strip():
            probe.insert(0, {"role": "system", "content": system})
        est = _est_tokens(probe)
        pid, model, _d = _route_by_difficulty(probe, None, est,
                                              force_difficulty="medium")
        if not pid:
            return None
        pool = _rank_verifier_pool(_role_candidates(
            _avoid_families_last(_build_chain(pid, model, est), avoid),
            producer or (None, None)))
        t_end = time.monotonic() + 2.0 * _VERIFY_DEADLINE
        tried = set()
        for attempt in (0, 1):
            cand = [e for e in pool if (e[0], e[1]) not in tried]
            if producer:
                pick = v.pick_verifier(producer, cand)
            else:
                pick = cand[0][:2] if cand else None
            if not pick:
                return None
            tried.add((pick[0], pick[1]))
            messages = list(probe)
            if attempt:
                strict = getattr(v, "STRICT_VERIFIER_SYSTEM", None)
                if isinstance(strict, str) and strict.strip():
                    messages = [m for m in base if m.get("role") != "system"]
                    messages.insert(0, {"role": "system", "content": strict})
                else:
                    messages = list(probe) + [{"role": "user", "content":
                                               "Answer with ONE line: VERDICT: ACCEPT or "
                                               "VERDICT: REVISE - <problem>."}]
            payload = {"model": pick[1], "stream": False, "messages": messages,
                       "max_tokens": int(getattr(v, "VERIFY_MAX_TOKENS", 400) or 400),
                       "_no_craft": True}
            resp, _exc = _dispatch_chat_with_deadline(
                pick[0], payload, max(1.0, min(_VERIFY_DEADLINE, t_end - time.monotonic())))
            text, readable = "", False
            if resp is not None:
                try:
                    if resp.status_code != 200:
                        _swarm_note_member_status(pick[0], pick[1], resp.status_code)
                    else:
                        data = resp.json() or {}
                        text = _message_text(
                            ((data.get("choices") or [{}])[0].get("message") or {}))
                        if str(text or "").strip():
                            _record_chat_usage(pick[0], pick[1], data, est)
                except (ValueError, AttributeError):
                    pass
                finally:
                    try:
                        resp.close()
                    except Exception:                            # noqa: BLE001
                        pass
            verdict = v.parse_verdict(text) if str(text or "").strip() else None
            readable = (isinstance(verdict, dict) and "ok" in verdict
                        and not verdict.get("unparsed"))
            if not _client_gone():
                _verifier_stats_note(pick[0], pick[1], readable)
            if readable:
                return {"ok": bool(verdict.get("ok")),
                        "problems": list(verdict.get("problems") or []),
                        "severity": str(verdict.get("severity") or "low")}
            # Retry only a reply that arrived but could not be read.
            if resp is None or not str(text or "").strip() or t_end - time.monotonic() < 8.0:
                return None
        return None
    except Exception:                                            # noqa: BLE001
        return None


def _avoid_families_last(chain, avoid_families=()):
    """`chain` with every entry whose verify.family(model) is in
    `avoid_families` moved to the BACK (order kept on both sides). Never
    excludes anything; a no-op without the verify module or families.
    Never raises."""
    chain = list(chain or ())
    try:
        fams = {str(f).strip().lower() for f in (avoid_families or ()) if f}
        fam = _verify_family() if fams else None
        if not fams or fam is None:
            return chain
        keep, back = [], []
        for e in chain:
            try:
                f = str(fam(e[1]) or "").strip().lower()
            except Exception:                                    # noqa: BLE001
                f = ""
            (back if f and f in fams else keep).append(e)
        return keep + back
    except Exception:                                            # noqa: BLE001
        return chain


def _swarm_stream_chunks(data):
    """The finished answer as the chat.completion.chunk objects a stream would
    have carried: one content/tool_calls delta, then the finish_reason. The
    fan-out has already completed by the time anything streams, so there is
    nothing to interleave -- but a CLI still expects stream shape, and a
    tool_calls delta that goes missing here is a turn that writes no files."""
    _dedupe_tool_calls_json(data)
    out_msg = ((data.get("choices") or [{}])[0].get("message") or {})
    delta = {"role": "assistant"}
    if out_msg.get("content"):
        delta["content"] = out_msg["content"]
    calls = out_msg.get("tool_calls")
    if calls:
        # The fan-out's winner is a NON-streaming message, and that shape has no
        # `index`. Copying it into a delta verbatim shipped tool calls with the
        # field missing -- measured through the live hub as
        # "tool_call index is None (NoneType), must be int". One AI SDK build
        # defaults it, its sibling in the same binary does not.
        delta["tool_calls"] = [dict(tc, index=tc.get("index", i))
                               if isinstance(tc, dict) else tc
                               for i, tc in enumerate(calls)]
    base = {"id": data.get("id") or ("chatcmpl-swarm-" + uuid.uuid4().hex),
            "object": "chat.completion.chunk",
            "created": data.get("created") or int(time.time()),
            "model": data.get("model") or "swarm"}
    yield dict(base, choices=[{"index": 0, "delta": delta, "finish_reason": None}])
    fin = (data.get("choices") or [{}])[0].get("finish_reason") or "stop"
    # ...and a winner that called a tool must not report the turn as finished:
    # "stop" tells the CLI to stop, and the tool call it already parsed is
    # discarded silently. Same defect the relay repairs for upstreams.
    if calls and fin == "stop":
        fin = "tool_calls"
    yield dict(base, choices=[{"index": 0, "delta": {}, "finish_reason": fin}])


def _pipeline_usage(data, est, final):
    """The usage a pipeline tier (swarm / crew* / multi / compound) tool turn
    reports for the ORIGINAL request -- not the compacted payload its actor
    saw, and never zero. It reported neither before: the streamed replay
    carried no usage frame at all (Codex read input_tokens = 0), the JSON
    shapes carried the actor's raw upstream count, so a CLI on these tiers
    never saw its context fill up and never compacted.

    The actor is named by data["model"] ("pid/model"). final=True: the whole
    reporting pass (hop compaction ratio + live window steering) -- for a
    reply no translator touches again. final=False: the ratio only; the
    stream translator (_responses_stream / _anthropic_stream) steers once, so
    steering is not applied twice. Mutates and returns `data`; never raises."""
    try:
        if not isinstance(data, dict):
            return data
        pid, _sep, model = str(data.get("model") or "").partition("/")
        if not (pid and model):
            pid = model = None
        _ctx_fix_chat_usage(data, est, pid, model, steer=bool(final))
    except Exception:                                            # noqa: BLE001
        pass
    return data


def _swarm_usage_line(data):
    """The replayed answer's usage as one more SSE line (an OpenAI usage-only
    chunk), or None when the answer carries none."""
    u = data.get("usage") if isinstance(data, dict) else None
    if not isinstance(u, dict) or not u:
        return None
    return b"data: " + json.dumps({
        "id": data.get("id") or "chatcmpl-swarm", "object": "chat.completion.chunk",
        "created": data.get("created") or int(time.time()),
        "model": data.get("model") or "swarm", "choices": [], "usage": u}).encode("utf-8")


def _swarm_sse_lines(data):
    """The same chunks as the RAW BYTE LINES an upstream OpenAI SSE stream would
    have produced. _responses_stream and _anthropic_stream both already accept a
    line_iter (it exists for the first-byte peek), and both use `resp` for
    nothing else -- so replaying the swarm's answer through them gives codex and
    claude a correctly-shaped stream without a second translator per protocol."""
    for chunk in _swarm_stream_chunks(data):
        yield b"data: " + json.dumps(chunk).encode("utf-8")
        yield b""
    usage_line = _swarm_usage_line(data)
    if usage_line is not None:
        yield usage_line
        yield b""
    yield b"data: [DONE]"


def _swarm_tool_turn(body):
    """The /v1/chat/completions wrapper around _swarm_tool_result."""
    out = _swarm_tool_result(body)
    if out is None:
        return None
    data, hdrs = out
    _pipeline_usage(data, _est_tokens(body.get("messages"), body.get("tools")), True)
    if not body.get("stream"):
        return (jsonify(data), 200, hdrs)

    def _one_shot():
        for chunk in _swarm_stream_chunks(data):
            yield "data: %s\n\n" % json.dumps(chunk)
        usage_line = _swarm_usage_line(data)
        if usage_line is not None:
            yield usage_line.decode("utf-8") + "\n\n"
        yield "data: [DONE]\n\n"
    return Response(_one_shot(), mimetype="text/event-stream", headers=hdrs)


class _ReplayUpstream:
    """Stands in for the upstream HTTP response when replaying an ALREADY
    FINISHED answer -- the swarm's -- through one of the per-protocol SSE
    translators. They read raw byte lines and, at the very end, close() the
    upstream; there is no connection here to close, and passing None instead
    crashed the stream after every event had already been emitted."""

    def __init__(self, lines):
        self._lines = lines

    def iter_lines(self, decode_unicode=False):
        return iter(self._lines)

    def close(self):
        pass


def _swarm_as_responses(body, messages, tools, est):
    """The swarm's answer in the Responses shape codex speaks, or None.

    Streaming replays the finished answer through _responses_stream, the same
    translator a real upstream stream goes through -- it takes a line_iter (it
    exists for the first-byte peek) and uses `resp` for nothing else, so there
    is no second translator to keep in step."""
    out = _swarm_for(body, messages, tools, body.get("max_output_tokens"))
    if out is None:
        return None
    data, hdrs = out
    label = (body.get("model") or "").strip() or data.get("model") or "swarm"
    if not body.get("stream"):
        _pipeline_usage(data, est, True)
        return jsonify(_chat_to_responses(data, label)), 200, hdrs
    _pipeline_usage(data, est, False)       # _responses_stream steers once
    return Response(stream_with_context(
        _responses_stream(_ReplayUpstream(_swarm_sse_lines(data)), label,
                          prompt_est=est)),
        mimetype="text/event-stream", headers=dict(_SSE_HEADERS, **hdrs))


def _swarm_as_anthropic(body, oai_messages, tools):
    """The swarm's answer in the Anthropic shape claude speaks, or None."""
    out = _swarm_for(body, oai_messages, tools, body.get("max_tokens"))
    if out is None:
        return None
    data, hdrs = out
    label = (body.get("model") or "").strip() or data.get("model") or "swarm"
    est = _est_tokens(oai_messages, tools)
    if not body.get("stream"):
        _pipeline_usage(data, est, True)
        return jsonify(_openai_resp_to_anthropic(data, label)), 200, hdrs
    _pipeline_usage(data, est, False)       # _anthropic_stream steers once
    return Response(stream_with_context(
        _anthropic_stream(_ReplayUpstream(_swarm_sse_lines(data)), label, est)),
        mimetype="text/event-stream", headers=dict(_SSE_HEADERS, **hdrs))


def _swarm_for(body, messages, tools, max_tokens):
    """Run the tool-turn fan-out for a NON-chat-completions endpoint.

    Returns (data, headers) exactly as _swarm_tool_result does, or None when
    nothing usable came back. The caller translates `data` into its own wire
    shape -- for a stream, by feeding _swarm_sse_lines(data) to the SSE
    translator it already has."""
    return _swarm_tool_result({"messages": messages, "tools": tools,
                               "model": body.get("model"),
                               "max_tokens": max_tokens,
                               "stream": bool(body.get("stream"))})


def _quality_route_kwargs(model, has_images):
    """quality_mode=True for the 'best' id, the same test /v1/chat/completions
    makes. Vision routing has its own model pool and no quality tier, so it is
    left alone there, matching the chat endpoint exactly."""
    if not has_images and (model or "").strip().lower() in ("best", "max"):
        return {"quality_mode": True}
    return {}


# Overall wall clock for ONE prose pipeline run (swarm / crew* / multi), in
# seconds; setting `swarm_max_seconds`, 0 = unbounded. Past it swarm.run starts
# no new stage and synthesises from what finished. Not a hard kill: a stage
# already in flight is bounded by its own hop deadline (_SWARM_HOP_DEADLINE).
#
# It is now the BASE of a budget sized to the plan (see swarm.run). MEASURED
# 2026-09-27: a 3-part request under a subscription manager (sub-claude/sonnet)
# spent the flat 180 s on plan + phase 1 + its verdict -- the CLI takes 30-150 s
# a call -- so phases 2 and 3 never started, review was skipped, and tally.py
# alone shipped after 359 s as "the answer". Raised to 300, plus
# `swarm_seconds_per_phase` for each phase past two, plus the manager's
# MEASURED latency per manager stage, never above `swarm_max_seconds_ceiling`;
# past the cap, `swarm_grace_seconds` for the fastest free models to finish
# what is missing (then a "Not finished" note names the rest).
_SWARM_MAX_SECONDS_DEFAULT = 300
_SWARM_SECONDS_PER_PHASE_DEFAULT = 60
_SWARM_MAX_SECONDS_CEILING_DEFAULT = 1200
_SWARM_GRACE_SECONDS_DEFAULT = 90
# A fast-finish hop is short by design: it is racing the grace window.
_SWARM_FAST_HOP_DEADLINE = 90


def _swarm_max_seconds():
    """The configured cap, or None for unbounded. Fails open to the default."""
    try:
        v = float(config.get_setting("swarm_max_seconds",
                                     _SWARM_MAX_SECONDS_DEFAULT))
    except Exception:                                            # noqa: BLE001
        v = float(_SWARM_MAX_SECONDS_DEFAULT)
    return v if v > 0 else None


def _swarm_setting_seconds(name, default, lo=0.0, hi=None):
    """A numeric pipeline-budget setting, clamped; the default on junk."""
    try:
        v = float(config.get_setting(name, default))
    except Exception:                                            # noqa: BLE001
        v = float(default)
    v = max(lo, v)
    return min(v, hi) if hi is not None else v


def _swarm_budget_kwargs(cap):
    """swarm.run / crews.run budget kwargs for a capped run ({} when the cap
    is off: an unbounded run has nothing to scale). The ceiling is bounded
    so the whole run -- ceiling, grace and the synthesis after it -- fits
    inside _PIPELINE_OUTER_MAX."""
    if not cap:
        return {}
    grace = _swarm_setting_seconds("swarm_grace_seconds",
                                   _SWARM_GRACE_SECONDS_DEFAULT, 0, 600)
    ceiling = _swarm_setting_seconds(
        "swarm_max_seconds_ceiling", _SWARM_MAX_SECONDS_CEILING_DEFAULT, 0,
        _PIPELINE_OUTER_MAX - _PIPELINE_OUTER_GRACE - grace)
    return {"seconds_per_phase": _swarm_setting_seconds(
                "swarm_seconds_per_phase", _SWARM_SECONDS_PER_PHASE_DEFAULT, 0, 600),
            "max_seconds_ceiling": max(float(cap), ceiling),
            "grace_seconds": grace,
            "fast_dispatch": _pipeline_bound(_swarm_fast_dispatch)}


# THE OUTER BOUND ON A PROSE PIPELINE RUN. swarm_max_seconds is not a hard kill:
# past it swarm.run starts no new stage and still SYNTHESISES, and a stage in
# flight walks up to _SWARM_STAGE_MAX_HOPS hops of _SWARM_HOP_DEADLINE each --
# fifteen minutes for one stage, on top of the cap. So the run gets an absolute
# ceiling too: its own cap (or the request deadline when the cap is off) plus
# room for ONE more stage hop, and never more than _PIPELINE_OUTER_MAX. Each
# stage hop is cut to what is left of it (_swarm_dispatch), so a run that is
# over simply stops dispatching and synthesises from what finished.
_PIPELINE_OUTER_GRACE = _SWARM_HOP_DEADLINE
_PIPELINE_OUTER_MAX = 1800
# Absolute monotonic deadline of the pipeline run being served. A ContextVar so
# it rides into the stage threads through _pipeline_bound's context copy.
_PIPELINE_DEADLINE = contextvars.ContextVar("free_llm_hub_pipeline_deadline",
                                            default=None)


def _pipeline_outer_bound(cap):
    """Seconds a whole pipeline run may take, cap included. Never raises."""
    try:
        base = cap or _request_deadline_seconds() or _PIPELINE_OUTER_MAX
        return min(float(base) + _PIPELINE_OUTER_GRACE, float(_PIPELINE_OUTER_MAX))
    except Exception:                                            # noqa: BLE001
        return float(_PIPELINE_OUTER_MAX)


def _pipeline_time_left():
    """Seconds left before the current pipeline run's outer bound, or None
    outside a pipeline."""
    try:
        at = _PIPELINE_DEADLINE.get()
    except Exception:                                            # noqa: BLE001
        return None
    return None if at is None else at - time.monotonic()


# THE PIPELINE FAST PATH IS FOR TRIVIAL ASKS ONLY. The classifier alone was too
# loose: LIVE, model "swarm" answered "Write a concise README section for a
# command-line tool named tally ... Include: a one-paragraph description, a
# usage block, a markdown table of exactly 3 flags (-l, -w, -c) with
# descriptions, and one example command with its output." on the fast path
# (204 s, one model) because it scores 'simple' -- so the pipeline and the
# subscription manager the user picked never ran. A trivial ask is ONE short
# question or one-line request whose answer is short (arithmetic, a fact,
# yes/no, a single value, a one-sentence rewrite): never a request to write /
# create / build / design / implement something, never one that enumerates
# several required parts.
_FAST_PATH_MAX_CHARS = 200
_FAST_PATH_CREATE_RE = re.compile(
    r"\b(?:" + "|".join(v for v in _CREATION_VERBS
                        # a one-sentence rewrite IS trivial; "code"/"port" are
                        # nouns far more often in a question ("status code")
                        if v not in ("rewrite", "code", "port")) + r")\b", re.I)
_FAST_PATH_PARTS_RE = re.compile(
    r"\b(?:include|includes|including|containing|contains|requirements?|"
    r"with the following|the following|must (?:have|include|contain))\s*:"
    r"|^\s*(?:\d+[.)]|[-*•])\s+\S", re.I | re.M)
_FAST_PATH_JOIN_RE = re.compile(r"[,;]|\band\b", re.I)


def _trivial_ask_text(messages):
    """The latest REAL user instruction (CLI wrapper blocks such as Claude
    Code's <system-reminder> removed), or "" when the turn does not end on
    one -- a tool result means the agent is mid-task."""
    for m in reversed(messages or []):
        if not isinstance(m, dict):
            continue
        if m.get("role") != "user":
            return ""
        return ctxwin.instruction_text(ctxwin.message_text(m))
    return ""


def _is_trivial_ask(messages, max_tokens=None):
    """True for ONE short question / one-line request with a short answer
    (see above). Judged on the latest real instruction alone. Never raises."""
    try:
        text = _trivial_ask_text(messages).strip()
        if not text or len(text) > _FAST_PATH_MAX_CHARS or text.count("\n") > 1:
            return False
        if _FAST_PATH_CREATE_RE.search(text) or _FAST_PATH_PARTS_RE.search(text):
            return False
        if len(_FAST_PATH_JOIN_RE.findall(text)) >= 3:
            return False            # "a, b, c and d": several deliverables
        if len([s for s in re.split(r"(?<=[.!?])\s+", text) if s.strip()]) > 2:
            return False            # more than a question + one format line
        return _classify_difficulty([{"role": "user", "content": text}],
                                    max_tokens) == "simple"
    except Exception:                                            # noqa: BLE001
        return False


def _has_prior_turns(messages):
    """True once the conversation has an answer in it (an assistant or tool
    message) -- i.e. it is not an opening turn. Never raises."""
    try:
        return any(isinstance(m, dict) and m.get("role") in ("assistant", "tool")
                   for m in messages or ())
    except Exception:                                            # noqa: BLE001
        return True


def _swarm_fast_path(body, messages, tools=None, max_tokens=None):
    """True when a pipeline id (swarm / crew* / multi / a "<category>-swarm"
    compound) should answer with ONE strong model instead: a TRIVIAL ask
    (_is_trivial_ask). A tool-carrying turn qualifies too -- LIVE, Claude
    Code on multi/coding-swarm spent ~180 s fanning "What is N plus 1?" out to
    five models -- but only when the turn ends on a fresh user instruction
    (first turn or a short follow-up, never mid-loop on a tool result) and the
    conversation itself is small. Medium/hard tool turns keep the fan-out.
    Flag `swarm_fast_path`, default on. Fails CLOSED to the pipeline -- the
    user did pick it."""
    try:
        # A CLI's OWN compaction request is one summary, never a project: a
        # pipeline turns it into a plan + phases + review + synthesis (MEASURED
        # 2026-10-03, opencode on coding-multi: 300-600 s per summary, the CLI
        # stuck on "compaction"). Always one strong model, whatever the flag.
        if ctxwin.is_compaction_request(messages):
            return True
        if not config.get_flag("swarm_fast_path", True):
            return False
        tools = tools if tools is not None else body.get("tools")
        if max_tokens is None:
            max_tokens = body.get("max_tokens") or body.get("max_output_tokens")
        # "The conversation itself is small" -- a size test on a CONVERSATION.
        # An OPENING turn (system + user messages, nothing answered yet) has
        # none: its size is the CLI's own system prompt and wrapper blocks.
        # MEASURED 2026-09-27, Claude Code with the hub's settings: the
        # opening turn of `-p "What is N plus 1?" --model multi` estimates
        # 13.5K tokens (system ~6.8K + CLAUDE.md reminders), so this gate
        # sent the one-liner to the five-model fan-out every time.
        if (tools and _has_prior_turns(messages)
                and _est_tokens(messages) >= STREAM_BIG_REQUEST_TOKENS):
            return False
        return _is_trivial_ask(messages, max_tokens)
    except Exception:                                            # noqa: BLE001
        return False


_PIPELINE_FAST_NOTE = "fast-path=simple question, one strong model"


def _note_pipeline_fast_path():
    """Mark this request as served by the pipeline fast path; the
    X-Free-LLM-Hub-Pipeline header is added on the way out (the /v1/responses
    and /v1/messages loops return from many places)."""
    try:
        g.hub_pipeline_note = _PIPELINE_FAST_NOTE
    except Exception:                                            # noqa: BLE001
        pass


@app.after_request
def _pipeline_note_after(response):
    try:
        note = getattr(g, "hub_pipeline_note", None)
        if note and "X-Free-LLM-Hub-Pipeline" not in response.headers:
            response.headers["X-Free-LLM-Hub-Pipeline"] = note
    except Exception:                                            # noqa: BLE001
        pass
    return response


def _wants_pipeline_trailer():
    """True only for the dashboard's own quick chat, which renders the
    plan/models/reviewer trailer under the answer. It marks its /v1 request
    with the same `X-Free-LLM-Hub: dashboard` header every dashboard write
    carries. Everyone else -- CLIs, SDKs, scripts -- gets the deliverable only."""
    try:
        return request.headers.get("X-Free-LLM-Hub") == "dashboard"
    except Exception:                                            # noqa: BLE001
        return False


# THE CONVERSATION, FOR A PROSE PIPELINE. swarm.run folds the earlier turns in
# `messages` into the brief itself; this is what the hub knows BEYOND them --
# the conversation's persisted rolling recap (the turns a CLI already compacted
# away) and, for a request from an /agent session, that session's memory
# block. Keyed exactly like compaction (ctxwin.conversation_key: the CLI's own
# session id, the dashboard chat's id, else a content hash), so a swarm/crew/
# multi request from any terminal CLI uses the same per-session recap.
_PIPELINE_CONTEXT_CHARS = 3000
_PIPELINE_MEMORY_CHARS = 2000


def _conversation_recap(conv):
    """The persisted rolling recap of conversation `conv`, or ""."""
    try:
        entry = _recap_store.get(conv) if conv else None
        recap = str((entry or {}).get("recap") or "").strip()
        exact = (entry or {}).get("exact")
        if recap and isinstance(exact, list) and _exact_facts_on():
            block = ctxwin.format_exact_facts([str(x) for x in exact if x])
            if block:
                recap += "\n\n" + block
        return recap
    except Exception:                                            # noqa: BLE001
        return ""


def _pipeline_context(body, messages, sid=None):
    """Bounded (<= _PIPELINE_CONTEXT_CHARS) context for swarm/crews.run's
    `context`, or "". Never raises."""
    try:
        sid = sid or _build_sid()
    except Exception:                                            # noqa: BLE001
        sid = None
    parts = []
    if sid:
        try:
            sess = agentic_chat.get_session(sid) or {}
            block = memory.context_block(
                sid, budget_chars=_PIPELINE_MEMORY_CHARS,
                project_dir=sess.get("project_dir") or None,
                query=swarm._last_user_text(messages))
        except Exception:                                        # noqa: BLE001
            block = ""
        if block:
            parts.append(block.strip())
    try:
        hdrs = request.headers
    except Exception:                                            # noqa: BLE001
        hdrs = None
    try:
        conv = ctxwin.conversation_key(hdrs, body, sid, messages)
    except Exception:                                            # noqa: BLE001
        conv = None
    recap = _conversation_recap(conv)
    room = _PIPELINE_CONTEXT_CHARS - sum(len(p) + 2 for p in parts) - 40
    if recap and room > 200:
        parts.append("Recap of the earlier turns:\n" + swarm._clip(recap, room))
    return "\n\n".join(parts).strip()[:_PIPELINE_CONTEXT_CHARS]


def _swarm_completion(body):
    """Run the swarm (or a crew) and return ONE ordinary chat-completions response."""
    asked = (body.get("model") or "").strip()
    if _swarm_fast_path(body, body.get("messages") or []):
        # MEASURED live: "coding-swarm" took 231 s to answer "What is 5767
        # plus 1" -- plan, workers, supervisor, review and synthesis, up to
        # thirteen calls, to agree on 5768 -- and a tool-carrying turn fanned
        # the same question out to five models (~180 s). A TRIVIAL ask (see
        # _is_trivial_ask) gets ONE strong model ('best', same pool and
        # category) instead, with or without tools.
        _log.info("[swarm] trivial %s ask -> one strong model (fast path, asked %r)",
                  "tool" if body.get("tools") else "tool-free", asked)
        fast = dict(body)
        fast["model"] = "best"
        resp = app.make_response(_chat_completions_uncached(fast))
        resp.headers["X-Free-LLM-Hub-Pipeline"] = _PIPELINE_FAST_NOTE
        return resp
    if body.get("tools"):
        # A tool-carrying turn cannot use the prose pipeline (it emits no tool
        # calls, so an agent driven by it writes nothing). Run the parallel
        # best-of-N form of "several models work on it together" instead, which
        # every CLI can actually execute. Falling through to ordinary routing
        # when nothing usable comes back is deliberate: a swarm that cannot
        # answer must not take the turn down with it.
        out = _swarm_tool_turn(body)
        if out is not None:
            return out
        # ...and this is what "falling through" has to mean, because it did not.
        #
        # REPORTED 2026-09-04: five consecutive /agent build turns from opencode
        # came back 503, each after ~155s, with no model recorded. The comment
        # directly above already promised the fall-through, and
        # _swarm_tool_result's docstring promises it twice ("so the caller can
        # fall through to ordinary single-model routing") -- but the code
        # returned a hard 503 instead, so choosing Swarm made a turn STRICTLY
        # more likely to die than choosing Normal. The better mode was the
        # riskier one.
        #
        # 'best', not 'auto': asking for Swarm is asking for the strongest
        # models available, and that intent should survive the fan-out failing.
        _log.info("[swarm-tools] nothing usable from the fan-out -> "
                  "falling back to single-model routing")
        fallback = dict(body)
        fallback["model"] = "best"
        return _chat_completions_uncached(fallback)
    messages = body.get("messages") or []
    if not messages:
        return _openai_error("messages is required.", 400)
    crew = _crew_name_for(asked)
    # Feed live stage progress + the per-role model list to the activity row.
    _watch = _act_pipeline_watcher()
    cap = _swarm_max_seconds()
    extra = {"max_seconds": cap} if cap else {}
    # The cap is the BASE of a plan-sized budget with a post-cap grace (see
    # _SWARM_MAX_SECONDS_DEFAULT); the outer bound below covers all of it.
    _budget = _swarm_budget_kwargs(cap)
    extra.update(_budget)
    _outer_span = ((_budget["max_seconds_ceiling"] + _budget["grace_seconds"])
                   if _budget else cap)
    # A configured subscription manager plans/checks/fixes; free models still
    # do the work. Absent -> no kwarg, the pipeline exactly as before.
    extra.update(_swarm_manager_kwargs())
    extra.update(_pipeline_check_kwargs())
    # The conversation beyond `messages` (recap / session memory); swarm.run
    # folds it into the brief with the earlier turns. Absent -> no kwarg.
    _ctx_text = _pipeline_context(body, messages)
    if _ctx_text:
        extra["context"] = _ctx_text
    # The outer bound is set BEFORE binding, so the context copy _pipeline_bound
    # takes carries it into every stage thread. Reset afterwards: a pooled
    # server thread must not hand a stale deadline to its next request.
    _outer_tok = _PIPELINE_DEADLINE.set(time.monotonic() + _pipeline_outer_bound(_outer_span))
    try:
        # Bound ONCE, here: the mode in force now (a "coding-swarm" id set it
        # on `g`) rides into every stage, including the ones swarm.run puts on
        # worker threads. See _pipeline_bound.
        dispatch = _pipeline_bound(_swarm_dispatch)
        if crew is not None:
            result = crews.run(messages, dispatch, crew, on_event=_watch, **extra)
        else:
            result = swarm.run(messages, dispatch, on_event=_watch, **extra)
    finally:
        _PIPELINE_DEADLINE.reset(_outer_tok)
    result = result if isinstance(result, dict) else {}
    _act_pipeline_result(result)
    # THE DELIVERABLE ONLY for an API/CLI caller. "**Plan followed**", "**Models
    # used**", "**Reviewer raised**" and "**Crew:**" were appended to every
    # answer, so a CLI that asked "multi" for a file got the file plus a report
    # about how it was made, pasted into the file. The same facts now go to the
    # activity row (_act_pipeline_result) and the X-Free-LLM-Hub-Pipeline
    # header. The dashboard's quick chat renders them under the answer and
    # marks its request (X-Free-LLM-Hub: dashboard), so it keeps them.
    if _wants_pipeline_trailer():
        text = (crews.format_answer(result) if crew is not None
                else swarm.format_answer(result))
    else:
        text = (result.get("text") or "").strip()
    pipeline_hdr = {}
    try:
        summary = swarm.trailer_summary(result)
        if summary:
            pipeline_hdr["X-Free-LLM-Hub-Pipeline"] = summary
    except Exception:                                            # noqa: BLE001
        pass
    if not text:
        # Same reasoning as the tool path above: a pipeline that produced
        # nothing must not be the reason the user gets no answer at all. One
        # more single-model attempt costs far less than the fan-out that just
        # failed, and it is the difference between a reply and a 503.
        _log.info("[swarm] pipeline produced no text -> falling back to "
                  "single-model routing")
        fallback = dict(body)
        fallback["model"] = "best"
        return _chat_completions_uncached(fallback)
    out = {
        "id": "chatcmpl-swarm-" + uuid.uuid4().hex,
        "object": "chat.completion",
        "created": int(time.time()),
        "model": asked,
        "choices": [{"index": 0, "finish_reason": "stop",
                     "message": {"role": "assistant", "content": text}}],
    }
    if body.get("stream"):
        # A pipeline cannot stream token-by-token; emit the finished answer as
        # one chunk rather than refusing the request (same trade-off the sub-*
        # relay hops already make).
        def _one_shot():
            chunk = {"id": out["id"], "object": "chat.completion.chunk",
                     "created": out["created"], "model": out["model"],
                     "choices": [{"index": 0, "delta": {"role": "assistant",
                                                        "content": text},
                                  "finish_reason": None}]}
            yield "data: %s\n\n" % json.dumps(chunk)
            done = {"id": out["id"], "object": "chat.completion.chunk",
                    "created": out["created"], "model": out["model"],
                    "choices": [{"index": 0, "delta": {}, "finish_reason": "stop"}]}
            yield "data: %s\n\n" % json.dumps(done)
            yield "data: [DONE]\n\n"
        return Response(_one_shot(), mimetype="text/event-stream",
                        headers=pipeline_hdr)
    return jsonify(out), 200, pipeline_hdr


# ---------------------------------------------------------------------------
# Foreign wire formats.
#
# Gemini CLI, the google-genai SDKs, Open WebUI, Enchanted, Continue's ollama
# provider, editor ghost-text autocomplete -- none of them can be pointed at an
# OpenAI endpoint, so without these the hub simply does not exist for any of
# them. Each one translates its request into an OpenAI body, calls the shared
# _chat_completions seam, and translates the answer back, so all of them inherit
# difficulty routing, the fallback chain, swarm/crew escalation, quota
# accounting and auto-compaction for free -- and keep inheriting improvements
# made after they were written.
# ---------------------------------------------------------------------------

def _call_router(openai_body):
    """Run a translated request through the real router.

    Returns (response, data, status). `data` is the parsed JSON for a buffered
    answer and None for a streamed one, in which case the caller iterates
    `response` itself."""
    rv = _chat_completions(openai_body)
    resp = app.make_response(rv)
    if resp.mimetype == "text/event-stream":
        return resp, None, resp.status_code
    try:
        return resp, resp.get_json(), resp.status_code
    except Exception:                                            # noqa: BLE001
        return resp, None, resp.status_code


def _sse_deltas(resp):
    """Yield (text, tool_calls, finish_reason, usage) from an OpenAI SSE stream.

    Every foreign streaming surface needs exactly this and nothing more, so the
    frame parsing lives here once rather than three times.

    An error frame (the passthrough's _chat_broken_frame when the upstream
    died before finishing) raises _UpstreamStreamError: each surface then
    ends with its OWN error shape instead of its success terminator. After a
    finish_reason the answer stands and a later error frame is skipped."""
    buf = ""
    seen_fin = False
    for raw in resp.response:
        buf += raw.decode("utf-8", "replace") if isinstance(raw, bytes) else raw
        while "\n\n" in buf:
            frame, buf = buf.split("\n\n", 1)
            for line in frame.splitlines():
                line = line.strip()
                if not line.startswith("data:"):
                    continue
                payload = line[5:].strip()
                if not payload or payload == "[DONE]":
                    continue
                try:
                    obj = json.loads(payload)
                except ValueError:
                    continue
                if isinstance(obj, dict) and obj.get("error") and not obj.get("choices"):
                    if not seen_fin:
                        raise _UpstreamStreamError(_stream_error_frame_text(obj))
                    continue            # after the finish: the answer stands
                choice = (obj.get("choices") or [{}])[0]
                delta = choice.get("delta") or {}
                if choice.get("finish_reason"):
                    seen_fin = True
                yield (delta.get("content") or "", delta.get("tool_calls"),
                       choice.get("finish_reason"), obj.get("usage"))


def _error_text(data, fallback):
    """Pull a human message out of whatever error envelope came back."""
    if isinstance(data, dict):
        err = data.get("error")
        if isinstance(err, dict) and err.get("message"):
            return str(err["message"])
        if isinstance(err, str):
            return err
    return fallback


# --------------------------------------------------------------------------- #
# Legacy text completions -- what editor ghost-text autocomplete still speaks
# --------------------------------------------------------------------------- #

@app.route("/v1/completions", methods=["POST"])
def v1_completions():
    body = request.get_json(force=True, silent=True)
    if not isinstance(body, dict):
        return _openai_error("Invalid JSON body.", 400)
    prompt = body.get("prompt")
    if isinstance(prompt, list):
        # The spec allows an array (and token arrays, which no free provider
        # accepts); join the string case and refuse the rest rather than
        # silently completing the wrong text.
        if not all(isinstance(x, str) for x in prompt):
            return _openai_error("Only string prompts are supported.", 400)
        prompt = "".join(prompt)
    if not isinstance(prompt, str) or not prompt:
        return _openai_error("'prompt' is required.", 400)

    openai_body = {"model": body.get("model") or "auto",
                   "messages": [{"role": "user", "content": prompt}]}
    for k in ("temperature", "top_p", "max_tokens", "stop", "seed", "stream", "user"):
        if body.get(k) is not None:
            openai_body[k] = body[k]

    if body.get("stream"):
        resp, _data, _status = _call_router(openai_body)
        if resp.mimetype != "text/event-stream":
            return resp                                   # an error, already shaped
        model = body.get("model") or "auto"
        cid = "cmpl-" + uuid.uuid4().hex

        def gen():
            try:
                for text, _tc, finish, _u in _sse_deltas(resp):
                    if not text and not finish:
                        continue
                    yield "data: " + json.dumps({
                        "id": cid, "object": "text_completion",
                        "created": int(time.time()), "model": model,
                        "choices": [{"text": text, "index": 0,
                                     "finish_reason": finish, "logprobs": None}],
                    }) + "\n\n"
            except _UpstreamStreamError as exc:
                # The upstream died before finishing: the OpenAI error frame,
                # never [DONE] (BROKEN UPSTREAM STREAMS).
                yield "data: " + json.dumps({"error": {
                    "message": str(exc), "type": "server_error",
                    "code": "ECONNRESET"}}) + "\n\n"
                return
            yield "data: [DONE]\n\n"
        return Response(stream_with_context(gen()), mimetype="text/event-stream",
                        headers=_SSE_HEADERS)

    resp, data, status = _call_router(openai_body)
    if status != 200 or not isinstance(data, dict):
        return resp
    choice = (data.get("choices") or [{}])[0]
    return jsonify({
        "id": "cmpl-" + uuid.uuid4().hex, "object": "text_completion",
        "created": int(time.time()), "model": data.get("model") or openai_body["model"],
        "choices": [{"text": (choice.get("message") or {}).get("content") or "",
                     "index": 0, "finish_reason": choice.get("finish_reason"),
                     "logprobs": None}],
        "usage": data.get("usage") or {},
    })


# --------------------------------------------------------------------------- #
# Embeddings
#
# The chat catalog deliberately drops these (routing must never pick an
# embedding model to generate text), which also left the hub unable to serve
# them at all. They are a different SURFACE, not junk: /v1/embeddings is what
# codebase indexing, RAG and semantic search call, and it is the one endpoint
# Continue, Open WebUI and every vector-store integration need before they can
# use this hub for anything but chat.
#
# Routing is deliberately simpler than the chat chain: there is no difficulty to
# assess and no swarm to escalate to, just "try the best available provider,
# fall through on failure". Vectors from DIFFERENT models are not comparable, so
# a silent fallback mid-corpus would poison an index -- which is why the model
# that actually served is always reported back in the response.
# --------------------------------------------------------------------------- #

def _embedding_chain(requested):
    """(pid, model) hops to try, best-first.

    An explicit '<pid>/<model>' pins to that one provider; anything else (or
    'auto') fans out across every provider that has an embedding model."""
    rows = embedding_models()
    if requested and requested not in ("auto", "best"):
        want = str(requested)
        exact = [(r["provider"], r["model"]) for r in rows if r["id"] == want]
        if exact:
            return exact
        # a bare model name, served by however many providers carry it
        by_name = [(r["provider"], r["model"]) for r in rows if r["model"] == want]
        if by_name:
            return by_name
        return []
    return [(r["provider"], r["model"]) for r in rows]


def _embed_upstream(pid, model, inputs, extra=None):
    """POST {base_url}/embeddings for one provider, rotating its key pool.

    Reuses the chat path's key rotation and quota accounting rather than opening
    a second, differently-behaved way of talking to a provider."""
    payload = {"model": model, "input": inputs}
    if isinstance(extra, dict):
        for k in ("encoding_format", "dimensions", "user"):
            if extra.get(k) is not None:
                payload[k] = extra[k]
    return _upstream_post(pid, "embeddings", payload)


@app.route("/v1/embeddings", methods=["POST"])
def v1_embeddings():
    body = request.get_json(force=True, silent=True)
    if not isinstance(body, dict):
        return _openai_error("Invalid JSON body.", 400)
    raw = body.get("input")
    if raw is None or raw == "" or raw == []:
        return _openai_error("'input' is required.", 400)
    inputs = raw if isinstance(raw, list) else [raw]
    if not all(isinstance(x, (str, int, list)) for x in inputs):
        return _openai_error("'input' must be a string or an array of strings.", 400)

    chain = _embedding_chain(body.get("model"))
    if not chain:
        return _openai_error(
            "No embedding model is available. Enable a provider that serves one, "
            "or open the dashboard once so the model catalog is discovered.", 503)

    errors = []
    for pid, model in chain[:_EMBED_MAX_HOPS]:
        try:
            resp = _embed_upstream(pid, model, inputs, body)
        except (requests.RequestException, RuntimeError) as exc:
            errors.append("%s: %s" % (pid, _sanitize(exc.__class__.__name__)))
            _record_outcome(pid, model, False)
            continue
        if resp.status_code != 200:
            errors.append("%s: HTTP %d" % (pid, resp.status_code))
            _record_outcome(pid, model, False)
            if resp.status_code in _DEAD_STATUSES:
                _mark_model_dead(pid, model, resp.status_code)
            continue
        try:
            data = resp.json()
        except ValueError:
            errors.append("%s: bad JSON" % pid)
            _record_outcome(pid, model, False)
            continue
        if not isinstance(data, dict) or not data.get("data"):
            errors.append("%s: empty" % pid)
            _record_outcome(pid, model, False)
            continue
        _record_outcome(pid, model, True)
        # Say which model actually produced these. Vectors from two models are
        # not comparable, so a caller indexing a corpus must be able to tell
        # that a hop changed underneath it rather than discovering it later as
        # unexplained retrieval nonsense.
        data["model"] = pid + "/" + model
        return jsonify(data), 200, {"X-Free-LLM-Hub-Model": pid + "/" + model}

    return _openai_error("All embedding providers failed: " + "; ".join(errors[:5]), 502)


@app.route("/api/embed", methods=["POST"])
@app.route("/api/embeddings", methods=["POST"])
def ollama_embed():
    """Ollama has TWO embedding endpoints with different shapes: the current
    /api/embed (input, embeddings[][]) and the deprecated /api/embeddings
    (prompt, embedding[]). Clients in the wild still use both."""
    if not _is_ollama_path(request.path):
        return _ollama_off()
    body = request.get_json(force=True, silent=True)
    if not isinstance(body, dict):
        return jsonify(wire_ollama.error_payload("Invalid JSON body.")), 400
    legacy = request.path == "/api/embeddings"
    raw = body.get("prompt") if legacy else body.get("input")
    if raw is None or raw == "":
        return jsonify(wire_ollama.error_payload(
            "'%s' is required." % ("prompt" if legacy else "input"))), 400
    inputs = raw if isinstance(raw, list) else [raw]

    chain = _embedding_chain(body.get("model"))
    if not chain:
        return jsonify(wire_ollama.error_payload(
            "No embedding model is available on this hub.")), 503
    pid, model = chain[0]
    try:
        resp = _embed_upstream(pid, model, inputs)
        data = resp.json() if resp.status_code == 200 else None
    except (requests.RequestException, RuntimeError, ValueError):
        data = None
    if not isinstance(data, dict) or not data.get("data"):
        _record_outcome(pid, model, False)
        return jsonify(wire_ollama.error_payload("Embedding provider failed.")), 502
    _record_outcome(pid, model, True)
    vectors = [row.get("embedding") or [] for row in data["data"]]
    if legacy:
        return jsonify({"embedding": vectors[0] if vectors else []})
    return jsonify({"model": wire_ollama.tag_name(pid + "/" + model),
                    "embeddings": vectors})


# --------------------------------------------------------------------------- #
# Ollama emulation
# --------------------------------------------------------------------------- #

def _ollama_off():
    return jsonify(wire_ollama.error_payload(
        "Ollama emulation is off. Enable the 'ollama_api' flag on the hub.")), 404


@app.route("/api/tags", methods=["GET"])
def ollama_tags():
    if not _is_ollama_path("/api/tags"):
        return _ollama_off()
    # 'auto' first: it is the id that actually routes, and Ollama clients pick
    # whatever is at the top of the list by default.
    rows = [{"id": m, "provider": "free-llm-hub"} for m in _virtual_model_ids()]
    rows += [{"id": m["id"], "provider": m.get("provider")} for m in aggregated_models()]
    return jsonify(wire_ollama.tags_payload(rows))


@app.route("/api/ps", methods=["GET"])
def ollama_ps():
    if not _is_ollama_path("/api/ps"):
        return _ollama_off()
    return jsonify({"models": []})       # nothing is resident: every model is remote


@app.route("/api/show", methods=["POST"])
def ollama_show():
    if not _is_ollama_path("/api/show"):
        return _ollama_off()
    body = request.get_json(force=True, silent=True) or {}
    name = body.get("model") or body.get("name") or "auto"
    return jsonify(wire_ollama.show_payload(name))


def _ollama_chat_like(kind):
    body = request.get_json(force=True, silent=True)
    if not isinstance(body, dict):
        return jsonify(wire_ollama.error_payload("Invalid JSON body.")), 400
    model = body.get("model") or "auto"
    openai_body = (wire_ollama.chat_to_openai(body) if kind == "chat"
                   else wire_ollama.generate_to_openai(body))
    # Ollama streams by DEFAULT -- an absent "stream" means true, the opposite
    # of OpenAI. Getting this backwards makes every client hang on first use.
    streaming = body.get("stream", True) is not False
    openai_body["stream"] = streaming
    started = time.time()

    if not streaming:
        resp, data, status = _call_router(openai_body)
        if status != 200 or not isinstance(data, dict):
            return jsonify(wire_ollama.error_payload(
                _error_text(data, "Upstream error."))), status
        ns = int((time.time() - started) * 1_000_000_000)
        out = (wire_ollama.chat_response(data, model, ns) if kind == "chat"
               else wire_ollama.generate_response(data, model, ns))
        return jsonify(out)

    resp, _data, status = _call_router(openai_body)
    if resp.mimetype != "text/event-stream":
        try:
            payload = resp.get_json()
        except Exception:                                        # noqa: BLE001
            payload = None
        return jsonify(wire_ollama.error_payload(
            _error_text(payload, "Upstream error."))), status

    def gen():
        usage, calls = None, None
        try:
            for text, tool_calls, _finish, u in _sse_deltas(resp):
                if u:
                    usage = u
                if tool_calls:
                    calls = tool_calls
                if not text:
                    continue
                yield wire_ollama.ndjson(
                    wire_ollama.chat_chunk(model, text) if kind == "chat"
                    else wire_ollama.generate_chunk(model, text))
        except _UpstreamStreamError as exc:
            # The upstream died before finishing: Ollama's streamed error line,
            # never done:true (BROKEN UPSTREAM STREAMS).
            yield wire_ollama.ndjson(wire_ollama.error_payload(str(exc)))
            return
        if calls and kind == "chat":
            yield wire_ollama.ndjson(wire_ollama.chat_chunk(model, "", calls))
        ns = int((time.time() - started) * 1_000_000_000)
        # The done:true line is what stops the client spinning. Without it the
        # text all arrives and the UI still looks stuck forever.
        yield wire_ollama.ndjson(wire_ollama.final_chunk(model, kind, ns, usage))

    return Response(stream_with_context(gen()),
                    mimetype="application/x-ndjson",
                    headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"})


@app.route("/api/chat", methods=["POST"])
def ollama_chat():
    if not _is_ollama_path("/api/chat"):
        return _ollama_off()
    return _ollama_chat_like("chat")


@app.route("/api/generate", methods=["POST"])
def ollama_generate():
    if not _is_ollama_path("/api/generate"):
        return _ollama_off()
    return _ollama_chat_like("generate")


# --------------------------------------------------------------------------- #
# Gemini (generateContent)
# --------------------------------------------------------------------------- #

def _gemini_models():
    rows = [{"id": m, "context_window": None} for m in _virtual_model_ids()]
    rows += [{"id": m["id"], "context_window": m.get("context_window")}
             for m in aggregated_models()]
    return rows


@app.route("/v1beta/models", methods=["GET"])
@app.route("/v1beta/openai/models", methods=["GET"])
def gemini_models():
    return jsonify(wire_gemini.models_payload(_gemini_models()))


@app.route("/v1beta/models/<path:spec>", methods=["GET", "POST"])
def gemini_generate(spec):
    """One route for every method, because a model id here can contain slashes
    ("openrouter/glm-5.3") and the method is a ":suffix" on the last segment --
    neither of which Flask can express as separate rules."""
    method = None
    if ":" in spec:
        spec, method = spec.rsplit(":", 1)
    model = wire_gemini.strip_model_prefix(spec)

    if request.method == "GET" and not method:
        return jsonify(wire_gemini.model_entry(model))

    body = request.get_json(force=True, silent=True)
    if not isinstance(body, dict):
        return jsonify(wire_gemini.error_payload("Invalid JSON body.", 400)), 400

    if method == "countTokens":
        msgs = wire_gemini.contents_to_messages(body)
        # No routing margin: this number is shown to the caller, not used to
        # keep a request under a provider limit.
        return jsonify(wire_gemini.count_tokens_payload(
            _est_tokens(msgs, body.get("tools"), overhead=0)))

    if method not in ("generateContent", "streamGenerateContent"):
        return jsonify(wire_gemini.error_payload(
            "Unsupported method '%s'." % (method or ""), 400)), 400

    openai_body = wire_gemini.to_openai(body, model)
    streaming = method == "streamGenerateContent"
    openai_body["stream"] = streaming

    if not streaming:
        resp, data, status = _call_router(openai_body)
        if status != 200 or not isinstance(data, dict):
            return jsonify(wire_gemini.error_payload(
                _error_text(data, "Upstream error."), status)), status
        return jsonify(wire_gemini.from_openai(data, model))

    resp, _data, status = _call_router(openai_body)
    if resp.mimetype != "text/event-stream":
        try:
            payload = resp.get_json()
        except Exception:                                        # noqa: BLE001
            payload = None
        return jsonify(wire_gemini.error_payload(
            _error_text(payload, "Upstream error."), status)), status

    # ?alt=sse is what Gemini CLI and the SDKs send. Without it the documented
    # shape is a JSON ARRAY delivered incrementally, and a client expecting that
    # cannot parse SSE frames at all -- so both are emitted properly.
    as_sse = (request.args.get("alt") or "").lower() == "sse"

    def gen():
        usage, first = None, True
        try:
            for text, tool_calls, finish, u in _sse_deltas(resp):
                if u:
                    usage = u
                if not text and not tool_calls and not finish:
                    continue
                chunk = wire_gemini.stream_chunk(text, model, finish, tool_calls)
                if as_sse:
                    yield "data: " + json.dumps(chunk) + "\n\n"
                else:
                    yield ("[" if first else ",") + json.dumps(chunk)
                    first = False
        except _UpstreamStreamError as exc:
            # The upstream died before finishing: Google's error envelope
            # (503 UNAVAILABLE), never the "stop" tail (BROKEN UPSTREAM STREAMS).
            err = wire_gemini.error_payload(str(exc), 503, "UNAVAILABLE")
            if as_sse:
                yield "data: " + json.dumps(err) + "\n\n"
            else:
                yield ("[" if first else ",") + json.dumps(err) + "]"
            return
        tail = wire_gemini.stream_chunk("", model, "stop", None, usage)
        if as_sse:
            yield "data: " + json.dumps(tail) + "\n\n"
        else:
            yield ("[" if first else ",") + json.dumps(tail) + "]"

    if as_sse:
        return Response(stream_with_context(gen()), mimetype="text/event-stream",
                        headers=_SSE_HEADERS)
    return Response(stream_with_context(gen()), mimetype="application/json",
                    headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"})


@app.route("/v1/chat/completions", methods=["POST"])
def v1_chat_completions():
    body = request.get_json(force=True, silent=True)
    if not isinstance(body, dict):
        return _openai_error("Invalid JSON body.", 400)
    # The tool results this turn carries credit the models whose calls made
    # them (bandit; a no-op without it). See _bandit_credit.
    _bandit_credit(body.get("messages"))
    # ...and the same results are OBSERVED evidence: receipts + project facts
    # (the hub runs nothing). See _v1_observe.
    _v1_observe(body.get("messages"), body)
    return _chat_completions(body)


def _chat_completions(body):
    """The router, with the response cache in front of it.

    Wrapping the seam rather than each route means every surface -- OpenAI,
    Gemini, Ollama, /v1/completions -- is cached by the same rules, and a
    surface added later cannot forget to be.

    Off unless the `response_cache` flag is on. The scarce resource here is
    other people's free tiers, not latency: a hit is a request that never comes
    off a daily allowance. But a cache also turns "ask again" into "the same
    answer", which is right for a retry after a dropped stream and wrong for
    someone pressing regenerate hoping for better -- and nothing in the request
    distinguishes those, so the choice belongs to whoever runs the hub.

    A client can bypass it for one request with `X-Free-LLM-Hub-Cache: bypass`,
    which still STORES the fresh answer."""
    # IDEMPOTENCY. A client that retries a POST it never saw the answer to --
    # a dropped connection, a proxy timeout, an SDK's own retry -- spends the
    # free quota twice for one question. `Idempotency-Key` says "this is that
    # same request", so the first answer is returned instead of a second one
    # being generated. Independent of the response cache: this is about a
    # RETRY of one request, not about two people asking the same thing, so it
    # applies even to tool-carrying turns the cache refuses.
    idem = (request.headers.get("Idempotency-Key") or "").strip()[:200]
    if idem:
        held = _idem_get(idem)
        if held is not None:
            return jsonify(held), 200, {"X-Free-LLM-Hub-Idempotent": "replayed"}

    if not config.get_flag("response_cache", False):
        return _idem_store(idem, _chat_completions_uncached(body))

    bypass = (request.headers.get("X-Free-LLM-Hub-Cache") or "").lower() == "bypass"
    if not bypass:
        hit = respcache.get(body, ttl=_cache_ttl())
        if hit is not None:
            return _cached_response(body, hit)
    return _idem_store(idem, _remember_completion(body, _chat_completions_uncached(body)))


# Answers held against an Idempotency-Key. Small and short-lived: this exists to
# cover a retry of a request in flight, not to remember yesterday.
_IDEM_TTL = 600
_IDEM_MAX = 128
_idem = {}                      # key -> (stored_at, data)
_idem_lock = threading.Lock()


def _idem_get(key):
    if not key:
        return None
    now = time.time()
    with _idem_lock:
        hit = _idem.get(key)
        if not hit:
            return None
        stored_at, data = hit
        if now - stored_at > _IDEM_TTL:
            _idem.pop(key, None)
            return None
        return data


def _idem_store(key, rv):
    """Remember a successful answer under its idempotency key.

    Streamed answers are deliberately NOT held: replaying one would mean
    buffering it here, and a client streaming a turn is watching it arrive --
    the retry case this covers is a client that got no answer at all."""
    if not key:
        return rv
    try:
        resp = app.make_response(rv)
    except Exception:                                            # noqa: BLE001
        return rv
    if resp.status_code != 200 or resp.mimetype == "text/event-stream":
        return resp
    try:
        data = resp.get_json()
    except Exception:                                            # noqa: BLE001
        return resp
    if not isinstance(data, dict):
        return resp
    with _idem_lock:
        if len(_idem) >= _IDEM_MAX:
            oldest = next(iter(_idem), None)
            if oldest is not None:
                _idem.pop(oldest, None)
        _idem[key] = (time.time(), data)
    return resp


def _cache_ttl():
    try:
        return max(30, int(config.get_value("response_cache_ttl", "")
                           or respcache.DEFAULT_TTL))
    except (TypeError, ValueError):
        return respcache.DEFAULT_TTL


def _cached_response(body, data):
    """Serve a stored completion in whichever shape THIS request asked for.

    A cached answer has to be able to come back as a stream: the commonest hit
    by far is the re-run of a turn whose stream dropped, and that client is
    still a streaming client. It arrives as a single chunk, which is honest --
    the tokens were not generated now."""
    headers = {"X-Free-LLM-Hub-Cache": "hit"}
    if not body.get("stream"):
        return jsonify(data), 200, headers
    text = ((data.get("choices") or [{}])[0].get("message") or {}).get("content") or ""
    model = data.get("model") or body.get("model") or "auto"
    cid = data.get("id") or ("chatcmpl-" + uuid.uuid4().hex)

    def gen():
        yield "data: " + json.dumps({
            "id": cid, "object": "chat.completion.chunk", "created": int(time.time()),
            "model": model,
            "choices": [{"index": 0, "delta": {"role": "assistant", "content": text},
                         "finish_reason": None}]}) + "\n\n"
        yield "data: " + json.dumps({
            "id": cid, "object": "chat.completion.chunk", "created": int(time.time()),
            "model": model,
            "choices": [{"index": 0, "delta": {}, "finish_reason": "stop"}],
            "usage": data.get("usage") or {}}) + "\n\n"
        yield "data: [DONE]\n\n"

    return Response(stream_with_context(gen()), mimetype="text/event-stream",
                    headers=dict(_SSE_HEADERS, **headers))


def _remember_completion(body, rv):
    """Store a fresh answer on its way out, buffered or streamed."""
    try:
        resp = app.make_response(rv)
    except Exception:                                            # noqa: BLE001
        return rv
    if resp.status_code != 200:
        return resp
    if resp.mimetype != "text/event-stream":
        try:
            respcache.put(body, resp.get_json())
        except Exception:                                        # noqa: BLE001
            pass
        return resp
    if not respcache.cacheable(body):
        return resp
    # A streamed answer is reassembled AS IT PASSES THROUGH, because the turns
    # worth caching are the expensive ones and those stream. Buffering the whole
    # thing first would hold the answer back from the client to serve a cache
    # that only helps the NEXT request.
    return Response(stream_with_context(_tee_and_store(resp.response, body)),
                    mimetype="text/event-stream", headers=dict(resp.headers))


def _tee_and_store(upstream, body):
    """Forward an SSE stream untouched while reassembling it for the cache."""
    parts, usage, model, cid = [], None, None, None
    buf = ""
    for raw in upstream:
        yield raw                                  # the client sees it unchanged
        buf += raw.decode("utf-8", "replace") if isinstance(raw, bytes) else raw
        while "\n\n" in buf:
            frame, buf = buf.split("\n\n", 1)
            for line in frame.splitlines():
                line = line.strip()
                if not line.startswith("data:"):
                    continue
                payload = line[5:].strip()
                if not payload or payload == "[DONE]":
                    continue
                try:
                    obj = json.loads(payload)
                except ValueError:
                    continue
                cid = cid or obj.get("id")
                model = model or obj.get("model")
                if obj.get("usage"):
                    usage = obj["usage"]
                delta = ((obj.get("choices") or [{}])[0] or {}).get("delta") or {}
                if delta.get("content"):
                    parts.append(delta["content"])
    text = "".join(parts)
    if not text.strip():
        return                       # a stream that produced nothing is not an answer
    try:
        respcache.put(body, {
            "id": cid or ("chatcmpl-" + uuid.uuid4().hex),
            "object": "chat.completion", "created": int(time.time()),
            "model": model or body.get("model") or "auto",
            "choices": [{"index": 0, "finish_reason": "stop",
                         "message": {"role": "assistant", "content": text}}],
            "usage": usage or {}})
    except Exception:                                            # noqa: BLE001
        pass


def _chat_completions_uncached(body):
    """The whole router, reachable WITHOUT an HTTP request of its own.

    Every wire format this hub speaks -- OpenAI, Anthropic, Gemini, Ollama, the
    legacy /v1/completions -- wants the same thing behind it: difficulty
    routing, the fallback chain, swarm/crew escalation, quota and reliability
    accounting, auto-compaction. /v1/messages predates this seam and duplicates
    that loop; doing the same for two more formats would have meant four copies
    of the one piece of logic where a divergence is silent and expensive.

    So the foreign surfaces translate their request into an OpenAI body, call
    this, and translate the answer back. They inherit every routing improvement
    automatically, including ones added after they were written.

    Still runs inside a real request context (it reads request.headers for
    X-Free-LLM-Hub-Exclude), it just no longer re-reads the JSON body."""
    if _client_gone():
        # The client left (e.g. while a pipeline ran): never start the
        # fallback walk this call usually is.
        return _client_gone_reply()
    try:
        body["messages"], image_count = _normalize_openai_messages(body.get("messages"))
    except ValueError as exc:
        return _openai_error(str(exc), 400)
    has_images = image_count > 0
    # A "<category>-<effort>" compound id (e.g. "coding-swarm") sets the mode and
    # becomes a plain effort tier. This is the one channel a flat-list CLI has
    # for choosing BOTH axes at once; done here, before the swarm dispatch, so
    # "coding-swarm"/"coding-multi" reach the pipeline exactly as bare
    # "swarm"/"multi" do, but with the pool cut to the category.
    body = _apply_category_effort(body)
    # "/orchestrator ..." as the whole message: the hub answers it itself.
    _orch_reply = _orch_command_response("chat", body, body.get("messages"))
    if _orch_reply is not None:
        return _orch_reply
    # FRONT DOOR (see _front_door_overflow): a conversation no alive model can
    # hold is refused here, BEFORE the pipeline dispatch and any hop -- and the
    # context state (original size, live-window steering) is set up once so the
    # pipeline tiers below report usage the same way the single-model path does.
    # Only on the real /v1/chat/completions route: Gemini, Ollama and
    # /v1/completions share this router but have no native overflow contract.
    _armed = _request_path_endswith("/v1/chat/completions")
    _est0 = _est_tokens(body.get("messages"), body.get("tools"))
    # signal=False: this early call only sets up the original size and the
    # steering state; arming the overflow signal here would change how a
    # pipeline actor hop is served (the later _ctx_begin arms the single-model
    # path exactly as before).
    _ctx_begin(body, body.get("messages"), _est0, signal=False)
    _fd = _front_door_overflow("openai", body.get("messages"), body.get("tools"), _est0,
                               stream=bool(body.get("stream")), images=has_images,
                               armed=_armed)
    if _fd is not None:
        return _fd
    # SWARM: an explicitly-selected virtual model, never an automatic mode — a
    # multi-pass pipeline applied behind a client's back would corrupt the agent
    # loops Codex/Claude Code run (see swarm.py's header). Tool-carrying turns
    # are refused outright for the same reason.
    if _is_swarm_model(body.get("model")):
        return _swarm_completion(body)
    # AUTO-ESCALATION to the crew pipeline. The dashboard project gate asks a
    # HUMAN "crew or plain?" before sending; an API client (hermes, openclaw,
    # a script) has no human to ask, so the hub decides by the same heuristic:
    # a tool-free, image-free, OPENING-turn 'auto' request that reads as a full
    # project gets the crew pipeline instead of one model. Tool-carrying turns
    # (agent loops) and explicit '<pid>/<model>' choices are never touched —
    # both are already a decision. Flag: crew_auto_escalate (default on).
    if (_is_orchestrate(body.get("model"))
            and config.get_flag("crew_auto_escalate", True)
            and not body.get("tools") and not has_images
            and len([m for m in (body.get("messages") or [])
                     if isinstance(m, dict) and m.get("role") == "user"]) == 1
            # opencode sends its compaction as ONE tool-free user message: a
            # summary to write, never a project for a crew.
            and not ctxwin.is_compaction_request(body.get("messages") or [])
            and crews.looks_like_full_project(
                swarm._last_user_text(body.get("messages")))):
        esc = dict(body)
        esc["model"] = "crew"
        return _swarm_completion(esc)
    # The request's wall clock starts HERE, before routing (a cold catalog fetch
    # is time the client is waiting too) and after the pipeline dispatch above,
    # which runs under its own cap. See _REQUEST_DEADLINE_DEFAULT.
    _begin_request_deadline()
    # Orchestrate (Auto): route by task difficulty AND request size so weak/small
    # providers take easy work and big requests avoid small-TPM providers (413).
    # Explicit '<pid>/<model>' bypasses model choice (chain still size-filters).
    # A NAMED CHAIN used as the model: resolve it to its first live entry and
    # keep the rest as the preferred head of the fallback chain, so the order
    # the user wrote is the order that runs. Resolved here rather than inside
    # the router because everything below reads body["model"], and a name that
    # reached _route_by_difficulty would simply score as an unknown id.
    chain_prefer = None
    if _is_chain_name(body.get("model")):
        chain_prefer = _chain_entries(body.get("model"))
        if chain_prefer:
            body = dict(body)
            body["model"] = chain_prefer[0][0] + "/" + chain_prefer[0][1]
        else:
            # Every model in the chain is gone or dead. Fall back to Auto rather
            # than failing: a saved preference must never be able to break a
            # request outright.
            body = dict(body)
            body["model"] = "auto"
    est = _est_tokens(body.get("messages"), body.get("tools"))
    has_tools = bool(body.get("tools"))
    # "Retry with a different model": the caller names the model(s) it does NOT
    # want this time. Honoured for the Auto pick as well as the fallback chain --
    # vetoing it only in the chain would let Auto re-pick the very model the user
    # just rejected and answer from hop 1.
    veto = _excluded_identities(request.headers.get("X-Free-LLM-Hub-Exclude"))
    diff = None
    # Did the CALLER name a model, or is the router choosing? A pinned model
    # opens the turn whatever its record says -- see _build_chain(pinned=).
    # Passed as a kwarg dict for the same reason exclude_identities is: an
    # ordinary orchestrated request keeps the exact call shape it always had, so
    # a stand-in for _build_chain never has to know about a parameter it does
    # not see.
    _pin_kw = {"pinned": True} if not _is_orchestrate(body.get("model")) else {}
    # A PINNED model that cannot see, handed an image. Routing sends an
    # unpinned image request to a vision model already; a pin is the caller
    # saying which model answers, and overriding it would be answering a
    # different question. So the image is described by something that CAN see
    # and the pinned model is given words. See _vision_assist.
    if has_images and _pin_kw:
        # _resolve_model, not a hand-rolled split: it is what the rest of the
        # handler uses, it knows sub-* providers, and it returns
        # (None, message) for anything it cannot resolve.
        _pin_pid, _pin_model = _resolve_model(body.get("model"))
        if _pin_pid and prov.get_provider(_pin_pid)                 and not _is_vision_model(_pin_pid, _pin_model):
            # This handler carries the turn in body["messages"], not a local.
            _msgs, _described = _vision_assist(body.get("messages"), est)
            if _described:
                body["messages"] = _msgs
                has_images = bool(_message_images(_msgs))
                # An image is worth thousands of tokens and a paragraph a few
                # hundred: routing the rewritten turn on the old estimate would
                # size it for a request that no longer exists.
                est = _est_tokens(_msgs, body.get("tools"))
    if not _pin_kw:
        router = _route_for_vision if has_images else _route_by_difficulty
        _rkw = {}
        if (body.get("model") or "").strip().lower() in ("best", "max") and not has_images:
            _rkw["quality_mode"] = True
        # A MODE id ("coding", "vision", ...) routes exactly like `auto` and
        # restricts the pool to that category for THIS request only -- the one
        # handle a CLI has for choosing a mode. Set on `g` rather than passed
        # down: the chain, the swarm and the retries all consult _active_mode(),
        # so one assignment covers every path this request takes.
        _req_mode = _valid_mode((body.get("model") or "").strip().lower())
        if _req_mode and _req_mode != MODE_ALL:
            g.model_mode = _req_mode
        pid, resolved, diff = router(body.get("messages"), body.get("max_tokens"), est,
                                     require_tools=has_tools, **_rkw)
        pid, resolved = _apply_orchestrator(pid, resolved, body.get("messages"), est,
                                            has_tools, has_images, veto, body, diff=diff)
        if veto and pid is not None and _normalize_model_identity(resolved) in veto:
            # Auto landed on exactly the model the user just rejected. Hand the
            # choice to _build_chain with an empty primary: it applies the same
            # veto, so its first entry is the best model that is NOT vetoed.
            pid, resolved = None, None
            for _p, _m in _build_chain("", "", est, require_vision=has_images,
                                       require_tools=has_tools,
                                       messages=body.get("messages"),
                                       exclude_identities=veto):
                pid, resolved = _p, _m
                break
            if pid is None:
                return _openai_error(
                    "No other model is available to retry with right now.", 503,
                    "upstream_error")
        if pid is None:
            if has_images:
                return _openai_error(
                    "No enabled verified vision model is available. Enable Google, "
                    "Cloudflare, or Z.AI with a usable vision model.", 400)
            pid, resolved = _resolve_model(body.get("model"))  # default/best or error
    else:
        pid, resolved = _resolve_model(body.get("model"))
    if pid is None:
        return _openai_error(resolved, 400)
    _blocked = _model_block_reason(pid, resolved)
    if _blocked:
        return _openai_error(_blocked, 403, "permission_error")
    if has_images and not _is_vision_model(pid, resolved):
        return _openai_error(
            "Model '%s/%s' is not a verified vision model." % (pid, resolved), 400)
    not_ready = _check_provider_ready(pid)
    if not_ready:
        return _openai_error(not_ready, 400)

    stream = bool(body.get("stream"))
    errors = _HopErrors()
    attempts = 0          # upstream hops actually tried (transparency header)
    last_hop = (None, None)
    last_hard = None  # last hard (non-retryable) upstream error, relayed if the chain is exhausted
    last_error = None  # class of the LAST failed hop (transparency header)
    # Pass exclude_identities ONLY when something is actually vetoed, so the
    # ordinary path keeps the exact call shape it always had (a stand-in for
    # _build_chain should not have to know about a parameter it never sees).
    _veto_kw = {"exclude_identities": veto} if veto else {}
    _walk_started = time.monotonic()
    # See _ChainClock: the request deadline and the trivial-turn hop budget.
    _mark_turn_shape(diff, est, pinned=bool(_pin_kw))
    _clock = _ChainClock(trivial=_is_trivial_turn(
        body.get("messages"), body.get("max_tokens"), diff, est, pinned=bool(_pin_kw)),
        tools=has_tools, est=est, stream=stream, pinned=bool(_pin_kw))
    _plan_quality_fallback(_clock, body.get("model"), has_images, bool(_pin_kw),
                           body.get("messages"), body.get("max_tokens"))
    # Context bookkeeping for this request (original size, conversation id).
    # The native overflow error is an OpenAI-client contract, so it is only
    # armed on the real /v1/chat/completions route -- not on the foreign
    # surfaces (Gemini, Ollama, /v1/completions) that reuse this router.
    _ctx_begin(body, body.get("messages"), est,
               signal=_request_path_endswith("/v1/chat/completions"))
    _chain = _build_chain(pid, resolved, est, require_vision=has_images,
                          prefer=chain_prefer,
                          require_tools=has_tools,
                          **_pin_kw,
                          messages=body.get("messages"),
                          **_veto_kw)
    # A trivial, tool-free, small turn may race its hop against the next one
    # (see _HEDGE_DELAY_MIN); the partner's payload is built like the loop's.
    _clock.plan_hedge(_chain, body, diff, est=est, tools=has_tools, images=has_images,
                      output_budget=True)
    # Gap 2: parallel specialists for a hard, fresh tool turn on auto/best --
    # their brief rides in the messages every hop is built from (dict(body)).
    body["messages"] = _single_turn_team_notes(body.get("messages"), body.get("tools"),
                                               _chain, (pid, resolved), est, diff,
                                               bool(_pin_kw), stream)
    for hop_pid, hop_model in _clock.walk(_chain):
        if _clock.consumed(hop_pid, hop_model):
            continue              # a hedge already ran this hop
        if _clock.spent():
            errors.append("stopped: request deadline reached")
            last_error = "deadline"
            break
        if stream and _header_budget_spent(_walk_started):
            # See _STREAM_HEADER_BUDGET: past this the client has stopped
            # listening for headers, so a further hop cannot be delivered even
            # if it succeeds.
            errors.append("stopped after %ds: the client's header timeout was "
                          "about to expire" % _STREAM_HEADER_BUDGET)
            break
        if not prov.is_model_allowed(hop_model):
            continue
        # MID-REQUEST re-check. _build_chain is computed ONCE, up front, so a
        # provider sidelined DURING this request (e.g. its 2nd distinct 402 ->
        # _mark_provider_authfail decides the account is broke) still has all its
        # remaining hops queued. MEASURED 2026-07-31: one Codex request burned
        # SEVEN consecutive puter/402 hops for exactly this reason before
        # reaching a model that could answer. Re-checking here drops the rest of
        # a provider's hops the moment it is proven dead.
        if _is_provider_dead(hop_pid):
            errors.append("%s: sidelined mid-request" % hop_pid)
            continue
        # See the matching comment in /v1/responses -- same fix, same reason:
        # dispatch a sub-* (local CLI relay) hop non-streaming even when the
        # client wants a stream, instead of skipping it outright, then emit
        # its complete answer as one synthetic SSE chunk below.
        is_sub_hop = _is_sub(hop_pid)
        payload = dict(body)
        payload["model"] = hop_model
        _apply_output_budget(payload, hop_pid)
        _apply_reasoning_effort(payload, hop_model, diff, pid=hop_pid)
        dispatch_stream = stream and not is_sub_hop
        payload["stream"] = dispatch_stream
        try:
            _act_pick(hop_pid, hop_model)
            attempts += 1
            last_hop = (hop_pid, hop_model)
            resp = _clock.dispatch(hop_pid, payload, dispatch_stream)
            # A hedge may have been won by the NEXT candidate (see served()).
            hop_pid, hop_model, payload = _clock.served(hop_pid, hop_model, payload)
            last_hop = (hop_pid, hop_model)
        except (requests.RequestException, RuntimeError) as exc:
            errors.append("%s: %s" % (hop_pid, _sanitize(exc.__class__.__name__)))
            _note_hop_detail(hop_pid, exc)       # log-only: class + message
            last_error = _classify_hop_error(exc=exc)
            if isinstance(exc, requests.exceptions.Timeout):
                # A hop that TIMES OUT (unlike a fast-fail 429/400) can burn
                # minutes doing it -- and an immediate retry of the same
                # request (codex's own client-level retry on 503, or this
                # chain's bonus whole-chain retry a bit further down) hits the
                # SAME slow hop again, compounding into a long stall with zero
                # progress. MEASURED 2026-08-03: nvidia/mistral-medium-3.5-128b
                # ReadTimeout'd 4 times running, ~7 minutes each, while every
                # other hop in the chain failed fast. Same short cooldown a
                # 429 already gets, so the NEXT chain build skips it long
                # enough for a retry to reach a hop that actually responds.
                # A plain ConnectionError deliberately stays OUT of this branch
                # (see test_a_fast_failing_hop_is_not_throttled_only_a_real_
                # timeout_is): a real connection-refused fails just as fast on
                # a retry, so there's nothing costly to protect against. The
                # SLOW failure mode that error class was missing turned out to
                # be a raw 5xx status (524 etc.) that never raises at all --
                # handled separately below, in the non-2xx branch.
                # Scoped to THIS model unless the evidence is provider-wide
                # (see _throttle_failed_hop).
                _throttle_failed_hop(hop_pid, hop_model, exc=exc)
                # ...and count it, so a provider that ONLY ever times out is eventually
                # parked rather than re-tried forever. Heavily gated -- see
                # _note_provider_timeout, which ignores everything that is not
                # provably the provider's own fault.
                _note_provider_timeout(hop_pid, exc)
            continue
        if resp.status_code == 200:
            if stream and is_sub_hop:
                try:
                    data = resp.json()
                except (ValueError, requests.RequestException):
                    errors.append("%s: non-JSON 200 body" % hop_pid)
                    last_error = "non-json"
                    resp.close()
                    continue
                if _chat_json_nonanswer(data, has_tools, body.get("tools")) and _skip_nonanswer():
                    # A 200 whose content IS the relay backend's error page (see
                    # _chat_json_nonanswer). Falls through to the next hop exactly
                    # like an empty 200, and sidelines the id so it stops winning.
                    errors.append("%s: upstream error returned as content" % hop_pid)
                    last_error = "empty"
                    _note_nonanswer(hop_pid, hop_model)
                    resp.close()
                    continue
                if _chat_json_is_empty(data):
                    errors.append("%s: empty (200 but no content)" % hop_pid)
                    last_error = "empty"
                    resp.close()
                    continue
                gate = _answer_gate(data, payload, has_tools, hop=(hop_pid, hop_model))
                if gate == "junk":
                    errors.append("%s: degenerate answer (nothing salvageable)" % hop_pid)
                    last_error = "junk"
                    _record_outcome(hop_pid, hop_model, False, junk=True)
                    resp.close()
                    continue
                _record_chat_usage(hop_pid, hop_model, data, est, ok=gate == "ok")
                delta, fin = _sub_stream_message(data)
                chunk = {"id": data.get("id", "chatcmpl-sub"), "object": "chat.completion.chunk",
                        "created": data.get("created", int(time.time())),
                        "model": hop_pid + "/" + hop_model,
                        "choices": [{"index": 0, "delta": delta,
                                    "finish_reason": None}]}
                done = dict(chunk, choices=[{"index": 0, "delta": {}, "finish_reason": fin}])
                body_bytes = (b"data: " + json.dumps(chunk).encode("utf-8") + b"\n\n" +
                             b"data: " + json.dumps(done).encode("utf-8") + b"\n\n" +
                             b"data: [DONE]\n\n")
                return Response(stream_with_context(_proxy_sse(resp, iter([body_bytes]))),
                                mimetype="text/event-stream",
                                headers=dict(_SSE_HEADERS, **_routing_headers(
                                    hop_pid, hop_model, attempts, last_error)))
            if stream:
                # #4: peek the first byte BEFORE committing the 200. A hung/slow
                # stream (no first byte within STREAM_FIRST_BYTE_TIMEOUT) falls
                # through to the next provider instead of stalling the client.
                it = resp.iter_content(chunk_size=None)
                if has_tools:
                    # Model-native tool-call markup typed as text (DeepSeek
                    # DSML) becomes real tool_calls BEFORE the peek sees it.
                    it = tool_rescue.rescue_stream(it, body.get("tools"), "frames")
                # Peek until REAL content: a 200 that streams no content must fall
                # through to the next model, not be handed to the client as empty.
                status, buffered = _peek_until_content(
                    it, _clock.peek_timeout(hop_model, est, pid=hop_pid),
                    content_grace=_clock.content_grace(),
                    check=_peek_check(payload, has_tools))
                _clock.note_peek(hop_pid, hop_model, status)
                if status == "starved":
                    # Ended at "length" on a stub / nothing: hidden reasoning
                    # ate the budget. One same-pair retry with room, before a
                    # byte reaches the client (see _stream_starve_retry).
                    resp.close()
                    _again = _stream_starve_retry(_clock, hop_pid, hop_model, payload, est,
                                                  has_tools, body.get("tools"), lines=False)
                    if _again is not None:
                        resp, it, status, buffered, payload = _again
                if status == "nonanswer" and not _skip_nonanswer():
                    status = "content"    # a 2nd bare announcement: served (one retry)
                if status != "content":
                    errors.append("%s: %s (200 but no content)" % (hop_pid, status))
                    last_error = _classify_hop_error(peek=status)
                    if status == "nonanswer":
                        # The relay streamed its own error page as the answer --
                        # sideline the id so it stops winning hop 1 (see
                        # _note_nonanswer; ranking alone never removed it).
                        _note_nonanswer(hop_pid, hop_model)
                    elif status == "junk":
                        _record_outcome(hop_pid, hop_model, False, junk=True)
                    resp.close()
                    continue
                _note_ttft(resp, hop_pid, hop_model)
                chained = _clock.guard(_chain_buffered(buffered, it),
                                       _CHAT_DEADLINE_TERMINATOR,
                                       "%s/%s" % (hop_pid, hop_model))
                # Visible text is held and judged before release (see
                # _StreamAnswerGate); tool-call deltas are never held.
                gated = _gate_stream(chained, "bytes", hop_pid, hop_model, payload, has_tools)
                relay = _proxy_sse(resp, gated, hop_pid=hop_pid, hop_model=hop_model,
                                   prompt_est=est,
                                   prompt_text=_prompt_text_for_check(payload),
                                   last_prompt=_last_user_text_for_check(payload),
                                   tools_offered=has_tools, answer_gate=gated)
                # A tools turn gets its frames checked; a plain chat stream keeps
                # the zero-copy byte passthrough exactly as it was.
                if has_tools:
                    relay = _repair_tool_sse(relay)
                    # ...then one copy of a call sent N times (tool_rescue.dedupe_stream)
                    relay = _dedupe_tool_stream(relay, "frames", hop_pid, hop_model)
                # Usage frames report the ORIGINAL request size (see
                # _reported_prompt_tokens); one is added when the client asked
                # for usage and the upstream sent none.
                relay = _ctx_usage_sse(relay, body, est, hop_pid, hop_model)
                return Response(stream_with_context(relay),
                                mimetype="text/event-stream",
                                headers=dict(_SSE_HEADERS, **_routing_headers(
                                    hop_pid, hop_model, attempts, last_error)))
            try:
                data = resp.json()
            except (ValueError, requests.RequestException):
                # Non-JSON / broken 200 body -> don't dead-end, try the next model.
                errors.append("%s: non-JSON 200 body" % hop_pid)
                last_error = "non-json"
                resp.close()
                continue
            # Starved by the token budget rather than broken -- empty at
            # "length", or a truncated STUB ("94" for 2994)? Give this SAME hop
            # one more go with room to answer, instead of serving the stub or
            # throwing away a model that was about to work (_starve_retry).
            _sk = _starve_kind(data, payload)
            if _sk:
                resp.close()
                data2, payload2 = _starve_retry(_clock, hop_pid, hop_model, payload, _sk)
                if data2 is None:
                    errors.append("%s: %s even with more room" % (
                        hop_pid, "empty" if _sk == "empty" else "truncated stub"))
                    last_error = "empty" if _sk == "empty" else "starved"
                    continue
                data, payload = data2, payload2
            if _chat_json_nonanswer(data, has_tools, body.get("tools")) and _skip_nonanswer():
                # A 200 whose content IS the relay backend's error page (see
                # _chat_json_nonanswer). Falls through to the next hop exactly
                # like an empty 200, and sidelines the id so it stops winning.
                errors.append("%s: upstream error returned as content" % hop_pid)
                last_error = "empty"
                _note_nonanswer(hop_pid, hop_model)
                resp.close()
                continue
            if _chat_json_is_empty(data):
                errors.append("%s: empty (200 but no content)" % hop_pid)
                last_error = "empty"
                resp.close()
                continue
            gate = _answer_gate(data, payload, has_tools, hop=(hop_pid, hop_model))
            if gate == "junk":
                # A 200 that is ONLY degeneration (see _answer_gate): next hop.
                errors.append("%s: degenerate answer (nothing salvageable)" % hop_pid)
                last_error = "junk"
                _record_outcome(hop_pid, hop_model, False, junk=True)
                resp.close()
                continue
            _record_chat_usage(hop_pid, hop_model, data, est, ok=gate == "ok")
            # The CLIENT sees the size of the request it sent, not of the
            # compacted one (usage_history above keeps the real upstream count).
            _ctx_fix_chat_usage(data, est, hop_pid, hop_model)
            # ...and ~the visible length it asked for (reasoning allowance).
            _fit_visible_to_caller(data, payload)
            # Max tier, hard, non-streamed TEXT: a cross-family verifier (+ one
            # corrector on a high-severity revise). Fail-open; see roles.
            _rv = _max_text_review(body.get("model"), diff, has_tools,
                                   body.get("messages"), hop_pid, hop_model, data,
                                   _chain, est, max_tokens=body.get("max_tokens"))
            if _rv:
                hop_pid, hop_model, data = _rv
            if isinstance(data, dict):
                data["model"] = hop_pid + "/" + hop_model
                # An answer cut off at the provider's OWN default budget is a
                # bug the caller cannot see or fix -- learn from it so the next
                # request to this provider carries an explicit budget.
                try:
                    _note_default_truncation(
                        hop_pid, body.get("max_tokens"),
                        ((data.get("choices") or [{}])[0] or {}).get("finish_reason"))
                except Exception:                                # noqa: BLE001
                    pass
            return jsonify(data), 200, _routing_headers(hop_pid, hop_model, attempts, last_error)
        # Non-2xx. Retryable (429/5xx) and HARD errors (404/400/model-not-found)
        # both advance to the NEXT provider — each chain hop is a DIFFERENT
        # provider, so a broken model/provider should fall through before we give
        # up. Key rotation for the SAME provider already happened in _upstream_chat.
        # A network error while INSPECTING the error body (stream=True leaves the body
        # unread) must also just advance, never escape the loop into a 500.
        try:
            errors.append("%s: HTTP %d" % (hop_pid, resp.status_code))
            last_error = _classify_hop_error(status=resp.status_code)
            if _resp_not_offered(resp):
                # Not loaded this minute (see _NOT_OFFERED_RE): _upstream_chat
                # already filed the short skip. No reliability failure, and
                # never the chain's relayed hard error -- just the next hop.
                errors[-1] = "%s: model not offered right now" % hop_pid
                resp.close()
                continue
            # EVERY non-2xx hop is a delivery failure for the reliability
            # ledger, not just 5xx. MEASURED 2026-08-07, chasing an
            # api.airforce error the user reported THREE times: g4f fronts ~42
            # backends, one of which is api.airforce with a GLOBAL 1 req/sec
            # cap shared by every g4f user, so its models answer
            #   429 "Global rate limit exceeded ... upgrade at api.airforce"
            #   402 "requires an active subscription"
            # 429 is deliberately NOT in _DEAD_STATUSES (a burst limit really
            # is temporary), so those ids returned after every cooldown, for
            # ever. Recording only timeouts and 5xx meant a hop that ONLY ever
            # 429s never accrued a penalty and kept winning slots. Laplace
            # smoothing keeps this fair: an occasional 429 among successes
            # barely moves the ratio, while a model that never delivers sinks.
            _record_outcome(hop_pid, hop_model, False)
            if resp.status_code >= 500:
                # 429 already gets throttled inside _upstream_chat once its key
                # pool is exhausted; a raw 5xx (502/503/524...) reaching here
                # never did -- so a hop that is actually down (not just rate
                # limited) got retried on every single request with zero
                # cooldown. MEASURED 2026-08-05: g4f-nvidia's mistral hop hit
                # HTTP 524 (Cloudflare gateway timeout) right after a
                # ConnectionError on the SAME hop moments earlier in a
                # different request -- nothing had cooled it down between them.
                # Scoped to THIS model; two distinct models failing within
                # _HOP_ESCALATE_WINDOW escalate to the whole provider.
                _throttle_failed_hop(hop_pid, hop_model)
            if resp.status_code in (400, 413):
                # A context-length rejection counts towards the native
                # overflow signal (see _ctx_overflow_reply).
                _ctx_note_overflow_resp(resp, hop_pid, hop_model)
            if resp.status_code == 400 and _classify_soft_400(resp):
                resp.close()
                continue
            if not _retryable(resp.status_code):
                # Capture the body once so the last hard error can be relayed verbatim
                # after the chain is exhausted (retryable errors stay generic 502).
                try:
                    body_json = resp.json()
                    body_text = None
                except ValueError:
                    body_json = None
                    body_text = _sanitize(resp.text)
                last_hard = {"pid": hop_pid, "status": resp.status_code,
                             "json": body_json, "text": body_text}
        except requests.RequestException as exc:
            errors.append("%s: %s reading error body" % (hop_pid, _sanitize(exc.__class__.__name__)))
        resp.close()
        continue
    if _client_gone():
        return _client_gone_reply()      # the walk stopped on a cancel
    if _clock.spent():
        # The walk stopped on the clock, not on the fleet: say so, as a status
        # the client can see, instead of dressing it up as "all providers
        # failed" (or, before the deadline existed, never answering at all).
        _log.warning("CHAT-DEADLINE stream=%s tools=%s est=%d errors=[%s] details=[%s]",
                     stream, has_tools, est, "; ".join(errors) or "none", _hop_details_log())
        return _with_headers(_openai_error(_deadline_error_text(_clock, errors), 504,
                                           "timeout_error"),
                             _routing_headers(last_hop[0], last_hop[1], attempts, "deadline"))
    # CONTEXT OVERFLOW. Every hop that could have served this either refused it
    # as too long or would have had to drop most of the history: tell the CLI
    # in its own protocol's words, so it compacts its OWN history instead of
    # retrying the same oversized turn into another 503.
    _ov = _ctx_overflow_reply("openai")
    if _ov is not None:
        return _ov
    # Chain exhausted. Tell the client HOW LONG until a model frees (Retry-After) so
    # its SDK waits out a short throttle and auto-continues once capacity returns.
    eta = _capacity_eta()
    try:  # DIAG (temporary): record WHY the chat chain exhausted (any CLI's 503).
        _log.warning("CHAT-503 stream=%s tools=%s images=%s est=%d errors=[%s] details=[%s] last_hard=%s body=%s",
                     stream, has_tools, has_images, est, "; ".join(errors) or "none", _hop_details_log(),
                     (str(last_hard.get("status")) + "/" + str(last_hard.get("pid"))) if last_hard else "none",
                     _last_hard_log_body(last_hard))
    except Exception:
        pass
    hdrs = _routing_headers(last_hop[0], last_hop[1], attempts, last_error)
    # The hub's own message, never the upstream body (see _chain_exhausted_text).
    # A hard 4xx still maps to a client-retryable status, as before.
    status = _retryable_relay_status(last_hard["status"]) if last_hard is not None else 503
    return _with_headers(_with_retry_after(_openai_error(
        _chain_exhausted_text(errors, last_hard, est, has_tools), status, "upstream_error"),
        eta), hdrs)


# ---------------------------------------------------------------------------
# OpenAI Responses API gateway (OpenAI Codex CLI support)
# ---------------------------------------------------------------------------
# Codex (2026+) speaks ONLY the Responses API (wire_api="responses"), never chat
# completions. Strategy: translate the Responses request DOWN to OpenAI chat
# messages, reuse the SAME difficulty routing + provider chain + key rotation +
# fallback as /v1/chat/completions, then translate the chat result (JSON or SSE)
# back UP into Responses objects/events. No new orchestration is introduced.


def _responses_tools_to_chat(tools):
    """Responses tools ({"type":"function","name","description","parameters"},
    sometimes nested under a "function" key) -> OpenAI chat tools."""
    out = []
    for tool in tools or []:
        if not isinstance(tool, dict):
            continue
        inner = tool.get("function") if isinstance(tool.get("function"), dict) else tool
        name = inner.get("name")
        if not name:
            continue
        out.append({"type": "function", "function": {
            "name": name,
            "description": inner.get("description") or "",
            "parameters": inner.get("parameters") or {"type": "object", "properties": {}},
        }})
    return out


# Responses/Codex roles -> roles every OpenAI-chat model template accepts. The
# big one: Codex sends its system prompt with role "developer", which most open
# model chat templates reject ("Unexpected message role"). Map it to system.
_RESP_ROLE_MAP = {"system": "system", "developer": "system", "user": "user",
                  "assistant": "assistant", "tool": "tool"}


def _norm_role(role):
    return _RESP_ROLE_MAP.get(str(role or "user").lower(), "user")


def _responses_to_chat(body):
    """Translate a Responses request body into OpenAI chat-completions messages.
    Handles `instructions` (-> leading system), a STRING or LIST `input`, and the
    message / function_call / function_call_output item types (unknown item types,
    e.g. reasoning, are skipped). Roles are normalized (developer -> system) so
    open model chat templates don't reject the request."""
    messages = []
    instructions = body.get("instructions")
    if isinstance(instructions, str) and instructions.strip():
        messages.append({"role": "system", "content": instructions})

    inp = body.get("input")
    if isinstance(inp, str):
        messages.append({"role": "user", "content": inp})
        return messages
    # A function_call with NO NAME, and its output, are left out. MEASURED
    # 2026-09-27 (/agent, codex): a model streamed a tool call whose name never
    # arrived, codex replayed it in every later request, and dahl then 400'd
    # the whole conversation: "messages[40].tool_calls[0].function.name: must
    # not be empty". Nothing ran for that call (codex cannot dispatch a
    # nameless tool), so dropping the pair loses nothing -- and its output
    # alone would be an orphan tool message, which strict templates reject too.
    nameless = {(it.get("call_id") or it.get("id"))
                for it in (inp or []) if isinstance(it, dict)
                and it.get("type") == "function_call"
                and not str(it.get("name") or "").strip()}
    nameless.discard(None)
    for item in inp or []:
        if isinstance(item, str):
            messages.append({"role": "user", "content": item})
            continue
        if not isinstance(item, dict):
            continue
        itype = item.get("type")
        if itype == "function_call" and not str(item.get("name") or "").strip():
            continue
        if itype == "function_call_output" and nameless and (
                item.get("call_id") or item.get("id")) in nameless:
            continue
        if itype == "function_call":
            messages.append({
                "role": "assistant",
                "content": None,
                "tool_calls": [{
                    "id": item.get("call_id") or item.get("id"),
                    "type": "function",
                    "function": {
                        "name": item.get("name") or "",
                        "arguments": item.get("arguments") or "{}",
                    },
                }],
            })
        elif itype == "function_call_output":
            output = item.get("output")
            content = output if isinstance(output, str) else json.dumps(output)
            messages.append({
                "role": "tool",
                "tool_call_id": item.get("call_id") or item.get("id"),
                "content": content,
            })
        elif itype == "message" or itype is None:
            role = _norm_role(item.get("role"))
            content = item.get("content")
            if isinstance(content, str):
                text = content
            else:
                parts = []
                multimodal = False
                for part in content or []:
                    if isinstance(part, str):
                        parts.append(part)
                    elif isinstance(part, dict):
                        ptype = part.get("type")
                        if ptype in ("input_text", "output_text", "text"):
                            parts.append(part.get("text") or "")
                        elif ptype in ("input_image", "image_url"):
                            if part.get("file_id") and not part.get("image_url"):
                                raise ValueError("Responses file_id images cannot be resolved by this hub")
                            image = _normalize_image_url(part.get("image_url") or part.get("url"))
                            parts.append({"type": "image_url", "image_url": image})
                            multimodal = True
                        elif ptype in ("input_audio", "audio", "input_video", "video"):
                            raise ValueError("audio and video inputs are not supported by this hub")
                if multimodal:
                    text = [({"type": "text", "text": p} if isinstance(p, str) else p)
                            for p in parts]
                else:
                    text = "".join(parts)
            messages.append({"role": role, "content": text})
        # else: unknown item type (reasoning, etc.) -> skip
    return messages


def _infer_tool_name(arguments, tool_defs):
    """The one offered tool whose schema the call's ARGUMENTS fit, or None.

    For a tool call whose name never arrived (see _responses_stream). Only an
    UNAMBIGUOUS fit counts: the arguments parse to a JSON object, every key is
    a declared property of the tool, every required property is present --
    and exactly one offered tool passes. A tool that declares no properties
    fits only an empty object. Anything else is None: guessing a name would
    run the wrong tool with the user's arguments."""
    try:
        args = json.loads(_repair_tool_arguments(arguments or "") or "{}")
    except (ValueError, TypeError):
        return None
    if not isinstance(args, dict):
        return None
    fits = []
    for t in tool_defs or []:
        if not isinstance(t, dict):
            continue
        fn = t.get("function") if isinstance(t.get("function"), dict) else t
        name = str(fn.get("name") or "").strip()
        if not name:
            continue
        params = fn.get("parameters") if isinstance(fn.get("parameters"), dict) else {}
        props = params.get("properties") if isinstance(params.get("properties"), dict) else {}
        required = [r for r in (params.get("required") or []) if isinstance(r, str)]
        if not props:
            if not args:
                fits.append(name)
            continue
        if set(args) <= set(props) and set(required) <= set(args):
            fits.append(name)
    return fits[0] if len(fits) == 1 else None


def _fix_nameless_tool_calls(chat_json, tool_defs):
    """Give every nameless tool call in a chat-completions body the name its
    arguments unambiguously imply (_infer_tool_name), and DROP the ones that
    stay nameless -- a Responses client (codex) cannot run a call without a
    name, and replays it in every later request. Mutates and returns the
    body; a message left with no tool calls loses the key, so
    _chat_json_is_empty sees an all-nameless reply as the empty 200 it is."""
    try:
        msg = ((chat_json.get("choices") or [{}])[0] or {}).get("message")
        if not isinstance(msg, dict) or not msg.get("tool_calls"):
            return chat_json
        kept = []
        for tc in msg.get("tool_calls") or []:
            if not isinstance(tc, dict):
                continue
            fn = tc.get("function") if isinstance(tc.get("function"), dict) else {}
            if not str(fn.get("name") or "").strip():
                name = _infer_tool_name(fn.get("arguments"), tool_defs)
                if not name:
                    _log.warning("[nameless-tool-call] dropped a tool call with no name")
                    continue
                fn = dict(fn, name=name)
                tc = dict(tc, function=fn)
            kept.append(tc)
        if kept:
            msg["tool_calls"] = kept
        else:
            msg.pop("tool_calls", None)
    except Exception:                                            # noqa: BLE001
        pass
    return chat_json


def _chat_to_responses(chat_json, model_label, tool_defs=None):
    """Non-streaming OpenAI chat-completions JSON -> a Responses `response` object.
    A tool call without a name is repaired from its arguments when that is
    unambiguous, else left out (_fix_nameless_tool_calls) -- never emitted."""
    _fix_nameless_tool_calls(chat_json, tool_defs)
    _dedupe_tool_calls_json(chat_json)
    choice = (chat_json.get("choices") or [{}])[0]
    msg = choice.get("message") or {}
    output = []
    content = msg.get("content")
    if isinstance(content, list):   # content-parts -> join their text (never relay a list)
        content = "".join((p.get("text") or "") for p in content if isinstance(p, dict))
    if content:
        output.append({
            "type": "message",
            "id": "msg_" + uuid.uuid4().hex,
            "status": "completed",
            "role": "assistant",
            "content": [{"type": "output_text", "text": content, "annotations": []}],
        })
    for tc in msg.get("tool_calls") or []:
        fn = tc.get("function") or {}
        output.append({
            "type": "function_call",
            "id": "fc_" + uuid.uuid4().hex,
            "call_id": tc.get("id"),
            "name": fn.get("name") or "",
            "arguments": _normalize_apply_patch_diff(
                fn.get("name") or "", _repair_tool_arguments(fn.get("arguments") or "")),
            "status": "completed",
        })
    usage = chat_json.get("usage") or {}
    pt = int(usage.get("prompt_tokens") or 0)
    ct = int(usage.get("completion_tokens") or 0)
    return {
        "id": "resp_" + uuid.uuid4().hex,
        "object": "response",
        "created_at": int(time.time()),
        "status": "completed",
        "model": model_label,
        "output": output,
        "usage": {"input_tokens": pt, "output_tokens": ct, "total_tokens": pt + ct},
    }


def _responses_stream(resp, model_label, line_iter=None, first=_MISSING, prompt_est=0,
                      hop_pid=None, hop_model=None, prompt_text=None, tools_offered=False,
                      last_prompt=None, answer_gate=None, tool_defs=None, served=None):
    """Consume an upstream OpenAI chat SSE stream and re-emit it as Responses API
    events for Codex. When `line_iter`/`first` are supplied (the first-byte peek
    already pulled the first line from this exact iterator) the pre-read line is
    processed first, then the rest of the SAME iterator — so fast-path output is
    identical to before. `hop_pid`/`hop_model` are used only to record the
    outcome if _STREAM_PROGRESS_DEADLINE fires. Event order:
      response.created
      [text]  output_item.added -> content_part.added -> output_text.delta* ->
              output_text.done -> content_part.done -> output_item.done
      [tools] output_item.added -> function_call_arguments.delta* ->
              function_call_arguments.done -> output_item.done
      response.completed
    The assistant message (if any) is output_index 0; each tool call takes the
    next index. Defensive: unparseable chunks are skipped, and a stream always
    ends with a terminal event so Codex never hangs: an upstream that died
    before its finish_reason gets `response.failed` (codex retries it, see
    BROKEN UPSTREAM STREAMS); any other failure still ends response.completed."""
    resp_id = "resp_" + uuid.uuid4().hex
    created = int(time.time())

    def _obj(status, output_items, usage=None):
        o = {"id": resp_id, "object": "response", "created_at": created,
             "status": status, "model": model_label, "output": output_items}
        if served:
            # Which provider/model REALLY answered. `model` stays the id the
            # client asked for (codex keys its model metadata on it), so the
            # served pair rides in the Responses API's own string map.
            o["metadata"] = dict(served)
        if usage is not None:
            o["usage"] = usage
        return o

    done_items = []          # [(output_index, item)] assembled so far
    next_index = 0
    text_started = False
    text_item_id = text_index = None
    text_buf = []
    tools = {}               # oai tool index -> {out_index,item_id,call_id,name,args[]}
    usage = None
    stream_fin = None        # last finish_reason seen, for the end-of-stream judgement
    cut_short = [False]      # the request deadline cut this stream (_DEADLINE_CUT_LINE)
    if line_iter is None:
        line_iter = resp.iter_lines(decode_unicode=False)

    def _announce_tool(st, repair=False):
        """Emit output_item.added for a tool call ONCE it has a name, plus the
        argument text buffered while it had none. MEASURED 2026-09-27: an
        upstream streamed a tool call whose name never arrived; announcing it
        on its first delta handed codex a function_call with name "", which
        it replayed in every later request until a strict provider 400'd the
        whole conversation. With `repair` (end of stream) a still-nameless
        call is named from its arguments when unambiguous (_infer_tool_name),
        else dropped -- never emitted unnamed."""
        nonlocal next_index
        if not st["name"] and repair:
            st["name"] = _infer_tool_name("".join(st["args"]), tool_defs) or ""
            if not st["name"]:
                _log.warning("[nameless-tool-call] %s/%s: dropped a streamed tool call "
                             "that never named its tool", hop_pid, hop_model)
                return
        if not st["name"] or st["out_index"] is not None:
            return
        st["out_index"] = next_index
        next_index += 1
        yield _sse_event("response.output_item.added", {
            "type": "response.output_item.added",
            "output_index": st["out_index"],
            "item": {"type": "function_call", "id": st["item_id"],
                     "call_id": st["call_id"], "name": st["name"],
                     "arguments": "", "status": "in_progress"}})
        if st["args"]:
            yield _sse_event("response.function_call_arguments.delta", {
                "type": "response.function_call_arguments.delta",
                "item_id": st["item_id"], "output_index": st["out_index"],
                "delta": "".join(st["args"])})

    def _finalize_open_items():
        """Emit done-events for whatever text/tool item is still in_progress and
        append it to done_items. Called once, either after a clean finish or from
        the except handler on a mid-stream failure (e.g. an upstream idle-read
        timeout) — without this, a caught exception left done_items empty even
        though real text had already been streamed to the client via delta events,
        so response.completed reported output: [] and the caller saw a clean
        'nothing happened' turn instead of the partial answer it actually got."""
        if text_started:
            full = "".join(text_buf)
            yield _sse_event("response.output_text.done", {
                "type": "response.output_text.done",
                "item_id": text_item_id, "output_index": text_index,
                "content_index": 0, "text": full})
            yield _sse_event("response.content_part.done", {
                "type": "response.content_part.done",
                "item_id": text_item_id, "output_index": text_index,
                "content_index": 0,
                "part": {"type": "output_text", "text": full, "annotations": []}})
            item = {"type": "message", "id": text_item_id, "status": "completed",
                    "role": "assistant",
                    "content": [{"type": "output_text", "text": full, "annotations": []}]}
            yield _sse_event("response.output_item.done", {
                "type": "response.output_item.done",
                "output_index": text_index, "item": item})
            done_items.append((text_index, item))

        # A call whose name NEVER arrived: name it from its arguments when that
        # is unambiguous, else leave it out entirely. Its output_item.added was
        # held back (see _announce_tool), so nothing about it reached the client.
        for st in sorted(tools.values(), key=lambda s: s["seq"]):
            if st["out_index"] is None:
                yield from _announce_tool(st, repair=True)
        for _oai_idx, st in sorted(((k, s) for k, s in tools.items()
                                    if s["out_index"] is not None),
                                   key=lambda kv: kv[1]["out_index"]):
            # Repair before emitting so we never hand the CLI a doubled-JSON tool_call
            # that it will replay and 503 on every later turn (see _repair_tool_arguments),
            # then strip a git-diff header block apply_patch parsers reject even though
            # the underlying hunk is valid (see _normalize_apply_patch_diff).
            full_args = _normalize_apply_patch_diff(
                st["name"], _repair_tool_arguments("".join(st["args"])))
            yield _sse_event("response.function_call_arguments.done", {
                "type": "response.function_call_arguments.done",
                "item_id": st["item_id"], "output_index": st["out_index"],
                "arguments": full_args})
            item = {"type": "function_call", "id": st["item_id"],
                    "call_id": st["call_id"], "name": st["name"],
                    "arguments": full_args,
                    "status": "incomplete" if cut_short[0] else "completed"}
            yield _sse_event("response.output_item.done", {
                "type": "response.output_item.done",
                "output_index": st["out_index"], "item": item})
            done_items.append((st["out_index"], item))

    last_progress = time.time()
    judged = False           # outcome already filed (stall / error / end check)
    reads = {}               # what the upstream iterator raised (_upstream_reads)
    try:
        yield _sse_event("response.created",
                         {"type": "response.created", "response": _obj("in_progress", [])})

        for raw in _upstream_reads(_chain_first(first, line_iter), reads):
            now = time.time()
            if _sse_chunk_is_progress(raw):
                last_progress = now
            elif now - last_progress > _STREAM_PROGRESS_DEADLINE:
                _log.warning("[stream-stall] %s/%s: no real content for %ds, cutting off",
                            hop_pid, hop_model, _STREAM_PROGRESS_DEADLINE)
                _record_outcome(hop_pid, hop_model, False)
                judged = True
                break
            if not raw or not raw.startswith(b"data:"):
                continue
            data = raw[5:].strip()
            if data == b"[DONE]":
                break
            try:
                chunk = json.loads(data.decode("utf-8"))
            except (ValueError, UnicodeDecodeError):
                continue
            if isinstance(chunk, dict) and chunk.get("error"):
                if stream_fin is None:
                    # The upstream gave up before finishing: a broken stream,
                    # not a finished answer (see the end of this loop).
                    reads["exc"] = _UpstreamStreamError(_stream_error_frame_text(chunk))
                    break
                # an error object AFTER the finish_reason: the answer stands --
                # stop cleanly, emit the terminal below (never relay the error
                # as content)
                _record_outcome(hop_pid, hop_model, False)
                judged = True
                break
            u = chunk.get("usage")
            if isinstance(u, dict) and (u.get("prompt_tokens") is not None
                                        or u.get("completion_tokens") is not None):
                usage = u
            choices = chunk.get("choices") or []
            if not choices:
                continue
            if (choices[0] or {}).get("finish_reason"):
                stream_fin = choices[0]["finish_reason"]
                if chunk.get("id") == _DEADLINE_CUT_ID:
                    cut_short[0] = True
            delta = (choices[0] or {}).get("delta") or {}

            # Reasoning-phase keepalive: a thinking model sends reasoning deltas for
            # up to a minute before its first visible token. Forward an SSE COMMENT
            # (ignored by every compliant parser, invents no event type codex would
            # have to understand) so the connection is visibly alive meanwhile.
            if delta.get("reasoning_content") or delta.get("reasoning"):
                yield ": keepalive\n\n"

            dtext = delta.get("content")
            if dtext is not None and not isinstance(dtext, str):
                # Some upstreams stream a non-string content delta (an int, or a
                # content-parts list). Coerce to str so `"".join(text_buf)` below
                # can't crash ("sequence item N: expected str instance, int found").
                dtext = "".join(
                    (p.get("text") or "") for p in dtext
                    if isinstance(p, dict)) if isinstance(dtext, list) else str(dtext)
            if dtext:
                if not text_started:
                    text_started = True
                    text_item_id = "msg_" + uuid.uuid4().hex
                    text_index = next_index
                    next_index += 1
                    yield _sse_event("response.output_item.added", {
                        "type": "response.output_item.added",
                        "output_index": text_index,
                        "item": {"type": "message", "id": text_item_id,
                                 "status": "in_progress", "role": "assistant",
                                 "content": []}})
                    yield _sse_event("response.content_part.added", {
                        "type": "response.content_part.added",
                        "item_id": text_item_id, "output_index": text_index,
                        "content_index": 0,
                        "part": {"type": "output_text", "text": "", "annotations": []}})
                text_buf.append(dtext)
                yield _sse_event("response.output_text.delta", {
                    "type": "response.output_text.delta",
                    "item_id": text_item_id, "output_index": text_index,
                    "content_index": 0, "delta": dtext})

            for tcd in delta.get("tool_calls") or []:
                if not isinstance(tcd, dict):
                    continue
                oai_idx = tcd.get("index", 0)
                fn = tcd.get("function") or {}
                st = tools.get(oai_idx)
                if st is None:
                    # out_index is assigned when the call is ANNOUNCED, which
                    # waits for its name (see _announce_tool).
                    st = {"out_index": None, "seq": len(tools),
                          "item_id": "fc_" + uuid.uuid4().hex,
                          "call_id": tcd.get("id") or ("call_" + uuid.uuid4().hex[:24]),
                          "name": str(fn.get("name") or "").strip(), "args": []}
                    tools[oai_idx] = st
                else:
                    if tcd.get("id"):
                        st["call_id"] = tcd["id"]
                    if str(fn.get("name") or "").strip() and not st["name"]:
                        st["name"] = str(fn["name"]).strip()
                args = fn.get("arguments")
                if args is not None and not isinstance(args, str):
                    args = str(args)  # tool-call args must be str for the join()
                if args:
                    st["args"].append(args)
                if st["out_index"] is None:
                    # Announces (with the buffered args) once a name exists.
                    yield from _announce_tool(st)
                elif args:
                    yield _sse_event("response.function_call_arguments.delta", {
                        "type": "response.function_call_arguments.delta",
                        "item_id": st["item_id"], "output_index": st["out_index"],
                        "delta": args})

        broken = reads.get("exc")
        if broken is not None and stream_fin is None:
            # The upstream died before its finish_reason (BROKEN UPSTREAM
            # STREAMS). Evidence, openai/codex main, read 2026-10-03:
            # codex-api/src/sse/responses.rs stores a `response.failed` error
            # and raises it when the body closes; sse/responses_error.rs
            # parse_failed_response: an UNKNOWN error code -> ApiError::Retryable
            # -> CodexErr::Stream ("stream disconnected before completion"),
            # which core/src/session/turn.rs retries up to the provider's
            # stream_max_retries (default 5, "Reconnecting... n/5"). Fatal
            # codes avoided: context_length_exceeded, insufficient_quota,
            # usage_not_included, invalid_prompt, server_is_overloaded (fatal
            # without a retry-after). A body closed with no response.completed
            # is retried the same way; the event only adds a readable reason.
            # NO output_item.done for the partial items: handle_output_item_done
            # records each one into history, and the retry rebuilds its prompt
            # from that history -- the partial would be duplicated.
            if not judged and not getattr(answer_gate, "cut", False):
                _note_broken_stream(hop_pid, hop_model, broken, "responses")
            failed = _obj("failed", [])
            failed["error"] = {"code": "upstream_error",
                               "message": _BROKEN_STREAM_TEXT % _stream_error_text(broken)}
            yield _sse_event("response.failed", {"type": "response.failed",
                                                 "response": failed})
            return
        if broken is not None:
            # Died AFTER its finish_reason: the answer is complete -- finish it
            # as any ended stream (judged, finalized, response.completed).
            _log.error("Responses stream error after the answer finished: %s",
                       _stream_error_text(broken))

        # Name what never got one, BEFORE the outcome is filed: a stream whose
        # only "tool call" stays nameless delivered nothing usable, and must
        # be judged exactly like an empty one.
        for st in tools.values():
            if not st["name"]:
                st["name"] = _infer_tool_name("".join(st["args"]), tool_defs) or ""
        if not judged and not getattr(answer_gate, "cut", False):
            # The stream ENDED: file the outcome it never used to (see
            # _record_stream_outcome). The client already has the bytes.
            _record_stream_outcome(hop_pid, hop_model, "".join(text_buf),
                                   tool_calls=any(st["name"] for st in tools.values()),
                                   finish_reason=stream_fin,
                                   prompt_text=prompt_text, tools_offered=tools_offered,
                                   last_prompt=last_prompt)
        yield from _finalize_open_items()

        # ALWAYS report usage, sized on the ORIGINAL request (see
        # _reported_prompt_tokens): Codex's auto-compaction keys on it, and a
        # stream with no usage -- most free upstreams, before the hub asked for
        # include_usage -- left Codex blind to its own context filling up.
        _u = usage if isinstance(usage, dict) else {}
        pt = _reported_prompt_tokens(_u.get("prompt_tokens"), prompt_est, hop_pid, hop_model)
        ct = _u.get("completion_tokens")
        if ct is None:
            ct = (len("".join(text_buf)) + sum(
                len("".join(st.get("args") or [])) for st in tools.values())) // 4
        ct = int(ct or 0)
        final_usage = {"input_tokens": pt, "output_tokens": ct, "total_tokens": pt + ct}
        final_output = [it for _i, it in sorted(done_items, key=lambda t: t[0])]
        if cut_short[0]:
            final = _obj("incomplete", final_output, final_usage)
            final["incomplete_details"] = {"reason": "max_output_tokens"}
            yield _sse_event("response.incomplete", {
                "type": "response.incomplete", "response": final})
        else:
            yield _sse_event("response.completed", {
                "type": "response.completed",
                "response": _obj("completed", final_output, final_usage)})
    except Exception as exc:  # never leave Codex hanging on a mid-stream failure
        _log.error("Responses stream error: %s", _sanitize(str(exc)))
        try:
            yield from _finalize_open_items()
        except Exception:
            pass
        partial = [it for _i, it in sorted(done_items, key=lambda t: t[0])]
        try:
            yield _sse_event("response.completed", {
                "type": "response.completed",
                "response": _obj("completed", partial)})
        except Exception:
            pass
    finally:
        # Usage goes to the REAL hop, never to model_label. model_label is the
        # id the CLIENT asked for, echoed back on purpose (codex sends "auto");
        # partitioning it filed every Codex stream's tokens under a phantom
        # provider "auto" with model "", so the real provider's usage row never
        # moved. No hop ids (the swarm replay, a sub-CLI hop whose usage
        # _record_chat_usage already filed) = nothing to record here.
        try:
            if not (hop_pid and hop_model):
                pass
            elif usage is not None:
                pt = int(usage.get("prompt_tokens") or 0)
                ct = int(usage.get("completion_tokens") or 0)
                usage_history.record(hop_pid, hop_model, pt, ct, estimated=False)
            else:
                usage_history.record(hop_pid, hop_model, prompt_est,
                                     len("".join(text_buf)) // 4, estimated=True)
        except Exception:
            pass
        resp.close()


@app.route("/v1/responses", methods=["POST"])
def v1_responses(_retry_pass=False, _hedged=False):
    body = request.get_json(force=True, silent=True)
    if not isinstance(body, dict):
        return _openai_error("Invalid JSON body.", 400)
    try:
        messages = _responses_to_chat(body)
        messages, image_count = _normalize_openai_messages(messages)
    except Exception as exc:
        return _openai_error("Could not translate request: " + _sanitize(str(exc)), 400)
    if not messages:
        return _openai_error("No input to send.", 400)
    if not _retry_pass:
        _bandit_credit(messages)       # see _bandit_credit
        _v1_observe(messages, body)    # observed evidence: receipts + facts
    # Codex picks a MODE on one screen and a REASONING LEVEL on the next; the
    # pair is the hub's (mode, effort). Must happen before the swarm dispatch
    # below, which keys off the model id. /v1/chat/completions has always read
    # a mode id; this protocol -- the one codex actually speaks -- never did,
    # so `model: "coding"` restricted nothing here even before the picker.
    body = _mode_and_effort(body)
    has_images = image_count > 0

    # Tools + size estimate up front (Codex sends huge tool schemas — they must
    # count toward routing so a big request doesn't land on a small-TPM provider).
    tools = _responses_tools_to_chat(body.get("tools"))
    est = _est_tokens(messages, tools)

    # Same routing as /v1/chat/completions: Auto/empty/claude-* -> difficulty
    # route across available, SIZE-CAPABLE providers; explicit '<pid>/<model>' bypasses.
    has_tools = bool(tools)
    diff = None
    _orch_reply = _orch_command_response("responses", body, messages, est)
    if _orch_reply is not None:
        return _orch_reply
    # FRONT DOOR (see _front_door_overflow): a conversation no alive model can
    # hold is refused HERE -- before the pipeline dispatch, routing and any hop,
    # so nothing is uploaded. The context state is set up once, early, so the
    # pipeline tiers below report usage like the single-model path.
    # signal=False: see the twin in _chat_completions_uncached.
    _ctx_begin(body, messages, est, signal=False)
    _fd = _front_door_overflow("responses", messages, tools, est,
                               stream=bool(body.get("stream")),
                               model_label=(body.get("model") or "auto"),
                               images=has_images)
    if _fd is not None:
        return _fd
    # SWARM on codex's own protocol. This dispatch used to exist only in
    # /v1/chat/completions -- which codex never calls -- so "swarm" arrived here
    # as an unknown bare id and _resolve_model turned it into a literal model on
    # the default provider. Measured live: 'groq/swarm ! groq: HTTP 404'.
    if _is_swarm_model(body.get("model")) and _swarm_fast_path(
            dict(body, tools=tools, max_tokens=body.get("max_output_tokens")), messages):
        # A TRIVIAL ask on a pipeline id: one strong model, no fan-out (see
        # _swarm_fast_path; the header names it).
        _note_pipeline_fast_path()
        body = dict(body, model="best")
    if _is_swarm_model(body.get("model")):
        served = _swarm_as_responses(body, messages, tools, est)
        if served is not None:
            return served
        if _client_gone():
            return _client_gone_reply()
        # No model could serve the fan-out. Still a request for maximum effort,
        # so continue as 'best' -- never as a model named "swarm".
        body = dict(body, model="best")
    # The request's wall clock starts here, before routing, after the
    # pipeline (which has its own cap). See _REQUEST_DEADLINE_DEFAULT.
    _begin_request_deadline()
    # Did the CALLER name a model, or is the router choosing? A pinned model
    # opens the turn whatever its record says -- see _build_chain(pinned=).
    # Passed as a kwarg dict for the same reason exclude_identities is: an
    # ordinary orchestrated request keeps the exact call shape it always had, so
    # a stand-in for _build_chain never has to know about a parameter it does
    # not see.
    _pin_kw = {"pinned": True} if not _is_orchestrate(body.get("model")) else {}
    if not _pin_kw:
        router = _route_for_vision if has_images else _route_by_difficulty
        pid, resolved, diff = router(messages, body.get("max_output_tokens"), est,
                                     require_tools=has_tools,
                                     **_quality_route_kwargs(body.get("model"), has_images))
        pid, resolved = _apply_orchestrator(pid, resolved, messages, est, has_tools,
                                            has_images, None, body, diff=diff)
        if pid is None:
            if has_images:
                return _openai_error(
                    "No enabled verified vision model is available. Enable Google, "
                    "Cloudflare, or Z.AI with a usable vision model.", 400)
            pid, resolved = _resolve_model(body.get("model"))
    else:
        pid, resolved = _resolve_model(body.get("model"))
    if pid is None:
        return _openai_error(resolved, 400)
    _blocked = _model_block_reason(pid, resolved)
    if _blocked:
        return _openai_error(_blocked, 403, "permission_error")
    if has_images and not _is_vision_model(pid, resolved):
        return _openai_error(
            "Model '%s/%s' is not a verified vision model." % (pid, resolved), 400)
    not_ready = _check_provider_ready(pid)
    if not_ready:
        return _openai_error(not_ready, 400)

    base_payload = {"messages": messages}
    if body.get("max_output_tokens"):
        try:
            base_payload["max_tokens"] = int(body["max_output_tokens"])
        except (TypeError, ValueError):
            pass
    if body.get("temperature") is not None:
        base_payload["temperature"] = body["temperature"]
    if body.get("top_p") is not None:
        base_payload["top_p"] = body["top_p"]
    if tools:
        base_payload["tools"] = tools
        if body.get("tool_choice") is not None:
            base_payload["tool_choice"] = body["tool_choice"]

    stream = bool(body.get("stream"))
    if stream:
        # Ask the upstream for usage: without it Codex saw none and its own
        # auto-compaction never fired (see _STREAM_USAGE_OPTIONS).
        base_payload["stream_options"] = dict(_STREAM_USAGE_OPTIONS)
    _ctx_begin(body, messages, est)
    errors = _HopErrors()
    last_hard = None  # last hard (non-retryable) upstream error, relayed if chain is exhausted
    last_error = None  # class of the LAST failed hop (transparency header)
    _tried = []  # DIAG: every hop the chain actually offered (root-cause the 503s)
    _err_bodies = {}  # DIAG: first raw error body per (pid:status) — reveals soft-400 reasons
    _walk_started = time.monotonic()
    # See _ChainClock: the request deadline and the trivial-turn hop budget.
    _mark_turn_shape(diff, est, pinned=bool(_pin_kw))
    _clock = _ChainClock(trivial=_is_trivial_turn(
        messages, body.get("max_output_tokens"), diff, est, pinned=bool(_pin_kw)),
        tools=has_tools, est=est, stream=stream, pinned=bool(_pin_kw))
    _plan_quality_fallback(_clock, body.get("model"), has_images, bool(_pin_kw),
                           messages, body.get("max_output_tokens"))
    _chain = _build_chain(pid, resolved, est, require_vision=has_images,
                          require_tools=has_tools, messages=messages,
                          **_pin_kw)
    # See the twin in /v1/chat/completions (hedging a trivial turn). A retry
    # pass after a walk that already hedged may not hedge again: one extra
    # upstream call per client request, not per walk.
    if not _hedged:
        _clock.plan_hedge(_chain, base_payload, diff, est=est, tools=has_tools,
                          images=has_images, lines=True)
    # Gap 2: parallel specialists for a hard, fresh tool turn on auto/best.
    base_payload["messages"] = _single_turn_team_notes(
        base_payload.get("messages"), base_payload.get("tools"), _chain,
        (pid, resolved), est, diff, bool(_pin_kw), stream)
    for hop_pid, hop_model in _clock.walk(_chain):
        if _clock.consumed(hop_pid, hop_model):
            continue              # a hedge already ran this hop
        _tried.append(hop_pid + "/" + hop_model)
        if _clock.spent():
            errors.append("stopped: request deadline reached")
            last_error = "deadline"
            break
        if stream and _header_budget_spent(_walk_started):
            # See _STREAM_HEADER_BUDGET: past this the client has stopped
            # listening for headers, so a further hop cannot be delivered even
            # if it succeeds.
            errors.append("stopped after %ds: the client's header timeout was "
                          "about to expire" % _STREAM_HEADER_BUDGET)
            break
        if not prov.is_model_allowed(hop_model):
            continue
        # MID-REQUEST re-check — see the twin in /v1/chat/completions. The chain
        # is built once, so without this a provider proven dead on hop 2 keeps
        # every one of its later hops (measured: 7 consecutive puter/402s).
        if _is_provider_dead(hop_pid):
            errors.append("%s: sidelined mid-request" % hop_pid)
            continue
        # A local-CLI relay hop (sub-*) is a subprocess that runs to completion —
        # it cannot stream token-by-token. User-approved tradeoff 2026-07-29:
        # rather than skip it outright whenever the client wants a stream
        # (which silently skipped every relay hop for interactive/streaming
        # codex sessions — their actual normal usage),
        # dispatch it NON-streaming regardless of what the client asked for,
        # then emit its complete answer as ONE synthetic chunk through the
        # SAME _responses_stream() a real stream uses below. The client sees
        # nothing for the call's duration, then the full answer arrives at
        # once — not real streaming, but no longer silently skipped either.
        is_sub_hop = _is_sub(hop_pid)
        payload = dict(base_payload)
        payload["model"] = hop_model
        _apply_reasoning_effort(payload, hop_model, diff, pid=hop_pid)
        dispatch_stream = stream and not is_sub_hop
        payload["stream"] = dispatch_stream
        try:
            _act_pick(hop_pid, hop_model)
            resp = _clock.dispatch(hop_pid, payload, dispatch_stream)
            hop_pid, hop_model, payload = _clock.served(hop_pid, hop_model, payload)
        except (requests.RequestException, RuntimeError) as exc:
            errors.append("%s: %s" % (hop_pid, _sanitize(exc.__class__.__name__)))
            _note_hop_detail(hop_pid, exc)       # log-only: class + message
            last_error = _classify_hop_error(exc=exc)
            if isinstance(exc, requests.exceptions.Timeout):
                # A hop that TIMES OUT (unlike a fast-fail 429/400) can burn
                # minutes doing it -- and an immediate retry of the same
                # request (codex's own client-level retry on 503, or this
                # chain's bonus whole-chain retry a bit further down) hits the
                # SAME slow hop again, compounding into a long stall with zero
                # progress. MEASURED 2026-08-03: nvidia/mistral-medium-3.5-128b
                # ReadTimeout'd 4 times running, ~7 minutes each, while every
                # other hop in the chain failed fast. Same short cooldown a
                # 429 already gets, so the NEXT chain build skips it long
                # enough for a retry to reach a hop that actually responds.
                # A plain ConnectionError deliberately stays OUT of this branch
                # (see test_a_fast_failing_hop_is_not_throttled_only_a_real_
                # timeout_is): a real connection-refused fails just as fast on
                # a retry, so there's nothing costly to protect against. The
                # SLOW failure mode that error class was missing turned out to
                # be a raw 5xx status (524 etc.) that never raises at all --
                # handled separately below, in the non-2xx branch.
                # Scoped to THIS model unless the evidence is provider-wide
                # (see _throttle_failed_hop).
                _throttle_failed_hop(hop_pid, hop_model, exc=exc)
                # ...and count it, so a provider that ONLY ever times out is eventually
                # parked rather than re-tried forever. Heavily gated -- see
                # _note_provider_timeout, which ignores everything that is not
                # provably the provider's own fault.
                _note_provider_timeout(hop_pid, exc)
            continue
        if resp.status_code == 200:
            # Echo back the id the client ASKED for (codex sends "auto", which now has
            # config metadata) instead of the resolved "pid/model" — otherwise codex
            # re-warns "Model metadata for `pid/model` not found" on every response
            # (issue #21070). The real model that answered is still shown on the hub
            # dashboard + activity feed, so no transparency is lost.
            model_label = (body.get("model") or "").strip() or (hop_pid + "/" + hop_model)
            if stream and is_sub_hop:
                try:
                    data = resp.json()
                except (ValueError, requests.RequestException):
                    errors.append("%s: non-JSON 200 body" % hop_pid)
                    last_error = "non-json"
                    resp.close()
                    continue
                if _chat_json_nonanswer(data, has_tools, tools) and _skip_nonanswer():
                    # A 200 whose content IS the relay backend's error page (see
                    # _chat_json_nonanswer). Falls through to the next hop exactly
                    # like an empty 200, and sidelines the id so it stops winning.
                    errors.append("%s: upstream error returned as content" % hop_pid)
                    last_error = "empty"
                    _note_nonanswer(hop_pid, hop_model)
                    resp.close()
                    continue
                if _chat_json_is_empty(data):
                    errors.append("%s: empty (200 but no content)" % hop_pid)
                    last_error = "empty"
                    resp.close()
                    continue
                gate = _answer_gate(data, payload, has_tools, hop=(hop_pid, hop_model))
                if gate == "junk":
                    errors.append("%s: degenerate answer (nothing salvageable)" % hop_pid)
                    last_error = "junk"
                    _record_outcome(hop_pid, hop_model, False, junk=True)
                    resp.close()
                    continue
                _record_chat_usage(hop_pid, hop_model, data, est, ok=gate == "ok")
                delta, _fin = _sub_stream_message(data)
                synth = json.dumps({"choices": [{"delta": delta}]}).encode("utf-8")
                line_iter = iter([b"data: " + synth, b"data: [DONE]"])
                return Response(stream_with_context(
                    _responses_stream(resp, model_label, line_iter=line_iter, prompt_est=est,
                                      tool_defs=tools,
                                      served=_served_metadata(hop_pid, hop_model))),
                    mimetype="text/event-stream",
                    headers=dict(_SSE_HEADERS, **_routing_headers(
                        hop_pid, hop_model, len(_tried), last_error)))
            if stream:
                # #4: peek the first line BEFORE committing the 200 SSE stream so a
                # hung/slow provider falls through to the next hop instead of stalling.
                line_it = resp.iter_lines(decode_unicode=False)
                if has_tools:
                    # DSML typed as text -> real tool_calls (tool_rescue).
                    line_it = tool_rescue.rescue_stream(line_it, tools, "lines")
                # Peek until REAL content (not just the first byte): an empty 200
                # (role delta + [DONE], no content) must fall through to the next
                # model instead of being streamed to codex as a dead-end answer.
                status, buffered = _peek_until_content(
                    line_it, _clock.peek_timeout(hop_model, est, pid=hop_pid),
                    content_grace=_clock.content_grace(),
                    check=_peek_check(payload, has_tools))
                _clock.note_peek(hop_pid, hop_model, status)
                if status == "starved":
                    # See the twin in /v1/chat/completions.
                    resp.close()
                    _again = _stream_starve_retry(_clock, hop_pid, hop_model, payload, est,
                                                  has_tools, tools, lines=True)
                    if _again is not None:
                        resp, line_it, status, buffered, payload = _again
                if status == "nonanswer" and not _skip_nonanswer():
                    status = "content"    # a 2nd bare announcement: served (one retry)
                if status != "content":
                    errors.append("%s: %s (200 but no content)" % (hop_pid, status))
                    last_error = _classify_hop_error(peek=status)
                    if status == "nonanswer":
                        # The relay streamed its own error page as the answer --
                        # sideline the id so it stops winning hop 1 (see
                        # _note_nonanswer; ranking alone never removed it).
                        _note_nonanswer(hop_pid, hop_model)
                    elif status == "junk":
                        _record_outcome(hop_pid, hop_model, False, junk=True)
                    resp.close()
                    continue
                _note_ttft(resp, hop_pid, hop_model)
                chained = _clock.guard(_chain_buffered(buffered, line_it),
                                       _DEADLINE_CUT_LINE, "%s/%s" % (hop_pid, hop_model))
                gated = _gate_stream(chained, "lines", hop_pid, hop_model, payload, has_tools)
                return Response(stream_with_context(
                    _responses_stream(resp, model_label,
                                      line_iter=(_dedupe_tool_stream(gated, "lines", hop_pid,
                                                                     hop_model)
                                                 if has_tools else gated),
                                      prompt_est=est,
                                      hop_pid=hop_pid, hop_model=hop_model,
                                      prompt_text=_prompt_text_for_check(payload),
                                      last_prompt=_last_user_text_for_check(payload),
                                      tools_offered=has_tools, answer_gate=gated,
                                      tool_defs=tools,
                                      served=_served_metadata(hop_pid, hop_model))),
                    mimetype="text/event-stream",
                    headers=dict(_SSE_HEADERS, **_routing_headers(
                        hop_pid, hop_model, len(_tried), last_error)))
            try:
                data = resp.json()
            except (ValueError, requests.RequestException):
                errors.append("%s: non-JSON 200 body" % hop_pid)
                last_error = "non-json"
                resp.close()
                continue
            # Starved (empty or a truncated stub at "length"): one same-pair
            # retry with room -- see the twin in /v1/chat/completions.
            _sk = _starve_kind(data, payload)
            if _sk:
                resp.close()
                data2, payload2 = _starve_retry(_clock, hop_pid, hop_model, payload, _sk)
                if data2 is None:
                    errors.append("%s: %s even with more room" % (
                        hop_pid, "empty" if _sk == "empty" else "truncated stub"))
                    last_error = "empty" if _sk == "empty" else "starved"
                    continue
                data, payload = data2, payload2
            # A nameless tool call is named from its arguments when that is
            # unambiguous, else removed -- so an all-nameless reply is the
            # empty 200 below (next hop), never a call codex cannot run.
            _fix_nameless_tool_calls(data, tools)
            if _chat_json_nonanswer(data, has_tools, tools) and _skip_nonanswer():
                # A 200 whose content IS the relay backend's error page (see
                # _chat_json_nonanswer). Falls through to the next hop exactly
                # like an empty 200, and sidelines the id so it stops winning.
                errors.append("%s: upstream error returned as content" % hop_pid)
                last_error = "empty"
                _note_nonanswer(hop_pid, hop_model)
                resp.close()
                continue
            if _chat_json_is_empty(data):
                errors.append("%s: empty (200 but no content)" % hop_pid)
                last_error = "empty"
                resp.close()
                continue
            gate = _answer_gate(data, payload, has_tools, hop=(hop_pid, hop_model))
            if gate == "junk":
                # A 200 that is ONLY degeneration (see _answer_gate): next hop.
                errors.append("%s: degenerate answer (nothing salvageable)" % hop_pid)
                last_error = "junk"
                _record_outcome(hop_pid, hop_model, False, junk=True)
                resp.close()
                continue
            _record_chat_usage(hop_pid, hop_model, data, est, ok=gate == "ok")
            _ctx_fix_chat_usage(data, est, hop_pid, hop_model)
            _fit_visible_to_caller(data, payload)
            _rv = _max_text_review(body.get("model"), diff, has_tools, messages,
                                   hop_pid, hop_model, data, _chain, est,
                                   max_tokens=body.get("max_output_tokens"))
            if _rv:
                hop_pid, hop_model, data = _rv
            out = _chat_to_responses(data, model_label, tool_defs=tools)
            out["metadata"] = _served_metadata(hop_pid, hop_model)
            return (jsonify(out), 200,
                    _routing_headers(hop_pid, hop_model, len(_tried), last_error))
        try:
            errors.append("%s: HTTP %d" % (hop_pid, resp.status_code))
            last_error = _classify_hop_error(status=resp.status_code)
            if _resp_not_offered(resp):
                # Not loaded this minute (see _NOT_OFFERED_RE): _upstream_chat
                # already filed the short skip. No reliability failure, and
                # never the chain's relayed hard error -- just the next hop.
                errors[-1] = "%s: model not offered right now" % hop_pid
                resp.close()
                continue
            # EVERY non-2xx hop is a delivery failure for the reliability
            # ledger, not just 5xx. MEASURED 2026-08-07, chasing an
            # api.airforce error the user reported THREE times: g4f fronts ~42
            # backends, one of which is api.airforce with a GLOBAL 1 req/sec
            # cap shared by every g4f user, so its models answer
            #   429 "Global rate limit exceeded ... upgrade at api.airforce"
            #   402 "requires an active subscription"
            # 429 is deliberately NOT in _DEAD_STATUSES (a burst limit really
            # is temporary), so those ids returned after every cooldown, for
            # ever. Recording only timeouts and 5xx meant a hop that ONLY ever
            # 429s never accrued a penalty and kept winning slots. Laplace
            # smoothing keeps this fair: an occasional 429 among successes
            # barely moves the ratio, while a model that never delivers sinks.
            _record_outcome(hop_pid, hop_model, False)
            if resp.status_code >= 500:
                # See the matching comment in /v1/chat/completions: a raw 5xx
                # (unlike 429, already handled inside _upstream_chat) never got
                # a cooldown here, so a genuinely down hop was retried on every
                # request. MEASURED 2026-08-05: g4f-nvidia/mistral-medium-3.5.
                _throttle_failed_hop(hop_pid, hop_model)
            _ekey = "%s:%d" % (hop_pid, resp.status_code)  # DIAG: capture first raw body
            if _ekey not in _err_bodies:
                try:
                    _err_bodies[_ekey] = _sanitize(resp.text)[:200]
                except Exception:
                    _err_bodies[_ekey] = "?"
            if resp.status_code in (400, 413):
                # A context-length rejection counts towards the native
                # overflow signal (see _ctx_overflow_reply).
                _ctx_note_overflow_resp(resp, hop_pid, hop_model)
            if resp.status_code == 400 and _classify_soft_400(resp):
                resp.close()
                continue
            if not _retryable(resp.status_code):
                try:
                    body_json = resp.json()
                    body_text = None
                except ValueError:
                    body_json = None
                    body_text = _sanitize(resp.text)
                last_hard = {"pid": hop_pid, "status": resp.status_code,
                             "json": body_json, "text": body_text}
        except requests.RequestException as exc:
            errors.append("%s: %s reading error body" % (hop_pid, _sanitize(exc.__class__.__name__)))
        resp.close()
        continue
    # No provider yielded a 200. We have NOT emitted any SSE yet, so return a
    # normal non-200 JSON OpenAI-style error (Codex checks the HTTP status before
    # opening the event stream and surfaces this cleanly) rather than a fake 200
    # SSE stream carrying an error.
    # Chain exhausted. Tell the client HOW LONG until a model frees (Retry-After) so
    # its SDK waits out a short throttle and auto-continues once capacity returns.
    # TRANSIENT-STORM RETRY. An agentic CLI fires many requests in quick
    # succession, and the free relays are metered PER MINUTE (g4f ~5/min,
    # llm7 20/min). A burst therefore 429s every hop in the chain at once and
    # Codex receives a hard 503 — which reads to the user as "it ignored me and
    # stopped", when the window would have refilled seconds later. MEASURED:
    # three Codex turns 503'd with every hop 429, while the same providers all
    # read healthy moments afterwards.
    # So when EVERY failure was transient, wait once and run the chain again.
    # Bounded to a single retry, and only when nothing hard failed — a real 400
    # or 404 still surfaces immediately, because retrying that just wastes time.
    if _client_gone():
        return _client_gone_reply()      # the walk stopped on a cancel
    if _clock.spent():
        # Stopped on the clock (see _ChainClock). No transient-storm retry: the
        # retry is the same request to codex, and its time is already gone.
        _log.warning("RESPONSES-DEADLINE stream=%s tools=%s est=%d tried=[%s] errors=[%s] details=[%s]",
                     stream, has_tools, est, ", ".join(_tried),
                     "; ".join(errors) or "none", _hop_details_log())
        return _with_headers(_openai_error(_deadline_error_text(_clock, errors), 504,
                                           "timeout_error"),
                             {"X-Free-LLM-Hub-Last-Error": "deadline"})
    # CONTEXT OVERFLOW, in Codex's own terms: a streamed response.failed with
    # code context_length_exceeded is what makes Codex mark its window full
    # and auto-compact (a bare 400 only prints an error). Before the storm
    # retry -- retrying the same oversized turn cannot help.
    _ov = _ctx_overflow_reply("responses", stream=stream,
                              model_label=(body.get("model") or "auto"))
    if _ov is not None:
        return _ov
    if (not last_hard and errors and not _retry_pass
            and all(_TRANSIENT_ERR_RE.search(e or "") for e in errors)):
        _log.info("[chain] all %d hops transient (429/5xx) — backing off %.1fs and retrying",
                  len(errors), _CHAIN_RETRY_DELAY)
        time.sleep(_CHAIN_RETRY_DELAY)
        return v1_responses(_retry_pass=True, _hedged=_clock._hedge_fired)
    eta = _capacity_eta()
    # DIAG (temporary): the access log only shows "503" — record WHY the responses
    # chain (Codex's path) exhausted so the real root cause is visible, not guessed.
    try:
        _lh_body = "none"
        if last_hard:
            try:
                _lh_body = (json.dumps(last_hard.get("json"))
                            if last_hard.get("json") is not None
                            else str(last_hard.get("text")))[:700]
            except Exception:
                _lh_body = "?"
        _log.warning(
            "RESPONSES-503 stream=%s tools=%s images=%s est=%d hops=%d tried=[%s] errors=[%s] details=[%s] last_hard=%s body=%s bodies=%s",
            stream, has_tools, has_images, est, len(_tried), ", ".join(_tried),
            "; ".join(errors) or "none", _hop_details_log(),
            (str(last_hard.get("status")) + "/" + str(last_hard.get("pid"))) if last_hard else "none",
            _lh_body, json.dumps(_err_bodies)[:1400])
    except Exception:
        pass
    # Codex's path carried no routing headers at all — surface at least the last
    # hop-failure class so 'why did the chain degrade' is one curl -i away.
    hdrs = {"X-Free-LLM-Hub-Last-Error": last_error or "none"}
    # The hub's own message, never the upstream body (see _chain_exhausted_text).
    status = _retryable_relay_status(last_hard["status"]) if last_hard is not None else 503
    return _with_headers(_with_retry_after(_openai_error(
        _chain_exhausted_text(errors, last_hard, est, has_tools), status, "upstream_error"),
        eta), hdrs)


# ---------------------------------------------------------------------------
# Anthropic-compatible gateway (Claude Code support)
# ---------------------------------------------------------------------------

def _blocks_to_text(content):
    """Anthropic content (str | [blocks]) -> plain text."""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts = []
        for block in content:
            if isinstance(block, str):
                parts.append(block)
            elif isinstance(block, dict):
                btype = block.get("type")
                if btype == "text":
                    parts.append(block.get("text") or "")
                elif btype == "tool_result":
                    parts.append(_blocks_to_text(block.get("content")))
                elif btype == "image":
                    parts.append("[image omitted]")
        return "\n".join(p for p in parts if p)
    return ""


def _anthropic_image_to_openai(block):
    source = block.get("source") if isinstance(block, dict) else None
    if not isinstance(source, dict):
        raise ValueError("Anthropic image.source must be an object")
    stype = source.get("type")
    if stype == "base64":
        mime = str(source.get("media_type") or "").lower()
        data = source.get("data")
        if mime not in _IMAGE_MIMES or not isinstance(data, str):
            raise ValueError("Anthropic base64 images need a supported media_type and data")
        value = "data:%s;base64,%s" % (mime, data)
    elif stype == "url":
        value = source.get("url")
    else:
        raise ValueError("unsupported Anthropic image source type '%s'" % stype)
    return {"type": "image_url", "image_url": _normalize_image_url(value)}


def _anthropic_to_openai_messages(body):
    """Anthropic system+messages -> OpenAI messages (tools included)."""
    out = []
    system_parts = []
    system = body.get("system")
    if system:
        text = system if isinstance(system, str) else _blocks_to_text(system)
        if text:
            system_parts.append(text)
    for msg in body.get("messages") or []:
        role = msg.get("role")
        content = msg.get("content")
        if role == "system":
            # CLAUDE CODE PUTS A SYSTEM MESSAGE INSIDE `messages`. MEASURED
            # 2026-09-27 (claude 2.1.283, body captured against a local stub):
            # messages = [user(<system-reminder>s + the question),
            #             system("# Environment ... Primary working directory
            #             ... agent types ... skills")]. It fell into the
            # "user" branch below, so the hub's LAST USER MESSAGE was the
            # environment block, not the question: the pipeline fast path
            # never recognised "What is N plus 1?" (so multi/coding-swarm
            # fanned it out to five models), the difficulty classifier read
            # the environment, and upstream models saw the cwd as a trailing
            # user turn. It is system context: folded into the leading system
            # message, where every OpenAI-shaped upstream accepts it.
            text = content if isinstance(content, str) else _blocks_to_text(content)
            if text and text not in system_parts:
                system_parts.append(text)
            continue
        if isinstance(content, str):
            out.append({"role": role, "content": content})
            continue
        blocks = content if isinstance(content, list) else []
        if role == "assistant":
            text_parts, tool_calls = [], []
            for block in blocks:
                if not isinstance(block, dict):
                    continue
                btype = block.get("type")
                if btype == "text":
                    text_parts.append(block.get("text") or "")
                elif btype == "tool_use":
                    tool_calls.append({
                        "id": block.get("id") or ("call_" + uuid.uuid4().hex[:12]),
                        "type": "function",
                        "function": {
                            "name": block.get("name") or "",
                            "arguments": json.dumps(block.get("input") or {}),
                        },
                    })
            entry = {"role": "assistant",
                     "content": "\n".join(p for p in text_parts if p) or None}
            if tool_calls:
                entry["tool_calls"] = tool_calls
            out.append(entry)
        else:  # user
            tool_results = [b for b in blocks
                            if isinstance(b, dict) and b.get("type") == "tool_result"]
            for tr in tool_results:
                out.append({"role": "tool",
                            "tool_call_id": tr.get("tool_use_id") or "",
                            "content": _blocks_to_text(tr.get("content")) or ""})
            rest = [b for b in blocks
                    if not (isinstance(b, dict) and b.get("type") == "tool_result")]
            content_parts = []
            has_image = False
            for block in rest:
                if isinstance(block, str):
                    content_parts.append({"type": "text", "text": block})
                elif isinstance(block, dict) and block.get("type") == "text":
                    content_parts.append({"type": "text", "text": block.get("text") or ""})
                elif isinstance(block, dict) and block.get("type") == "image":
                    content_parts.append(_anthropic_image_to_openai(block))
                    has_image = True
            text = "".join(p.get("text", "") for p in content_parts
                           if p.get("type") == "text")
            if content_parts or not tool_results:
                out.append({"role": "user", "content": content_parts if has_image else text})
    if system_parts:
        out.insert(0, {"role": "system", "content": "\n\n".join(system_parts)})
    return out


def _anthropic_tools_to_openai(tools):
    out = []
    for tool in tools or []:
        if not isinstance(tool, dict) or not tool.get("name"):
            continue
        out.append({"type": "function", "function": {
            "name": tool["name"],
            "description": tool.get("description") or "",
            "parameters": tool.get("input_schema") or {"type": "object", "properties": {}},
        }})
    return out


def _anthropic_tool_choice_to_openai(tc):
    if not isinstance(tc, dict):
        return None
    ttype = tc.get("type")
    if ttype == "auto":
        return "auto"
    if ttype == "any":
        return "required"
    if ttype == "tool" and tc.get("name"):
        return {"type": "function", "function": {"name": tc["name"]}}
    return None


def _map_stop_reason(finish_reason):
    return {"stop": "end_turn", "length": "max_tokens",
            "tool_calls": "tool_use", "function_call": "tool_use",
            "content_filter": "end_turn"}.get(finish_reason or "stop", "end_turn")


def _estimate_input_tokens(body):
    """Input tokens of an Anthropic request, as Claude Code would be billed:
    system, every text block, tool_use inputs, tool_result contents, the TOOL
    SCHEMAS (Claude Code ships ~15-20K tokens of them -- leaving them out made
    every count low by exactly the part that never changes), images sized from
    their own bytes, and non-Latin text at its real density. No routing margin:
    this number is read by the client."""
    chars = 0
    extra = 0.0

    def _text(t):
        nonlocal chars, extra
        if isinstance(t, str) and t:
            chars += len(t)
            extra += ctxwin.nonlatin_extra_tokens(t)

    def _blocks(content):
        nonlocal extra
        if isinstance(content, str):
            _text(content)
            return
        if not isinstance(content, list):
            return
        for block in content:
            if isinstance(block, str):
                _text(block)
                continue
            if not isinstance(block, dict):
                continue
            btype = block.get("type")
            if btype == "text":
                _text(block.get("text"))
            elif btype == "tool_result":
                _blocks(block.get("content"))
            elif btype == "tool_use":
                _text(str(block.get("name") or ""))
                try:
                    _text(json.dumps(block.get("input") or {}, ensure_ascii=False))
                except (TypeError, ValueError):
                    pass
            elif btype == "image":
                src = block.get("source") if isinstance(block.get("source"), dict) else {}
                extra += ctxwin.image_tokens(
                    url=src.get("url"),
                    b64=src.get("data") if src.get("type") == "base64" else None)
            elif btype == "document":
                src = block.get("source") if isinstance(block.get("source"), dict) else {}
                if src.get("type") == "text":
                    _text(src.get("data"))
                else:
                    extra += ctxwin.IMAGE_TOKENS_DEFAULT

    _blocks(body.get("system"))
    for msg in body.get("messages") or []:
        if isinstance(msg, dict):
            _blocks(msg.get("content"))
    tools = body.get("tools")
    if isinstance(tools, list) and tools:
        try:
            chars += len(json.dumps(tools, ensure_ascii=False))
        except (TypeError, ValueError):
            pass
    return max(1, chars // 4 + int(extra))


def _openai_resp_to_anthropic(data, model_str):
    _dedupe_tool_calls_json(data)
    choice = (data.get("choices") or [{}])[0]
    msg = choice.get("message") or {}
    content = []
    text = msg.get("content")
    if isinstance(text, list):   # content-parts -> join their text (never relay a list)
        text = "".join((p.get("text") or "") for p in text if isinstance(p, dict))
    if text:
        content.append({"type": "text", "text": text})
    for tc in msg.get("tool_calls") or []:
        fn = tc.get("function") or {}
        if not ((fn.get("name") or "").strip()):
            continue   # drop a nameless tool_call — never emit a blank-name tool_use
        try:
            args = json.loads(fn.get("arguments") or "{}")
        except ValueError:
            args = {}
        if not isinstance(args, dict):
            args = {}
        content.append({"type": "tool_use",
                        "id": tc.get("id") or ("toolu_" + uuid.uuid4().hex[:16]),
                        "name": fn.get("name"),
                        "input": args})
    if not content:
        content = [{"type": "text", "text": ""}]
    usage = data.get("usage") or {}
    return {
        "id": "msg_" + str(data.get("id") or uuid.uuid4().hex),
        "type": "message",
        "role": "assistant",
        "model": model_str,
        "content": content,
        "stop_reason": _map_stop_reason(choice.get("finish_reason")),
        "stop_sequence": None,
        "usage": {"input_tokens": int(usage.get("prompt_tokens") or 0),
                  "output_tokens": int(usage.get("completion_tokens") or 0)},
    }


def _sse_event(name, obj):
    return ("event: %s\ndata: %s\n\n" % (name, json.dumps(obj, ensure_ascii=False))).encode("utf-8")


def _anthropic_close_blocks(block_index, text_open, tool_blocks, late_text, closed):
    """The content_block events that end an Anthropic stream: a stop for every
    block still open (the live text block, every tool block), then the text
    that arrived after a tool call started as ONE text block, or an empty text
    block when nothing was sent at all. Idempotent -- `closed` and `late_text`
    are updated in place -- so the error path after a partial close never
    stops a block twice. See the note in _anthropic_stream."""
    open_ = [i for i in ([text_open] if text_open is not None else [])
             + sorted(tool_blocks.values()) if i not in closed]
    for i in open_:
        closed.add(i)
        yield _sse_event("content_block_stop", {"type": "content_block_stop", "index": i})
    started = [block_index] + list(closed) + list(tool_blocks.values())
    late = "".join(late_text)
    del late_text[:]
    nxt = max(started) + 1
    if late.strip():
        closed.add(nxt)
        yield _sse_event("content_block_start", {
            "type": "content_block_start", "index": nxt,
            "content_block": {"type": "text", "text": ""}})
        yield _sse_event("content_block_delta", {
            "type": "content_block_delta", "index": nxt,
            "delta": {"type": "text_delta", "text": late}})
        yield _sse_event("content_block_stop", {"type": "content_block_stop", "index": nxt})
    elif nxt == 0 and not closed:
        # upstream produced nothing: still emit a valid shape
        closed.add(0)
        yield _sse_event("content_block_start", {
            "type": "content_block_start", "index": 0,
            "content_block": {"type": "text", "text": ""}})
        yield _sse_event("content_block_stop", {"type": "content_block_stop", "index": 0})


def _anthropic_final_usage(real_in, input_est, pid, model, out_tokens):
    """The closing message_delta's usage: output tokens, plus input tokens
    sized on the ORIGINAL request (the upstream count scaled back up by the
    hop's compaction, or the estimate when upstream reported none)."""
    u = {"output_tokens": int(out_tokens or 0)}
    try:
        u["input_tokens"] = _reported_prompt_tokens(real_in, input_est, pid, model)
    except Exception:                                            # noqa: BLE001
        pass
    return u


def _anthropic_stream(resp, model_str, input_tokens, line_iter=None, first=_MISSING,
                      hop_pid=None, hop_model=None, prompt_text=None, tools_offered=False,
                      last_prompt=None, answer_gate=None):
    """Translate an upstream OpenAI SSE stream into the Anthropic event
    sequence: message_start -> content_block_start -> content_block_delta* ->
    content_block_stop -> message_delta -> message_stop. When `line_iter`/`first`
    are supplied (the first-byte peek already pulled the first line from this exact
    iterator) the pre-read line is processed first, then the rest of the SAME
    iterator — fast-path output is identical to before.

    `hop_pid`/`hop_model` (the REAL resolved provider/model, not the client-facing
    `model_str` -- Claude Code sends its own requested model string, which is not
    necessarily "pid/model") are used only to key usage_history recording."""
    msg_id = "msg_" + uuid.uuid4().hex
    if line_iter is None:
        line_iter = resp.iter_lines(decode_unicode=False)
    last_progress = time.time()
    message_ended = False
    try:
        yield _sse_event("message_start", {"type": "message_start", "message": {
            "id": msg_id, "type": "message", "role": "assistant", "model": model_str,
            "content": [], "stop_reason": None, "stop_sequence": None,
            # the same figure the closing message_delta reports (live window
            # steering included, _reported_prompt_tokens)
            "usage": {"input_tokens": _reported_prompt_tokens(None, input_tokens),
                      "output_tokens": 0}}})
        yield _sse_event("ping", {"type": "ping"})

        # EVERY BLOCK IS STARTED ONCE AND STOPPED ONCE, and no delta ever names
        # a stopped block. Claude Code rejects anything else as a malformed
        # stream ("event referenced an already-closed content block"), keeps
        # what it had and -- in -p mode -- asks the model to "resume" in a
        # SECOND request: a second answer. It used to happen whenever text
        # arrived between a tool call's argument deltas (the tool block was
        # stopped for the text, then got more arguments) or when a failure
        # after the final stop sent the stop again. Now text before the first
        # tool call streams live; text after it is sent as ONE text block after
        # the tool blocks, which stay open until the upstream is done.
        block_index = -1        # highest anthropic block index started
        text_open = None        # index of the open live text block
        tool_blocks = {}        # openai tool_call index -> anthropic block index
        late_text = []          # text that arrived after a tool call started
        closed = set()          # block indexes already stopped
        finish_reason = None
        out_tokens = None
        real_out_tokens = None   # usage_history: only set from a REAL upstream usage object
        real_in_tokens = None
        text_chars = 0
        text_parts = []          # for the end-of-stream judgement only
        judged = False           # outcome already filed (stall / error)
        reads = {}               # what the upstream iterator raised (_upstream_reads)

        for raw in _upstream_reads(_chain_first(first, line_iter), reads):
            now = time.time()
            if _sse_chunk_is_progress(raw):
                last_progress = now
            elif now - last_progress > _STREAM_PROGRESS_DEADLINE:
                _log.warning("[stream-stall] %s/%s: no real content for %ds, cutting off",
                            hop_pid, hop_model, _STREAM_PROGRESS_DEADLINE)
                _record_outcome(hop_pid, hop_model, False)
                judged = True
                break
            if not raw or not raw.startswith(b"data:"):
                continue
            data = raw[5:].strip()
            if data == b"[DONE]":
                break
            try:
                chunk = json.loads(data.decode("utf-8"))
            except (ValueError, UnicodeDecodeError):
                continue
            if isinstance(chunk, dict) and chunk.get("error"):
                if finish_reason is None:
                    # gave up before finishing: a broken stream (end of loop)
                    reads["exc"] = _UpstreamStreamError(_stream_error_frame_text(chunk))
                    break
                # error object after the finish_reason -> the answer stands:
                # stop cleanly, emit terminal below
                _record_outcome(hop_pid, hop_model, False)
                judged = True
                break
            usage = chunk.get("usage")
            if isinstance(usage, dict) and usage.get("completion_tokens") is not None:
                out_tokens = usage.get("completion_tokens")
                real_out_tokens = out_tokens
                if usage.get("prompt_tokens") is not None:
                    real_in_tokens = usage.get("prompt_tokens")
            choices = chunk.get("choices") or []
            if not choices:
                continue
            choice = choices[0] or {}
            if choice.get("finish_reason"):
                finish_reason = choice["finish_reason"]
            delta = choice.get("delta") or {}

            # A reasoning model can think for a minute before its first visible
            # token. Upstream is sending reasoning deltas the whole time, but we
            # forward nothing — so the CLI sees a dead connection and may give up.
            # A ping is the protocol's own keepalive: no content, no shape change.
            if delta.get("reasoning_content") or delta.get("reasoning"):
                yield _sse_event("ping", {"type": "ping"})

            dtext = delta.get("content")
            if dtext is not None and not isinstance(dtext, str):
                # Coerce a non-string content delta (int / content-parts list) so
                # len(dtext) and the text_delta below can't crash — same upstream
                # quirk that broke the /v1/responses stream.
                dtext = "".join(
                    (p.get("text") or "") for p in dtext
                    if isinstance(p, dict)) if isinstance(dtext, list) else str(dtext)
            if dtext:
                text_chars += len(dtext)
                if hop_pid and text_chars <= _STREAM_DIGEST_CAP:
                    text_parts.append(dtext)
                if tool_blocks:
                    late_text.append(dtext)        # see the note on block_index
                else:
                    if text_open is None:
                        block_index += 1
                        text_open = block_index
                        yield _sse_event("content_block_start", {
                            "type": "content_block_start", "index": block_index,
                            "content_block": {"type": "text", "text": ""}})
                    yield _sse_event("content_block_delta", {
                        "type": "content_block_delta", "index": text_open,
                        "delta": {"type": "text_delta", "text": dtext}})

            for tcd in delta.get("tool_calls") or []:
                if not isinstance(tcd, dict):
                    continue
                oai_idx = tcd.get("index", 0)
                fn = tcd.get("function") or {}
                if oai_idx not in tool_blocks:
                    if text_open is not None:
                        closed.add(text_open)
                        yield _sse_event("content_block_stop",
                                         {"type": "content_block_stop", "index": text_open})
                        text_open = None
                    block_index += 1
                    tool_blocks[oai_idx] = block_index
                    yield _sse_event("content_block_start", {
                        "type": "content_block_start", "index": block_index,
                        "content_block": {
                            "type": "tool_use",
                            "id": tcd.get("id") or ("toolu_" + uuid.uuid4().hex[:16]),
                            "name": fn.get("name") or "",
                            "input": {}}})
                args = fn.get("arguments")
                if args is not None and not isinstance(args, str):
                    args = str(args)
                if args:
                    yield _sse_event("content_block_delta", {
                        "type": "content_block_delta", "index": tool_blocks[oai_idx],
                        "delta": {"type": "input_json_delta", "partial_json": args}})

        broken = reads.get("exc")
        if broken is not None and finish_reason is None:
            # The upstream died before its finish_reason (BROKEN UPSTREAM
            # STREAMS): the body ENDS here, cleanly, with NO further event --
            # no content_block_stop, message_delta, message_stop or error.
            # Evidence, code.claude.com/docs/en/errors (read 2026-10-03,
            # VERIFIED): "Connection lost mid-response ... You also see this
            # variant when a proxy or gateway ends the response body cleanly
            # before the response has finished", and Claude Code retries
            # "Dropped connections ... before Claude has completed any part of
            # its response ... even if some text had already started
            # streaming" (CLAUDE_CODE_MAX_RETRIES, default 10). An `event:
            # error` (overloaded_error) is retried only "before any of
            # Claude's response has streamed" -- and the commit here always
            # follows content, so the clean end is the signal that retries.
            # Stopping the open text block would COMPLETE it, and a failure
            # "after Claude has completed a block" is never retried. A text
            # block already stopped by a tool call stays kept (Claude Code:
            # "The response above may be incomplete"), never reported done.
            # (The Anthropic TS SDK raises an `event: error` frame as APIError
            # with no status; the closed source's reading of it is INFERRED.)
            if not judged and not getattr(answer_gate, "cut", False):
                _note_broken_stream(hop_pid, hop_model, broken, "messages")
            message_ended = True        # the except below must not close it
            return
        if broken is not None:
            # Died AFTER its finish_reason: the answer is complete.
            _log.error("Anthropic stream error after the answer finished: %s",
                       _stream_error_text(broken))
        if not judged and not getattr(answer_gate, "cut", False):
            # The stream ENDED: file the outcome it never used to (see
            # _record_stream_outcome). The client already has the bytes.
            _record_stream_outcome(hop_pid, hop_model, "".join(text_parts),
                                   tool_calls=bool(tool_blocks), finish_reason=finish_reason,
                                   prompt_text=prompt_text, tools_offered=tools_offered,
                                   last_prompt=last_prompt)
        for ev in _anthropic_close_blocks(block_index, text_open, tool_blocks,
                                          late_text, closed):
            yield ev
        if out_tokens is None:
            out_tokens = max(1, text_chars // 4)
        yield _sse_event("message_delta", {
            "type": "message_delta",
            "delta": {"stop_reason": _map_stop_reason(finish_reason), "stop_sequence": None},
            "usage": _anthropic_final_usage(real_in_tokens, input_tokens, hop_pid,
                                            hop_model, out_tokens)})
        message_ended = True
        yield _sse_event("message_stop", {"type": "message_stop"})
    except Exception as exc:
        # A fault in this translator's OWN handling (an upstream that dies is
        # caught by _upstream_reads and answered with _anthropic_broken_event
        # above). Propagating would truncate the SSE body with NO terminal
        # event, which leaves Claude Code waiting forever on a turn that is
        # already dead. Close the message properly instead.
        # NOTE: `except Exception` deliberately does not catch GeneratorExit, so a
        # normal client disconnect still tears the generator down as before.
        _log.error("Anthropic stream error: %s", _sanitize(str(exc)))
        try:
            if message_ended:
                return          # message_stop already went out: nothing to close
            # Stops only what is still open -- a block stopped before the
            # failure is never stopped twice (see the note on block_index).
            for ev in _anthropic_close_blocks(block_index, text_open, tool_blocks,
                                              late_text, closed):
                yield ev
            if out_tokens is None:
                out_tokens = max(1, text_chars // 4)
            yield _sse_event("message_delta", {
                "type": "message_delta",
                "delta": {"stop_reason": _map_stop_reason(finish_reason),
                          "stop_sequence": None},
                "usage": _anthropic_final_usage(real_in_tokens, input_tokens, hop_pid,
                                                hop_model, out_tokens)})
            yield _sse_event("message_stop", {"type": "message_stop"})
        except Exception:
            pass    # client socket already gone / state not yet bound
    finally:
        try:
            if hop_pid and hop_model:
                if real_out_tokens is not None:
                    pt = real_in_tokens if real_in_tokens is not None else int(input_tokens or 0)
                    usage_history.record(hop_pid, hop_model, pt, int(real_out_tokens),
                                         estimated=False)
                else:
                    usage_history.record(hop_pid, hop_model, int(input_tokens or 0),
                                         int(out_tokens or (text_chars // 4)), estimated=True)
        except Exception:
            pass
        resp.close()


@app.route("/v1/messages", methods=["POST"])
def v1_messages():
    body = request.get_json(force=True, silent=True)
    if not isinstance(body, dict):
        return _anthropic_error("invalid_request_error", "Invalid JSON body.", 400)
    try:
        oai_messages = _anthropic_to_openai_messages(body)
        oai_messages, image_count = _normalize_openai_messages(oai_messages)
    except Exception as exc:
        return _anthropic_error("invalid_request_error",
                                "Could not translate request: " + _sanitize(exc), 400)
    if not oai_messages:
        return _anthropic_error("invalid_request_error", "No messages to send.", 400)
    _bandit_credit(oai_messages)       # see _bandit_credit
    _v1_observe(oai_messages, body)    # observed evidence: receipts + facts
    has_images = image_count > 0
    # A "<category>-<effort>" compound (e.g. from ANTHROPIC_MODEL=coding-swarm)
    # sets the mode and becomes a plain effort tier, before the swarm dispatch
    # below reads the id -- same as the other two protocols.
    body = _apply_category_effort(body)
    # Claude Code sends model 'claude-*' + a big system/tools payload -> orchestrate
    # by difficulty AND request size (skip small-TPM providers for large requests).
    tools = _anthropic_tools_to_openai(body.get("tools"))
    est = _est_tokens(oai_messages, tools)
    has_tools = bool(tools)
    diff = None
    _orch_reply = _orch_command_response("messages", body, oai_messages, est)
    if _orch_reply is not None:
        return _orch_reply
    # FRONT DOOR (see _front_door_overflow and the twin in /v1/responses).
    _ctx_begin(body, oai_messages, est, signal=False)
    _fd = _front_door_overflow("anthropic", oai_messages, tools, est,
                               stream=bool(body.get("stream")), images=has_images)
    if _fd is not None:
        return _fd
    # Same two modes, on claude's protocol. See the note in /v1/responses.
    if _is_swarm_model(body.get("model")) and _swarm_fast_path(
            dict(body, tools=tools), oai_messages):
        _note_pipeline_fast_path()
        body = dict(body, model="best")
    if _is_swarm_model(body.get("model")):
        served = _swarm_as_anthropic(body, oai_messages, tools)
        if served is not None:
            return served
        if _client_gone():
            return _client_gone_reply()
        body = dict(body, model="best")
    # The request's wall clock starts here, before routing, after the
    # pipeline (which has its own cap). See _REQUEST_DEADLINE_DEFAULT.
    _begin_request_deadline()
    # A bare CATEGORY id (ANTHROPIC_MODEL=coding) restricts the pool to that
    # category for THIS request, exactly as /v1/chat/completions does. REPORTED:
    # without this, "coding" was merely orchestrate-able (_mode_keys() is in
    # _is_orchestrate), so Claude Code routed over EVERY category and the mode
    # it asked for was silently ignored. After the swarm dispatch above, so the
    # "swarm" category key -- also the fan-out id -- has already been consumed.
    _req_mode = _valid_mode((body.get("model") or "").strip().lower())
    if _req_mode and _req_mode != MODE_ALL:
        try:
            g.model_mode = _req_mode
        except Exception:                                        # noqa: BLE001
            pass
    # Did the CALLER name a model, or is the router choosing? A pinned model
    # opens the turn whatever its record says -- see _build_chain(pinned=).
    # Passed as a kwarg dict for the same reason exclude_identities is: an
    # ordinary orchestrated request keeps the exact call shape it always had, so
    # a stand-in for _build_chain never has to know about a parameter it does
    # not see.
    _pin_kw = {"pinned": True} if not _is_orchestrate(body.get("model")) else {}
    if not _pin_kw:
        router = _route_for_vision if has_images else _route_by_difficulty
        pid, resolved, diff = router(oai_messages, body.get("max_tokens"), est,
                                     require_tools=has_tools,
                                     **_quality_route_kwargs(body.get("model"), has_images))
        pid, resolved = _apply_orchestrator(pid, resolved, oai_messages, est, has_tools,
                                            has_images, None, body, diff=diff)
        if pid is None:
            if has_images:
                return _anthropic_error(
                    "invalid_request_error",
                    "No enabled verified vision model is available. Enable Google, "
                    "Cloudflare, or Z.AI with a usable vision model.", 400)
            pid, resolved = _resolve_model(body.get("model"))
    else:
        pid, resolved = _resolve_model(body.get("model"))
    if pid is None:
        return _anthropic_error("invalid_request_error", resolved, 400)
    _blocked = _model_block_reason(pid, resolved)
    if _blocked:
        return _anthropic_error("permission_error", _blocked, 403)
    if has_images and not _is_vision_model(pid, resolved):
        return _anthropic_error(
            "invalid_request_error",
            "Model '%s/%s' is not a verified vision model." % (pid, resolved), 400)
    not_ready = _check_provider_ready(pid)
    if not_ready:
        return _anthropic_error("invalid_request_error", not_ready, 400)

    base_payload = {"messages": oai_messages}
    if body.get("max_tokens"):
        try:
            base_payload["max_tokens"] = int(body["max_tokens"])
        except (TypeError, ValueError):
            pass
    if body.get("temperature") is not None:
        base_payload["temperature"] = body["temperature"]
    if body.get("top_p") is not None:
        base_payload["top_p"] = body["top_p"]
    if body.get("stop_sequences"):
        base_payload["stop"] = body["stop_sequences"]
    if tools:
        base_payload["tools"] = tools
        tc = _anthropic_tool_choice_to_openai(body.get("tool_choice"))
        if tc:
            base_payload["tool_choice"] = tc

    stream = bool(body.get("stream"))
    requested_model = body.get("model") if isinstance(body.get("model"), str) else None
    # The ORIGINAL request's size, tools and tool_use/tool_result blocks
    # included -- what Claude Code is told it sent (message_start, and the
    # final message_delta), whatever the hop was actually given.
    input_est = _estimate_input_tokens(body)
    if stream:
        base_payload["stream_options"] = dict(_STREAM_USAGE_OPTIONS)
    _ctx_begin(body, oai_messages, input_est)

    errors = _HopErrors()
    attempts = 0          # upstream hops actually tried (transparency header)
    last_hop = (None, None)
    last_hard = None  # last hard (non-retryable) upstream error, relayed if the chain is exhausted
    last_error = None  # class of the LAST failed hop (transparency header)
    _walk_started = time.monotonic()
    # See _ChainClock: the request deadline and the trivial-turn hop budget.
    _mark_turn_shape(diff, est, pinned=bool(_pin_kw))
    _clock = _ChainClock(trivial=_is_trivial_turn(
        oai_messages, body.get("max_tokens"), diff, est, pinned=bool(_pin_kw)),
        tools=has_tools, est=est, stream=stream, pinned=bool(_pin_kw))
    _plan_quality_fallback(_clock, body.get("model"), has_images, bool(_pin_kw),
                           oai_messages, body.get("max_tokens"))
    _chain = _build_chain(pid, resolved, est, require_vision=has_images,
                          require_tools=has_tools, messages=oai_messages,
                          **_pin_kw)
    # See the twin in /v1/chat/completions (hedging a trivial turn).
    _clock.plan_hedge(_chain, base_payload, diff, est=est, tools=has_tools,
                      images=has_images, lines=True)
    # Gap 2: parallel specialists for a hard, fresh tool turn on auto/best.
    base_payload["messages"] = _single_turn_team_notes(
        base_payload.get("messages"), base_payload.get("tools"), _chain,
        (pid, resolved), est, diff, bool(_pin_kw), stream)
    for hop_pid, hop_model in _clock.walk(_chain):
        if _clock.consumed(hop_pid, hop_model):
            continue              # a hedge already ran this hop
        if _clock.spent():
            errors.append("stopped: request deadline reached")
            last_error = "deadline"
            break
        if stream and _header_budget_spent(_walk_started):
            # See _STREAM_HEADER_BUDGET: past this the client has stopped
            # listening for headers, so a further hop cannot be delivered even
            # if it succeeds.
            errors.append("stopped after %ds: the client's header timeout was "
                          "about to expire" % _STREAM_HEADER_BUDGET)
            break
        if not prov.is_model_allowed(hop_model):
            continue
        if stream and _is_sub(hop_pid):
            errors.append("%s: skipped (a local CLI cannot stream)" % hop_pid)
            last_error = "skipped"
            continue
        payload = dict(base_payload)
        payload["model"] = hop_model
        _apply_reasoning_effort(payload, hop_model, diff, pid=hop_pid)
        payload["stream"] = stream
        try:
            _act_pick(hop_pid, hop_model)
            attempts += 1
            last_hop = (hop_pid, hop_model)
            resp = _clock.dispatch(hop_pid, payload, stream)
            hop_pid, hop_model, payload = _clock.served(hop_pid, hop_model, payload)
            last_hop = (hop_pid, hop_model)
        except (requests.RequestException, RuntimeError) as exc:
            errors.append("%s: %s" % (hop_pid, _sanitize(exc.__class__.__name__)))
            _note_hop_detail(hop_pid, exc)       # log-only: class + message
            last_error = _classify_hop_error(exc=exc)
            if isinstance(exc, requests.exceptions.Timeout):
                # A hop that TIMES OUT (unlike a fast-fail 429/400) can burn
                # minutes doing it -- and an immediate retry of the same
                # request (codex's own client-level retry on 503, or this
                # chain's bonus whole-chain retry a bit further down) hits the
                # SAME slow hop again, compounding into a long stall with zero
                # progress. MEASURED 2026-08-03: nvidia/mistral-medium-3.5-128b
                # ReadTimeout'd 4 times running, ~7 minutes each, while every
                # other hop in the chain failed fast. Same short cooldown a
                # 429 already gets, so the NEXT chain build skips it long
                # enough for a retry to reach a hop that actually responds.
                # A plain ConnectionError deliberately stays OUT of this branch
                # (see test_a_fast_failing_hop_is_not_throttled_only_a_real_
                # timeout_is): a real connection-refused fails just as fast on
                # a retry, so there's nothing costly to protect against. The
                # SLOW failure mode that error class was missing turned out to
                # be a raw 5xx status (524 etc.) that never raises at all --
                # handled separately below, in the non-2xx branch.
                # Scoped to THIS model unless the evidence is provider-wide
                # (see _throttle_failed_hop).
                _throttle_failed_hop(hop_pid, hop_model, exc=exc)
                # ...and count it, so a provider that ONLY ever times out is eventually
                # parked rather than re-tried forever. Heavily gated -- see
                # _note_provider_timeout, which ignores everything that is not
                # provably the provider's own fault.
                _note_provider_timeout(hop_pid, exc)
            continue
        if resp.status_code == 200:
            model_str = requested_model or (hop_pid + "/" + hop_model)
            if stream:
                # #4: peek the first line BEFORE committing the 200 SSE stream so a
                # hung/slow provider falls through to the next hop instead of stalling.
                line_it = resp.iter_lines(decode_unicode=False)
                if has_tools:
                    # DSML typed as text -> real tool_use blocks (tool_rescue).
                    line_it = tool_rescue.rescue_stream(line_it, tools, "lines")
                # Peek until REAL content so an empty 200 falls through to the next
                # model instead of being handed to the client as a dead-end answer.
                status, buffered = _peek_until_content(
                    line_it, _clock.peek_timeout(hop_model, est, pid=hop_pid),
                    content_grace=_clock.content_grace(),
                    check=_peek_check(payload, has_tools))
                _clock.note_peek(hop_pid, hop_model, status)
                if status == "starved":
                    # See the twin in /v1/chat/completions.
                    resp.close()
                    _again = _stream_starve_retry(_clock, hop_pid, hop_model, payload, est,
                                                  has_tools, tools, lines=True)
                    if _again is not None:
                        resp, line_it, status, buffered, payload = _again
                if status == "nonanswer" and not _skip_nonanswer():
                    status = "content"    # a 2nd bare announcement: served (one retry)
                if status != "content":
                    errors.append("%s: %s (200 but no content)" % (hop_pid, status))
                    last_error = _classify_hop_error(peek=status)
                    if status == "nonanswer":
                        # The relay streamed its own error page as the answer --
                        # sideline the id so it stops winning hop 1 (see
                        # _note_nonanswer; ranking alone never removed it).
                        _note_nonanswer(hop_pid, hop_model)
                    elif status == "junk":
                        _record_outcome(hop_pid, hop_model, False, junk=True)
                    resp.close()
                    continue
                _note_ttft(resp, hop_pid, hop_model)
                chained = _clock.guard(_chain_buffered(buffered, line_it),
                                       _DEADLINE_CUT_LINE, "%s/%s" % (hop_pid, hop_model))
                gated = _gate_stream(chained, "lines", hop_pid, hop_model, payload, has_tools)
                return Response(stream_with_context(
                    _anthropic_stream(resp, model_str, input_est,
                                     line_iter=(_dedupe_tool_stream(gated, "lines", hop_pid,
                                                                    hop_model)
                                                if has_tools else gated),
                                     hop_pid=hop_pid, hop_model=hop_model,
                                     prompt_text=_prompt_text_for_check(payload),
                                     last_prompt=_last_user_text_for_check(payload),
                                     tools_offered=has_tools, answer_gate=gated)),
                    mimetype="text/event-stream",
                    headers=dict(_SSE_HEADERS, **_routing_headers(
                        hop_pid, hop_model, attempts, last_error)))
            try:
                data = resp.json()
            except (ValueError, requests.RequestException):
                errors.append("%s: non-JSON 200 body" % hop_pid)
                last_error = "non-json"
                resp.close()
                continue
            # Starved (empty or a truncated stub at "length"): one same-pair
            # retry with room -- see the twin in /v1/chat/completions.
            _sk = _starve_kind(data, payload)
            if _sk:
                resp.close()
                data2, payload2 = _starve_retry(_clock, hop_pid, hop_model, payload, _sk)
                if data2 is None:
                    errors.append("%s: %s even with more room" % (
                        hop_pid, "empty" if _sk == "empty" else "truncated stub"))
                    last_error = "empty" if _sk == "empty" else "starved"
                    continue
                data, payload = data2, payload2
            if _chat_json_nonanswer(data, has_tools, tools) and _skip_nonanswer():
                # A 200 whose content IS the relay backend's error page (see
                # _chat_json_nonanswer). Falls through to the next hop exactly
                # like an empty 200, and sidelines the id so it stops winning.
                errors.append("%s: upstream error returned as content" % hop_pid)
                last_error = "empty"
                _note_nonanswer(hop_pid, hop_model)
                resp.close()
                continue
            if _chat_json_is_empty(data):
                errors.append("%s: empty (200 but no content)" % hop_pid)
                last_error = "empty"
                resp.close()
                continue
            gate = _answer_gate(data, payload, has_tools, hop=(hop_pid, hop_model))
            if gate == "junk":
                # A 200 that is ONLY degeneration (see _answer_gate): next hop.
                errors.append("%s: degenerate answer (nothing salvageable)" % hop_pid)
                last_error = "junk"
                _record_outcome(hop_pid, hop_model, False, junk=True)
                resp.close()
                continue
            _record_chat_usage(hop_pid, hop_model, data, est, ok=gate == "ok")
            _ctx_fix_chat_usage(data, input_est, hop_pid, hop_model)
            _fit_visible_to_caller(data, payload)
            _rv = _max_text_review(body.get("model"), diff, has_tools, oai_messages,
                                   hop_pid, hop_model, data, _chain, est,
                                   max_tokens=body.get("max_tokens"), usage_est=input_est)
            if _rv:
                hop_pid, hop_model, data = _rv
            return jsonify(_openai_resp_to_anthropic(data, model_str)), 200, \
                _routing_headers(hop_pid, hop_model, attempts, last_error)
        # Non-2xx. Retryable (429/5xx) AND hard errors (404/400/model-not-found)
        # both advance to the NEXT provider (a different provider/model) before we
        # surface an error; within-provider key rotation already ran upstream. A
        # network error reading the (unread, stream=True) error body must also just
        # advance, never escape the loop into a 500.
        try:
            errors.append("%s: HTTP %d" % (hop_pid, resp.status_code))
            last_error = _classify_hop_error(status=resp.status_code)
            if _resp_not_offered(resp):
                # Not loaded this minute (see _NOT_OFFERED_RE): _upstream_chat
                # already filed the short skip. No reliability failure, and
                # never the chain's relayed hard error -- just the next hop.
                errors[-1] = "%s: model not offered right now" % hop_pid
                resp.close()
                continue
            # EVERY non-2xx hop is a delivery failure for the reliability
            # ledger, not just 5xx. MEASURED 2026-08-07, chasing an
            # api.airforce error the user reported THREE times: g4f fronts ~42
            # backends, one of which is api.airforce with a GLOBAL 1 req/sec
            # cap shared by every g4f user, so its models answer
            #   429 "Global rate limit exceeded ... upgrade at api.airforce"
            #   402 "requires an active subscription"
            # 429 is deliberately NOT in _DEAD_STATUSES (a burst limit really
            # is temporary), so those ids returned after every cooldown, for
            # ever. Recording only timeouts and 5xx meant a hop that ONLY ever
            # 429s never accrued a penalty and kept winning slots. Laplace
            # smoothing keeps this fair: an occasional 429 among successes
            # barely moves the ratio, while a model that never delivers sinks.
            _record_outcome(hop_pid, hop_model, False)
            if resp.status_code >= 500:
                # See the matching comment in /v1/chat/completions: a raw 5xx
                # (unlike 429, already handled inside _upstream_chat) never got
                # a cooldown here, so a genuinely down hop was retried on every
                # request. MEASURED 2026-08-05: g4f-nvidia/mistral-medium-3.5.
                _throttle_failed_hop(hop_pid, hop_model)
            if resp.status_code in (400, 413):
                # A context-length rejection counts towards the native
                # overflow signal (see _ctx_overflow_reply).
                _ctx_note_overflow_resp(resp, hop_pid, hop_model)
            if resp.status_code == 400 and _classify_soft_400(resp):
                resp.close()
                continue
            if not _retryable(resp.status_code):
                # Capture the last hard error's detail to relay once the chain is done.
                detail = _upstream_error_detail(resp)
                last_hard = {"pid": hop_pid, "http": resp.status_code,
                             "status": _retryable_relay_status(resp.status_code),
                             "detail": detail}
        except requests.RequestException as exc:
            errors.append("%s: %s reading error body" % (hop_pid, _sanitize(exc.__class__.__name__)))
        resp.close()
        continue
    if _client_gone():
        return _client_gone_reply()      # the walk stopped on a cancel
    if _clock.spent():
        # Stopped on the clock (see _ChainClock), not on the fleet.
        _log.warning("MESSAGES-DEADLINE stream=%s tools=%s est=%d errors=[%s] details=[%s]",
                     stream, has_tools, est, "; ".join(errors) or "none", _hop_details_log())
        return _with_headers(_anthropic_error("api_error",
                                              _deadline_error_text(_clock, errors), 504),
                             _routing_headers(last_hop[0], last_hop[1], attempts, "deadline"))
    # CONTEXT OVERFLOW, in Anthropic's words: "prompt is too long" is what
    # Claude Code's reactive compaction keys on.
    _ov = _ctx_overflow_reply("anthropic")
    if _ov is not None:
        return _ov
    # Chain exhausted -> Retry-After so the client waits out a short throttle + auto-continues.
    eta = _capacity_eta()
    try:  # DIAG (temporary): record WHY the messages chain exhausted (Claude Code's 503).
        _log.warning("MESSAGES-503 stream=%s tools=%s images=%s est=%d errors=[%s] details=[%s] last_hard=%s body=%s",
                     stream, has_tools, has_images, est, "; ".join(errors) or "none", _hop_details_log(),
                     (str(last_hard.get("status")) + "/" + str(last_hard.get("pid"))) if last_hard else "none",
                     _last_hard_log_body(last_hard))
    except Exception:
        pass
    hdrs = _routing_headers(last_hop[0], last_hop[1], attempts, last_error)
    # The hub's own message, never the upstream body (see _chain_exhausted_text).
    return _with_headers(_with_retry_after(_anthropic_error(
        "api_error", _chain_exhausted_text(errors, last_hard, est, has_tools),
        last_hard["status"] if last_hard is not None else 503), eta), hdrs)


@app.route("/v1/messages/count_tokens", methods=["POST"])
def v1_count_tokens():
    """Estimate (see _estimate_input_tokens: tools, tool_use/tool_result, images
    and non-Latin text included) so Anthropic clients that pre-count don't 404
    -- and so the count Claude Code compacts on matches what it sends."""
    body = request.get_json(force=True, silent=True)
    if not isinstance(body, dict):
        return _anthropic_error("invalid_request_error", "Invalid JSON body.", 400)
    return jsonify({"input_tokens": _estimate_input_tokens(body)})


# ---------------------------------------------------------------------------
# Image generation (Text-to-Image) — a few free providers offer a genuinely
# free image-gen endpoint alongside their free chat models. NONE of these are
# OpenAI /chat/completions-compatible (each is a bespoke shape), so they get
# their own dispatch functions and their own /v1/images/generations route,
# separate from the chat gateway above. Deliberately NO Pillow/webp dependency
# added — the hub stays "Flask + requests only" (README's stated contract);
# images pass through as whatever bytes the provider returns, base64-encoded
# for the JSON response. `response_format` is always answered as `b64_json`
# regardless of what the caller asks for — there is no hosting here to hand
# back a real fetchable `url`, and a `data:` URI in the `url` field would
# break any client (including the real OpenAI SDK) that tries to GET it.
# ---------------------------------------------------------------------------
# Puter is deliberately ABSENT: every one of its 59 image models bills the
# account (0.3-17c per image, verified against its own catalog 2026-07-31), so
# none of them are free-rotation material. They stay one click away in the
# picker as explicit pins — see providers.py's puter image_models.
_IMAGE_PROVIDER_ORDER = ("cloudflare", "modelscope", "pollinations")
MAX_IMAGE_HOPS = 4              # bound worst-case latency (ModelScope polls up to 60s/hop)
_MODELSCOPE_POLL_DEADLINE = 60  # seconds


def _image_model_rows(pid):
    """Registry image-model rows ({'id','label',...}) for one provider."""
    p = prov.get_provider(pid) or {}
    return [m for m in (p.get("image_models") or []) if isinstance(m, dict) and m.get("id")]


def _image_candidates():
    """Available (pid, model_id) image-generation pairs, in priority order —
    same manual/auto shape as _vision_candidates(), backed by config's
    separate `images` CAS state (independent priority from vision/chat).

    The auto tail is INTERLEAVED across providers (best model of provider A,
    best of B, best of C, then each provider's 2nd, ...) rather than grouped
    by provider. MAX_IMAGE_HOPS bounds how many candidates a single request
    will try, and Cloudflare alone lists 4 image models — grouping would let
    every hop be spent on one broken/exhausted provider before a working,
    entirely different provider is ever reached.

    PAID image models (row["free"] is False) are deliberately EXCLUDED here —
    they never appear in auto/manual rotation and are reachable only via an
    explicit '<provider>/<model>' pin through _resolve_image_model, exactly
    like every paid CHAT provider already works in this hub. This is
    per-MODEL, not per-provider, because a provider can mix free and paid
    image models in the same row (e.g. google has both)."""
    by_provider = {}
    for pid in _available_providers():
        for row in _image_model_rows(pid):
            if not row.get("free", True):
                continue
            model = row["id"]
            if prov.is_model_allowed(model) and not _is_model_dead(pid, model):
                by_provider.setdefault(pid, []).append((pid, model))

    state = config.get_images_state()
    manual = state.get("manual_priority") if state.get("priority_mode") == "manual" else []
    ordered = []
    for item in manual or []:
        if "/" not in str(item):
            continue
        head, rest = str(item).split("/", 1)
        pair = (head, rest)
        lst = by_provider.get(head) or []
        if pair in lst:
            lst.remove(pair)
            ordered.append(pair)

    provider_order = sorted(by_provider.keys(),
                            key=lambda pid: _IMAGE_PROVIDER_ORDER.index(pid)
                            if pid in _IMAGE_PROVIDER_ORDER else 99)
    tail = []
    max_len = max((len(v) for v in by_provider.values()), default=0)
    for round_i in range(max_len):
        for pid in provider_order:
            models = by_provider.get(pid) or []
            if round_i < len(models):
                tail.append(models[round_i])
    return ordered + tail


def _resolve_image_model(model):
    """'<pid>/<model>' -> (pid, model). 'auto'/empty -> top _image_candidates()
    pick. Returns (pid, model) or (None, error_message)."""
    model = model.strip() if isinstance(model, str) else ""
    if "/" in model:
        head, rest = model.split("/", 1)
        if prov.get_provider(head) and any(row["id"] == rest for row in _image_model_rows(head)):
            return head, rest
        return None, "Unknown image model '%s'." % model
    candidates = _image_candidates()
    if not candidates:
        return None, ("No enabled provider offers free image generation yet. Enable "
                      "Cloudflare Workers AI, ModelScope, or Pollinations on the dashboard.")
    return candidates[0]


def _b64_bytes(raw_bytes):
    return base64.b64encode(raw_bytes).decode("ascii")


def _cf_account_id_for_image(pcfg, api_key):
    """Resolve the Cloudflare account id for the IMAGE endpoint (.../ai/run/
    {model}), honoring a user-pasted custom base URL FIRST — the same
    fallback _resolve_base_url already gives the chat-completions path when a
    narrowly-scoped token can't self-resolve via _cf_account_id. Without this,
    the documented workaround ("paste your account-scoped base URL") had zero
    effect here even though the error message told the user to do exactly
    that (found in review: image generation stayed permanently broken for
    such tokens while chat on the same token worked fine)."""
    custom = pcfg.get("base_url")
    if custom:
        match = re.search(r"/accounts/([^/]+)/ai", custom)
        if match:
            return match.group(1)
    return _cf_account_id(api_key)


def _cf_generate_image(pcfg, model, prompt, size=1024, steps=4):
    """Cloudflare Workers AI's NATIVE image endpoint (NOT /chat/completions):
    POST .../accounts/{account_id}/ai/run/{model}. flux-1-schnell returns JSON
    {"result":{"image": "<base64 png>"}}; SD-family models return raw PNG
    bytes directly. Returns (status, b64_or_None, error_detail_or_None)."""
    keys = pcfg.get("api_keys") or []
    if not keys:
        return 400, None, "no api key for provider cloudflare"
    api_key = keys[0]
    account_id = _cf_account_id_for_image(pcfg, api_key)
    if not account_id:
        return 400, None, ("could not resolve the Cloudflare account id from this token — "
                           "paste your account-scoped base URL into 'Advanced: custom base "
                           "URL' on the Cloudflare card")
    url = "https://api.cloudflare.com/client/v4/accounts/%s/ai/run/%s" % (account_id, model)
    try:
        resp = requests.post(
            url, headers={"Authorization": "Bearer " + api_key, "Content-Type": "application/json"},
            json={"prompt": (prompt or "")[:2048], "steps": int(steps or 4)},
            timeout=(CONNECT_TIMEOUT, CHAT_READ_TIMEOUT))
    except requests.RequestException as exc:
        return 502, None, exc.__class__.__name__
    if resp.status_code != 200:
        return resp.status_code, None, _upstream_error_detail(resp)
    ctype = (resp.headers.get("Content-Type") or "").lower()
    if "application/json" in ctype:
        data = resp.json()
        if not data.get("success", True):
            return 502, None, _sanitize(str(data.get("errors")))
        b64 = (data.get("result") or {}).get("image")
        if not b64:
            return 502, None, "Cloudflare Workers AI returned no image data"
        return 200, b64, None
    if not resp.content:
        return 502, None, "Cloudflare Workers AI returned an empty body"
    return 200, _b64_bytes(resp.content), None


def _is_safe_external_url(url):
    """Lightweight SSRF guard for a URL the hub is about to fetch SERVER-SIDE
    on the strength of an upstream provider's own response (not user input
    directly) — e.g. ModelScope's task-result image URL. Review found the
    prior code fetched such a URL with no validation at all despite a comment
    claiming "no SSRF surface"; that claim only holds if the URL is actually
    checked. Blocks non-https schemes, embedded credentials, and any hostname
    that resolves to a private/loopback/link-local/reserved/multicast address
    (defends a misbehaving or compromised upstream, not just a malicious one)."""
    try:
        parsed = urlsplit(url)
    except ValueError:
        return False
    if parsed.scheme != "https" or not parsed.hostname:
        return False
    if parsed.username or parsed.password:
        return False
    try:
        infos = socket.getaddrinfo(parsed.hostname, None)
    except socket.gaierror:
        return False
    for info in infos:
        try:
            ip = ipaddress.ip_address(info[4][0])
        except ValueError:
            return False
        if ip.is_private or ip.is_loopback or ip.is_link_local \
                or ip.is_reserved or ip.is_multicast or ip.is_unspecified:
            return False
    return True


def _modelscope_generate_image(pcfg, model, prompt, size=1024, steps=4):
    """ModelScope's async task API (NOT /chat/completions): POST
    /v1/images/generations with X-ModelScope-Async-Mode:true returns a
    task_id; poll /v1/tasks/{id} (X-ModelScope-Task-Type: image_generation)
    until SUCCEED, then download output_images[0]. The hub called ModelScope
    itself, but the returned URL still comes from that response's JSON body,
    so a misbehaving/compromised upstream could point it somewhere else —
    validated via _is_safe_external_url() before the download, same as this
    codebase already requires for a comparable provider-returned-URL fetch
    elsewhere. Returns (status, b64_or_None, error_detail)."""
    keys = pcfg.get("api_keys") or []
    if not keys:
        return 400, None, "no api key for provider modelscope"
    api_key = keys[0]
    base = "https://api-inference.modelscope.cn"
    try:
        resp = requests.post(
            base + "/v1/images/generations",
            headers={"Authorization": "Bearer " + api_key, "Content-Type": "application/json",
                     "X-ModelScope-Async-Mode": "true"},
            json={"model": model, "prompt": (prompt or "")[:2000]},
            timeout=(CONNECT_TIMEOUT, MODELS_READ_TIMEOUT))
    except requests.RequestException as exc:
        return 502, None, exc.__class__.__name__
    if resp.status_code not in (200, 201):
        return resp.status_code, None, _upstream_error_detail(resp)
    task_id = (resp.json() or {}).get("task_id")
    if not task_id:
        return 502, None, "ModelScope returned no task_id"
    deadline = time.time() + _MODELSCOPE_POLL_DEADLINE
    img_url = None
    while time.time() < deadline:
        time.sleep(2)
        try:
            pr = requests.get(base + "/v1/tasks/" + task_id,
                              headers={"Authorization": "Bearer " + api_key,
                                       "X-ModelScope-Task-Type": "image_generation"},
                              timeout=(CONNECT_TIMEOUT, MODELS_READ_TIMEOUT))
        except requests.RequestException:
            continue
        pd = pr.json() if pr.status_code == 200 else {}
        status = str(pd.get("task_status") or "").upper()
        if status in ("SUCCEED", "SUCCEEDED"):
            outs = pd.get("output_images") or (pd.get("output") or {}).get("images") or []
            img_url = outs[0] if outs else None
            break
        if status in ("FAILED", "FAIL", "ERROR"):
            return 502, None, "ModelScope task failed: %s" % _sanitize(str(pd), 200)
    if not img_url:
        return 504, None, "ModelScope task timed out or returned no image"
    if not _is_safe_external_url(img_url):
        return 502, None, "ModelScope returned an unsafe image URL"
    try:
        img_resp = requests.get(img_url, timeout=(CONNECT_TIMEOUT, 30))
    except requests.RequestException as exc:
        return 502, None, "Could not download the generated image: %s" % exc.__class__.__name__
    if img_resp.status_code != 200 or not img_resp.content:
        return 502, None, "Could not download the generated image (HTTP %d)" % img_resp.status_code
    return 200, _b64_bytes(img_resp.content), None


def _parse_wh(size, default=1024):
    """'WIDTHxHEIGHT' -> (width, height), each clamped to [256, 1536].
    Falls back to a square `default` for anything unparseable. A single
    scalar in, squared for both dimensions, was the prior bug here — a
    'portrait' pick silently became a square image."""
    width = height = default
    if isinstance(size, str) and "x" in size.lower():
        parts = size.lower().split("x")
        try:
            width = max(256, min(1536, int(parts[0])))
            height = max(256, min(1536, int(parts[1]))) if len(parts) > 1 else width
        except (ValueError, IndexError):
            width = height = default
    return width, height


def _pollinations_generate_image(pcfg, model, prompt, size=1024, steps=4):
    """Pollinations' anonymous GET-URL image API (NOT /chat/completions): GET
    image.pollinations.ai/prompt/{prompt}?... -> raw image bytes. No key
    required; an optional saved key/token just lifts limits."""
    keys = pcfg.get("api_keys") or []
    api_key = keys[0] if keys else None
    width, height = _parse_wh(size)
    query = "width=%d&height=%d&model=%s&nologo=true&seed=%d" % (
        width, height, quote(model or "flux", safe=""), random.randint(1, 1_000_000))
    url = "https://image.pollinations.ai/prompt/%s?%s" % (
        quote((prompt or "")[:1500], safe=""), query)
    headers = {"Authorization": "Bearer " + api_key} if api_key else {}
    try:
        resp = requests.get(url, headers=headers, timeout=(CONNECT_TIMEOUT, 90))
    except requests.RequestException as exc:
        return 502, None, exc.__class__.__name__
    if resp.status_code != 200 or not resp.content:
        status = resp.status_code if resp.status_code != 200 else 502
        return status, None, _sanitize(resp.text or "empty body", 300)
    return 200, _b64_bytes(resp.content), None


_AIHORDE_POLL_DEADLINE = 300      # anonymous queue can genuinely take minutes
_AIHORDE_ANON_KEY = "0000000000"  # AI Horde's documented public anonymous key


def _aihorde_generate_image(pcfg, model, prompt, size=1024, steps=4):
    """AI Horde (aihorde.net, formerly Stable Horde) -- a community-run,
    GPU-donated distributed inference network. VERIFIED live 2026-07-27:
    submitted a real anonymous job (apikey "0000000000"), watched the queue
    position advance, downloaded and hex-verified an actual WebP image --
    zero payment, zero signup. A personal free account/key jumps the
    (otherwise lowest-priority) anonymous queue but isn't required. Async
    submit-then-poll, same shape as this file's other async generators
    (r2=false requests base64 inline, skipping the extra download hop)."""
    keys = pcfg.get("api_keys") or []
    api_key = keys[0] if keys else _AIHORDE_ANON_KEY
    headers = {"apikey": api_key, "Content-Type": "application/json",
               "Client-Agent": "free-llm-hub:1.0:https://github.com/last-million/free-llm-hub"}
    width, height = _parse_wh(size)
    if not keys:
        # MEASURED 2026-07-27: the anonymous key 0000000000 gets a real 403
        # ("the client needs to already have the required kudos") for any
        # request over 661x661px -- a real anti-abuse limit, not a fluke; the
        # hub's own default size (1024x1024) blew straight past it. A
        # personal key (real kudos balance) isn't capped the same way, so
        # only clamp when actually running anonymous.
        width, height = min(width, 640), min(height, 640)
    body = {"prompt": (prompt or "")[:2000],
            "params": {"width": width, "height": height, "steps": 20,
                       "sampler_name": "k_euler", "cfg_scale": 7.5},
            "nsfw": False, "models": [model], "r2": False}
    try:
        resp = requests.post("https://aihorde.net/api/v2/generate/async",
                             headers=headers, json=body,
                             timeout=(CONNECT_TIMEOUT, CHAT_READ_TIMEOUT))
    except requests.RequestException as exc:
        return 502, None, exc.__class__.__name__
    if resp.status_code not in (200, 202):
        return resp.status_code, None, _upstream_error_detail(resp)
    job_id = (resp.json() or {}).get("id")
    if not job_id:
        return 502, None, "AI Horde returned no job id"
    check_url = "https://aihorde.net/api/v2/generate/check/" + job_id
    status_url = "https://aihorde.net/api/v2/generate/status/" + job_id
    deadline = time.time() + _AIHORDE_POLL_DEADLINE
    done = False
    while time.time() < deadline:
        time.sleep(4)
        try:
            cr = requests.get(check_url, timeout=(CONNECT_TIMEOUT, MODELS_READ_TIMEOUT))
        except requests.RequestException:
            continue
        cd = cr.json() if cr.status_code == 200 else {}
        if cd.get("faulted"):
            return 502, None, "AI Horde job faulted"
        if cd.get("done"):
            done = True
            break
    if not done:
        return 504, None, "AI Horde timed out waiting for a free worker"
    try:
        sr = requests.get(status_url, timeout=(CONNECT_TIMEOUT, MODELS_READ_TIMEOUT))
    except requests.RequestException as exc:
        return 502, None, exc.__class__.__name__
    if sr.status_code != 200:
        return sr.status_code, None, _upstream_error_detail(sr)
    gens = (sr.json() or {}).get("generations") or []
    if not gens or not gens[0].get("img"):
        return 502, None, "AI Horde returned no image data"
    return 200, gens[0]["img"], None


# --------------------------------------------------------------------------- #
# PAID image generators — OpenAI, Google (Gemini image), OpenRouter, Higgsfield.
# Every model these dispatch is registered with "free": False in providers.py,
# so _image_candidates() (per-model "free" filter) never auto/manual-routes to
# them — reachable ONLY via an explicit "<provider>/<model>" pin through
# _resolve_image_model, same as this hub's existing paid CHAT providers
# (deepseek/kimi/minimax): enabled+keyed but excluded from auto, usable only
# when explicitly named. Same (status, b64_or_None, error_detail_or_None)
# return convention as the free generators above.
# --------------------------------------------------------------------------- #

def _openai_generate_image(pcfg, model, prompt, size="1024x1024", steps=4):
    """OpenAI's real Images API: POST /v1/images/generations. Standard,
    stable, well-documented REST shape (model, prompt, n, size) ->
    {"data":[{"b64_json":...} or {"url":...}]}."""
    keys = pcfg.get("api_keys") or []
    if not keys:
        return 400, None, "no api key for provider openai"
    api_key = keys[0]
    valid_sizes = {"1024x1024", "1536x1024", "1024x1536"}
    body = {"model": model, "prompt": (prompt or "")[:32000], "n": 1,
            "size": size if size in valid_sizes else "1024x1024"}
    try:
        resp = requests.post(
            "https://api.openai.com/v1/images/generations",
            headers={"Authorization": "Bearer " + api_key, "Content-Type": "application/json"},
            json=body, timeout=(CONNECT_TIMEOUT, CHAT_READ_TIMEOUT))
    except requests.RequestException as exc:
        return 502, None, exc.__class__.__name__
    if resp.status_code != 200:
        return resp.status_code, None, _upstream_error_detail(resp)
    data = (resp.json() or {}).get("data") or []
    if not data:
        return 502, None, "OpenAI returned no image data"
    item = data[0]
    b64 = item.get("b64_json")
    if b64:
        return 200, b64, None
    url = item.get("url")
    if url and _is_safe_external_url(url):
        try:
            img = requests.get(url, timeout=(CONNECT_TIMEOUT, 30))
        except requests.RequestException as exc:
            return 502, None, "could not download image: %s" % exc.__class__.__name__
        if img.status_code == 200 and img.content:
            return 200, _b64_bytes(img.content), None
    return 502, None, "OpenAI returned neither b64_json nor a fetchable url"


def _google_generate_image(pcfg, model, prompt, size="1024x1024", steps=4):
    """Gemini's generateContent REST endpoint with responseModalities:["IMAGE"]
    -- the standard, stable Gemini REST shape (verified against
    ai.google.dev/api/generate-content): response image bytes appear at
    candidates[].content.parts[].inlineData.data."""
    keys = pcfg.get("api_keys") or []
    if not keys:
        return 400, None, "no api key for provider google"
    api_key = keys[0]
    url = "https://generativelanguage.googleapis.com/v1beta/models/%s:generateContent" % model
    body = {"contents": [{"parts": [{"text": (prompt or "")[:8000]}]}],
            "generationConfig": {"responseModalities": ["IMAGE"]}}
    try:
        resp = requests.post(url, params={"key": api_key},
                             headers={"Content-Type": "application/json"}, json=body,
                             timeout=(CONNECT_TIMEOUT, CHAT_READ_TIMEOUT))
    except requests.RequestException as exc:
        return 502, None, exc.__class__.__name__
    if resp.status_code != 200:
        return resp.status_code, None, _upstream_error_detail(resp)
    data = resp.json() or {}
    for cand in data.get("candidates") or []:
        for part in (cand.get("content") or {}).get("parts") or []:
            inline = part.get("inlineData") or part.get("inline_data")
            if inline and inline.get("data"):
                return 200, inline["data"], None
    return 502, None, "Google returned no image data"


def _openrouter_generate_image(pcfg, model, prompt, size="1024x1024", steps=4):
    """OpenRouter's image-capable chat/completions: modalities:["image"] on
    a normal chat request; the image comes back in
    choices[0].message.images[].image_url.url, either a data: URI or a real
    fetchable URL depending on the model."""
    keys = pcfg.get("api_keys") or []
    if not keys:
        return 400, None, "no api key for provider openrouter"
    api_key = keys[0]
    try:
        resp = requests.post(
            "https://openrouter.ai/api/v1/chat/completions",
            headers={"Authorization": "Bearer " + api_key, "Content-Type": "application/json"},
            json={"model": model, "modalities": ["image"],
                  "messages": [{"role": "user", "content": prompt or ""}]},
            timeout=(CONNECT_TIMEOUT, CHAT_READ_TIMEOUT))
    except requests.RequestException as exc:
        return 502, None, exc.__class__.__name__
    if resp.status_code != 200:
        return resp.status_code, None, _upstream_error_detail(resp)
    data = resp.json() or {}
    choice = (data.get("choices") or [{}])[0]
    msg = choice.get("message") or {}
    for img in (msg.get("images") or []):
        url = (img.get("image_url") or {}).get("url") if isinstance(img, dict) else None
        if isinstance(url, str) and url.startswith("data:"):
            try:
                return 200, url.split(",", 1)[1], None
            except IndexError:
                continue
        if url and _is_safe_external_url(url):
            try:
                r2 = requests.get(url, timeout=(CONNECT_TIMEOUT, 30))
            except requests.RequestException:
                continue
            if r2.status_code == 200 and r2.content:
                return 200, _b64_bytes(r2.content), None
    return 502, None, "OpenRouter returned no image data"


def _higgsfield_generate_image(pcfg, model, prompt, size="1024x1024", steps=4):
    """Higgsfield's bespoke API (NOT OpenAI-compatible): composite credential
    "Authorization: Key <id>:<secret>", async submit (model-specific endpoint
    path) -> request_id -> poll /requests/{id}/status until completed, then
    fetch images[].url. The composite credential is stored as a single
    "KEY_ID:KEY_SECRET" string in the existing api_keys slot -- split it here."""
    keys = pcfg.get("api_keys") or []
    if not keys or ":" not in keys[0]:
        return 400, None, "Higgsfield needs a KEY_ID:KEY_SECRET credential (paste both, colon-separated)"
    key_id, key_secret = keys[0].split(":", 1)
    endpoints = {
        "higgsfield/text2image/soul": "/v1/text2image/soul",
        "flux-pro/kontext/max/text-to-image": "/v1/flux-pro/kontext/max/text-to-image",
        "bytedance/seedream/v4/text-to-image": "/v1/bytedance/seedream/v4/text-to-image",
        "higgsfield/nano-banana-pro": "/v1/text2image/nano-banana-pro",
    }
    endpoint = endpoints.get(model, "/v1/text2image/soul")
    base = "https://platform.higgsfield.ai"
    headers = {"Authorization": "Key %s:%s" % (key_id, key_secret), "Content-Type": "application/json"}
    width, height = _parse_wh(size)
    body = {"prompt": (prompt or "")[:2000], "width_and_height": "%dx%d" % (width, height), "batch_size": 1}
    try:
        resp = requests.post(base + endpoint, headers=headers, json=body,
                             timeout=(CONNECT_TIMEOUT, 60))
    except requests.RequestException as exc:
        return 502, None, exc.__class__.__name__
    if resp.status_code not in (200, 201, 202):
        return resp.status_code, None, _upstream_error_detail(resp)
    sj = resp.json() if resp.content else {}
    rid = sj.get("request_id") or sj.get("id") or (sj.get("data") or {}).get("id")
    if not rid:
        return 502, None, "Higgsfield returned no request id"
    deadline = time.time() + 90
    img_url = None
    while time.time() < deadline:
        time.sleep(2)
        try:
            pr = requests.get(base + "/requests/" + rid + "/status", headers=headers,
                              timeout=(CONNECT_TIMEOUT, 30))
        except requests.RequestException:
            continue
        pd = pr.json() if pr.status_code == 200 else {}
        st = str(pd.get("status") or "").lower()
        if st in ("completed", "succeeded", "success"):
            imgs = pd.get("images") or (pd.get("result") or {}).get("images") or []
            if imgs:
                first = imgs[0]
                img_url = first.get("url") if isinstance(first, dict) else first
            break
        if st in ("failed", "nsfw", "cancelled", "error"):
            return 502, None, "Higgsfield task %s" % st
    if not img_url:
        return 504, None, "Higgsfield timed out or returned no image"
    if not _is_safe_external_url(img_url):
        return 502, None, "Higgsfield returned an unsafe image URL"
    try:
        img = requests.get(img_url, timeout=(CONNECT_TIMEOUT, 60))
    except requests.RequestException as exc:
        return 502, None, "could not download image: %s" % exc.__class__.__name__
    if img.status_code != 200 or not img.content:
        return 502, None, "could not download image (HTTP %d)" % img.status_code
    return 200, _b64_bytes(img.content), None


_IMAGE_GENERATORS = {
    "cloudflare": _cf_generate_image,
    "modelscope": _modelscope_generate_image,
    "pollinations": _pollinations_generate_image,
    "aihorde": _aihorde_generate_image,
    "openai": _openai_generate_image,
    "google": _google_generate_image,
    "openrouter": _openrouter_generate_image,
    "higgsfield": _higgsfield_generate_image,
    # Driver-based, not an images REST endpoint — see _puter_generate_image.
    "puter": _puter_generate_image,
}


_IMAGE_TEXT_QA_PROMPT = (
    "Look closely at this image. Does it contain any text (words, letters, "
    "numbers, a sign, a label, a logo wordmark) that is garbled, misspelled, "
    "malformed, duplicated, or otherwise clearly wrong? AI image generators "
    "frequently render text incorrectly even when everything else looks "
    "right. Reply with exactly one word first, YES or NO. If YES, add one "
    "short sentence naming what is wrong. If the image has no text at all, "
    "reply NO."
)


def _image_text_qa_flagged(b64_raw):
    """User 2026-08-05: "verify with vision each image to see if there is
    TEXT issue... sometimes image generators do mistakes in text." Ask a
    vision-capable model whether a just-generated image has a text-rendering
    defect. `b64_raw` is whatever format the generator returned (png/jpeg/
    webp vary by provider) -- re-encoded here via _to_webp_b64 so the data
    URL always carries a mime type that actually matches its bytes. True if
    flagged, False if clean, None if no vision model could be reached at all
    -- the caller fails OPEN on None (keeps the image rather than blocking
    generation on an unrelated vision-provider outage). Tries up to 2 vision
    candidates; never raises."""
    try:
        candidates = _vision_candidates()[:2]
    except Exception:                                              # noqa: BLE001
        return None
    if not candidates:
        return None
    b64, mime = _to_webp_b64(b64_raw)
    for pid, model in candidates:
        payload = {
            "model": model, "max_tokens": 120, "stream": False,
            "messages": [{
                "role": "user",
                "content": [
                    {"type": "text", "text": _IMAGE_TEXT_QA_PROMPT},
                    {"type": "image_url",
                     "image_url": {"url": "data:%s;base64,%s" % (mime, b64)}},
                ],
            }],
        }
        try:
            resp = _dispatch_chat(pid, payload, False)
        except (requests.RequestException, RuntimeError):
            continue
        if resp.status_code != 200:
            continue
        try:
            data = resp.json()
            text = ((data.get("choices") or [{}])[0].get("message") or {}).get("content") or ""
        except (ValueError, requests.RequestException):
            continue
        return text.strip().upper().startswith("YES")
    return None


def _call_image_generator(pid, generator, pcfg, model, prompt, size, steps):
    """Same key-pool-rotation policy as the chat path's _upstream_chat
    (_KEY_ROTATE_STATUSES / _next_key_start, app.py ~3012-3027) -- MEASURED
    2026-07-27: every one of the 7 generators above only ever reads
    api_keys[0], so a provider with a 3-key pool where key[0] is
    revoked/exhausted had the whole provider abandoned for image generation
    instead of trying key[1]/key[2], unlike text chat which already recovers
    within a hop. Generators are left untouched -- each attempt gets a pcfg
    view scoped to exactly ONE key, so their existing single-key logic
    (async polling, SSRF-checked downloads, composite Higgsfield
    KEY_ID:KEY_SECRET credentials) runs exactly as before; rotation only
    decides which key populates that view on the next attempt."""
    keys = pcfg.get("api_keys") or []
    if len(keys) <= 1:
        return generator(pcfg, model, prompt, size=size, steps=steps)
    n = len(keys)
    start = _next_key_start(pid, n)
    result = (400, None, "no api key for provider %s" % pid)
    for i in range(n):
        is_last = (i == n - 1)
        one_key_cfg = dict(pcfg)
        one_key_cfg["api_keys"] = [keys[(start + i) % n]]
        result = generator(one_key_cfg, model, prompt, size=size, steps=steps)
        if result[0] in _KEY_ROTATE_STATUSES and not is_last:
            continue
        return result
    return result


def _save_generated_image(b64, prompt, pid, model):
    """Best-effort persist of one successful generation for the history
    gallery. Never raises -- a history-tracking bug must never break a real
    image-generation response."""
    try:
        image_history.save(base64.b64decode(b64), prompt, pid, model)
    except Exception:
        pass


_WEBP_QUALITY = 82      # visually lossless for photos, ~30% of the JPEG bytes


def _to_webp_b64(b64):
    """Re-encode a generated image to WebP. Returns (b64, mime).

    WHY IN THE HUB AND NOT IN THE BRIEF: "convert the images to WebP" written
    as an instruction is a step a model can forget, and every provider returns
    something different (cloudflare/flux answers JPEG, pollinations PNG). Doing
    it here means every client — every CLI, the dashboard, a raw curl — gets
    WebP without knowing anything about it, and the page it builds is already
    carrying the smaller file.

    Falls back to the original bytes if Pillow is missing or the re-encode
    fails: a slightly larger image is a much better outcome than a 500."""
    try:
        raw = base64.b64decode(b64)
    except (binascii.Error, ValueError):
        return b64, "image/png"
    try:
        from PIL import Image
        img = Image.open(io.BytesIO(raw))
        # WebP has no palette mode and only keeps alpha in RGBA — normalise
        # first or Pillow raises on P/CMYK images from some generators.
        if img.mode not in ("RGB", "RGBA"):
            img = img.convert("RGBA" if "A" in img.getbands() else "RGB")
        buf = io.BytesIO()
        img.save(buf, format="WEBP", quality=_WEBP_QUALITY, method=4)
        return base64.b64encode(buf.getvalue()).decode("ascii"), "image/webp"
    except Exception:
        # Unknown/broken format, or Pillow built without WebP. Report the mime
        # HONESTLY rather than claiming webp for bytes that are not.
        if raw[:8] == b"\x89PNG\r\n\x1a\n":
            return b64, "image/png"
        if raw[:3] == b"\xff\xd8\xff":
            return b64, "image/jpeg"
        return b64, "image/png"


@app.route("/v1/images/generations", methods=["POST"])
def v1_images_generations():
    body = request.get_json(force=True, silent=True)
    if not isinstance(body, dict):
        return _openai_error("Invalid JSON body.", 400)
    prompt = body.get("prompt")
    if not isinstance(prompt, str) or not prompt.strip():
        return _openai_error("'prompt' is required.", 400)
    try:
        n = max(1, min(4, int(body.get("n") or 1)))
    except (TypeError, ValueError):
        n = 1
    # Kept as the original "WxH" string (not pre-parsed into one scalar) so
    # each generator decides for itself what to do with it: Cloudflare/
    # ModelScope don't accept a size param at all and ignore it; Pollinations
    # (the one provider that does) parses width/height independently via
    # _parse_wh() so a non-square pick isn't silently squared.
    size = body.get("size") if isinstance(body.get("size"), str) else "1024x1024"
    try:
        steps = max(1, min(8, int(body.get("steps") or 4)))
    except (TypeError, ValueError):
        steps = 4

    requested = body.get("model") if isinstance(body.get("model"), str) else "auto"
    pid, model = _resolve_image_model(requested)
    if pid is None:
        return _openai_error(model, 400)
    not_ready = _check_provider_ready(pid)
    if not_ready:
        return _openai_error(not_ready, 400)

    tried = {(pid, model)}
    chain = [(pid, model)] + [c for c in _image_candidates() if c not in tried]
    errors = []
    images_b64 = []
    landed_pid = landed_model = None
    # Fallback if EVERY hop's image gets text-flagged: a real (if imperfect)
    # image beats a 502 over a soft quality heuristic -- see below.
    text_flagged_fallback = None
    for hop_pid, hop_model in chain[:MAX_IMAGE_HOPS]:
        generator = _IMAGE_GENERATORS.get(hop_pid)
        if not generator:
            continue
        pcfg = config.get_provider_config(hop_pid)
        try:
            status, b64, detail = _call_image_generator(
                hop_pid, generator, pcfg, hop_model, prompt, size, steps)
        except (requests.RequestException, RuntimeError) as exc:
            errors.append("%s: %s" % (hop_pid, _sanitize(exc.__class__.__name__)))
            continue
        quota.record(hop_pid, hop_model)
        if status == 200 and b64:
            # User 2026-08-05: "verify with vision each image... ask to
            # regenerate it to fix the text." A flagged image is treated as a
            # soft failure -- fall through to the NEXT hop (a different
            # provider/model, a real chance at different output) rather than
            # accepting it. None (no vision model reachable) fails OPEN and
            # accepts immediately, same as a clean result.
            if _image_text_qa_flagged(b64):
                errors.append("%s: vision flagged text issue, retrying next hop" % hop_pid)
                if text_flagged_fallback is None:
                    text_flagged_fallback = (b64, hop_pid, hop_model)
                continue
            images_b64.append(b64)
            landed_pid, landed_model = hop_pid, hop_model
            _save_generated_image(b64, prompt, hop_pid, hop_model)
            break
        if status == 429:
            # Unlike _upstream_chat, these generators don't surface a
            # Retry-After header through their (status, b64, detail) return
            # shape, so assume the same short per-minute-burst cooldown the
            # chat path uses when no Retry-After is present. Without this the
            # rate-limited provider stayed top-ranked and got retried again on
            # the very next request instead of cooling down.
            quota.mark_throttled(hop_pid, 60)
        if status in _DEAD_STATUSES:
            _mark_model_dead(hop_pid, hop_model, status)
        errors.append("%s: HTTP %s %s" % (hop_pid, status, _sanitize(detail or "")))
    if not images_b64 and text_flagged_fallback is not None:
        # Every hop that produced an image got text-flagged -- a real image
        # with a possible text defect still beats failing the whole request.
        b64, landed_pid, landed_model = text_flagged_fallback
        images_b64.append(b64)
        _save_generated_image(b64, prompt, landed_pid, landed_model)
    if not images_b64:
        return _openai_error(
            "All image providers failed: " + ("; ".join(errors) or "none available"),
            502, "upstream_error")

    # n > 1: reuse the SAME confirmed-working hop for the rest — no need to
    # re-run the fallback chain once we know this hop actually answers.
    generator = _IMAGE_GENERATORS[landed_pid]
    pcfg = config.get_provider_config(landed_pid)
    for _extra in range(n - 1):
        try:
            status, b64, _detail = _call_image_generator(
                landed_pid, generator, pcfg, landed_model, prompt, size, steps)
        except (requests.RequestException, RuntimeError):
            break
        quota.record(landed_pid, landed_model)
        if status == 200 and b64 and not _image_text_qa_flagged(b64):
            images_b64.append(b64)
        else:
            break

    # WebP on the way out, so every consumer gets the smaller file without
    # having to ask for it. `mime` is an extra field the OpenAI shape does not
    # define — clients that don't know it ignore it, and ours uses it instead of
    # assuming image/png (which was wrong for every JPEG we have ever returned).
    converted = [_to_webp_b64(b) for b in images_b64]
    return jsonify({
        "created": int(time.time()),
        "model": landed_pid + "/" + landed_model,
        "data": [{"b64_json": b, "mime": m} for b, m in converted],
    }), 200


def _images_payload():
    state = config.get_images_state()
    models = []
    for p in prov.list_providers():
        pid = p["id"]
        pcfg = config.get_provider_config(pid)
        rows = _image_model_rows(pid)
        # Quota state per PROVIDER, resolved once and stamped on each of its
        # model rows: picking an image model is pointless if the provider it
        # belongs to has nothing left, and finding that out from a failed
        # generation is the worst way to learn it.
        q = _provider_quota_row(pid, p) if rows else None
        allow = _puter_allowance() if (rows and _is_puter_driver(pid) and
                                       pcfg.get("api_keys")) else None
        if allow:
            exhausted = allow["remaining"] <= 0
            quota_label = ("no credit left" if exhausted
                           else "%.2f¢ left" % allow["remaining_cents"])
        elif q:
            exhausted = bool(q.get("exhausted"))
            quota_label = "out of free quota" if exhausted else None
        else:
            exhausted, quota_label = False, None
        for row in rows:
            model = row["id"]
            models.append({
                "exhausted": exhausted,
                "quota_label": quota_label,
                "id": pid + "/" + model,
                "provider": pid,
                "model": model,
                "provider_name": p.get("name") or pid,
                "label": row.get("label") or model,
                "text_in_image": row.get("text_in_image"),
                # Carries the per-image price for metered models, which is what
                # the picker turns into its cost tag ("~0.5c per 1024x1024")
                # instead of a vague "costs credit".
                "notes": row.get("notes") or "",
                "free": row.get("free", True),
                "configured": bool(pcfg.get("enabled") and
                                   (pcfg.get("api_key") or not _needs_key(pid))),
                "dead": _is_model_dead(pid, model),
            })
    available_order = [pid + "/" + model for pid, model in _image_candidates()]
    return {"state": state, "models": models, "effective_priority": available_order}


@app.route("/api/images", methods=["GET", "POST"])
def api_images():
    if request.method == "GET":
        return jsonify(_images_payload())
    body = request.get_json(force=True, silent=True)
    if not isinstance(body, dict):
        return jsonify({"error": "invalid JSON body"}), 400
    if "revision" not in body:
        return jsonify({"error": "revision is required"}), 400
    mode = body.get("priority_mode")
    if mode not in ("auto", "manual"):
        return jsonify({"error": "priority_mode must be 'auto' or 'manual'"}), 400
    manual = body.get("manual_priority", [])
    if not isinstance(manual, list) or any(not isinstance(v, str) for v in manual):
        return jsonify({"error": "manual_priority must be an array of model ids"}), 400
    valid = {p["id"] + "/" + row["id"] for p in prov.list_providers()
             for row in _image_model_rows(p["id"])}
    unknown = [value for value in manual if value not in valid]
    if unknown:
        return jsonify({"error": "unknown image model(s): " + ", ".join(unknown)}), 400
    deduped = []
    for value in manual:
        if value not in deduped:
            deduped.append(value)

    def _update(state):
        state["priority_mode"] = mode
        state["manual_priority"] = deduped if mode == "manual" else []
        return state

    try:
        config.update_images_state(body["revision"], _update)
    except config.RevisionConflict as exc:
        return jsonify({"error": "images state changed; reload and retry",
                        "current_revision": exc.current_revision,
                        "state": config.get_images_state()}), 409
    return jsonify(_images_payload())


@app.route("/api/images/history", methods=["GET"])
def api_images_history():
    """Metadata for previously generated images (newest first), no image
    bytes -- the dashboard gallery fetches each thumbnail separately via
    GET /api/images/history/<id>, so listing many entries here stays cheap."""
    return jsonify({"images": image_history.list_entries()})


@app.route("/api/images/history/<image_id>", methods=["GET"])
def api_images_history_file(image_id):
    """Raw bytes of one generated image, for <img src> use. Auth still goes
    through the normal /api/* control-token guard -- an <img> tag can't set a
    custom header, so this relies on the guard's existing '?token=' query-
    param fallback (already used elsewhere in this file for the same reason)."""
    raw, mime_type = image_history.get_file(image_id)
    if raw is None:
        return jsonify({"error": "not found"}), 404
    return Response(raw, mimetype=mime_type or "image/png")


@app.route("/api/images/history/<image_id>", methods=["DELETE"])
def api_images_history_delete(image_id):
    if not image_history.delete(image_id):
        return jsonify({"error": "not found"}), 404
    return jsonify({"ok": True})


# ---------------------------------------------------------------------------
# Auto-update: git-pull every N hours and self-restart when the repo owner ships
# new commits. Opt-in (on by default), skipped if the working tree is dirty so a
# user's local edits are never clobbered. Never touches ~/.free-llm-hub config
# (that lives outside the repo), so keys/enabled flags survive every update.
# ---------------------------------------------------------------------------
_REPO_DIR = os.path.dirname(os.path.abspath(__file__))
_AUTO_UPDATE_INTERVAL_H = float(os.environ.get("AUTO_UPDATE_INTERVAL_HOURS", "5") or "5")
_auto_update_state = {
    "enabled": None,          # resolved at boot from env + config
    "interval_hours": _AUTO_UPDATE_INTERVAL_H,
    "last_check": 0,          # epoch of last pull attempt
    "last_result": "not run yet",
    "updating": False,
}
_auto_update_thread = None
_auto_update_lock = threading.Lock()


def _git(*args, timeout=120):
    """Run a git command in the repo dir; return (rc, stdout, stderr). Never raises."""
    try:
        r = subprocess.run(["git", "-C", _REPO_DIR, *args],
                           capture_output=True, text=True, timeout=timeout,
                           creationflags=_CREATE_NO_WINDOW)
        return r.returncode, (r.stdout or "").strip(), (r.stderr or "").strip()
    except Exception as exc:
        return 1, "", "%s: %s" % (exc.__class__.__name__, exc)


def _is_git_repo():
    rc, out, _ = _git("rev-parse", "--is-inside-work-tree")
    return rc == 0 and out == "true"


# Auto-update pulls and then os.execv's freshly fetched code, so an `origin`
# repointed to an untrusted fork (accidentally or by a compromised dependency/
# setup step) would otherwise run arbitrary code as this user. This does not
# defend against the upstream repo itself being compromised — only against
# a wrong/hostile remote — the accepted residual risk is documented in
# docs/security_best_practices_report.md (SEC-002).
_TRUSTED_REMOTE_RE = re.compile(
    r"^(?:https://github\.com/|git@github\.com:)last-million/free-llm-hub(?:\.git)?/?$",
    re.IGNORECASE)


def _origin_is_trusted():
    rc, url, _ = _git("remote", "get-url", "origin")
    return rc == 0 and bool(_TRUSTED_REMOTE_RE.match(url.strip()))


def _hub_mode_is_off():
    """True only when the user has DELIBERATELY stood the hub down as the machine
    default (a completed hub-mode 'off' transition: desired=='off' AND phase=='off').
    A fresh/never-managed config defaults to desired='on'/phase='unmanaged', so this
    stays False there and leaves always-on auto-update unaffected. Used so auto-update
    won't silently re-exec (respawn) a hub the user just switched off."""
    try:
        st = config.get_hub_mode_state() or {}
    except Exception:
        return False
    return (str(st.get("desired") or "").lower() == "off"
            and str(st.get("phase") or "").lower() == "off")


def _auto_update_enabled():
    """ALWAYS ON. Auto-update is not a user-facing option: the hub keeps itself
    current (git pull every AUTO_UPDATE_INTERVAL_HOURS, default 5) and restarts
    only when the pull actually brought new commits. It is inherently safe —
    it skips a dirty tree, is a no-op outside a git checkout, and never touches
    ~/.free-llm-hub (keys/config live outside the repo), so there is nothing for
    a user to opt out of.

    `AUTO_UPDATE=0` remains ONLY as a developer escape hatch (used by the test
    harness to keep a pinned checkout from restarting mid-run). The old
    `auto_update` config flag is deliberately ignored — it is no longer written
    or read by the dashboard."""
    env = os.environ.get("AUTO_UPDATE")
    if env is not None:
        return env.strip().lower() not in ("0", "false", "no", "off", "")
    return True


# --------------------------------------------------------------------------- #
# Zip-install auto-update: the same 5-hour self-heal as a git clone, for
# someone who downloaded "Download ZIP" from GitHub instead of cloning.
#
# git's dirty-tree skip ("don't clobber local edits") has no free equivalent
# without git, so this builds one: a manifest of {relpath: sha256} for every
# file that was part of the LAST update this code itself applied. Before
# applying a new one, every manifested file's CURRENT on-disk hash must still
# match — any mismatch means the user (or something else) touched a file
# since our last update, and the whole cycle is skipped, exactly like git
# skipping a dirty tree rather than force-pulling over it.
#
# On the very first check for a given zip install (no manifest yet) there is
# nothing to compare against — same trusted-baseline assumption a fresh git
# clone gets on day one: presumed unmodified until proven otherwise.
# --------------------------------------------------------------------------- #
_ZIP_UPDATE_URL = "https://github.com/last-million/free-llm-hub/archive/refs/heads/main.zip"
_ZIP_MANIFEST_PATH = os.path.join(_REPO_DIR, ".free-llm-hub-update-manifest.json")
# Never let a runtime/user artifact block the dirty-check or get shipped into
# the manifest — these are exactly what a git install's .gitignore also keeps
# out of the tree that `git status --porcelain` watches.
_ZIP_UPDATE_IGNORE_DIRS = {".git", ".venv", "venv", "__pycache__", "node_modules"}
_ZIP_UPDATE_IGNORE_FILES = {".free-llm-hub-update-manifest.json", ".calvoun-brief.md"}


def _zip_manifest_of(root_dir):
    """{relpath (forward-slash, sorted) -> sha256} for every real file under
    root_dir, skipping the runtime/ignore set above. Never raises — an
    unreadable file is simply left out (worst case it re-downloads next time)."""
    manifest = {}
    for dirpath, dirnames, filenames in os.walk(root_dir):
        dirnames[:] = [d for d in dirnames if d not in _ZIP_UPDATE_IGNORE_DIRS
                       and not d.endswith(".pyc")]
        for fn in filenames:
            # ".calvoun-brief-<session>.md" as well as the shared name: the
            # brief became per-session so swarm workers stop overwriting each
            # other's, and a per-session name is no more part of the install
            # than the shared one was.
            if (fn in _ZIP_UPDATE_IGNORE_FILES or fn.endswith((".pyc", ".pyo"))
                    or fn.startswith(".calvoun-brief-")):
                continue
            full = os.path.join(dirpath, fn)
            rel = os.path.relpath(full, root_dir).replace(os.sep, "/")
            try:
                with open(full, "rb") as f:
                    manifest[rel] = hashlib.sha256(f.read()).hexdigest()
            except OSError:
                continue
    return manifest


def _zip_apply_needed(new_manifest):
    """True if copying new_manifest's files over _REPO_DIR would actually
    change anything. Deliberately checks ONLY new_manifest's own keys against
    disk (not a full-tree walk) — the live install also holds gitignored/
    local-only files (config.json, .hublog.*, ...) that are never part of the
    shipped zip and must never make this comparison look 'different' when the
    tracked source files are already identical."""
    for rel, expected_hash in new_manifest.items():
        full = os.path.join(_REPO_DIR, *rel.split("/"))
        try:
            with open(full, "rb") as f:
                actual_hash = hashlib.sha256(f.read()).hexdigest()
        except OSError:
            return True
        if actual_hash != expected_hash:
            return True
    return False


def _zip_tree_is_dirty(old_manifest):
    """True if any file the LAST zip-update wrote has since changed on disk —
    the zip-install equivalent of `git status --porcelain` reporting dirty."""
    for rel, expected_hash in old_manifest.items():
        full = os.path.join(_REPO_DIR, *rel.split("/"))
        try:
            with open(full, "rb") as f:
                actual_hash = hashlib.sha256(f.read()).hexdigest()
        except OSError:
            return True  # a file our own last update wrote is now missing/unreadable
        if actual_hash != expected_hash:
            return True
    return False


def _load_zip_manifest():
    try:
        with open(_ZIP_MANIFEST_PATH, "r", encoding="utf-8") as f:
            return json.load(f)
    except (OSError, ValueError):
        return None


def _save_zip_manifest(manifest):
    with open(_ZIP_MANIFEST_PATH, "w", encoding="utf-8") as f:
        json.dump(manifest, f)


def _manifest_fingerprint(manifest):
    """Short, stable label for a manifest -- the zip-update analogue of a git
    short SHA, used only for the human-readable status string/log lines."""
    blob = json.dumps(sorted(manifest.items())).encode("utf-8")
    return hashlib.sha256(blob).hexdigest()[:7]


def _do_zip_update_check():
    """One zip-update cycle: download the latest source zip, skip if the local
    tree has diverged from what we last applied, otherwise overwrite and
    re-exec via the same _finish_update_apply tail the git path uses. Caller
    (_do_update_check) already holds _auto_update_lock."""
    old_manifest = _load_zip_manifest()
    if old_manifest and _zip_tree_is_dirty(old_manifest):
        _auto_update_state["last_result"] = (
            "skipped: local files differ from the last applied update")
        _log.warning("Zip auto-update: local tree diverged from the last applied "
                    "update — skipping, same as git's dirty-tree skip.")
        return _auto_update_state["last_result"]
    tmp_dir = None
    try:
        zip_path = os.path.join(tempfile.gettempdir(),
                                "free-llm-hub-update-%d.zip" % os.getpid())
        r = requests.get(_ZIP_UPDATE_URL, timeout=(10, 60))
        r.raise_for_status()
        with open(zip_path, "wb") as f:
            f.write(r.content)
        tmp_dir = tempfile.mkdtemp(prefix="free-llm-hub-update-")
        with zipfile.ZipFile(zip_path) as zf:
            zf.extractall(tmp_dir)
        os.remove(zip_path)
        # GitHub's archive zip wraps everything in one '<repo>-<branch>/' folder.
        entries = [d for d in os.listdir(tmp_dir) if os.path.isdir(os.path.join(tmp_dir, d))]
        if len(entries) != 1:
            raise RuntimeError("unexpected archive layout: %r" % entries)
        src_root = os.path.join(tmp_dir, entries[0])
        new_manifest = _zip_manifest_of(src_root)
        if not new_manifest:
            raise RuntimeError("downloaded archive had no files")
        before_label = _manifest_fingerprint(old_manifest) if old_manifest else "initial"
        after_label = _manifest_fingerprint(new_manifest)
        # Checked against what's ACTUALLY on disk right now, not just the saved
        # manifest — on a fresh zip install's very first check there IS no saved
        # manifest yet, and treating that as "always different" would force an
        # unnecessary restart even when the download is byte-identical to what
        # is already installed.
        if not _zip_apply_needed(new_manifest):
            _save_zip_manifest(new_manifest)  # still record the baseline
            _auto_update_state["last_result"] = "up to date (%s)" % after_label
            return _auto_update_state["last_result"]
        # New/changed code. Copy every file over the live install — additive/
        # overwrite only, a file the new zip no longer ships is left in place
        # rather than deleted, the safer side of the same "never destroy more
        # than the update itself changed" principle git's ff-only pull already
        # gives for free.
        for rel in new_manifest:
            src = os.path.join(src_root, *rel.split("/"))
            dst = os.path.join(_REPO_DIR, *rel.split("/"))
            os.makedirs(os.path.dirname(dst), exist_ok=True)
            shutil.copy2(src, dst)
        _save_zip_manifest(new_manifest)
    except Exception as exc:
        _auto_update_state["last_result"] = "zip update failed: " + _sanitize(str(exc))[:160]
        _log.warning("Zip auto-update: failed: %s", exc)
        return _auto_update_state["last_result"]
    finally:
        if tmp_dir:
            shutil.rmtree(tmp_dir, ignore_errors=True)
    deps_ok = _sync_deps_after_pull()
    return _finish_update_apply(before_label, after_label, deps_ok)


def _do_update_check():
    """One update cycle. Dispatches on install type — a git clone pulls via git,
    a plain zip/folder download self-updates via _do_zip_update_check — so BOTH
    install methods get the same 5-hour auto-heal, not just git users. Returns a
    short human status string (also stored in _auto_update_state)."""
    with _auto_update_lock:
        _auto_update_state["last_check"] = int(time.time())
        if _is_git_repo():
            return _do_git_update_check()
        return _do_zip_update_check()


def _do_git_update_check():
    """One pull cycle: skip if dirty, pull --ff-only, re-exec if HEAD moved.
    Caller (_do_update_check) already holds _auto_update_lock."""
    if not _origin_is_trusted():
        _auto_update_state["last_result"] = (
            "skipped: 'origin' is not the trusted last-million/free-llm-hub repo")
        _log.warning("Auto-update: refusing to pull — origin remote is untrusted.")
        return _auto_update_state["last_result"]
    # --untracked-files=no: only a modification to a TRACKED file can make
    # `pull --ff-only` clobber real work. Counting untracked files as "dirty"
    # meant one stray note, editor swapfile or stray log in the working tree
    # silently disabled auto-update FOREVER -- found live on 2026-08-30, where a
    # single untracked .md had been parking every 5-hourly check at
    # "skipped: local uncommitted changes" with nothing surfacing that the hub
    # had stopped updating itself. The narrow case this gives up (an incoming
    # commit adding a path that already exists untracked) still fails safely:
    # git refuses the merge and the rc2 != 0 branch below reports it.
    rc, dirty, _ = _git("status", "--porcelain", "--untracked-files=no")
    if rc == 0 and dirty:
        _auto_update_state["last_result"] = "skipped: local uncommitted changes"
        return _auto_update_state["last_result"]
    rc, before, _ = _git("rev-parse", "HEAD")
    # Name the remote and branch explicitly rather than relying on the branch's
    # upstream tracking. MEASURED 2026-08-30: a git-filter-repo run removes the
    # 'origin' remote by design, and re-adding it does NOT restore tracking --
    # so a bare `git pull --ff-only` died with "There is no tracking information
    # for the current branch" and auto-update was silently off. Nothing about
    # this repo's identity depends on that config: _origin_is_trusted() has
    # already checked the remote, and the branch is the one we are on.
    _rcb, _branch, _ = _git("rev-parse", "--abbrev-ref", "HEAD")
    _branch = (_branch or "").strip() or "main"
    rc2, _out, err = _git("pull", "--ff-only", "origin", _branch)
    if rc2 != 0:
        _auto_update_state["last_result"] = "pull failed: " + _sanitize(err)[:160]
        return _auto_update_state["last_result"]
    _rc, after, _ = _git("rev-parse", "HEAD")
    # Run every cycle, not only when before != after: a dependency install
    # that failed on a PRIOR cycle must keep retrying even once HEAD stops
    # moving (git pull is a no-op the moment it succeeded once), or a hub
    # stuck on stale deps would silently stop trying forever. Cheap when
    # nothing changed -- one hash compare against the stamp file.
    deps_ok = _sync_deps_after_pull()
    if not (before and after and before != after):
        _auto_update_state["last_result"] = "up to date (%s)" % (after[:7] if after else "?")
        return _auto_update_state["last_result"]
    return _finish_update_apply(before[:7], after[:7], deps_ok)


def _finish_update_apply(before_label, after_label, deps_ok):
    """Shared tail for BOTH install types once new code has actually landed on
    disk: handle a failed dependency sync, a user-stood-down hub, busy
    sessions, or the clear-to-restart case. Caller already holds
    _auto_update_lock."""
    if not deps_ok:
        _auto_update_state["last_result"] = (
            "updated %s->%s — restart deferred: dependency install failed, "
            "retrying next check" % (before_label, after_label))
        _log.warning("Auto-update: updated %s->%s but dependency install failed; "
                    "NOT re-executing into a broken environment.",
                    before_label, after_label)
        return _auto_update_state["last_result"]
    # New code landed. Normally we re-exec to apply it — but if the user has
    # deliberately switched the hub OFF as the default (hub-mode off), respect
    # that "leave me stood down" intent and do NOT respawn the process; the
    # update applies on the next manual restart instead.
    if _hub_mode_is_off():
        _auto_update_state["last_result"] = (
            "updated %s->%s — restart deferred (hub switched off as default)"
            % (before_label, after_label))
        _log.info("Auto-update: updated %s->%s but hub-mode is off; deferring re-exec.",
                 before_label, after_label)
        return _auto_update_state["last_result"]
    _auto_update_state["updating"] = True
    busy = _agentic_busy_session_ids()
    runs = _swarm_busy_run_ids()
    with _runtime_condition:
        inflight = _runtime_active[0]
    if not busy and not runs and not inflight:
        _auto_update_state["last_result"] = "updated %s->%s — restarting" % (before_label, after_label)
        _log.info("Auto-update: new code applied (%s -> %s), re-executing.",
                 before_label, after_label)
        _reexec_soon()
    else:
        _auto_update_state["last_result"] = (
            "updated %s->%s — restart deferred: %d task(s) still running"
            % (before_label, after_label,
               len(busy) + len(runs) + (1 if inflight else 0)))
        _log.info("Auto-update: updated %s->%s but %d session(s)/%d swarm run(s)/"
                 "%d inflight request(s) busy; deferring restart until they finish.",
                 before_label, after_label, len(busy), len(runs), inflight)
        _reexec_when_idle(busy, runs)
    return _auto_update_state["last_result"]


def _sync_deps_after_pull():
    """Best-effort `pip install -r requirements.txt`, run ONLY when the pulled
    tree's hash differs from the last install (same stamp file and hash
    convention run.bat/run.sh already use for a fast plain start, so a normal
    pull with no dependency change costs one hash compare, not a pip round
    trip). Returns True if it is now safe to re-exec (deps match what HEAD
    needs), False if a required install failed.

    WHY THIS EXISTS: _do_update_check() pulls new code and os.execv's into it,
    but execv keeps the SAME already-imported interpreter/site-packages --
    nothing else in this file ever re-ran pip. A commit that adds a new
    dependency would pull clean, then crash the very next line on import,
    taking down an auto-updating hub that was working fine before the pull."""
    try:
        req_path = os.path.join(_REPO_DIR, "requirements.txt")
        stamp_path = os.path.join(_REPO_DIR, ".venv", ".deps-stamp")
        with open(req_path, "rb") as f:
            h = hashlib.sha256(f.read()).hexdigest()
        try:
            with open(stamp_path, "r", encoding="utf-8") as f:
                current = f.read().strip()
        except OSError:
            current = None
        if current == h:
            return True
        _log.info("Auto-update: requirements.txt changed, installing before restarting.")
        r = subprocess.run([sys.executable, "-m", "pip", "install", "-q", "-r", req_path],
                           capture_output=True, text=True, timeout=300,
                           creationflags=_CREATE_NO_WINDOW)
        if r.returncode != 0:
            _log.error("Auto-update: pip install failed, deferring restart: %s",
                      _sanitize((r.stderr or "")[:300]))
            return False
        os.makedirs(os.path.dirname(stamp_path), exist_ok=True)
        with open(stamp_path, "w", encoding="utf-8") as f:
            f.write(h)
        return True
    except Exception as exc:
        _log.error("Auto-update: dependency sync failed, deferring restart: %s", exc)
        return False


def _reexec_soon():
    """Replace this process with a fresh one (applies pulled code). Env (incl.
    PORT) is inherited across execv, so the gateway comes back on the same port."""
    def _go():
        time.sleep(1.0)
        try:
            os.execv(sys.executable, [sys.executable] + sys.argv)
        except Exception as exc:
            _log.error("Auto-update re-exec failed: %s", exc)
            _auto_update_state["updating"] = False
    threading.Thread(target=_go, daemon=True).start()


# Longest an update will wait for work to finish before restarting anyway.
# A run is several waves of workers, each allowed up to
# swarm_windows.AGENT_TIMEOUT (two hours) when it is visibly working -- and a
# restart mid-run is what this deferral exists to avoid (the next hub resumes
# an interrupted run, but the phases it was on start over). Four hours still
# guarantees the pulled code applies on the same day it was pulled.
_DEFER_RESTART_MAX = 4 * 3600.0


def _agentic_busy_session_ids():
    """Agent chat session ids currently mid-turn (turn_lock held), snapshotted
    right now. A re-exec kills every in-flight connection outright (no HTTP
    response, no SSE event) -- an active agentic turn can legitimately run up
    to _TURN_TIMEOUT (1800s), so restarting out from under one is exactly the
    "stopped my work" a user would notice and be annoyed by."""
    ids = set()
    for sid, sess in list(agentic_chat._REGISTRY.items()):
        try:
            if sess.turn_lock.locked():
                ids.add(sid)
        except Exception:                                          # noqa: BLE001
            continue
    return ids


def _swarm_busy_run_ids():
    """Swarm runs that are still going, snapshotted right now.

    A SWARM IS WORK THE TURN LOCK CANNOT SEE. _agentic_busy_session_ids finds a
    worker while its turn is running, but a run spends real time between
    phases -- a wave finishing, the next one being scheduled, a worker being
    spawned -- and in those gaps no lock is held anywhere. Restarting in one of
    those gaps kills the whole run: the workers are children of this process
    and the walk thread goes with it, so a twenty-minute five-phase job dies
    two phases in and comes back marked "interrupted by a hub restart".

    REQUESTED: "make sure people who installed it get the git pull and restart
    without interrupting the work."
    """
    try:
        return {r["run_id"] for r in swarm_windows.list_runs()
                if r.get("state") in (swarm_windows.PENDING, swarm_windows.RUNNING)}
    except Exception:                                            # noqa: BLE001
        return set()


def _still_running(busy_sessions, busy_runs):
    """How many of the snapshotted tasks are still going. 0 means restart."""
    live = {sid for sid in busy_sessions
            if sid in agentic_chat._REGISTRY
            and agentic_chat._REGISTRY[sid].turn_lock.locked()}
    runs = _swarm_busy_run_ids() & set(busy_runs or ())
    with _runtime_condition:
        inflight = _runtime_active[0]
    return len(live) + len(runs) + (1 if inflight else 0)


def _reexec_when_idle(busy_snapshot, busy_runs=()):
    """Restart once every session busy AT UPDATE-CHECK TIME (plus any request
    already in flight on /v1/*) has finished -- and not a moment later, even
    if the hub stays continuously busy. Deliberately does NOT wait for
    sessions that START after the snapshot: an always-on hub could otherwise
    defer forever and the pulled code would never actually apply."""
    def _go():
        # A ceiling, because a swarm that hangs must not defer the update
        # forever. Generous on purpose: a worker may run up to
        # swarm_windows.AGENT_TIMEOUT while it is producing output, and a run
        # is several waves of them, so anything under this is a run that is
        # still legitimately working.
        deadline = time.time() + _DEFER_RESTART_MAX
        while True:
            busy = _still_running(busy_snapshot, busy_runs)
            if not busy:
                break
            if time.time() > deadline:
                _log.warning("Auto-update: %d task(s) still running after %.0f min; "
                             "restarting anyway.", busy, _DEFER_RESTART_MAX / 60.0)
                break
            _auto_update_state["last_result"] = (
                "update pulled — restart deferred: %d task(s) still running" % busy)
            time.sleep(3.0)
        _log.info("Auto-update: deferred restart proceeding — snapshotted tasks are done.")
        _reexec_soon()
    threading.Thread(target=_go, daemon=True, name="freehub-update-wait").start()


def _auto_update_loop():
    interval = max(0.25, _auto_update_state["interval_hours"]) * 3600.0
    # A short initial delay lets the server finish booting before the first check.
    time.sleep(min(interval, 60))
    while True:
        if _auto_update_enabled():
            try:
                _do_update_check()
            except Exception as exc:
                _log.error("Auto-update cycle error: %s", exc)
        # Sleep in small slices so a disabled->enabled flip is honored promptly.
        slept = 0.0
        while slept < interval:
            time.sleep(min(30.0, interval - slept))
            slept += 30.0


def _start_auto_update():
    global _auto_update_thread
    _auto_update_state["enabled"] = _auto_update_enabled()
    if _auto_update_thread is not None:
        return
    _auto_update_thread = threading.Thread(target=_auto_update_loop, daemon=True)
    _auto_update_thread.start()


@app.route("/api/auto-update", methods=["GET", "POST"])
def api_auto_update():
    """GET -> current state (diagnostics only; the dashboard no longer shows it).
    POST {check:true} -> run one update cycle now (may restart on new commits).

    There is NO enable/disable: auto-update is always on (see
    _auto_update_enabled). A POST carrying {enabled:...} is accepted but ignored
    so an older cached dashboard can't silently turn it off; the response's
    `enabled` always reflects the truth."""
    if request.method == "POST":
        body = request.get_json(force=True, silent=True) or {}
        if body.get("check"):
            threading.Thread(target=_do_update_check, daemon=True).start()
    st = dict(_auto_update_state)
    st["enabled"] = _auto_update_enabled()   # always True (unless the dev env escape)
    st["always_on"] = True
    st["is_git_repo"] = _is_git_repo()
    return jsonify(st)


