def _print_banner():
    key = config.get_local_api_key()
    control_token = config.ensure_control_token()
    snippets = _connect_snippets()
    line = "=" * 74
    print(line)
    print("  Calvoun Free LLM Hub -- local gateway for free LLM providers")
    print(line)
    print("  Dashboard:   http://%s:%d/" % (HOST, PORT))
    print("  OpenAI API:  http://%s:%d/v1  (chat/completions, models)" % (HOST, PORT))
    print("  Anthropic:   http://%s:%d/v1/messages  (Claude Code compatible)" % (HOST, PORT))
    if key:
        print("  Local key:   SET (required on /v1/* as Bearer or x-api-key)")
    else:
        print("  Local key:   not set -- /v1/* is open on localhost")
    print(line)
    print("  Control token (paste into the dashboard once, first load):")
    print("    " + control_token)
    print("  This gates /api/* (dashboard config, hub mode, shutdown). It is")
    print("  stored in config.json (0600) and never sent to any provider.")
    print(line)
    # Say it out loud when routing is NOT picking the best model. This flag has
    # no UI: it sat False in a real config with no way for anyone to have set it
    # deliberately, and the only symptom was "why does chat not use the good
    # models" -- a question that took a routing trace to answer. A line in the
    # banner turns that into something visible.
    if not config.get_flag("route_always_best", True):
        print("  Routing:     SPREADING across the top band, not always-best.")
        print("               Every medium/hard turn may land on a weaker model")
        print("               to stretch quota. Undo: route_always_best=true in")
        print("               ~/.free-llm-hub/config.json")
        print("=" * 74)
    print("  Connect Claude Code:")
    for ln in snippets["claude_code"].splitlines():
        print("    " + ln)
    print("  Connect OpenAI-compatible CLIs (aider, opencode, ...):")
    for ln in snippets["openai"].splitlines():
        print("    " + ln)
    print(line)


# STOP MEANS OFF FOR EVERY CLI TOO. Owner, 2026-09-30: "when we click Stop
# the hub in Settings it should really stop it and auto disconnect from all
# CLIs". A CLI still wired to a stopped hub fails every request; disconnected,
# it goes back to its own provider. The ones Stop disconnected are remembered
# and wired again when the hub starts (a Stop is usually temporary) -- only
# those: a CLI the owner disconnected by hand stays disconnected.
_STOP_DISCONNECTED_SETTING = "stop_disconnected_clis"


def _route_json(resp):
    """The JSON body of a route function's return value (resp or (resp, code))."""
    try:
        if isinstance(resp, tuple):
            resp = resp[0]
        return resp.get_json(silent=True) or {}
    except Exception:                                            # noqa: BLE001
        return {}


def _disconnect_all_clis():
    """Disconnect every CLI wired to this hub (config or env). Returns
    {"disconnected": [ids], "failed": [{id, why}]}. Never raises."""
    done, failed = [], []
    for entry in CLI_REGISTRY:
        cid = entry.get("id")
        try:
            if not _cli_connected(entry)[0]:
                continue
        except Exception:                                        # noqa: BLE001
            continue
        try:
            data = _route_json(api_cli_disconnect(cid))
        except Exception as exc:                                 # noqa: BLE001
            failed.append({"id": cid, "why": _sanitize(str(exc), 160)})
            continue
        if data.get("ok") and not data.get("still_connected"):
            done.append(cid)
        else:
            failed.append({"id": cid, "why": _sanitize(str(data.get("note") or data.get("error")
                                                            or "still connected"), 160)})
    return {"disconnected": done, "failed": failed}


def _reconnect_clis_after_stop():
    """At boot: wire again exactly the CLIs the last Stop disconnected.
    Returns the ids reconnected. Never raises."""
    try:
        ids = [c for c in (config.get_setting(_STOP_DISCONNECTED_SETTING) or [])
               if isinstance(c, str)]
    except Exception:                                            # noqa: BLE001
        return []
    if not ids:
        return []
    back = []
    for cid in ids:
        try:
            with app.test_request_context("/api/clis/%s/autofix" % cid, method="POST", json={}):
                data = _route_json(api_cli_autofix(cid))
            if data.get("ok") or data.get("connected"):
                back.append(cid)
        except Exception as exc:                                 # noqa: BLE001
            _log.warning("[stop] could not reconnect %s: %s", cid, _sanitize(str(exc), 160))
    try:
        config.set_setting(_STOP_DISCONNECTED_SETTING, None)
    except Exception:                                            # noqa: BLE001
        pass
    if back:
        _log.info("[stop] reconnected %d CLI(s) the last Stop disconnected: %s",
                  len(back), ", ".join(back))
    return back


def _mark_runtime_started():
    config.clear_intentional_stop()
    for _attempt in range(3):
        state = config.get_runtime_state()

        def _running(value):
            value.update({"desired": "running", "phase": "running",
                          "shutdown_requested_at": None, "last_error": None})
            return value

        try:
            config.update_runtime_state(state["revision"], _running)
            return
        except config.RevisionConflict:
            continue


def _claim_single_instance():
    """Take an exclusive OS lock so a second hub cannot run against one config.

    TWO COPIES OF THIS HUB SHARE ~/.free-llm-hub, and that is how every API key
    on this install was lost: both processes read and write config.json and
    secret.key, one of them could not read the key for a moment, and the config
    was then saved without the secrets it could not decrypt. The launchers
    already refuse a second start, but nothing stopped `python app.py` directly,
    and a scheduled task starting one at logon races anything started by hand --
    three live processes were found at once.

    An OS byte-range lock, not a pidfile: it is released by the kernel when the
    process dies, so it cannot go stale after a crash or a taskkill.

    FAILS OPEN on anything that is not real contention. Refusing to start is a
    serious failure -- it locks the user out of their own hub -- so the only
    errno values that count as "someone else has it" are the ones that mean
    exactly that. A filesystem that cannot lock at all (NFS without lockd, some
    SMB and FUSE mounts) reports ENOLCK/ENOTSUP/EINVAL, and inability to CHECK
    must never be read as proof of contention: that is the same mistake that
    cost the keys, applied to the start path instead.

    HUB_FORCE=1 overrides, because both launchers already document it as the way
    past their own version of this check."""
    if os.environ.get("HUB_FORCE"):
        _log.info("HUB_FORCE set -- skipping the single-instance check")
        return True
    path = os.path.join(os.path.dirname(config._config_path()), "instance.lock")
    # A dedicated file, NOT config.json.lock: config.py takes a blocking
    # cross-process lock on byte 0 of that one for every write, and holding it
    # here would deadlock the hub against its own first save.
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        fh = open(path, "a+b")
    except OSError as exc:
        _log.warning("single-instance check unavailable (%s) -- starting anyway", exc)
        return True
    busy = {errno.EACCES, errno.EAGAIN, errno.EWOULDBLOCK, errno.EDEADLK, 36}
    try:
        try:
            import msvcrt
            msvcrt.locking(fh.fileno(), msvcrt.LK_NBLCK, 1)
        except ImportError:
            import fcntl
            fcntl.flock(fh.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
    except OSError as exc:
        if exc.errno in busy:
            fh.close()
            return False                      # genuinely held by another hub
        _log.warning("single-instance check unavailable (%s) -- starting anyway", exc)
        fh.close()
        return True
    except Exception as exc:                                     # noqa: BLE001
        _log.warning("single-instance check unavailable (%s) -- starting anyway", exc)
        fh.close()
        return True
    _INSTANCE_LOCK.append(fh)     # held for the life of the process, never closed
    return True


_INSTANCE_LOCK = []


if __name__ == "__main__":
    from werkzeug.serving import make_server

    _recover_interrupted_hub_transition()
    _mark_runtime_started()
    # Agent CLIs the previous hub process launched and never stopped (a hard
    # restart kills the hub, not its children on Windows): stopped before
    # this hub starts any turn of its own -- see agent_servers.stale_agent_clis.
    try:
        _stale = agent_servers.stop_stale_agent_clis()
        if _stale:
            _log.info("[boot] stopped %d agent CLI process(es) the previous hub left running: %s",
                      len(_stale), ", ".join("%s(%s)" % (p["name"], p["pid"]) for p in _stale)[:300])
    except Exception as _exc:                                    # noqa: BLE001
        _log.warning("[boot] could not check for leftover agent CLIs: %s", _exc)
    # The CLIs the last Stop disconnected, wired again once the server answers.
    threading.Thread(target=lambda: (time.sleep(15), _reconnect_clis_after_stop()),
                     daemon=True, name="stop-reconnect").start()
    _bootstrap_no_key_providers()  # no-key providers have nothing to configure -> on
    _init_quota_persistence()      # restore quota/dead-model state from the last run
    _bandit_boot()                 # task bandit state: state_dir()/task-bandit.json
    try:                           # the goal/task board -- state_dir()/taskboard.json
        taskboard.configure(os.path.join(config.state_dir(), "taskboard.json"))
    except Exception as _exc:                                    # noqa: BLE001
        _log.warning("[taskboard] not configured: %s", _exc)
    # Declared context windows follow the fleet (agentic_chat.declared_window);
    # registered here, after the windows above are restored, so every CLI
    # config written from now on is sized on known windows.
    agentic_chat.set_window_provider(_stable_declared_window_for)
    _start_ctx_reference_refresh()  # OpenRouter's public windows, for inference
    _seed_default_blocks()         # ship the owner's blocklist to every install
    # Encrypt any provider keys still stored in plaintext. A no-op once done, so
    # an ordinary start does not rewrite the config file for nothing.
    try:
        _migrated = config.encrypt_existing_secrets()
        if _migrated:
            _log.info("encrypted %d provider key(s) at rest", _migrated)
    except Exception as _exc:                                    # noqa: BLE001
        _log.warning("could not encrypt stored keys: %s", _exc)
    _print_banner()
    _start_auto_update()
    _start_aa_refresh()
    _start_arena_refresh()
    _start_answer_canary()   # flag answer_canary is read per tick, so off = no calls
    # Previews that outlived the hub that started them (crash, kill, restart
    # while a project was running) keep holding their ports forever. Found 99
    # of the 100 held on this machine, which makes the next preview fail with
    # "no free port". Only the hub's own range is swept.
    try:
        freed = workspace.sweep_own_range()
        if freed:
            _log.info("reclaimed %d preview port(s) left by a previous run", freed)
    except Exception as exc:                                     # noqa: BLE001
        _log.warning("could not sweep preview ports: %s", exc)
    workspace.start_reaper()   # stop previews nobody is watching
    _load_perf_stats()         # measured reliability/latency from previous runs
    try:
        # Swarm runs outlive the process that started them. The hub restarts
        # itself every five hours to git pull, and before this a swarm that
        # finished at hour four left nothing behind at hour five: no result to
        # read back, and any run still going became a thread nobody could find.
        back = swarm_windows.load()
        if back:
            _log.info("restored %d swarm run(s) from disk", back)
        # ...and the ones that were still going get finished, not filed as
        # failed. Workers spawn CLI processes, so this waits for the catalogs
        # and the agent setup below to have started: a short delay, on a
        # thread, rather than blocking the bind.
        threading.Timer(20, _resume_interrupted_swarms).start()
    except Exception as exc:                                     # noqa: BLE001
        _log.warning("could not restore swarm runs: %s", exc)
    _maybe_auto_create_desktop_shortcut()
    _start_agent_cli_autoinstall()
    vision_status.start_heartbeat()
    _start_heartbeat_scheduler()   # agents wake themselves on the owner's schedule
    _warm_catalogs_async()     # so the first CLI to ask does not pay the sweep
    _repair_opencode_config()  # a limitless model entry is a session that never compacts
    _start_declared_window_resync()   # connected CLIs follow a changed declared window
    threading.Thread(target=_start_playwright_mcp, daemon=True,
                     name="playwright-mcp").start()   # one browser, kept between turns
    threading.Thread(target=_refresh_codex_catalog, daemon=True,
                     name="codex-catalog").start()   # /model offers the hub's modes
    if not _claim_single_instance():
        _log.error("another Calvoun hub is already running against %s -- "
                   "stop it first, or set HUB_FORCE=1 to start anyway.",
                   os.path.dirname(config._config_path()))
        raise SystemExit(1)
    server = make_server(HOST, PORT, app, threaded=True)
    # After the single-instance claim, never before: a second hub that is
    # about to exit must not file the RUNNING hub's turns as interrupted.
    # (Started after the bind so the claim stays right next to it.)
    threading.Thread(target=_recover_memory_state, daemon=True,
                     name="memory-recover").start()
    _runtime_server[0] = server
    try:
        server.serve_forever()
    finally:
        _runtime_server[0] = None
        server.server_close()
        # Flush what this run learned. The throttled saves during the run keep
        # a crash cheap; this makes a clean stop (or an auto-update re-exec)
        # lose nothing at all.
        _save_perf_stats(force=True)
